CREATE OR REPLACE FUNCTION "private"."user_can_read_trip_conversation"("p_org_id" "uuid", "p_trip_id" "uuid", "p_driver_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Check 1: dispatcher/admin of the owning org (~95% of requests)
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.user_id         = (SELECT auth.uid())
      AND om.organization_id = p_org_id
      AND (om.status = 'active' OR om.status IS NULL)
  )
  -- Check 2: driver assigned to this conversation
  OR (
    p_driver_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.drivers d
      WHERE d.id      = p_driver_id
        AND d.user_id = (SELECT auth.uid())
    )
  )
  -- Check 3: linked client org
  OR EXISTS (
    SELECT 1
    FROM public.trips             t
    JOIN public.clients           c  ON c.id  = t.client_id
    JOIN public.organization_members om
      ON om.user_id          = (SELECT auth.uid())
     AND om.organization_id  = c.linked_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE t.id = p_trip_id
  )
  -- Check 4: linked supplier org (direct relationship)
  OR EXISTS (
    SELECT 1
    FROM public.trips             t
    JOIN public.suppliers         s  ON s.id  = t.supplier_id
    JOIN public.organization_members om
      ON om.user_id          = (SELECT auth.uid())
     AND om.organization_id  = s.linked_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE t.id = p_trip_id
  )
  -- Check 5: supplier org via accepted indent direct_quote
  OR EXISTS (
    SELECT 1
    FROM public.trips                t
    JOIN public.indents              i  ON i.id        = t.indent_id
    JOIN public.direct_quotes        dq ON dq.indent_id = i.id
                                       AND dq.status   = 'accepted'
    JOIN public.organization_members om
      ON om.user_id          = (SELECT auth.uid())
     AND om.organization_id  = dq.bidder_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE t.id          = p_trip_id
      AND t.supplier_id IS NULL
      AND t.indent_id   IS NOT NULL
  )
$$;


ALTER FUNCTION "private"."user_can_read_trip_conversation"("p_org_id" "uuid", "p_trip_id" "uuid", "p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."user_can_read_trip_message"("p_org_id" "uuid", "p_conv_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Check 1: dispatcher/admin of the owning org (covers ~95% of requests)
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.user_id        = (SELECT auth.uid())
      AND om.organization_id = p_org_id
      AND (om.status = 'active' OR om.status IS NULL)
  )
  -- Check 2: driver assigned to this conversation
  OR EXISTS (
    SELECT 1
    FROM public.trip_conversations tc
    JOIN public.drivers d ON d.id = tc.driver_id
    WHERE tc.id       = p_conv_id
      AND d.user_id   = (SELECT auth.uid())
  )
  -- Check 3: linked client org
  OR EXISTS (
    SELECT 1
    FROM public.trip_conversations tc
    JOIN public.trips             t  ON t.id  = tc.trip_id
    JOIN public.clients           c  ON c.id  = t.client_id
    JOIN public.organization_members om
      ON om.user_id          = (SELECT auth.uid())
     AND om.organization_id  = c.linked_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE tc.id = p_conv_id
  )
  -- Check 4: linked supplier org (direct relationship)
  OR EXISTS (
    SELECT 1
    FROM public.trip_conversations tc
    JOIN public.trips             t  ON t.id  = tc.trip_id
    JOIN public.suppliers         s  ON s.id  = t.supplier_id
    JOIN public.organization_members om
      ON om.user_id          = (SELECT auth.uid())
     AND om.organization_id  = s.linked_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE tc.id = p_conv_id
  )
  -- Check 5: supplier org via accepted indent direct_quote
  OR EXISTS (
    SELECT 1
    FROM public.trip_conversations   tc
    JOIN public.trips                t  ON t.id        = tc.trip_id
    JOIN public.indents              i  ON i.id        = t.indent_id
    JOIN public.direct_quotes        dq ON dq.indent_id = i.id
                                       AND dq.status   = 'accepted'
    JOIN public.organization_members om
      ON om.user_id          = (SELECT auth.uid())
     AND om.organization_id  = dq.bidder_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE tc.id          = p_conv_id
      AND t.supplier_id  IS NULL
      AND t.indent_id    IS NOT NULL
  )
$$;


ALTER FUNCTION "private"."user_can_read_trip_message"("p_org_id" "uuid", "p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_bid"("p_bid_id" "uuid", "p_actor_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_post_id uuid;
BEGIN
  SELECT post_id INTO v_post_id FROM public.bids WHERE id = p_bid_id;

  IF NOT EXISTS (
    SELECT 1 FROM public.posts p
    WHERE p.id = v_post_id AND p.organization_id = p_actor_org_id
  ) THEN
    RAISE EXCEPTION 'Not authorized to accept bids for this post';
  END IF;

  UPDATE public.bids SET status = 'accepted', updated_at = now() WHERE id = p_bid_id;
  UPDATE public.bids SET status = 'rejected', updated_at = now()
    WHERE post_id = v_post_id AND id <> p_bid_id AND status = 'pending';
  UPDATE public.posts SET is_active = false, updated_at = now() WHERE id = v_post_id;
END;
$$;


ALTER FUNCTION "public"."accept_bid"("p_bid_id" "uuid", "p_actor_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_driver_invite"("p_invite_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite       public.driver_invites;
  v_driver_id    uuid;
  v_name         text;
  v_phone        text;
  v_email        text;
  v_phone_last10 text;
BEGIN
  SELECT *
  INTO v_invite
  FROM public.driver_invites
  WHERE id = p_invite_id
    AND to_user_id = auth.uid()
    AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invite not found or already responded';
  END IF;

  -- Guard: block if caller already has an active connection to this org
  IF EXISTS (
    SELECT 1 FROM public.drivers
    WHERE organization_id = v_invite.from_organization_id
      AND user_id = auth.uid()
      AND left_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Already connected to this organization. Leave first before re-joining.';
  END IF;

  -- Resolve caller identity from profiles + auth.users
  SELECT
    coalesce(
      nullif(trim(p.full_name), ''),
      nullif(trim(u.raw_user_meta_data->>'full_name'), ''),
      nullif(trim(u.raw_user_meta_data->>'name'), ''),
      'Driver'
    ),
    nullif(trim(coalesce(p.phone, u.raw_user_meta_data->>'phone')), ''),
    nullif(trim(coalesce(p.email, u.email)), '')
  INTO v_name, v_phone, v_email
  FROM auth.users u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = auth.uid();

  v_phone_last10 := public.normalize_phone_last10(v_phone);

  -- Merge exception: claim an unlinked (manual / tracking-only) roster entry
  -- that was added by phone before this driver had a Pulse account.
  -- Only applies when: user_id IS NULL, left_at IS NULL, phone matches.
  IF length(v_phone_last10) = 10 THEN
    SELECT d.id
    INTO v_driver_id
    FROM public.drivers d
    WHERE d.organization_id = v_invite.from_organization_id
      AND d.user_id IS NULL
      AND d.left_at IS NULL
      AND d.phone IS NOT NULL
      AND public.normalize_phone_last10(d.phone) = v_phone_last10
    ORDER BY d.updated_at DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF v_driver_id IS NOT NULL THEN
    -- Claim the unlinked manual row: set user_id and apply invite pay terms
    UPDATE public.drivers
    SET user_id          = auth.uid(),
        name             = coalesce(nullif(trim(v_name), ''), name),
        email            = coalesce(nullif(trim(v_email), ''), email),
        tracking_only    = false,
        status           = 'offline',
        payable_amount   = coalesce(v_invite.payable_amount, payable_amount),
        commission_percent = coalesce(v_invite.commission_percent, commission_percent),
        commission_per_km  = coalesce(v_invite.commission_per_km, commission_per_km),
        updated_at       = now()
    WHERE id = v_driver_id;
  ELSE
    -- New employment stint: always INSERT a fresh drivers row (new passbook)
    INSERT INTO public.drivers (
      organization_id,
      name,
      phone,
      email,
      user_id,
      status,
      tracking_only,
      hired_at,
      payable_amount,
      commission_percent,
      commission_per_km
    )
    VALUES (
      v_invite.from_organization_id,
      coalesce(nullif(trim(v_name), ''), 'Driver'),
      v_phone,
      v_email,
      auth.uid(),
      'offline',
      false,
      now(),
      v_invite.payable_amount,
      v_invite.commission_percent,
      v_invite.commission_per_km
    )
    RETURNING id INTO v_driver_id;
  END IF;

  UPDATE public.driver_invites
  SET status       = 'accepted',
      responded_at = now(),
      responded_by = auth.uid()
  WHERE id = p_invite_id;

  RETURN jsonb_build_object(
    'driver_id',       v_driver_id,
    'organization_id', v_invite.from_organization_id
  );
END;
$$;


ALTER FUNCTION "public"."accept_driver_invite"("p_invite_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_driver_invite"("p_invite_id" "uuid") IS 'Accept fleet invite. Merge exception: claims an unlinked phone-only roster entry if one exists. Otherwise always INSERTs a new drivers row (new employment stint / passbook). Guard raises if caller already has an active connection to the org.';



CREATE OR REPLACE FUNCTION "public"."accept_partner_view"("org_id" "uuid", "trip_id" "uuid", "partner_sales" numeric, "partner_paid" numeric, "contact_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := accept_partner_view.org_id;
  v_trip_id uuid := accept_partner_view.trip_id;
  v_partner_sales numeric := accept_partner_view.partner_sales;
  v_partner_paid numeric := accept_partner_view.partner_paid;
  v_contact_id uuid := accept_partner_view.contact_id;
  trip_org_id uuid;
  first_contact_id uuid;
  first_contact_type text;
  first_party_name text;
  effective_contact_type text;
  v_amount_in numeric;
  v_amount_out numeric;
BEGIN
  IF NOT public.is_org_member(v_org_id) THEN
    RETURN;
  END IF;

  SELECT t.organization_id INTO trip_org_id
  FROM public.trips t
  WHERE t.id = v_trip_id;

  SELECT tr.contact_id, tr.contact_type, tr.party_name
  INTO first_contact_id, first_contact_type, first_party_name
  FROM public.transactions tr
  WHERE tr.organization_id = v_org_id
    AND tr.trip_id = v_trip_id
    AND (v_contact_id IS NULL OR tr.contact_id = v_contact_id)
  ORDER BY tr.created_at
  LIMIT 1;

  DELETE FROM public.transactions
  WHERE public.transactions.organization_id = v_org_id
    AND public.transactions.trip_id = v_trip_id
    AND (v_contact_id IS NULL OR public.transactions.contact_id = v_contact_id);

  IF trip_org_id IS NOT NULL AND trip_org_id = v_org_id THEN
    UPDATE public.trips t
    SET
      client_price = COALESCE(v_partner_sales, 0),
      supplier_rate = COALESCE(v_partner_sales, 0),
      updated_at = now()
    WHERE t.id = v_trip_id
      AND t.organization_id = v_org_id;
  END IF;

  effective_contact_type := first_contact_type;
  IF effective_contact_type IS NULL AND (v_contact_id IS NOT NULL OR first_contact_id IS NOT NULL) THEN
    SELECT 'client' INTO effective_contact_type
    FROM public.clients c
    WHERE c.organization_id = v_org_id AND c.id = COALESCE(v_contact_id, first_contact_id)
    LIMIT 1;
    IF effective_contact_type IS NULL THEN
      SELECT 'supplier' INTO effective_contact_type
      FROM public.suppliers s
      WHERE s.organization_id = v_org_id AND s.id = COALESCE(v_contact_id, first_contact_id)
      LIMIT 1;
    END IF;
  END IF;

  -- Partner paid: supplier (contact=client) receives → amount_in; client (contact=supplier) pays → amount_out.
  IF v_partner_paid IS NOT NULL AND v_partner_paid <> 0 THEN
    IF effective_contact_type = 'client' THEN
      v_amount_in := GREATEST(COALESCE(v_partner_paid, 0), 0);
      v_amount_out := GREATEST(COALESCE(-v_partner_paid, 0), 0);
    ELSIF effective_contact_type = 'supplier' THEN
      v_amount_in := GREATEST(COALESCE(-v_partner_paid, 0), 0);
      v_amount_out := GREATEST(COALESCE(v_partner_paid, 0), 0);
    ELSE
      v_amount_in := CASE WHEN v_partner_paid > 0 THEN v_partner_paid ELSE 0 END;
      v_amount_out := CASE WHEN v_partner_paid < 0 THEN (-v_partner_paid) ELSE 0 END;
    END IF;
    INSERT INTO public.transactions (
      organization_id,
      trip_id,
      party_name,
      description,
      amount_in,
      amount_out,
      transaction_date,
      contact_id,
      contact_type
    ) VALUES (
      v_org_id,
      v_trip_id,
      COALESCE(first_party_name, 'Ledger update'),
      'Shared ledger sync',
      v_amount_in,
      v_amount_out,
      current_date,
      COALESCE(v_contact_id, first_contact_id),
      effective_contact_type
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."accept_partner_view"("org_id" "uuid", "trip_id" "uuid", "partner_sales" numeric, "partner_paid" numeric, "contact_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_partner_view"("org_id" "uuid", "trip_id" "uuid", "partner_sales" numeric, "partner_paid" numeric, "contact_id" "uuid") IS 'Self-correct: update caller org ledger for trip to match partner_sales/partner_paid. Used by Update my book and resolve_dispute (Accept dispute). Client pays → amount_out; supplier receives → amount_in.';



CREATE OR REPLACE FUNCTION "public"."accept_pending_team_invitation"("p_invite_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_inv         public.organization_team_invites%ROWTYPE;
  v_profile     public.profiles%ROWTYPE;
  v_member_id   uuid;
  v_canon       text;
  v_existing    public.organization_members%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_inv
  FROM public.organization_team_invites
  WHERE id = p_invite_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;

  IF v_inv.status = 'accepted' THEN
    SELECT om.id INTO v_member_id
    FROM public.organization_members om
    WHERE om.organization_id = v_inv.organization_id
      AND om.user_id = v_uid
      AND om.status IN ('active', 'invited')
    LIMIT 1;
    RETURN jsonb_build_object(
      'organization_id', v_inv.organization_id,
      'membership_id', v_member_id,
      'already_accepted', true
    );
  END IF;

  IF v_inv.status <> 'pending' THEN
    RAISE EXCEPTION 'Invitation is no longer valid';
  END IF;

  IF v_inv.expires_at <= now() THEN
    UPDATE public.organization_team_invites
    SET status = 'expired', updated_at = now()
    WHERE id = v_inv.id;
    RAISE EXCEPTION 'Invitation has expired';
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = v_uid;
  v_canon := public.normalize_phone_canon(v_profile.phone);
  IF v_canon IS NULL OR v_canon <> v_inv.invitee_phone_canon THEN
    RAISE EXCEPTION 'Phone number does not match this invitation';
  END IF;

  SELECT * INTO v_existing
  FROM public.organization_members
  WHERE organization_id = v_inv.organization_id
    AND user_id = v_uid;

  IF FOUND THEN
    IF v_existing.status = 'active' THEN
      UPDATE public.organization_team_invites
      SET status = 'accepted', accepted_user_id = v_uid, updated_at = now()
      WHERE id = v_inv.id;
      RETURN jsonb_build_object(
        'organization_id', v_inv.organization_id,
        'membership_id', v_existing.id,
        'already_member', true
      );
    END IF;

    UPDATE public.organization_members
    SET
      role        = v_inv.role,
      permissions = v_inv.permissions,
      status      = 'active',
      joined_at   = now()
    WHERE id = v_existing.id
    RETURNING id INTO v_member_id;
  ELSE
    INSERT INTO public.organization_members (
      organization_id, user_id, role, status, permissions, joined_at
    ) VALUES (
      v_inv.organization_id,
      v_uid,
      v_inv.role,
      'active',
      v_inv.permissions,
      now()
    )
    RETURNING id INTO v_member_id;
  END IF;

  UPDATE public.organization_team_invites
  SET
    status           = 'accepted',
    accepted_user_id = v_uid,
    updated_at       = now()
  WHERE id = v_inv.id;

  RETURN jsonb_build_object(
    'organization_id', v_inv.organization_id,
    'membership_id', v_member_id,
    'already_member', false
  );
END;
$$;


ALTER FUNCTION "public"."accept_pending_team_invitation"("p_invite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_team_invite"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.organization_members
  SET status = 'active'
  WHERE organization_id = p_org_id
    AND user_id = (SELECT auth.uid())
    AND status = 'invited';
END;
$$;


ALTER FUNCTION "public"."accept_team_invite"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acknowledge_global_alert"("p_alert_key" "text", "p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_members m
    WHERE m.organization_id = p_org_id
      AND m.user_id = (SELECT auth.uid())
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF p_alert_key IS NULL OR btrim(p_alert_key) = '' THEN
    RAISE EXCEPTION 'invalid alert key';
  END IF;

  INSERT INTO public.b2b_operations_dismissals (organization_id, alert_key, dismissed_at)
  VALUES (p_org_id, btrim(p_alert_key), now())
  ON CONFLICT (organization_id, alert_key) DO UPDATE
    SET dismissed_at = excluded.dismissed_at;
END;
$$;


ALTER FUNCTION "public"."acknowledge_global_alert"("p_alert_key" "text", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acknowledge_ledger_messages_for_transaction"("p_message_id" "uuid", "p_conversation_id" "uuid", "p_acknowledged_at" "text") RETURNS integer
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  WITH src AS (
    SELECT tm.conversation_id, tm.metadata ->> 'transaction_id' AS tx_id
    FROM public.trip_messages tm
    WHERE tm.id = p_message_id
      AND tm.conversation_id = p_conversation_id
  ),
  updated AS (
    UPDATE public.trip_messages tm
    SET metadata = COALESCE(tm.metadata, '{}'::jsonb)
      || jsonb_build_object('acknowledged_at', to_jsonb(p_acknowledged_at))
    FROM src
    WHERE src.tx_id IS NOT NULL
      AND tm.conversation_id = src.conversation_id
      AND tm.message_type = ANY (ARRAY['ledger_event'::text, 'ledger'::text, 'payment'::text])
      AND (tm.metadata ->> 'transaction_id') IS NOT DISTINCT FROM src.tx_id
    RETURNING tm.id
  )
  SELECT count(*)::integer FROM updated;
$$;


ALTER FUNCTION "public"."acknowledge_ledger_messages_for_transaction"("p_message_id" "uuid", "p_conversation_id" "uuid", "p_acknowledged_at" "text") OWNER TO "postgres";


