CREATE OR REPLACE FUNCTION "public"."add_driver_ledger_entry"("p_org_id" "uuid", "p_driver_id" "uuid", "p_type" "text", "p_amount" numeric, "p_description" "text" DEFAULT NULL::"text", "p_trip_id" "uuid" DEFAULT NULL::"uuid", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_reference_type" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_balance    numeric := 0;
  v_signed     numeric;
  v_entry_id   uuid;
BEGIN
  v_signed := CASE
    WHEN p_type IN ('advance','salary','reimbursement','settlement') THEN  p_amount
    WHEN p_type = 'deduction'                                        THEN -p_amount
    ELSE p_amount
  END;

  SELECT COALESCE(balance_after, 0) INTO v_balance
  FROM public.driver_ledger
  WHERE driver_id = p_driver_id
  ORDER BY created_at DESC LIMIT 1;

  INSERT INTO public.driver_ledger
    (organization_id, driver_id, trip_id, type, amount, balance_after,
     description, reference_type, reference_id, created_by)
  VALUES
    (p_org_id, p_driver_id, p_trip_id, p_type, p_amount, v_balance + v_signed,
     p_description, p_reference_type, p_reference_id, auth.uid())
  RETURNING id INTO v_entry_id;

  RETURN v_entry_id;
END;
$$;


ALTER FUNCTION "public"."add_driver_ledger_entry"("p_org_id" "uuid", "p_driver_id" "uuid", "p_type" "text", "p_amount" numeric, "p_description" "text", "p_trip_id" "uuid", "p_reference_id" "uuid", "p_reference_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_profile"("p_org_id" "uuid", "p_admin_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_status public.kyc_verification_status;
BEGIN
  SELECT verification_status INTO v_current_status
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF v_current_status != 'pending' THEN
    RAISE EXCEPTION 'Profile is not PENDING. Current status: %', v_current_status;
  END IF;

  UPDATE public.organizations
  SET
    verification_status = 'verified',
    verified_at         = now(),
    verified_by         = p_admin_id,
    updated_at          = now()
  WHERE id = p_org_id;

  INSERT INTO public.verification_audit_logs
    (org_id, changed_by, previous_status, new_status, notes)
  VALUES
    (p_org_id, p_admin_id, 'pending', 'verified', p_notes);

  RETURN jsonb_build_object('ok', true, 'org_id', p_org_id, 'verification_status', 'verified');
END;
$$;


ALTER FUNCTION "public"."admin_approve_profile"("p_org_id" "uuid", "p_admin_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_force_unlock_profile"("p_org_id" "uuid", "p_admin_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_status public.kyc_verification_status;
BEGIN
  IF p_reason IS NULL OR TRIM(p_reason) = '' THEN
    RAISE EXCEPTION 'A reason is required for force-unlock.';
  END IF;

  SELECT verification_status INTO v_current_status
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF v_current_status != 'verified' THEN
    RAISE EXCEPTION 'Force-unlock is only valid on VERIFIED profiles. Current: %', v_current_status;
  END IF;

  UPDATE public.organizations
  SET
    verification_status = 'unverified',
    frozen_at           = NULL,
    verified_at         = NULL,
    verified_by         = NULL,
    updated_at          = now()
  WHERE id = p_org_id;

  INSERT INTO public.verification_audit_logs
    (org_id, changed_by, previous_status, new_status, notes)
  VALUES
    (p_org_id, p_admin_id, 'verified', 'unverified',
     'force_unlock: ' || TRIM(p_reason));

  RETURN jsonb_build_object('ok', true, 'org_id', p_org_id, 'verification_status', 'unverified');
END;
$$;


ALTER FUNCTION "public"."admin_force_unlock_profile"("p_org_id" "uuid", "p_admin_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_profile"("p_org_id" "uuid", "p_admin_id" "uuid", "p_rejection_reasons" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_status public.kyc_verification_status;
BEGIN
  IF p_rejection_reasons IS NULL
     OR jsonb_array_length(p_rejection_reasons->'checklist') = 0
  THEN
    RAISE EXCEPTION 'At least one rejection reason is required.';
  END IF;

  SELECT verification_status INTO v_current_status
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF v_current_status != 'pending' THEN
    RAISE EXCEPTION 'Profile is not PENDING. Current status: %', v_current_status;
  END IF;

  UPDATE public.organizations
  SET
    verification_status  = 'rejected',
    frozen_at             = NULL,
    rejection_reasons     = p_rejection_reasons,
    kyc_rejected_reason   = p_rejection_reasons->>'notes',
    updated_at            = now()
  WHERE id = p_org_id;

  INSERT INTO public.verification_audit_logs
    (org_id, changed_by, previous_status, new_status, rejection_reasons, notes)
  VALUES
    (p_org_id, p_admin_id, 'pending', 'rejected', p_rejection_reasons, p_notes);

  RETURN jsonb_build_object('ok', true, 'org_id', p_org_id, 'verification_status', 'rejected');
END;
$$;


ALTER FUNCTION "public"."admin_reject_profile"("p_org_id" "uuid", "p_admin_id" "uuid", "p_rejection_reasons" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_invoice_number"("p_org_id" "uuid", "p_financial_yr" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fy   text;
  v_seq  bigint;
BEGIN
  -- Derive financial year from current date (India: Apr–Mar)
  IF p_financial_yr IS NULL THEN
    IF extract(month FROM now()) >= 4 THEN
      v_fy := extract(year FROM now())::text || '-' ||
              right((extract(year FROM now())::int + 1)::text, 2);
    ELSE
      v_fy := (extract(year FROM now())::int - 1)::text || '-' ||
              right(extract(year FROM now())::text, 2);
    END IF;
  ELSE
    v_fy := p_financial_yr;
  END IF;

  -- Atomic increment (INSERT … ON CONFLICT UPDATE)
  INSERT INTO public.invoice_sequences (org_id, financial_year, last_seq)
  VALUES (p_org_id, v_fy, 1)
  ON CONFLICT (org_id, financial_year)
  DO UPDATE SET last_seq = invoice_sequences.last_seq + 1
  RETURNING last_seq INTO v_seq;

  RETURN 'INV/' || v_fy || '/' || lpad(v_seq::text, 5, '0');
END;
$$;


ALTER FUNCTION "public"."allocate_invoice_number"("p_org_id" "uuid", "p_financial_yr" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_operational_sequence"("p_org_id" "uuid", "p_entity_type" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entity text := lower(trim(p_entity_type));
  v_current bigint;
  v_next bigint;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization is required';
  END IF;

  INSERT INTO public.operational_sequences (organization_id, entity_type, current_value)
  VALUES (p_org_id, v_entity, 0)
  ON CONFLICT (organization_id, entity_type) DO NOTHING;

  SELECT current_value
  INTO v_current
  FROM public.operational_sequences
  WHERE organization_id = p_org_id
    AND entity_type = v_entity
  FOR UPDATE;

  v_next := coalesce(v_current, 0) + 1;

  UPDATE public.operational_sequences
  SET current_value = v_next,
      updated_at = now()
  WHERE organization_id = p_org_id
    AND entity_type = v_entity;

  RETURN v_next;
END;
$$;


ALTER FUNCTION "public"."allocate_operational_sequence"("p_org_id" "uuid", "p_entity_type" "text") OWNER TO "postgres";

