CREATE TABLE IF NOT EXISTS "public"."trips" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "trip_number" "text" NOT NULL,
    "indent_id" "uuid",
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "pickup_area" "text" NOT NULL,
    "drop_location" "text" NOT NULL,
    "distance" numeric(10,2),
    "estimated_duration" interval,
    "client_id" "uuid",
    "client_name" "text" NOT NULL,
    "supplier_id" "uuid",
    "driver_id" "uuid",
    "vehicle_id" "uuid",
    "client_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "supplier_rate" numeric(12,2) DEFAULT 0 NOT NULL,
    "margin" numeric(12,2) GENERATED ALWAYS AS (("client_price" - "supplier_rate")) STORED,
    "platform_fee" numeric(12,2) DEFAULT 0 NOT NULL,
    "driver_commission" numeric(12,2) DEFAULT 0 NOT NULL,
    "is_guaranteed" boolean DEFAULT false NOT NULL,
    "payment_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "amount_paid" numeric(12,2) DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'assigned'::"text" NOT NULL,
    "pickup_date" "date",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "load_type" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "driver_display_name" "text",
    "vehicle_display_number" "text",
    "pickup_lat" numeric(12,7),
    "pickup_lon" numeric(12,7),
    "drop_lat" numeric(12,7),
    "drop_lon" numeric(12,7),
    "owner_user_id" "uuid",
    "created_by_user_id" "uuid",
    "assigned_by_user_id" "uuid",
    "load_tons" numeric(10,2),
    "advance_paid" numeric(12,2) DEFAULT 0 NOT NULL,
    "trip_payout_mode" "text",
    "deleted_at" timestamp with time zone,
    "display_trip_id" "text",
    "driver_display_trip_id" "text",
    "last_location_at" timestamp with time zone,
    "actual_distance_traveled_km" numeric(12,2),
    "last_location_chat_at" timestamp with time zone,
    "booking_ref" "text",
    "start_odometer_km" numeric(10,1),
    "end_odometer_km" numeric(10,1),
    "odometer_distance_km" numeric(10,1),
    "gps_distance_km" numeric(10,1),
    "distance_discrepancy_km" numeric(10,1),
    "distance_source" "text",
    "odometer_verification_state" "text" DEFAULT 'none'::"text" NOT NULL,
    "odometer_notes" "text",
    "odometer_updated_by" "uuid",
    "odometer_updated_at" timestamp with time zone,
    "trip_code" "text",
    "sequence_number" integer,
    "source_indent_id" "uuid",
    "source_indent_code" "text",
    "converted_from_indent_at" timestamp with time zone,
    "converted_by" "uuid",
    "trip_operational_code" "text",
    "indent_reference_code" "text",
    "status_change_origin" "text",
    "pod_received_at" timestamp with time zone,
    "pod_required" boolean DEFAULT true NOT NULL,
    "supplier_trip_sequence" integer,
    CONSTRAINT "trips_advance_paid_nonnegative" CHECK (("advance_paid" >= (0)::numeric)),
    CONSTRAINT "trips_check" CHECK (("amount_paid" <= "client_price")),
    CONSTRAINT "trips_check1" CHECK (((("status" = 'completed'::"text") AND ("completed_at" IS NOT NULL)) OR (("status" <> 'completed'::"text") AND ("completed_at" IS NULL)))),
    CONSTRAINT "trips_distance_source_check" CHECK ((("distance_source" = ANY (ARRAY['odometer'::"text", 'gps'::"text", 'hybrid'::"text", 'estimated'::"text"])) OR ("distance_source" IS NULL))),
    CONSTRAINT "trips_load_tons_nonnegative" CHECK ((("load_tons" IS NULL) OR ("load_tons" >= (0)::numeric))),
    CONSTRAINT "trips_odometer_verification_state_check" CHECK (("odometer_verification_state" = ANY (ARRAY['none'::"text", 'partial'::"text", 'driver_verified'::"text", 'business_verified'::"text", 'gps_verified'::"text"]))),
    CONSTRAINT "trips_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'partial'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "trips_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending_acceptance'::"text", 'assigned'::"text", 'in_progress'::"text", 'picked_up'::"text", 'in_transit'::"text", 'transit'::"text", 'at_pickup'::"text", 'loading'::"text", 'at_drop'::"text", 'unloading'::"text", 'completed'::"text", 'cancelled'::"text", 'delivered'::"text", 'done'::"text", 'active'::"text"]))),
    CONSTRAINT "trips_trip_payout_mode_check" CHECK ((("trip_payout_mode" IS NULL) OR ("trip_payout_mode" = ANY (ARRAY['market'::"text", 'asset'::"text"]))))
);


ALTER TABLE "public"."trips" OWNER TO "postgres";


COMMENT ON TABLE "public"."trips" IS 'Core trip execution table. margin auto-computed GENERATED ALWAYS. Soft-delete via deleted_at.';



COMMENT ON COLUMN "public"."trips"."margin" IS 'Auto-computed: client_price - supplier_rate. GENERATED ALWAYS STORED.';



COMMENT ON COLUMN "public"."trips"."driver_display_name" IS 'Cached driver name for display. Kept in sync by trigger.';



COMMENT ON COLUMN "public"."trips"."vehicle_display_number" IS 'Cached vehicle number for display. Synced from vehicles when vehicle_id set; can be set ad-hoc when vehicle_id is null.';



COMMENT ON COLUMN "public"."trips"."pickup_lat" IS 'Latitude of pickup place (from place search).';



COMMENT ON COLUMN "public"."trips"."pickup_lon" IS 'Longitude of pickup place (from place search).';



COMMENT ON COLUMN "public"."trips"."drop_lat" IS 'Latitude of drop place (from place search).';



COMMENT ON COLUMN "public"."trips"."drop_lon" IS 'Longitude of drop place (from place search).';



COMMENT ON COLUMN "public"."trips"."trip_payout_mode" IS 'Ledger payout lane: market = supplier settlement (aggregator); asset = own fleet (driver + vehicle). NULL = infer from supplier_id at read time.';



COMMENT ON COLUMN "public"."trips"."deleted_at" IS 'Soft-delete timestamp. NULL = active record.';



COMMENT ON COLUMN "public"."trips"."driver_display_trip_id" IS 'Per-driver sequential label (TRP###), same format as fleet trip_number but from driver_trip_counters.';



COMMENT ON COLUMN "public"."trips"."actual_distance_traveled_km" IS 'Best-known distance progress (km); maintained from odometer span on driver_locations when available.';



COMMENT ON COLUMN "public"."trips"."last_location_chat_at" IS 'Timestamp of the last location_ping system_log message written to trip_messages. Used to rate-limit the trigger so pings are consolidated (max 1 per 30 min).';



COMMENT ON COLUMN "public"."trips"."status_change_origin" IS 'Ephemeral marker (e.g. business_simulated) read by status→chat trigger; not shown in UI.';



COMMENT ON COLUMN "public"."trips"."pod_received_at" IS 'When POD was uploaded and confirmed. Null = POD not yet received.
   Used as a soft gate before invoicing: invoice generation warns if pod_received_at is null.';



COMMENT ON COLUMN "public"."trips"."pod_required" IS 'Whether this trip type requires POD before invoicing. Default true. Can be set false for
   advance-payment or contract trips where POD is waived.';



COMMENT ON CONSTRAINT "trips_status_check" ON "public"."trips" IS 'Trip lifecycle statuses; in_transit + picked_up unblock driver chat broadcasts. Legacy literals kept for existing rows.';



CREATE OR REPLACE FUNCTION "public"."apply_roster_deploy_from_direct_quote"("p_quote_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid") RETURNS SETOF "public"."trips"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quote public.direct_quotes%ROWTYPE;
  v_bidder uuid;
BEGIN
  SELECT * INTO v_quote FROM public.direct_quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Direct quote not found';
  END IF;

  IF (v_quote.status IS NULL OR lower(v_quote.status) <> 'accepted') THEN
    RAISE EXCEPTION 'Quote must be accepted before creating a trip';
  END IF;

  v_bidder := v_quote.bidder_organization_id;

  IF NOT public.is_org_member(v_bidder) THEN
    RAISE EXCEPTION 'Not authorized to deploy this quote';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.drivers d
    WHERE d.id = p_driver_id AND d.organization_id = v_bidder
  ) THEN
    RAISE EXCEPTION 'Driver must belong to your organization';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.vehicles v
    WHERE v.id = p_vehicle_id AND v.organization_id = v_bidder
  ) THEN
    RAISE EXCEPTION 'Vehicle must belong to your organization';
  END IF;

  UPDATE public.direct_quotes
  SET
    driver_id = p_driver_id,
    vehicle_id = p_vehicle_id,
    updated_at = now()
  WHERE id = p_quote_id;

  RETURN QUERY
  SELECT *
  FROM public.create_trip_from_direct_quote(p_quote_id, NULL::text);
END;
$$;


ALTER FUNCTION "public"."apply_roster_deploy_from_direct_quote"("p_quote_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_roster_deploy_from_direct_quote"("p_quote_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid") IS 'Staff Handshake (Asset): supplier sets roster driver/vehicle on accepted quote and creates trip atomically. Caller must be member of bidder_organization_id.';



CREATE OR REPLACE FUNCTION "public"."archive_chat_messages"("p_older_than" interval DEFAULT '1 year'::interval, "p_batch" integer DEFAULT 5000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_moved integer;
BEGIN
  WITH moved AS (
    DELETE FROM chat_messages m
    WHERE m.id IN (
      SELECT cm.id
      FROM chat_messages cm
      JOIN chat_conversations cc ON cc.id = cm.conversation_id
      WHERE cm.created_at < now() - p_older_than
        AND cc.conversation_type NOT IN ('direct', 'direct_org')
      ORDER BY cm.created_at
      LIMIT greatest(coalesce(p_batch, 5000), 1)
    )
    RETURNING m.*
  )
  INSERT INTO chat_messages_archive (
    id, conversation_id, organization_id, sender_user_id, sender_type,
    sender_name, sender_role, message_type, content, metadata, reply_to_id,
    client_message_id, edited_at, deleted_at, legacy_source, created_at
  )
  SELECT
    id, conversation_id, organization_id, sender_user_id, sender_type,
    sender_name, sender_role, message_type, content, metadata, reply_to_id,
    client_message_id, edited_at, deleted_at, legacy_source, created_at
  FROM moved;

  GET DIAGNOSTICS v_moved = ROW_COUNT;
  RETURN v_moved;
END;
$$;


ALTER FUNCTION "public"."archive_chat_messages"("p_older_than" interval, "p_batch" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."archive_chat_messages"("p_older_than" interval, "p_batch" integer) IS 'Moves non-DM messages older than p_older_than into chat_messages_archive. Skips direct and direct_org (persistent WhatsApp-style DMs).';



CREATE OR REPLACE FUNCTION "public"."assign_aggregate_trip_driver"("p_trip_id" "uuid", "p_driver_org_id" "uuid", "p_driver_phone" "text", "p_vehicle_display_number" "text" DEFAULT NULL::"text", "p_vehicle_id" "uuid" DEFAULT NULL::"uuid", "p_driver_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip       public.trips%ROWTYPE;
  v_driver     public.drivers%ROWTYPE;
  v_phone_norm text;
  v_last10     text;
  v_driver_name text;
  v_profile_id uuid;
  v_status     text;
  v_name_arg   text;
BEGIN
  v_name_arg := nullif(trim(coalesce(p_driver_name, '')), '');

  v_phone_norm := trim(regexp_replace(coalesce(p_driver_phone, ''), '\s+', '', 'g'));
  IF length(v_phone_norm) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Phone required (at least 10 digits)');
  END IF;
  v_last10 := regexp_replace(v_phone_norm, '\D', '', 'g');
  IF length(v_last10) >= 10 THEN
    v_last10 := right(v_last10, 10);
  ELSE
    v_last10 := v_phone_norm;
  END IF;

  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Trip not found');
  END IF;

  IF lower(trim(coalesce(v_trip.status::text, ''))) IN ('completed', 'delivered', 'done')
     OR v_trip.completed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Cannot change driver or vehicle after the trip is completed.'
    );
  END IF;

  -- Authorization: caller must be one of:
  --   1. A member of the trip-owner org (dispatcher editing their own trip)
  --   2. A member of the linked supplier org (integrated supplier)
  --   3. A member of the driver-assignment org (fleet owner assigning their driver/vehicle)
  --      This covers awarded/non-integrated fleet owners who won a bid but whose
  --      supplier record lacks linked_organization_id.
  IF NOT (
    public.is_org_member(v_trip.organization_id)
    OR EXISTS (
      SELECT 1 FROM public.suppliers s
      WHERE s.id = v_trip.supplier_id
        AND s.linked_organization_id IS NOT NULL
        AND public.is_org_member(s.linked_organization_id)
    )
    OR public.is_org_member(p_driver_org_id)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not authorized to assign this trip');
  END IF;

  IF p_vehicle_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.trips t
      WHERE t.vehicle_id = p_vehicle_id
        AND t.id <> p_trip_id
        AND lower(trim(coalesce(t.status::text, ''))) NOT IN (
          'completed', 'cancelled', 'done', 'delivered'
        )
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error',
        'Vehicle is already assigned to another active trip. Complete or unassign that trip first.'
      );
    END IF;
  END IF;

  SELECT * INTO v_driver
  FROM public.drivers
  WHERE organization_id = p_driver_org_id
    AND (
      phone = v_phone_norm
      OR right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) = v_last10
    )
  ORDER BY CASE WHEN phone = v_phone_norm THEN 0 ELSE 1 END
  LIMIT 1;

  IF NOT FOUND THEN
    SELECT id, full_name INTO v_profile_id, v_driver_name
    FROM public.profiles
    WHERE length(phone) >= 10
      AND right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) = v_last10
    LIMIT 1;
    -- Prefer the caller-supplied name over the profile lookup, then the placeholder.
    v_driver_name := coalesce(v_name_arg, nullif(trim(coalesce(v_driver_name, '')), ''), 'Driver');

    INSERT INTO public.drivers (organization_id, name, phone, user_id, status, tracking_only)
    VALUES (p_driver_org_id, v_driver_name, v_phone_norm, NULL, 'offline', true)
    RETURNING * INTO v_driver;
  ELSIF v_name_arg IS NOT NULL
        AND v_driver.tracking_only IS TRUE
        AND coalesce(trim(v_driver.name), '') IN ('', 'Driver', '—') THEN
    -- Upgrade a placeholder-named tracking-only row to the caller-supplied name.
    UPDATE public.drivers
    SET name = v_name_arg
    WHERE id = v_driver.id
    RETURNING * INTO v_driver;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.trips t
    WHERE t.driver_id = v_driver.id
      AND t.id <> p_trip_id
      AND lower(trim(coalesce(t.status::text, ''))) NOT IN ('completed', 'cancelled', 'done', 'delivered')
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error',
      'Driver is already assigned to another active trip. Complete or unassign that trip first.'
    );
  END IF;

  v_status := lower(trim(coalesce(v_trip.status::text, '')));

  UPDATE public.trips
  SET
    driver_id = v_driver.id,
    vehicle_id = CASE
      WHEN p_vehicle_id IS NOT NULL THEN p_vehicle_id
      ELSE vehicle_id
    END,
    vehicle_display_number = CASE
      WHEN p_vehicle_id IS NOT NULL THEN NULL
      WHEN p_vehicle_display_number IS NOT NULL AND trim(p_vehicle_display_number) <> '' THEN trim(p_vehicle_display_number)
      ELSE vehicle_display_number
    END,
    status = CASE
      WHEN v_trip.started_at IS NOT NULL THEN v_trip.status
      WHEN v_trip.completed_at IS NOT NULL THEN v_trip.status
      WHEN v_status IN (
        'in_transit', 'in_progress', 'intransit', 'transit', 'picked_up', 'pickup',
        'at_pickup', 'at_drop', 'loading', 'unloading', 'dispatched', 'on_route',
        'going_to_pickup', 'moving', 'started', 's_in', 's_out', 'd_in', 'd_out',
        'pod_pending', 'arrived', 'at_destination'
      ) THEN v_trip.status
      WHEN v_status IN ('pending', 'assigned', 'draft', 'confirmed') OR v_status = '' THEN 'assigned'
      ELSE v_trip.status
    END,
    updated_at = now()
  WHERE id = p_trip_id;

  PERFORM public.generate_trip_otp(p_trip_id, 15);

  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip_id;

  RETURN jsonb_build_object(
    'ok', true,
    'trip', to_jsonb(v_trip),
    'driver_id', v_driver.id
  );
END;
$$;


ALTER FUNCTION "public"."assign_aggregate_trip_driver"("p_trip_id" "uuid", "p_driver_org_id" "uuid", "p_driver_phone" "text", "p_vehicle_display_number" "text", "p_vehicle_id" "uuid", "p_driver_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_aggregate_trip_driver"("p_trip_id" "uuid", "p_driver_org_id" "uuid", "p_driver_phone" "text", "p_vehicle_display_number" "text", "p_vehicle_id" "uuid", "p_driver_name" "text") IS 'Assigns an aggregate/phone driver to a trip. p_driver_name (optional) sets the name on driver-row creation and upgrades a placeholder-named tracking-only row, replacing the legacy ''Driver'' fallback.';



CREATE OR REPLACE FUNCTION "public"."assign_driver_display_trip_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  seq bigint;
BEGIN
  IF NEW.driver_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.driver_id IS NOT NULL
       AND NEW.driver_id IS NOT NULL
       AND OLD.driver_id IS DISTINCT FROM NEW.driver_id
    THEN
      NEW.driver_display_trip_id := NULL;
    END IF;
  END IF;

  IF NEW.driver_display_trip_id IS NOT NULL AND btrim(NEW.driver_display_trip_id::text) <> '' THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.driver_trip_counters (driver_id)
  VALUES (NEW.driver_id)
  ON CONFLICT (driver_id) DO NOTHING;

  UPDATE public.driver_trip_counters
  SET trip_seq = trip_seq + 1
  WHERE driver_id = NEW.driver_id
  RETURNING trip_seq INTO seq;

  NEW.driver_display_trip_id := 'TRP' || lpad(seq::text, 3, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assign_driver_display_trip_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_org_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT NULLIF(
    trim(
      COALESCE(
        current_setting('request.jwt.claim.org_id', true),
        (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'org_id')
      )
    ),
    ''
  )::uuid;
$$;


ALTER FUNCTION "public"."auth_org_id"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auth_org_id"() IS 'Optional active organization id from JWT (org_id claim). When null, supplier view falls back to membership-based scoping.';



CREATE OR REPLACE FUNCTION "public"."award_indent_to_trip"("p_indent_id" "uuid", "p_supplier_rate" numeric DEFAULT NULL::numeric, "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_supplier_org_id" "uuid" DEFAULT NULL::"uuid", "p_driver_id" "uuid" DEFAULT NULL::"uuid", "p_vehicle_id" "uuid" DEFAULT NULL::"uuid", "p_vehicle_display_number" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."trips"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_indent        public.indents%ROWTYPE;
  v_org_id        uuid;
  v_trip          public.trips%ROWTYPE;
  v_supplier_id   uuid;
  v_supplier_rate numeric;
  v_vehicle_disp  text;
BEGIN
  SELECT * INTO v_indent FROM public.indents WHERE id = p_indent_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Indent % not found', p_indent_id;
  END IF;

  IF lower(coalesce(v_indent.status, '')) = 'cancelled' THEN
    RAISE EXCEPTION 'Cannot create trip: indent % is cancelled', p_indent_id;
  END IF;

  IF coalesce(trim(v_indent.pickup_area), '') = '' THEN
    RAISE EXCEPTION 'Cannot create trip: indent % has no pickup_area', p_indent_id;
  END IF;
  IF coalesce(trim(v_indent.drop_location), '') = '' THEN
    RAISE EXCEPTION 'Cannot create trip: indent % has no drop_location', p_indent_id;
  END IF;
  IF coalesce(v_indent.client_price, 0) <= 0 THEN
    RAISE EXCEPTION 'Cannot create trip: indent % has no client_price', p_indent_id;
  END IF;

  v_org_id := v_indent.organization_id;

  IF NOT public.is_org_member(v_org_id) THEN
    RAISE EXCEPTION 'Not authorized: caller is not a member of org %', v_org_id;
  END IF;

  SELECT t.* INTO v_trip
  FROM public.trips t
  WHERE t.indent_id = p_indent_id
  LIMIT 1;

  IF FOUND THEN
    IF lower(coalesce(v_trip.status, '')) NOT IN ('completed', 'cancelled') THEN
      UPDATE public.trips
      SET
        driver_id             = COALESCE(p_driver_id,  driver_id),
        vehicle_id            = COALESCE(p_vehicle_id, vehicle_id),
        vehicle_display_number = CASE
          WHEN p_vehicle_display_number IS NOT NULL AND trim(p_vehicle_display_number) <> ''
          THEN trim(p_vehicle_display_number)
          ELSE vehicle_display_number
        END,
        updated_at = now()
      WHERE id = v_trip.id;
      SELECT * INTO v_trip FROM public.trips WHERE id = v_trip.id;
    END IF;
    RETURN NEXT v_trip;
    RETURN;
  END IF;

  v_supplier_rate := COALESCE(
    p_supplier_rate,
    (v_indent.assigned_supplier_rate)::numeric,
    v_indent.supplier_target,
    0
  );

  -- supplier_id resolution:
  -- 1. Explicit param (direct suppliers row id)
  v_supplier_id := p_supplier_id;

  -- 2. indent.assigned_supplier_id is an organizations FK (bidder org id) — look up
  --    the suppliers row in this org that is linked to that bidder org.
  IF v_supplier_id IS NULL AND v_indent.assigned_supplier_id IS NOT NULL THEN
    SELECT id INTO v_supplier_id
    FROM public.suppliers
    WHERE organization_id = v_org_id
      AND linked_organization_id = v_indent.assigned_supplier_id
    LIMIT 1;
  END IF;

  -- 3. Explicit bidder org id (same lookup)
  IF v_supplier_id IS NULL AND p_supplier_org_id IS NOT NULL THEN
    SELECT id INTO v_supplier_id
    FROM public.suppliers
    WHERE organization_id = v_org_id
      AND linked_organization_id = p_supplier_org_id
    LIMIT 1;
  END IF;

  v_vehicle_disp := NULLIF(TRIM(COALESCE(p_vehicle_display_number, '')), '');

  INSERT INTO public.trips (
    organization_id,
    trip_number,
    indent_id,
    source,
    pickup_area,
    drop_location,
    client_name,
    client_price,
    supplier_rate,
    supplier_id,
    driver_id,
    vehicle_id,
    vehicle_display_number,
    status,
    pickup_date,
    load_type,
    platform_fee,
    driver_commission,
    payment_status,
    amount_paid
  ) VALUES (
    v_org_id,
    '',
    p_indent_id,
    'indent',
    coalesce(v_indent.pickup_area, ''),
    coalesce(v_indent.drop_location, ''),
    coalesce(v_indent.client_name, ''),
    coalesce(v_indent.client_price, 0),
    v_supplier_rate,
    v_supplier_id,
    p_driver_id,
    p_vehicle_id,
    v_vehicle_disp,
    CASE WHEN p_driver_id IS NOT NULL THEN 'assigned' ELSE 'draft' END,
    v_indent.pickup_date,
    coalesce(v_indent.load_type, ''),
    0,
    0,
    'pending',
    0
  )
  RETURNING * INTO v_trip;

  UPDATE public.indents
  SET status = 'completed', updated_at = now()
  WHERE id = p_indent_id;

  RETURN NEXT v_trip;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."award_indent_to_trip"("p_indent_id" "uuid", "p_supplier_rate" numeric, "p_supplier_id" "uuid", "p_supplier_org_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid", "p_vehicle_display_number" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_indent_to_trip"("p_indent_id" "uuid", "p_supplier_rate" numeric, "p_supplier_id" "uuid", "p_supplier_org_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid", "p_vehicle_display_number" "text") IS 'Convert a single awarded/open indent into a trips row (manual-assignment path — no direct quote).
   Idempotent: returns existing trip if already created, applying any new driver/vehicle.
   Resolution order: supplier_rate = p_supplier_rate → indent.assigned_supplier_rate → indent.supplier_target;
   supplier_id = p_supplier_id → lookup by indent.assigned_supplier_id (org FK via linked_organization_id)
     → lookup by p_supplier_org_id.
   Sets indent.status = completed after insert. Caller must be org member.';



CREATE OR REPLACE FUNCTION "public"."backfill_trip_room_operational_batch"("p_limit" integer DEFAULT 3000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row   record;
  v_done  integer := 0;
  v_limit integer := greatest(coalesce(p_limit, 3000), 1);
BEGIN
  FOR v_row IN
    SELECT tm.id
    FROM public.trip_messages tm
    JOIN public.trip_conversations tc ON tc.id = tm.conversation_id
    JOIN public.chat_conversations cc
      ON cc.trip_id = tc.trip_id AND cc.conversation_type = 'trip'
    WHERE tm.message_type IN (
      'status_change', 'system', 'system_log', 'update',
      'ledger_event', 'ledger', 'payment', 'ledger_update',
      'document_upload', 'document_share',
      'location_log', 'tracking', 'assignment_update'
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.chat_messages cm
      WHERE cm.conversation_id = cc.id
        AND cm.metadata->>'legacy_trip_message_id' = tm.id::text
    )
    ORDER BY tm.created_at
    LIMIT v_limit
  LOOP
    IF public.fn_mirror_legacy_trip_message_to_room(v_row.id) THEN
      v_done := v_done + 1;
    END IF;
  END LOOP;
  RETURN v_done;
END;
$$;


ALTER FUNCTION "public"."backfill_trip_room_operational_batch"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_trip_room_operational_batch"("p_limit" integer) IS 'Idempotent batch backfill of legacy operational trip_messages into unified trip rooms.';



CREATE OR REPLACE FUNCTION "public"."batch_award_indents_to_trips"("p_org_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inserted integer;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH to_convert AS (
    SELECT i.*
    FROM public.indents i
    LEFT JOIN public.trips t ON t.indent_id = i.id
    WHERE i.organization_id = p_org_id
      AND i.status = 'awarded'
      AND t.id IS NULL
  ),
  inserted AS (
    INSERT INTO public.trips (
      organization_id,
      owner_user_id,
      created_by_user_id,
      trip_number,
      indent_id,
      source,
      pickup_area,
      drop_location,
      pickup_lat,
      pickup_lon,
      drop_lat,
      drop_lon,
      distance,
      estimated_duration,
      client_name,
      client_id,
      client_price,
      supplier_rate,
      supplier_id,
      status,
      pickup_date,
      load_type,
      notes,
      platform_fee,
      driver_commission,
      payment_status,
      amount_paid
    )
    SELECT
      tc.organization_id,
      tc.owner_user_id,
      auth.uid(),
      '',
      tc.id,
      'batch_conversion',
      tc.pickup_area,
      tc.drop_location,
      tc.pickup_lat,
      tc.pickup_lon,
      tc.drop_lat,
      tc.drop_lon,
      tc.distance,
      tc.estimated_duration,
      tc.client_name,
      tc.client_id,
      tc.client_price,
      tc.supplier_target,
      tc.assigned_supplier_id,
      'assigned',
      tc.pickup_date,
      tc.load_type,
      tc.notes,
      0,
      0,
      'pending',
      0
    FROM to_convert tc
    RETURNING id
  )
  SELECT count(*) INTO v_inserted FROM inserted;

  UPDATE public.indents
  SET status = 'completed', updated_at = now()
  WHERE id IN (
    SELECT tc.id FROM public.indents tc
    LEFT JOIN public.trips t ON t.indent_id = tc.id
    WHERE tc.organization_id = p_org_id
      AND tc.status = 'awarded'
      AND t.id IS NOT NULL
  );

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."batch_award_indents_to_trips"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."batch_award_indents_to_trips"("p_org_id" "uuid") IS 'O(n) batch conversion: inserts one trip per awarded indent that has no trip yet.
   Uses a single set-based INSERT…SELECT so no per-row round-trips.
   Returns count of newly created trips. Caller must be org member.';



CREATE OR REPLACE FUNCTION "public"."can_access_trip_location"("p_trip_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id    uuid;
  v_client_id uuid;
  v_supplier_id uuid;
  v_uid       uuid;
BEGIN
  v_uid := (SELECT auth.uid());
  IF v_uid IS NULL THEN RETURN FALSE; END IF;

  SELECT organization_id, client_id, supplier_id
    INTO v_org_id, v_client_id, v_supplier_id
    FROM public.trips
   WHERE id = p_trip_id
   LIMIT 1;

  IF v_org_id IS NULL THEN RETURN FALSE; END IF;

  -- Fleet / owner org member
  IF public.is_org_member(v_org_id) THEN RETURN TRUE; END IF;

  -- Client org: the client entity on this trip links to the caller's org
  IF v_client_id IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.clients c
      JOIN public.organization_members om
        ON om.organization_id = c.linked_organization_id
       AND om.user_id = v_uid
       AND om.status = 'active'
     WHERE c.id = v_client_id
       AND c.linked_organization_id IS NOT NULL
  ) THEN RETURN TRUE; END IF;

  -- Supplier org: the supplier entity on this trip links to the caller's org
  IF v_supplier_id IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.suppliers s
      JOIN public.organization_members om
        ON om.organization_id = s.linked_organization_id
       AND om.user_id = v_uid
       AND om.status = 'active'
     WHERE s.id = v_supplier_id
       AND s.linked_organization_id IS NOT NULL
  ) THEN RETURN TRUE; END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_access_trip_location"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_access_trip_location"("p_trip_id" "uuid") IS 'Returns true if auth.uid() may read driver location data for the trip: fleet org member, client org member, or supplier org member. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."cancel_pending_sent_connections_to_partner_owner"("p_from_org_id" "uuid", "p_partner_owner_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ids uuid[];
BEGIN
  WITH deleted AS (
    DELETE FROM public.connection_requests cr
    USING public.organizations o
    WHERE cr.from_organization_id = p_from_org_id
      AND cr.status = 'pending'
      AND cr.to_organization_id = o.id
      AND o.owner_id = p_partner_owner_id
      AND EXISTS (
        SELECT 1
        FROM public.organization_members om
        WHERE om.organization_id = p_from_org_id
          AND om.user_id = auth.uid()
          AND om.status = 'active'
      )
    RETURNING cr.id
  )
  SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_ids FROM deleted;

  RETURN v_ids;
END;
$$;


ALTER FUNCTION "public"."cancel_pending_sent_connections_to_partner_owner"("p_from_org_id" "uuid", "p_partner_owner_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_pending_sent_connections_to_partner_owner"("p_from_org_id" "uuid", "p_partner_owner_id" "uuid") IS 'Deletes all pending sent connection_requests from p_from_org_id to orgs owned by p_partner_owner_id.';



CREATE OR REPLACE FUNCTION "public"."cancel_team_invite_pending"("p_invite_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.organization_team_invites ti
  SET status = 'cancelled', updated_at = now()
  WHERE ti.id = p_invite_id
    AND ti.status = 'pending'
    AND EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.organization_id = ti.organization_id
        AND om.user_id = (SELECT auth.uid())
        AND om.role IN ('owner', 'admin')
        AND om.status = 'active'
    );
END;
$$;


ALTER FUNCTION "public"."cancel_team_invite_pending"("p_invite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_trip_status_with_notification"("p_trip_id" "uuid", "p_organization_id" "uuid", "p_new_status" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_user_name" "text" DEFAULT 'Dispatcher'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prev_status TEXT;
  v_changed_at  TEXT;
BEGIN
  -- Verify org ownership and capture previous status
  SELECT status INTO v_prev_status
  FROM   public.trips
  WHERE  id = p_trip_id AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'trip_not_found: % / %', p_trip_id, p_organization_id;
  END IF;

  -- Update trip status
  UPDATE public.trips
  SET    status     = p_new_status,
         updated_at = NOW()
  WHERE  id = p_trip_id;

  v_changed_at := to_char(
    now() AT TIME ZONE 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );

  -- Insert one system message per conversation for this trip.
  -- These INSERT events propagate via Realtime → NEW_MESSAGE handler →
  -- SYSTEM_UPDATE branch in the store (metadata.new_status updates TripMeta).
  INSERT INTO public.trip_messages (
    conversation_id, organization_id,
    sender_user_id, sender_role, sender_name,
    content, message_type, metadata,
    is_read, is_delivered
  )
  SELECT
    tc.id,
    tc.organization_id,
    p_user_id,
    'system',
    'System',
    p_user_name || ' changed status: '
      || COALESCE(v_prev_status, '—') || ' → ' || p_new_status,
    'status_change',
    jsonb_build_object(
      'event_type',      'status_change',
      'previous_status', v_prev_status,
      'new_status',      p_new_status,
      'changed_by',      p_user_id,
      'changed_by_name', p_user_name,
      'changed_at',      v_changed_at
    ),
    TRUE,   -- is_read (system messages are auto-read)
    TRUE    -- is_delivered
  FROM public.trip_conversations tc
  WHERE tc.trip_id = p_trip_id;

  RETURN jsonb_build_object(
    'ok',              TRUE,
    'previous_status', v_prev_status,
    'new_status',      p_new_status,
    'changed_at',      v_changed_at
  );
END;
$$;


ALTER FUNCTION "public"."change_trip_status_with_notification"("p_trip_id" "uuid", "p_organization_id" "uuid", "p_new_status" "text", "p_user_id" "uuid", "p_user_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_email_registered_for_signup"("p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_email text := lower(trim(coalesce(p_email, '')));
  v_found text;
BEGIN
  IF v_email = '' OR position('@' in v_email) = 0 THEN
    RETURN jsonb_build_object('exists', false);
  END IF;

  SELECT lower(trim(u.email)) INTO v_found
  FROM auth.users u
  WHERE lower(trim(u.email)) = v_email
  LIMIT 1;

  IF v_found IS NULL THEN
    SELECT lower(trim(p.email)) INTO v_found
    FROM public.profiles p
    WHERE lower(trim(p.email)) = v_email
    LIMIT 1;
  END IF;

  IF v_found IS NULL THEN
    RETURN jsonb_build_object('exists', false);
  END IF;

  RETURN jsonb_build_object(
    'exists', true,
    'masked_email', regexp_replace(v_found, '(^.).*(@.*$)', '\1***\2')
  );
END;
$_$;


ALTER FUNCTION "public"."check_email_registered_for_signup"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_ocr_scan_quota"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_tier text;
  v_limit bigint;
  v_used bigint;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'used', 0,
      'limit', 0,
      'tier', 'forbidden',
      'reason', 'not_org_member'
    );
  END IF;

  SELECT tier, monthly_limit INTO v_tier, v_limit
  FROM public.resolve_ocr_scan_monthly_limit(p_org_id);

  SELECT count(*)::bigint INTO v_used
  FROM public.ocr_jobs j
  WHERE j.organization_id = p_org_id
    AND j.created_at >= date_trunc('month', now())
    AND NOT j.is_duplicate
    AND j.status IN ('pending', 'processing', 'completed');

  IF v_limit IS NULL THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'used', v_used,
      'limit', null,
      'tier', v_tier
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_used < v_limit,
    'used', v_used,
    'limit', v_limit,
    'tier', v_tier,
    'reason', CASE WHEN v_used >= v_limit THEN 'monthly_limit_reached' ELSE null END
  );
END;
$$;


