COMMENT ON FUNCTION "public"."check_ocr_scan_quota"("p_org_id" "uuid") IS 'Pulse Scan quota: pulse_core 50/mo, invoice_pro 500/mo, enterprise (metadata.ocr_unlimited) unlimited.';



CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_scope" "text", "p_max" integer, "p_window" interval DEFAULT '00:01:00'::interval) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.rpc_rate_limits
  WHERE user_id = p_user_id AND scope = p_scope AND created_at > now() - p_window;
  IF v_count >= p_max THEN RETURN false; END IF;
  INSERT INTO public.rpc_rate_limits (user_id, scope) VALUES (p_user_id, p_scope);
  RETURN true;
END;
$$;


