CREATE OR REPLACE FUNCTION "public"."check_trip_finance_adjustment_org_match"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.trips t
    WHERE t.id = NEW.trip_id
      AND t.organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'trip_finance_adjustments: trip_id must belong to organization_id';
  END IF;
  RETURN NEW;
END;
$$;


