CREATE OR REPLACE FUNCTION "public"."claim_pending_team_invites"("p_user_id" "uuid", "p_phone" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canon text;
  v_inv   public.organization_team_invites%ROWTYPE;
  v_count integer := 0;
BEGIN
  v_canon := public.normalize_phone_canon(p_phone);
  IF v_canon IS NULL OR length(v_canon) < 10 THEN
    RETURN 0;
  END IF;

  FOR v_inv IN
    SELECT *
    FROM public.organization_team_invites
    WHERE invitee_phone_canon = v_canon
      AND status = 'pending'
      AND expires_at > now()
    ORDER BY created_at ASC
  LOOP
    INSERT INTO public.organization_members (
      organization_id, user_id, role, status, permissions, joined_at
    ) VALUES (
      v_inv.organization_id,
      p_user_id,
      v_inv.role,
      'active',
      v_inv.permissions,
      now()
    )
    ON CONFLICT (organization_id, user_id) DO UPDATE
      SET
        role        = EXCLUDED.role,
        permissions = EXCLUDED.permissions,
        status      = 'active',
        joined_at   = now();

    UPDATE public.organization_team_invites
    SET
      status           = 'accepted',
      accepted_user_id = p_user_id,
      updated_at       = now()
    WHERE id = v_inv.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."claim_pending_team_invites"("p_user_id" "uuid", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_trip_by_otp"("p_code" "text", "p_max_attempts" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip_id uuid;
  v_org_id uuid;
  v_uid uuid;
  v_driver_id uuid;
  v_driver_name text;
  v_row trip_otps%ROWTYPE;
  v_updated int;
  v_preassigned_driver_id uuid;
  v_allowed_norm text;
  v_claimant_phone text;
  v_normalized_claimant text;
  v_existing_driver_id uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_row FROM public.trip_otps WHERE trip_otps.code = trim(coalesce(p_code, '')) LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invalid or expired OTP');
  END IF;

  IF v_row.used_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invalid or expired OTP');
  END IF;

  IF v_row.expires_at <= now() THEN
    UPDATE public.trip_otps SET failed_attempts = failed_attempts + 1 WHERE id = v_row.id;
    RETURN jsonb_build_object('ok', false, 'error', 'Invalid or expired OTP');
  END IF;

  IF v_row.failed_attempts >= greatest(1, p_max_attempts) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Too many attempts. Ask for a new OTP.');
  END IF;

  UPDATE public.trip_otps
  SET used_at = now()
  WHERE id = v_row.id
    AND used_at IS NULL
    AND expires_at > now()
    AND failed_attempts < greatest(1, p_max_attempts)
  RETURNING trip_id INTO v_trip_id;

  IF v_trip_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invalid or expired OTP');
  END IF;

  SELECT organization_id INTO v_org_id FROM public.trips WHERE id = v_trip_id;
  IF v_org_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Trip not found');
  END IF;

  SELECT t.driver_id, d.phone_normalised
  INTO v_preassigned_driver_id, v_allowed_norm
  FROM public.trips t
  LEFT JOIN public.drivers d ON d.id = t.driver_id
  WHERE t.id = v_trip_id;

  IF v_preassigned_driver_id IS NOT NULL
     AND v_allowed_norm IS NOT NULL
     AND length(v_allowed_norm) >= 10 THEN

    SELECT coalesce(
      nullif(trim(p.phone), ''),
      nullif(trim(u.phone::text), ''),
      nullif(trim(u.raw_user_meta_data->>'phone'), '')
    )
    INTO v_claimant_phone
    FROM auth.users u
    LEFT JOIN public.profiles p ON p.id = u.id
    WHERE u.id = v_uid;

    v_normalized_claimant := public.normalise_phone(v_claimant_phone);

    IF length(coalesce(v_normalized_claimant, '')) < 10 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Only the driver with the registered mobile number can claim this trip. Add your phone in profile or sign in with that number.'
      );
    END IF;

    IF v_normalized_claimant <> v_allowed_norm THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Only the driver with the registered mobile number can claim this trip.'
      );
    END IF;

    UPDATE public.drivers
    SET user_id = v_uid,
        status = 'offline',
        updated_at = now()
    WHERE id = v_preassigned_driver_id
      AND user_id IS NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'trip_id', v_trip_id,
      'organization_id', v_org_id,
      'driver_id', v_preassigned_driver_id
    );
  END IF;

  SELECT id INTO v_existing_driver_id
  FROM public.drivers
  WHERE organization_id = v_org_id AND user_id = v_uid
  LIMIT 1;

  IF v_existing_driver_id IS NOT NULL THEN
    v_driver_id := v_existing_driver_id;
  ELSE
    SELECT coalesce(
      nullif(trim(p.phone), ''),
      nullif(trim(u.phone::text), ''),
      nullif(trim(u.raw_user_meta_data->>'phone'), '')
    )
    INTO v_claimant_phone
    FROM auth.users u
    LEFT JOIN public.profiles p ON p.id = u.id
    WHERE u.id = v_uid;

    v_normalized_claimant := public.normalise_phone(v_claimant_phone);

    IF length(coalesce(v_normalized_claimant, '')) >= 10 THEN
      SELECT id INTO v_existing_driver_id
      FROM public.drivers
      WHERE organization_id = v_org_id
        AND phone_normalised = v_normalized_claimant
        AND left_at IS NULL
      LIMIT 1;
    END IF;

    IF v_existing_driver_id IS NOT NULL THEN
      UPDATE public.drivers
      SET user_id = v_uid,
          status = 'offline',
          updated_at = now()
      WHERE id = v_existing_driver_id
        AND user_id IS NULL;
      v_driver_id := v_existing_driver_id;
    END IF;
  END IF;

  IF v_driver_id IS NULL THEN
    SELECT trim(coalesce(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', ''))
    INTO v_driver_name FROM auth.users WHERE id = v_uid;
    IF coalesce(v_driver_name, '') = '' THEN
      v_driver_name := 'Driver';
    END IF;
    INSERT INTO public.drivers (organization_id, user_id, name, phone, status, tracking_only)
    VALUES (v_org_id, v_uid, v_driver_name, NULL, 'offline', true)
    RETURNING id INTO v_driver_id;
  END IF;

  UPDATE public.trips
  SET driver_id = v_driver_id, updated_at = now()
  WHERE id = v_trip_id AND driver_id IS NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Trip already claimed by another driver');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'trip_id', v_trip_id,
    'organization_id', v_org_id,
    'driver_id', v_driver_id
  );
END;
$$;


ALTER FUNCTION "public"."claim_trip_by_otp"("p_code" "text", "p_max_attempts" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_trip_by_otp"("p_code" "text", "p_max_attempts" integer) IS 'Claim aggregate trip by OTP. Pre-assigned: validates claimant phone vs driver phone using last-10-digit normalization (consistent with get_pending_otp_trips listing). No pre-assigned: find driver by org+user_id or org+claimant phone and reuse; else create tracking_only driver. Race-safe. Phone from profiles.phone preferred over raw_user_meta_data.';



