CREATE OR REPLACE FUNCTION "public"."compute_client_health_score"("p_org_id" "uuid", "p_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_revenue        numeric := 0;
  v_margin         numeric := 0;
  v_collected      numeric := 0;
  v_outstanding    numeric := 0;
  v_trips_total    int     := 0;
  v_trips_completed int    := 0;
  v_avg_delay      numeric := 0;
  v_distinct_months int    := 0;
  v_recent_revenue  numeric := 0;
  v_prior_revenue   numeric := 0;
  v_margin_pct     numeric := 0;
  v_profitability  numeric := 0;
  v_payment_score  numeric := 0;
  v_operations     numeric := 0;
  v_consistency    numeric := 0;
  v_growth         numeric := 0;
  v_score          int     := 0;
  v_level          text;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN jsonb_build_object('score', 0, 'level', 'unknown');
  END IF;

  SELECT
    COALESCE(SUM(t.client_price), 0),
    COALESCE(SUM(t.margin), 0),
    COUNT(*),
    COUNT(*) FILTER (WHERE t.status = 'completed'),
    COUNT(DISTINCT date_trunc('month', COALESCE(t.pickup_date, t.created_at)))
  INTO v_revenue, v_margin, v_trips_total, v_trips_completed, v_distinct_months
  FROM public.trips t
  WHERE t.client_id = p_client_id
    AND t.organization_id = p_org_id
    AND COALESCE(t.pickup_date, t.created_at) >= now() - INTERVAL '6 months';

  SELECT
    COALESCE(SUM(tx.amount_in), 0),
    AVG(NULLIF((COALESCE(tx.transaction_date, tx.created_at::date) - t.pickup_date), 0))
  INTO v_collected, v_avg_delay
  FROM public.transactions tx
  JOIN public.trips t ON t.id = tx.trip_id
  WHERE t.client_id = p_client_id
    AND tx.organization_id = p_org_id
    AND COALESCE(tx.amount_in, 0) > 0
    AND t.pickup_date IS NOT NULL
    AND COALESCE(t.pickup_date, t.created_at) >= now() - INTERVAL '6 months';

  v_outstanding := GREATEST(v_revenue - v_collected, 0);

  SELECT COALESCE(SUM(client_price), 0) INTO v_recent_revenue
  FROM public.trips
  WHERE client_id = p_client_id AND organization_id = p_org_id
    AND COALESCE(pickup_date, created_at) >= now() - INTERVAL '3 months';

  SELECT COALESCE(SUM(client_price), 0) INTO v_prior_revenue
  FROM public.trips
  WHERE client_id = p_client_id AND organization_id = p_org_id
    AND COALESCE(pickup_date, created_at) >= now() - INTERVAL '6 months'
    AND COALESCE(pickup_date, created_at) <  now() - INTERVAL '3 months';

  v_margin_pct := CASE WHEN v_revenue > 0 THEN (v_margin / v_revenue) * 100 ELSE 0 END;

  -- Sub-scores (each 0–100).
  v_profitability := LEAST(GREATEST(v_margin_pct * 4, 0), 100);  -- 25%+ margin = full marks

  v_payment_score := CASE
    WHEN v_revenue = 0          THEN 100
    WHEN v_avg_delay IS NULL    THEN 80
    WHEN v_avg_delay <= 7       THEN 100
    WHEN v_avg_delay <= 15      THEN 85
    WHEN v_avg_delay <= 30      THEN 70
    WHEN v_avg_delay <= 45      THEN 55
    WHEN v_avg_delay <= 60      THEN 40
    ELSE 25
  END;

  v_operations := CASE
    WHEN v_trips_total = 0 THEN 100
    ELSE (v_trips_completed::numeric / v_trips_total) * 100
  END;

  v_consistency := LEAST(v_distinct_months * (100.0 / 6.0), 100);

  v_growth := CASE
    WHEN v_prior_revenue = 0 AND v_recent_revenue > 0 THEN 100
    WHEN v_prior_revenue = 0                          THEN 50
    ELSE LEAST(GREATEST(((v_recent_revenue - v_prior_revenue) / v_prior_revenue) * 100 + 50, 0), 100)
  END;

  v_score := ROUND(
      v_profitability * 0.30
    + v_payment_score * 0.30
    + v_operations    * 0.20
    + v_consistency   * 0.10
    + v_growth        * 0.10
  );

  v_level := CASE
    WHEN v_score >= 90 THEN 'excellent'
    WHEN v_score >= 70 THEN 'good'
    WHEN v_score >= 50 THEN 'warning'
    ELSE                    'critical'
  END;

  RETURN jsonb_build_object(
    'score',                v_score,
    'level',                v_level,
    'profitabilityScore',   ROUND(v_profitability),
    'paymentScore',         ROUND(v_payment_score),
    'operationsScore',      ROUND(v_operations),
    'consistencyScore',     ROUND(v_consistency),
    'growthScore',          ROUND(v_growth),
    'breakdown', jsonb_build_object(
      'revenue6m',         v_revenue,
      'margin6m',          v_margin,
      'marginPct',         ROUND(v_margin_pct, 2),
      'collected6m',       v_collected,
      'outstanding6m',     v_outstanding,
      'avgPaymentDelay',   ROUND(COALESCE(v_avg_delay, 0)::numeric, 1),
      'tripsTotal',        v_trips_total,
      'tripsCompleted',    v_trips_completed,
      'distinctMonths',    v_distinct_months,
      'recentRevenue',     v_recent_revenue,
      'priorRevenue',      v_prior_revenue
    )
  );
END;
$$;


ALTER FUNCTION "public"."compute_client_health_score"("p_org_id" "uuid", "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_compliance_score"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_required          text[];
  v_total             int;
  v_active            int;
  v_expired           int;
  v_expiring_7d       int;
  v_expiring_30d      int;
  v_verified          int;
  v_pending           int;
  v_missing           int;
  v_validity          int;
  v_completeness      int;
  v_verification      int;
  v_score             int;
  v_level             text;
BEGIN
  v_required := CASE p_entity_type
    WHEN 'vehicle'      THEN ARRAY['rc','insurance','fitness','permit','pollution']
    WHEN 'driver'       THEN ARRAY['license','medical']
    WHEN 'supplier'     THEN ARRAY['gst','pan']
    WHEN 'organization' THEN ARRAY[]::text[]
    ELSE                       ARRAY[]::text[]
  END;

  SELECT
    COUNT(*)                                                                                   ,
    COUNT(*) FILTER (WHERE status IN ('active','verified'))                                    ,
    COUNT(*) FILTER (
      WHERE status = 'expired'
         OR (expiry_date IS NOT NULL AND expiry_date < CURRENT_DATE)
    )                                                                                          ,
    COUNT(*) FILTER (
      WHERE expiry_date IS NOT NULL
        AND expiry_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '7 days'
        AND status NOT IN ('replaced','rejected')
    )                                                                                          ,
    COUNT(*) FILTER (
      WHERE expiry_date IS NOT NULL
        AND expiry_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '30 days'
        AND status NOT IN ('replaced','rejected')
    )                                                                                          ,
    COUNT(*) FILTER (WHERE status = 'verified')                                                ,
    COUNT(*) FILTER (WHERE status = 'pending')
  INTO
    v_total, v_active, v_expired, v_expiring_7d, v_expiring_30d, v_verified, v_pending
  FROM public.entity_documents
  WHERE entity_type = p_entity_type
    AND entity_id   = p_entity_id
    AND status     <> 'replaced';

  v_missing := (
    SELECT COUNT(*)
    FROM unnest(v_required) AS r(doc)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.entity_documents ed
      WHERE ed.entity_type = p_entity_type
        AND ed.entity_id   = p_entity_id
        AND ed.doc_type    = r.doc
        AND ed.status     <> 'replaced'
    )
  );

  v_validity := CASE
    WHEN v_total > 0
      THEN ROUND(((v_total - v_expired)::numeric / v_total) * 100)
    WHEN cardinality(v_required) = 0 THEN 100
    ELSE 0
  END;

  v_completeness := CASE
    WHEN cardinality(v_required) > 0
      THEN ROUND(((cardinality(v_required) - v_missing)::numeric / cardinality(v_required)) * 100)
    ELSE 100
  END;

  v_verification := CASE
    WHEN v_total > 0 THEN ROUND((v_verified::numeric / v_total) * 100)
    ELSE 100
  END;

  v_score := ROUND(v_validity * 0.40 + v_completeness * 0.35 + v_verification * 0.25);

  v_level := CASE
    WHEN v_score >= 90 THEN 'excellent'
    WHEN v_score >= 70 THEN 'good'
    WHEN v_score >= 50 THEN 'warning'
    ELSE                    'critical'
  END;

  RETURN jsonb_build_object(
    'score',              v_score,
    'level',              v_level,
    'validityScore',      v_validity,
    'completenessScore',  v_completeness,
    'verificationScore',  v_verification,
    'breakdown', jsonb_build_object(
      'total',        v_total,
      'active',       v_active,
      'expired',      v_expired,
      'expiring7d',   v_expiring_7d,
      'expiring30d',  v_expiring_30d,
      'verified',     v_verified,
      'pending',      v_pending,
      'missing',      v_missing
    )
  );
END;
$$;


ALTER FUNCTION "public"."compute_compliance_score"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_driver_performance_score"("p_org_id" "uuid", "p_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trips_total     int     := 0;
  v_trips_completed int     := 0;
  v_on_time         int     := 0;
  v_on_time_eligible int    := 0;
  v_revenue         numeric := 0;
  v_earnings        numeric := 0;
  v_paid            numeric := 0;
  v_distinct_months int     := 0;
  v_avg_rating      numeric := 0;
  v_rating_count    int     := 0;
  v_completion_pct  numeric := 0;
  v_on_time_pct     numeric := 0;
  v_settlement      numeric := 0;
  v_productivity    numeric := 0;
  v_ratings_score   numeric := 0;
  v_score           int     := 0;
  v_level           text;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN jsonb_build_object('score', 0, 'level', 'unknown');
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'completed'),
    COUNT(*) FILTER (
      WHERE completed_at IS NOT NULL
        AND pickup_date IS NOT NULL
        AND completed_at::date <= pickup_date + INTERVAL '1 day'
    ),
    COUNT(*) FILTER (WHERE completed_at IS NOT NULL AND pickup_date IS NOT NULL),
    COALESCE(SUM(client_price), 0),
    COALESCE(SUM(
      CASE
        WHEN driver_commission IS NOT NULL AND driver_commission > 0 THEN driver_commission
        WHEN supplier_rate     IS NOT NULL AND supplier_rate > 0     THEN supplier_rate * 0.10
        ELSE COALESCE(client_price, 0) * 0.10
      END
    ), 0),
    COUNT(DISTINCT date_trunc('month', COALESCE(pickup_date, created_at)))
  INTO
    v_trips_total, v_trips_completed, v_on_time, v_on_time_eligible,
    v_revenue, v_earnings, v_distinct_months
  FROM public.trips
  WHERE driver_id = p_driver_id
    AND organization_id = p_org_id
    AND COALESCE(pickup_date, created_at) >= now() - INTERVAL '6 months';

  SELECT COALESCE(SUM(amount_out), 0)
  INTO v_paid
  FROM public.transactions
  WHERE contact_id = p_driver_id
    AND contact_type = 'driver'
    AND organization_id = p_org_id
    AND COALESCE(amount_out, 0) > 0
    AND COALESCE(transaction_date, created_at::date) >= (now() - INTERVAL '6 months')::date;

  -- Ratings — `driver_ratings` table may or may not exist depending on
  -- the org's history; guard via a soft try/catch.
  BEGIN
    SELECT COALESCE(AVG(rating), 0), COUNT(*)
    INTO   v_avg_rating, v_rating_count
    FROM   public.driver_ratings
    WHERE  driver_id = p_driver_id;
  EXCEPTION
    WHEN undefined_table THEN
      v_avg_rating := 0;
      v_rating_count := 0;
  END;

  v_completion_pct := CASE WHEN v_trips_total > 0 THEN (v_trips_completed::numeric / v_trips_total) * 100 ELSE 0 END;
  v_on_time_pct    := CASE WHEN v_on_time_eligible > 0 THEN (v_on_time::numeric / v_on_time_eligible) * 100 ELSE 0 END;
  v_settlement     := CASE WHEN v_earnings > 0 THEN LEAST((v_paid / v_earnings) * 100, 100) ELSE 100 END;
  v_productivity   := LEAST(
    CASE WHEN v_distinct_months > 0
      THEN (v_trips_total::numeric / v_distinct_months) * 5
      ELSE 0
    END,
    100
  );
  v_ratings_score  := CASE WHEN v_rating_count > 0 THEN LEAST(v_avg_rating * 20, 100) ELSE 70 END;

  v_score := ROUND(
      v_settlement      * 0.30
    + v_completion_pct  * 0.25
    + v_on_time_pct     * 0.20
    + v_productivity    * 0.15
    + v_ratings_score   * 0.10
  );

  v_level := CASE
    WHEN v_score >= 90 THEN 'excellent'
    WHEN v_score >= 70 THEN 'good'
    WHEN v_score >= 50 THEN 'warning'
    ELSE                    'critical'
  END;

  RETURN jsonb_build_object(
    'score',           v_score,
    'level',           v_level,
    'settlementScore', ROUND(v_settlement),
    'completionScore', ROUND(v_completion_pct),
    'onTimeScore',     ROUND(v_on_time_pct),
    'productivityScore', ROUND(v_productivity),
    'ratingsScore',    ROUND(v_ratings_score),
    'breakdown', jsonb_build_object(
      'tripsTotal',     v_trips_total,
      'tripsCompleted', v_trips_completed,
      'onTime',         v_on_time,
      'onTimeEligible', v_on_time_eligible,
      'revenue6m',      v_revenue,
      'earnings6m',     v_earnings,
      'paid6m',         v_paid,
      'distinctMonths', v_distinct_months,
      'avgRating',      ROUND(v_avg_rating, 2),
      'ratingCount',    v_rating_count
    )
  );
END;
$$;


ALTER FUNCTION "public"."compute_driver_performance_score"("p_org_id" "uuid", "p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_supplier_reliability_score"("p_org_id" "uuid", "p_supplier_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trips_total      int     := 0;
  v_trips_completed  int     := 0;
  v_trips_cancelled  int     := 0;
  v_on_time          int     := 0;
  v_on_time_eligible int     := 0;
  v_distinct_months  int     := 0;
  v_rate_stddev      numeric := 0;
  v_rate_avg         numeric := 0;
  v_completion_pct   numeric := 0;
  v_cancellation_pct numeric := 0;
  v_on_time_pct      numeric := 0;
  v_completion_score numeric := 0;
  v_on_time_score    numeric := 0;
  v_cancel_score     numeric := 0;
  v_availability     numeric := 0;
  v_pricing_score    numeric := 0;
  v_score            int     := 0;
  v_level            text;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN jsonb_build_object('score', 0, 'level', 'unknown');
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'completed'),
    COUNT(*) FILTER (WHERE status = 'cancelled'),
    COUNT(*) FILTER (
      WHERE completed_at IS NOT NULL
        AND pickup_date IS NOT NULL
        AND completed_at::date <= pickup_date + INTERVAL '1 day'
    ),
    COUNT(*) FILTER (WHERE completed_at IS NOT NULL AND pickup_date IS NOT NULL),
    COUNT(DISTINCT date_trunc('month', COALESCE(pickup_date, created_at))),
    COALESCE(stddev_pop(supplier_rate) FILTER (WHERE supplier_rate > 0), 0),
    COALESCE(avg(supplier_rate)        FILTER (WHERE supplier_rate > 0), 0)
  INTO
    v_trips_total, v_trips_completed, v_trips_cancelled,
    v_on_time, v_on_time_eligible, v_distinct_months,
    v_rate_stddev, v_rate_avg
  FROM public.trips
  WHERE supplier_id = p_supplier_id
    AND organization_id = p_org_id
    AND COALESCE(pickup_date, created_at) >= now() - INTERVAL '6 months';

  v_completion_pct   := CASE WHEN v_trips_total > 0 THEN (v_trips_completed::numeric / v_trips_total) * 100 ELSE 0 END;
  v_cancellation_pct := CASE WHEN v_trips_total > 0 THEN (v_trips_cancelled::numeric / v_trips_total) * 100 ELSE 0 END;
  v_on_time_pct      := CASE WHEN v_on_time_eligible > 0 THEN (v_on_time::numeric / v_on_time_eligible) * 100 ELSE 0 END;

  v_completion_score := v_completion_pct;
  v_on_time_score    := v_on_time_pct;
  v_cancel_score     := GREATEST(100 - v_cancellation_pct * 4, 0);  -- 0% = 100, 25% = 0
  v_availability     := LEAST(v_distinct_months * (100.0 / 6.0), 100);
  v_pricing_score    := CASE
    WHEN v_rate_avg = 0 THEN 100
    ELSE LEAST(GREATEST(100 - (v_rate_stddev / v_rate_avg) * 200, 0), 100)
  END;

  v_score := ROUND(
      v_completion_score * 0.30
    + v_on_time_score    * 0.25
    + v_cancel_score     * 0.20
    + v_availability     * 0.15
    + v_pricing_score    * 0.10
  );

  v_level := CASE
    WHEN v_score >= 90 THEN 'excellent'
    WHEN v_score >= 70 THEN 'good'
    WHEN v_score >= 50 THEN 'warning'
    ELSE                    'critical'
  END;

  RETURN jsonb_build_object(
    'score',              v_score,
    'level',              v_level,
    'completionScore',    ROUND(v_completion_score),
    'onTimeScore',        ROUND(v_on_time_score),
    'cancellationScore',  ROUND(v_cancel_score),
    'availabilityScore',  ROUND(v_availability),
    'pricingScore',       ROUND(v_pricing_score),
    'breakdown', jsonb_build_object(
      'tripsTotal',       v_trips_total,
      'tripsCompleted',   v_trips_completed,
      'tripsCancelled',   v_trips_cancelled,
      'onTime',           v_on_time,
      'onTimeEligible',   v_on_time_eligible,
      'completionPct',    ROUND(v_completion_pct, 2),
      'cancellationPct',  ROUND(v_cancellation_pct, 2),
      'onTimePct',        ROUND(v_on_time_pct, 2),
      'distinctMonths',   v_distinct_months,
      'rateStddev',       ROUND(v_rate_stddev, 2),
      'rateAvg',          ROUND(v_rate_avg, 2)
    )
  );
END;
$$;


ALTER FUNCTION "public"."compute_supplier_reliability_score"("p_org_id" "uuid", "p_supplier_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_vehicle_performance_score"("p_org_id" "uuid", "p_vehicle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trips_total       int     := 0;
  v_trips_completed   int     := 0;
  v_trips_cancelled   int     := 0;
  v_revenue           numeric := 0;
  v_expense           numeric := 0;
  v_distance          numeric := 0;
  v_distinct_months   int     := 0;
  v_trips_stddev      numeric := 0;
  v_trips_avg         numeric := 0;
  v_completion_pct    numeric := 0;
  v_margin_pct        numeric := 0;
  v_expense_ratio     numeric := 0;
  v_profitability     numeric := 0;
  v_utilization       numeric := 0;
  v_cost_efficiency   numeric := 0;
  v_consistency       numeric := 0;
  v_score             int     := 0;
  v_level             text;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN jsonb_build_object('score', 0, 'level', 'unknown');
  END IF;

  -- 1. Trip aggregate metrics restricted to vehicle + window.
  WITH _vehicle_trips AS (
    SELECT
      t.id,
      t.client_price,
      t.supplier_rate,
      t.status,
      t.distance,
      COALESCE(t.pickup_date, t.created_at) AS trip_date
    FROM public.trips t
    WHERE t.vehicle_id = p_vehicle_id
      AND t.organization_id = p_org_id
      AND COALESCE(t.pickup_date, t.created_at) >= now() - INTERVAL '6 months'
  ),
  _per_month AS (
    SELECT
      date_trunc('month', trip_date) AS m,
      COUNT(*)::int                  AS month_trips
    FROM _vehicle_trips
    GROUP BY 1
  )
  SELECT
    COALESCE((SELECT COUNT(*) FROM _vehicle_trips), 0),
    COALESCE((SELECT COUNT(*) FROM _vehicle_trips WHERE status = 'completed'), 0),
    COALESCE((SELECT COUNT(*) FROM _vehicle_trips WHERE status = 'cancelled'), 0),
    COALESCE((SELECT SUM(client_price) FROM _vehicle_trips), 0),
    COALESCE((SELECT SUM(distance) FROM _vehicle_trips), 0),
    COALESCE((SELECT COUNT(*) FROM _per_month), 0),
    COALESCE((SELECT stddev_pop(month_trips) FROM _per_month), 0),
    COALESCE((SELECT avg(month_trips) FROM _per_month), 0)
  INTO
    v_trips_total, v_trips_completed, v_trips_cancelled,
    v_revenue, v_distance, v_distinct_months,
    v_trips_stddev, v_trips_avg;

  -- 2. Expense (excluding driver compensation — matches monthly RPC).
  SELECT COALESCE(SUM(tx.amount_out), 0)
  INTO v_expense
  FROM public.transactions tx
  JOIN public.trips t ON t.id = tx.trip_id
  WHERE t.vehicle_id = p_vehicle_id
    AND t.organization_id = p_org_id
    AND tx.amount_out > 0
    AND (tx.contact_type IS DISTINCT FROM 'driver')
    AND COALESCE(t.pickup_date, t.created_at) >= now() - INTERVAL '6 months';

  -- 3. Sub-score computation.
  v_completion_pct := CASE WHEN v_trips_total > 0
    THEN (v_trips_completed::numeric / v_trips_total) * 100 ELSE 0 END;
  v_margin_pct := CASE WHEN v_revenue > 0
    THEN ((v_revenue - v_expense) / v_revenue) * 100 ELSE 0 END;
  v_expense_ratio := CASE WHEN v_revenue > 0
    THEN (v_expense / v_revenue) * 100 ELSE 0 END;

  -- Profitability: clamp margin% to 0..100 (negative margins floor to 0).
  v_profitability := LEAST(GREATEST(v_margin_pct, 0), 100);

  -- Utilization: months with trips / total months in window (max 6).
  v_utilization := LEAST(v_distinct_months * (100.0 / 6.0), 100);

  -- Cost efficiency: 100 - expense_ratio, clamped (so 50% expense ratio → 50).
  v_cost_efficiency := LEAST(GREATEST(100 - v_expense_ratio, 0), 100);

  -- Consistency: 100 - (CV × 100), clamped. Even cadence → high score.
  v_consistency := CASE
    WHEN v_trips_avg = 0 THEN 0
    ELSE LEAST(GREATEST(100 - (v_trips_stddev / v_trips_avg) * 100, 0), 100)
  END;

  v_score := ROUND(
      v_profitability   * 0.30
    + v_utilization     * 0.25
    + v_completion_pct  * 0.20
    + v_cost_efficiency * 0.15
    + v_consistency     * 0.10
  );

  v_level := CASE
    WHEN v_trips_total = 0 THEN 'unknown'
    WHEN v_score >= 90     THEN 'excellent'
    WHEN v_score >= 70     THEN 'good'
    WHEN v_score >= 50     THEN 'warning'
    ELSE                        'critical'
  END;

  RETURN jsonb_build_object(
    'score',              v_score,
    'level',              v_level,
    'profitabilityScore', ROUND(v_profitability),
    'utilizationScore',   ROUND(v_utilization),
    'completionScore',    ROUND(v_completion_pct),
    'costEfficiencyScore',ROUND(v_cost_efficiency),
    'consistencyScore',   ROUND(v_consistency),
    'breakdown', jsonb_build_object(
      'tripsTotal',       v_trips_total,
      'tripsCompleted',   v_trips_completed,
      'tripsCancelled',   v_trips_cancelled,
      'revenue',          ROUND(v_revenue, 2),
      'expense',          ROUND(v_expense, 2),
      'profit',           ROUND(v_revenue - v_expense, 2),
      'marginPct',        ROUND(v_margin_pct, 2),
      'expenseRatio',     ROUND(v_expense_ratio, 2),
      'distance',         ROUND(v_distance, 2),
      'distinctMonths',   v_distinct_months,
      'tripsPerMonthAvg', ROUND(v_trips_avg, 2),
      'tripsPerMonthCv',  CASE WHEN v_trips_avg > 0 THEN ROUND(v_trips_stddev / v_trips_avg, 3) ELSE 0 END
    )
  );
END;
$$;


ALTER FUNCTION "public"."compute_vehicle_performance_score"("p_org_id" "uuid", "p_vehicle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_to_accounting_books"("p_message_id" "uuid", "p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_msg record;
  v_trip_id uuid;
  v_conv_id uuid;
  v_meta jsonb;
  v_tx_str text;
  v_tx_id uuid;
  v_amount numeric(12, 2);
  v_is_receiver boolean;
  v_party_name text;
  v_desc text;
  v_new_book_id uuid;
  v_ack timestamptz := (CURRENT_TIMESTAMP AT TIME ZONE 'UTC');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'Forbidden: caller is not a member of this organization';
  END IF;

  SELECT
    tm.id,
    tm.conversation_id,
    tm.message_type,
    tm.metadata,
    tc.trip_id
  INTO v_msg
  FROM public.trip_messages tm
  INNER JOIN public.trip_conversations tc ON tc.id = tm.conversation_id
  WHERE tm.id = p_message_id
  FOR UPDATE OF tm;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Message not found';
  END IF;

  IF v_msg.message_type NOT IN ('ledger_event', 'ledger', 'payment', 'ledger_update') THEN
    RAISE EXCEPTION 'Invalid message type for accounting booking';
  END IF;

  v_conv_id := v_msg.conversation_id;
  v_trip_id := v_msg.trip_id;
  v_meta := coalesce(v_msg.metadata, '{}'::jsonb);

  IF NOT (
    btrim(coalesce(v_meta->>'receiver_org_id', '')) = p_org_id::text
    OR btrim(coalesce(v_meta->>'sender_org_id', '')) = p_org_id::text
  ) THEN
    RAISE EXCEPTION 'Privacy Violation: Org not involved in this ledger.';
  END IF;

  v_tx_str := btrim(coalesce(v_meta->>'transaction_id', ''));
  IF v_tx_str = '' THEN
    RAISE EXCEPTION 'Missing transaction_id in ledger metadata';
  END IF;

  BEGIN
    v_tx_id := v_tx_str::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Invalid transaction_id in ledger metadata';
  END;

  IF NOT EXISTS (SELECT 1 FROM public.transactions WHERE id = v_tx_id) THEN
    RAISE EXCEPTION 'Source transaction not found for chat mirror';
  END IF;

  v_amount := (v_meta->>'amount')::numeric;
  IF v_amount IS NULL OR v_amount <= 0 THEN
    RAISE EXCEPTION 'Invalid amount in ledger metadata';
  END IF;

  v_is_receiver := btrim(coalesce(v_meta->>'receiver_org_id', '')) = p_org_id::text;

  v_party_name := CASE
    WHEN v_is_receiver THEN nullif(btrim(coalesce(v_meta->>'sender_org_name', '')), '')
    ELSE nullif(btrim(coalesce(v_meta->>'receiver_org_name', '')), '')
  END;
  IF v_party_name IS NULL THEN
    v_party_name := 'Unknown';
  END IF;

  v_desc := concat_ws(
    ' | ',
    nullif(btrim(coalesce(v_meta->>'category', '')), ''),
    'Mode: ' || coalesce(nullif(btrim(coalesce(v_meta->>'payment_mode', '')), ''), 'Cash'),
    CASE
      WHEN nullif(btrim(coalesce(v_meta->>'reference_number', '')), '') IS NOT NULL
        THEN 'UTR: ' || btrim(v_meta->>'reference_number')
    END,
    CASE
      WHEN nullif(btrim(coalesce(v_meta->>'notes', '')), '') IS NOT NULL
        THEN 'Notes: ' || btrim(v_meta->>'notes')
    END,
    'Mirrored from: ' || CASE
      WHEN v_is_receiver THEN coalesce(nullif(btrim(v_meta->>'sender_org_name', ''), ''), 'Partner')
      ELSE coalesce(nullif(btrim(v_meta->>'receiver_org_name', ''), ''), 'Partner')
    END
  );

  INSERT INTO public.accounting_books (trip_id, amount, organization_id, reference_msg_id)
  VALUES (v_trip_id, v_amount, p_org_id, p_message_id)
  ON CONFLICT (reference_msg_id) DO NOTHING
  RETURNING id INTO v_new_book_id;

  IF v_new_book_id IS NULL THEN
    SELECT ab.id INTO v_new_book_id
    FROM public.accounting_books ab
    WHERE ab.reference_msg_id = p_message_id;
  END IF;

  INSERT INTO public.transactions (
    organization_id,
    trip_id,
    party_name,
    description,
    amount_in,
    amount_out,
    transaction_date,
    contact_type,
    contact_id,
    chat_mirror_of_transaction_id
  )
  VALUES (
    p_org_id,
    v_trip_id,
    v_party_name,
    coalesce(v_desc, ''),
    CASE WHEN v_is_receiver THEN v_amount ELSE 0 END,
    CASE WHEN v_is_receiver THEN 0 ELSE v_amount END,
    (v_ack AT TIME ZONE 'UTC')::date,
    NULL,
    NULL,
    v_tx_id
  )
  ON CONFLICT (organization_id, chat_mirror_of_transaction_id)
    WHERE chat_mirror_of_transaction_id IS NOT NULL
  DO NOTHING;

  UPDATE public.trip_messages tm
  SET metadata = jsonb_set(
    jsonb_set(coalesce(tm.metadata, '{}'::jsonb), '{is_booked}', 'true'::jsonb, true),
    '{acknowledged_at}',
    to_jsonb(v_ack),
    true
  )
  WHERE tm.conversation_id = v_conv_id
    AND tm.message_type IN ('ledger_event', 'ledger', 'payment', 'ledger_update')
    AND coalesce(tm.metadata->>'transaction_id', '') = v_tx_str;

  RETURN jsonb_build_object(
    'success', true,
    'book_id', v_new_book_id
  );
END;
$$;


ALTER FUNCTION "public"."confirm_to_accounting_books"("p_message_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_to_accounting_books"("p_message_id" "uuid", "p_org_id" "uuid") IS 'Atomically books a ledger chat message: accounting_books row, mirrored transactions row, and is_booked/acknowledged_at on all matching ledger messages in the conversation.';



CREATE OR REPLACE FUNCTION "public"."confirm_trip_feedback"("p_msg_id" "uuid", "p_rating" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_submitted text;
  v_n         int;
BEGIN
  p_rating := GREATEST(1, LEAST(5, p_rating));

  v_submitted := to_char(
    (now() AT TIME ZONE 'utc'),
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );

  UPDATE public.trip_messages
  SET    metadata =
           jsonb_set(
             COALESCE(metadata, '{}'::jsonb),
             '{rating}',
             to_jsonb(p_rating),
             true
           )
           || jsonb_build_object(
                'submitted_at',     to_jsonb(v_submitted),
                'submitted_score', to_jsonb(p_rating)
              )
  WHERE  id = p_msg_id
    AND  (metadata->>'submitted_at') IS NULL;

  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n = 1 THEN
    RETURN jsonb_build_object('ok', true, 'submitted_at', v_submitted);
  END IF;

  IF EXISTS (SELECT 1 FROM public.trip_messages WHERE id = p_msg_id) THEN
    RETURN jsonb_build_object('error', 'already_submitted');
  END IF;

  RETURN jsonb_build_object('error', 'message_not_found');
END;
$$;


ALTER FUNCTION "public"."confirm_trip_feedback"("p_msg_id" "uuid", "p_rating" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_trip_feedback"("p_msg_id" "uuid", "p_rating" integer) IS 'One-tap chat feedback: jsonb_set(metadata,{rating}) plus submitted_at/submitted_score; no ratings table insert.';



CREATE OR REPLACE FUNCTION "public"."consume_driver_invite"("p_invite_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite public.driver_invites%ROWTYPE;
  v_auth_phone text;
  v_auth_norm text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO v_invite
  FROM public.driver_invites
  WHERE id = p_invite_id
    AND status = 'pending'
    AND expires_at > now()
    AND driver_id IS NOT NULL
    AND to_user_id IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  SELECT coalesce(
    nullif(trim(p.phone), ''),
    nullif(trim(u.phone::text), ''),
    nullif(trim(u.raw_user_meta_data->>'phone'), '')
  )
  INTO v_auth_phone
  FROM auth.users u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = auth.uid();

  v_auth_norm := public.normalise_phone(v_auth_phone);
  IF length(coalesce(v_auth_norm, '')) < 10
     OR v_auth_norm <> v_invite.phone_normalised THEN
    RETURN false;
  END IF;

  UPDATE public.drivers
  SET user_id = auth.uid(),
      status = 'offline',
      updated_at = now()
  WHERE id = v_invite.driver_id
    AND user_id IS NULL;

  UPDATE public.driver_invites
  SET status = 'consumed',
      consumed_at = now(),
      to_user_id = auth.uid()
  WHERE id = p_invite_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."consume_driver_invite"("p_invite_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consume_driver_invite"("p_invite_id" "uuid") IS 'Driver app: after phone OTP auth, link roster driver row when invite token + phone match.';



CREATE TABLE IF NOT EXISTS "public"."organization_team_invites" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "invited_by" "uuid" NOT NULL,
    "invitee_name" "text" NOT NULL,
    "invitee_phone" "text" NOT NULL,
    "invitee_phone_canon" "text" NOT NULL,
    "invitee_email" "text",
    "role" "text" NOT NULL,
    "permissions" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "accepted_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '90 days'::interval) NOT NULL,
    CONSTRAINT "organization_team_invites_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."organization_team_invites" OWNER TO "postgres";


COMMENT ON TABLE "public"."organization_team_invites" IS 'Pre-account team invites by phone. Claimed on signup when phone matches.';



CREATE OR REPLACE FUNCTION "public"."create_team_invite_pending"("p_org_id" "uuid", "p_phone" "text", "p_name" "text", "p_email" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT 'member'::"text", "p_permissions" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."organization_team_invites"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canon text;
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_row   public.organization_team_invites;
  v_uid   uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = p_org_id
      AND om.user_id = v_uid
      AND om.role IN ('owner', 'admin')
      AND om.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Only active org admins can invite team members';
  END IF;

  v_canon := public.normalize_phone_canon(p_phone);
  IF v_canon IS NULL OR length(v_canon) < 10 THEN
    RAISE EXCEPTION 'Enter a valid 10-digit mobile number';
  END IF;

  IF trim(coalesce(p_name, '')) = '' THEN
    RAISE EXCEPTION 'Employee name is required';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE public.normalize_phone_canon(p.phone) = v_canon
  ) THEN
    RAISE EXCEPTION 'This phone already has a Pulse account — invite them as an existing user';
  END IF;

  IF v_email IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM auth.users u WHERE lower(trim(u.email)) = v_email)
       OR EXISTS (SELECT 1 FROM public.profiles p WHERE lower(trim(p.email)) = v_email) THEN
      RAISE EXCEPTION 'This email already has a Pulse account — use Invite existing user (sign-in path), not Awaiting Signup';
    END IF;
  END IF;

  INSERT INTO public.organization_team_invites (
    organization_id,
    invited_by,
    invitee_name,
    invitee_phone,
    invitee_phone_canon,
    invitee_email,
    role,
    permissions
  ) VALUES (
    p_org_id,
    v_uid,
    trim(p_name),
    trim(p_phone),
    v_canon,
    nullif(trim(coalesce(p_email, '')), ''),
    coalesce(nullif(trim(p_role), ''), 'member'),
    coalesce(p_permissions, '{}'::jsonb)
  )
  ON CONFLICT (organization_id, invitee_phone_canon)
    WHERE status = 'pending'
  DO UPDATE SET
    invitee_name  = EXCLUDED.invitee_name,
    invitee_email = EXCLUDED.invitee_email,
    role          = EXCLUDED.role,
    permissions   = EXCLUDED.permissions,
    invited_by    = EXCLUDED.invited_by,
    updated_at    = now(),
    expires_at    = now() + interval '90 days'
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."create_team_invite_pending"("p_org_id" "uuid", "p_phone" "text", "p_name" "text", "p_email" "text", "p_role" "text", "p_permissions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_trip_from_assigned_indent"("p_indent_id" "uuid", "p_driver_id" "uuid" DEFAULT NULL::"uuid", "p_vehicle_id" "uuid" DEFAULT NULL::"uuid", "p_vehicle_display_number" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."trips"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_indent             public.indents%ROWTYPE;
  v_org_id             uuid;
  v_supplier_org_id    uuid;
  v_supplier_id        uuid;
  v_trip               public.trips%ROWTYPE;
  v_vehicle_display    text;
  v_supplier_rate      numeric;
  v_actor_user_id      uuid := auth.uid();
  v_created_by_user_id uuid := NULL;
  v_bidder_org_name    text;
  v_try                integer := 0;
BEGIN
  v_vehicle_display := NULLIF(TRIM(COALESCE(p_vehicle_display_number, '')), '');

  IF v_actor_user_id IS NOT NULL THEN
    INSERT INTO public.users (id, name)
    VALUES (v_actor_user_id, 'User')
    ON CONFLICT (id) DO NOTHING;
  END IF;

  SELECT id INTO v_created_by_user_id
  FROM public.users
  WHERE id = v_actor_user_id
  LIMIT 1;

  SELECT * INTO v_indent FROM public.indents WHERE id = p_indent_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Indent % not found', p_indent_id;
  END IF;

  IF lower(coalesce(v_indent.status, '')) IN ('cancelled', 'closed') THEN
    RAISE EXCEPTION 'Cannot create trip: indent % is not available', p_indent_id;
  END IF;

  v_supplier_org_id := v_indent.assigned_supplier_id;
  IF v_supplier_org_id IS NULL THEN
    RAISE EXCEPTION 'Indent has no assigned supplier';
  END IF;

  IF NOT public.is_org_member(v_supplier_org_id) THEN
    RAISE EXCEPTION 'Not authorized to deploy this load';
  END IF;

  IF coalesce(trim(v_indent.pickup_area), '') = '' THEN
    RAISE EXCEPTION 'Cannot create trip: indent % has no pickup_area', p_indent_id;
  END IF;
  IF coalesce(trim(v_indent.drop_location), '') = '' THEN
    RAISE EXCEPTION 'Cannot create trip: indent % has no drop_location', p_indent_id;
  END IF;
  IF coalesce(v_indent.client_price, 0) <= 0 THEN
    RAISE EXCEPTION 'Cannot create trip: indent % has no client_price', p_indent_id;
  END IF;

  IF p_driver_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.drivers d
      WHERE d.id = p_driver_id AND d.organization_id = v_supplier_org_id
    ) THEN
      RAISE EXCEPTION 'Driver must belong to your organization';
    END IF;
  END IF;

  IF p_vehicle_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.vehicles v
      WHERE v.id = p_vehicle_id AND v.organization_id = v_supplier_org_id
    ) THEN
      RAISE EXCEPTION 'Vehicle must belong to your organization';
    END IF;
  END IF;

  v_org_id := v_indent.organization_id;

  SELECT t.* INTO v_trip
  FROM public.trips t
  WHERE t.indent_id = p_indent_id
  LIMIT 1;

  IF FOUND THEN
    IF lower(coalesce(v_trip.status, '')) NOT IN ('completed', 'cancelled') THEN
      UPDATE public.trips
      SET
        driver_id = COALESCE(p_driver_id, driver_id),
        vehicle_id = COALESCE(p_vehicle_id, vehicle_id),
        vehicle_display_number = CASE
          WHEN v_vehicle_display IS NOT NULL THEN v_vehicle_display
          ELSE vehicle_display_number
        END,
        updated_at = now()
      WHERE id = v_trip.id;
      SELECT * INTO v_trip FROM public.trips WHERE id = v_trip.id;
    END IF;
    UPDATE public.indents SET status = 'completed', updated_at = now() WHERE id = p_indent_id;
    RETURN NEXT v_trip;
    RETURN;
  END IF;

  v_supplier_rate := COALESCE(
    (v_indent.assigned_supplier_rate)::numeric,
    v_indent.supplier_target,
    0
  );

  SELECT id INTO v_supplier_id
  FROM public.suppliers
  WHERE organization_id = v_org_id
    AND linked_organization_id = v_supplier_org_id
  LIMIT 1;

  IF v_supplier_id IS NULL THEN
    SELECT COALESCE(NULLIF(TRIM(o.name), ''), 'Supplier')
    INTO v_bidder_org_name
    FROM public.organizations o
    WHERE o.id = v_supplier_org_id;

    INSERT INTO public.suppliers (
      organization_id,
      linked_organization_id,
      name,
      is_active,
      is_verified
    )
    VALUES (
      v_org_id,
      v_supplier_org_id,
      COALESCE(v_bidder_org_name, 'Supplier'),
      true,
      false
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_supplier_id;

    IF v_supplier_id IS NULL THEN
      SELECT id INTO v_supplier_id
      FROM public.suppliers
      WHERE organization_id = v_org_id
        AND linked_organization_id = v_supplier_org_id
      LIMIT 1;
    END IF;
  END IF;

  LOOP
    v_try := v_try + 1;
    BEGIN
      INSERT INTO public.trips (
        organization_id,
        owner_user_id,
        created_by_user_id,
        trip_number,
        indent_id,
        source,
        pickup_area,
        drop_location,
        client_name,
        client_price,
        supplier_rate,
        supplier_id,
        driver_id,
        vehicle_id,
        status,
        pickup_date,
        load_type,
        vehicle_display_number,
        platform_fee,
        driver_commission,
        payment_status,
        amount_paid
      ) VALUES (
        v_org_id,
        v_indent.owner_user_id,
        v_created_by_user_id,
        '',
        p_indent_id,
        'indent',
        coalesce(v_indent.pickup_area, ''),
        coalesce(v_indent.drop_location, ''),
        coalesce(v_indent.client_name, ''),
        coalesce(v_indent.client_price, 0),
        v_supplier_rate,
        v_supplier_id,
        p_driver_id,
        p_vehicle_id,
        CASE WHEN p_driver_id IS NOT NULL THEN 'assigned' ELSE 'draft' END,
        v_indent.pickup_date,
        coalesce(v_indent.load_type, ''),
        v_vehicle_display,
        0,
        0,
        'pending',
        0
      )
      RETURNING * INTO v_trip;

      UPDATE public.indents SET status = 'completed', updated_at = now() WHERE id = p_indent_id;
      RETURN NEXT v_trip;
      RETURN;
    EXCEPTION
      WHEN unique_violation THEN
        SELECT t.* INTO v_trip
        FROM public.trips t
        WHERE t.indent_id = p_indent_id
        LIMIT 1;
        IF FOUND THEN
          UPDATE public.indents SET status = 'completed', updated_at = now() WHERE id = p_indent_id;
          RETURN NEXT v_trip;
          RETURN;
        END IF;
        IF v_try >= 3 THEN
          RAISE;
        END IF;
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."create_trip_from_assigned_indent"("p_indent_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid", "p_vehicle_display_number" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_trip_from_assigned_indent"("p_indent_id" "uuid", "p_driver_id" "uuid", "p_vehicle_id" "uuid", "p_vehicle_display_number" "text") IS 'Supplier Claimed deploy: create trip from indent assigned to caller org (no direct_quotes row). Idempotent.';



CREATE OR REPLACE FUNCTION "public"."create_trip_from_direct_quote"("p_quote_id" "uuid") RETURNS SETOF "public"."trips"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quote public.direct_quotes%ROWTYPE;
  v_indent public.indents%ROWTYPE;
  v_supplier_id uuid;
  v_org_id uuid;
  v_trip public.trips%ROWTYPE;
  v_shipper_org_name text;
  v_bidder_org_name text;
BEGIN
  SELECT * INTO v_quote FROM public.direct_quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Direct quote not found';
  END IF;
  IF (v_quote.status IS NULL OR lower(v_quote.status) <> 'accepted') THEN
    RAISE EXCEPTION 'Quote must be accepted before creating a trip';
  END IF;

  SELECT * INTO v_indent FROM public.indents WHERE id = v_quote.indent_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Indent not found';
  END IF;

  v_org_id := v_indent.organization_id;

  -- Caller must be member of indent org (shipper) or bidder org (supplier)
  IF NOT (
    public.is_org_member(v_org_id) OR public.is_org_member(v_quote.bidder_organization_id)
  ) THEN
    RAISE EXCEPTION 'Not authorized to create trip from this quote';
  END IF;

  -- Idempotent: return existing trip for this indent if any
  SELECT t.* INTO v_trip
  FROM public.trips t
  WHERE t.indent_id = v_quote.indent_id
  LIMIT 1;
  IF FOUND THEN
    RETURN NEXT v_trip;
    RETURN;
  END IF;

  -- Resolve org names for supplier/client rows
  SELECT coalesce(nullif(trim(o.name), ''), 'Connected') INTO v_shipper_org_name
  FROM public.organizations o WHERE o.id = v_org_id;

  SELECT coalesce(nullif(trim(o.name), ''), 'Connected') INTO v_bidder_org_name
  FROM public.organizations o WHERE o.id = v_quote.bidder_organization_id;

  -- Ensure organization_relations row exists (shipper → supplier_client direction).
  -- Mirrors what on_connection_request_approved does for request_shipper_client.
  INSERT INTO public.organization_relations (from_organization_id, to_organization_id, relation_type, status)
  VALUES (v_quote.bidder_organization_id, v_org_id, 'supplier_client', 'active')
  ON CONFLICT (from_organization_id, to_organization_id, relation_type)
  DO UPDATE SET status = 'active', updated_at = now();

  -- Ensure the shipper has an integrated suppliers row for the bidder org.
  INSERT INTO public.suppliers (organization_id, name, linked_organization_id, supplier_type, updated_at)
  VALUES (v_org_id, v_bidder_org_name, v_quote.bidder_organization_id, 'integrated', now())
  ON CONFLICT (organization_id, linked_organization_id)
    WHERE linked_organization_id IS NOT NULL
  DO UPDATE SET
    supplier_type = 'integrated',
    linked_organization_id = v_quote.bidder_organization_id,
    updated_at = now();

  -- Resolve supplier_id: shipper's supplier row linked to bidder org (now guaranteed to exist)
  SELECT id INTO v_supplier_id
  FROM public.suppliers
  WHERE organization_id = v_org_id
    AND linked_organization_id = v_quote.bidder_organization_id
  LIMIT 1;

  INSERT INTO public.trips (
    organization_id,
    trip_number,
    indent_id,
    source,
    pickup_area,
    drop_location,
    client_name,
    client_price,
    supplier_rate,
    supplier_id,
    driver_id,
    vehicle_id,
    status,
    pickup_date,
    load_type
  ) VALUES (
    v_org_id,
    '',
    v_quote.indent_id,
    'direct_quote',
    coalesce(v_indent.pickup_area, ''),
    coalesce(v_indent.drop_location, ''),
    coalesce(v_indent.client_name, ''),
    coalesce(v_indent.client_price, 0),
    coalesce(v_quote.amount, 0),
    v_supplier_id,
    v_quote.driver_id,
    v_quote.vehicle_id,
    'assigned',
    v_indent.pickup_date,
    coalesce(v_indent.load_type, '')
  )
  RETURNING * INTO v_trip;

  RETURN NEXT v_trip;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."create_trip_from_direct_quote"("p_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_trip_from_direct_quote"("p_quote_id" "uuid") IS 'Create a trip from an accepted direct quote (Load Hub award). Atomically ensures organization_relations + integrated suppliers row exist before inserting the trip, so visibility is consistent from the moment of creation. Idempotent: returns existing trip if one exists for the indent.';



CREATE OR REPLACE FUNCTION "public"."create_trip_from_direct_quote"("p_quote_id" "uuid", "p_vehicle_display_number" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."trips"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_quote              public.direct_quotes%ROWTYPE;
  v_indent             public.indents%ROWTYPE;
  v_supplier_id        uuid;
  v_org_id             uuid;
  v_trip               public.trips%ROWTYPE;
  v_vehicle_display    text;
  v_try                integer := 0;
  v_actor_user_id      uuid := auth.uid();
  v_created_by_user_id uuid := NULL;
  v_bidder_org_name    text;
BEGIN
  v_vehicle_display := NULLIF(TRIM(COALESCE(p_vehicle_display_number, '')), '');

  IF v_actor_user_id IS NOT NULL THEN
    INSERT INTO public.users (id, name)
    VALUES (v_actor_user_id, 'User')
    ON CONFLICT (id) DO NOTHING;
  END IF;

  SELECT id INTO v_created_by_user_id
  FROM public.users
  WHERE id = v_actor_user_id
  LIMIT 1;

  -- Lock quote and indent rows to serialize concurrent calls for the same indent
  SELECT * INTO v_quote FROM public.direct_quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Direct quote not found';
  END IF;
  IF (v_quote.status IS NULL OR lower(v_quote.status) <> 'accepted') THEN
    RAISE EXCEPTION 'Quote must be accepted before creating a trip';
  END IF;

  SELECT * INTO v_indent FROM public.indents WHERE id = (v_quote).indent_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Indent not found';
  END IF;

  v_org_id := v_indent.organization_id;

  IF NOT (
    public.is_org_member(v_org_id) OR public.is_org_member((v_quote).bidder_organization_id)
  ) THEN
    RAISE EXCEPTION 'Not authorized to create trip from this quote';
  END IF;

  -- Idempotency: if trip already exists for this indent, update and return it
  SELECT t.* INTO v_trip
  FROM public.trips t
  WHERE t.indent_id = (v_quote).indent_id
  LIMIT 1;
  IF FOUND THEN
    UPDATE public.trips
    SET
      driver_id = COALESCE((v_quote).driver_id, driver_id),
      vehicle_id = COALESCE((v_quote).vehicle_id, vehicle_id),
      updated_at = now(),
      vehicle_display_number = CASE
        WHEN v_vehicle_display IS NOT NULL THEN v_vehicle_display
        ELSE vehicle_display_number
      END
    WHERE id = (v_trip).id;
    SELECT * INTO v_trip FROM public.trips WHERE id = (v_trip).id;
    UPDATE public.indents SET status = 'completed', updated_at = now() WHERE id = (v_quote).indent_id;
    RETURN NEXT v_trip;
    RETURN;
  END IF;

  -- Resolve or auto-create supplier row linked to bidder org
  SELECT id INTO v_supplier_id
  FROM public.suppliers
  WHERE organization_id = v_org_id
    AND linked_organization_id = (v_quote).bidder_organization_id
  LIMIT 1;

  IF v_supplier_id IS NULL THEN
    SELECT COALESCE(NULLIF(TRIM(o.name), ''), 'Supplier')
    INTO v_bidder_org_name
    FROM public.organizations o
    WHERE o.id = (v_quote).bidder_organization_id;

    INSERT INTO public.suppliers (
      organization_id, linked_organization_id, name, is_active, is_verified
    )
    VALUES (
      v_org_id, (v_quote).bidder_organization_id,
      COALESCE(v_bidder_org_name, 'Supplier'), true, false
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_supplier_id;

    IF v_supplier_id IS NULL THEN
      SELECT id INTO v_supplier_id
      FROM public.suppliers
      WHERE organization_id = v_org_id
        AND linked_organization_id = (v_quote).bidder_organization_id
      LIMIT 1;
    END IF;
  END IF;

  LOOP
    v_try := v_try + 1;
    BEGIN
      INSERT INTO public.trips (
        organization_id, owner_user_id, created_by_user_id,
        trip_number, indent_id, source,
        pickup_area, drop_location, client_name,
        client_price, supplier_rate, supplier_id,
        driver_id, vehicle_id, status,
        pickup_date, load_type, vehicle_display_number,
        platform_fee, driver_commission, payment_status, amount_paid
      ) VALUES (
        v_org_id, (v_indent).owner_user_id, v_created_by_user_id,
        '', (v_quote).indent_id, 'direct_quote',
        coalesce((v_indent).pickup_area, ''), coalesce((v_indent).drop_location, ''),
        coalesce((v_indent).client_name, ''),
        coalesce((v_indent).client_price, 0), coalesce((v_quote).amount, 0), v_supplier_id,
        (v_quote).driver_id, (v_quote).vehicle_id, 'assigned',
        (v_indent).pickup_date, coalesce((v_indent).load_type, ''),
        v_vehicle_display, 0, 0, 'pending', 0
      )
      RETURNING * INTO v_trip;

      UPDATE public.indents SET status = 'completed', updated_at = now() WHERE id = (v_quote).indent_id;
      RETURN NEXT v_trip;
      RETURN;

    EXCEPTION
      WHEN unique_violation THEN
        -- Two cases:
        --   (a) trips_one_per_indent fired: concurrent insert won; return that trip
        --   (b) trip_number collision: counter drifted; sync and retry
        SELECT t.* INTO v_trip
        FROM public.trips t
        WHERE t.indent_id = (v_quote).indent_id
        LIMIT 1;
        IF FOUND THEN
          UPDATE public.indents SET status = 'completed', updated_at = now() WHERE id = (v_quote).indent_id;
          RETURN NEXT v_trip;
          RETURN;
        END IF;

        -- Case (b): sync counter to actual max, then retry
        INSERT INTO public.organization_counters (organization_id, trip_seq)
        VALUES (v_org_id, 0)
        ON CONFLICT (organization_id) DO NOTHING;

        UPDATE public.organization_counters oc
        SET trip_seq = greatest(
          oc.trip_seq,
          coalesce((
            SELECT max(
              CASE
                WHEN t.trip_number ~ '[0-9]+$'
                THEN (regexp_match(t.trip_number, '([0-9]+)$'))[1]::bigint
                ELSE 0
              END
            )
            FROM public.trips t
            WHERE t.organization_id = v_org_id
          ), 0)
        )
        WHERE oc.organization_id = v_org_id;

        IF v_try >= 3 THEN
          RAISE EXCEPTION 'Could not create trip: repeated unique conflict after counter sync';
        END IF;
    END;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."create_trip_from_direct_quote"("p_quote_id" "uuid", "p_vehicle_display_number" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_trip_from_direct_quote"("p_quote_id" "uuid", "p_vehicle_display_number" "text") IS 'Create a trip from an accepted direct quote. Resolves supplier_id by linked_organization_id lookup;
   auto-creates a suppliers row for the bidder org if none exists so supplier_id is never NULL.';



CREATE OR REPLACE FUNCTION "public"."deactivate_posts_for_terminal_indent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF TG_OP <> 'UPDATE' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  v_status := lower(trim(coalesce(NEW.status::text, '')));
  IF NOT (
    v_status = ANY (
      ARRAY['awarded', 'completed', 'cancelled', 'closed', 'expired']::text[]
    )
  ) THEN
    RETURN NEW;
  END IF;

  UPDATE public.posts p
  SET
    is_active = false,
    updated_at = now()
  WHERE p.source_indent_id = NEW.id
    AND p.is_active = true;

  UPDATE public.bids b
  SET
    status = 'rejected',
    updated_at = now()
  WHERE b.status = 'pending'
    AND b.post_id IN (
      SELECT p.id FROM public.posts p WHERE p.source_indent_id = NEW.id
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."deactivate_posts_for_terminal_indent"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."deactivate_posts_for_terminal_indent"() IS 'On indent awarded/completed/cancelled/closed/expired: deactivate linked LOAD stories and reject pending bids.';



CREATE OR REPLACE FUNCTION "public"."discover_extract_city"("p_location" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT NULLIF(
    lower(trim(split_part(coalesce(p_location, ''), ',', 1))),
    ''
  );
$$;


ALTER FUNCTION "public"."discover_extract_city"("p_location" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_organizations"("p_org_id" "uuid", "p_search" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "avatar_seed" "text", "connection_status" "text", "address_line" "text", "city" "text", "state" "text", "profile_role" "text", "mutual_count" integer, "average_rating" numeric, "trip_count" integer, "lane_overlap_count" integer, "recommendation_score" integer, "is_in_user_trip_city" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Auth guard (cannot use RAISE in sql language; use a CTE check instead)
  -- Replicated via RLS + is_org_member — callers without membership get 0 rows.

  WITH
  -- ── 1. Caller's approved peer orgs ───────────────────────────────────────
  user_peers AS (
    SELECT
      CASE
        WHEN cr.from_organization_id = p_org_id THEN cr.to_organization_id
        ELSE cr.from_organization_id
      END AS peer_org_id
    FROM public.connection_requests cr
    WHERE cr.status = 'approved'
      AND (cr.from_organization_id = p_org_id OR cr.to_organization_id = p_org_id)
  ),

  -- ── 2. Cities the caller operates in (from indent pickup/drop) ───────────
  user_cities AS (
    SELECT DISTINCT public.discover_extract_city(loc) AS city
    FROM (
      SELECT pickup_area  AS loc FROM public.indents WHERE organization_id = p_org_id AND deleted_at IS NULL
      UNION ALL
      SELECT drop_location       FROM public.indents WHERE organization_id = p_org_id AND deleted_at IS NULL
    ) t
    WHERE public.discover_extract_city(loc) IS NOT NULL
  ),

  -- ── 3. Active LOAD post cities per org (single scan, not UNION of same table) ──
  post_lane_cities AS (
    SELECT
      p.organization_id                       AS org_id,
      public.discover_extract_city(p.origin)  AS city
    FROM public.posts p
    WHERE p.is_active = true AND p.type = 'LOAD' AND p.origin IS NOT NULL
    UNION
    SELECT
      p.organization_id,
      public.discover_extract_city(p.destination)
    FROM public.posts p
    WHERE p.is_active = true AND p.type = 'LOAD' AND p.destination IS NOT NULL
  ),

  candidate_post_cities AS (
    SELECT plc.org_id, array_agg(DISTINCT plc.city) AS cities
    FROM post_lane_cities plc
    WHERE plc.city IS NOT NULL
    GROUP BY plc.org_id
  ),

  -- ── 4. Base candidates (unchanged logic, realistic row estimate) ─────────
  base_candidates AS (
    SELECT
      o.id,
      o.name,
      o.avatar_seed,                            -- was always NULL::text — fixed
      NULLIF(trim(o.address_line), '') AS address_line,
      NULLIF(trim(o.city),         '') AS city,
      NULLIF(trim(o.state),        '') AS state,
      lower(coalesce(p.role, 'user'))  AS profile_role,
      COALESCE(cr.status, 'none')      AS connection_status
    FROM public.organizations o
    LEFT JOIN public.profiles p
           ON p.id = o.owner_id
    LEFT JOIN public.connection_requests cr
           ON (cr.from_organization_id = p_org_id AND cr.to_organization_id = o.id)
           OR (cr.to_organization_id   = p_org_id AND cr.from_organization_id = o.id)
    WHERE o.id        <> p_org_id
      AND o.deleted_at IS NULL
      AND coalesce(lower(p.role), 'user') <> 'driver'
      AND COALESCE(cr.status, 'none')     <> 'approved'
      AND (
        coalesce(trim(p_search), '') = ''
        OR o.name ILIKE '%' || trim(p_search) || '%'
      )
  ) /* ROWS 200 */,

  -- ── 5. Mutual count: pre-aggregated, one pass ────────────────────────────
  -- For each candidate org, count how many of the caller's peers are also
  -- connected to that org.
  peer_connections AS (
    SELECT
      CASE
        WHEN cr.from_organization_id IN (SELECT peer_org_id FROM user_peers) THEN cr.to_organization_id
        ELSE cr.from_organization_id
      END AS candidate_id,
      CASE
        WHEN cr.from_organization_id IN (SELECT peer_org_id FROM user_peers) THEN cr.from_organization_id
        ELSE cr.to_organization_id
      END AS the_peer_id
    FROM public.connection_requests cr
    WHERE cr.status = 'approved'
      AND (
        cr.from_organization_id IN (SELECT peer_org_id FROM user_peers)
        OR cr.to_organization_id IN (SELECT peer_org_id FROM user_peers)
      )
  ),
  mutual_counts AS (
    SELECT
      bc.id               AS org_id,
      count(DISTINCT pc.the_peer_id)::int AS mutual_count
    FROM base_candidates bc
    LEFT JOIN peer_connections pc ON pc.candidate_id = bc.id
    GROUP BY bc.id
  ),

  -- ── 6. Trip count: clients + suppliers linked to candidate, single JOIN ──
  linked_clients AS (
    SELECT c.organization_id AS viewer_org, c.linked_organization_id AS linked_org, c.id AS client_id
    FROM public.clients c
    WHERE c.organization_id = p_org_id
      AND c.deleted_at IS NULL
      AND c.linked_organization_id IN (SELECT id FROM base_candidates)
  ),
  linked_suppliers AS (
    SELECT s.organization_id AS viewer_org, s.linked_organization_id AS linked_org, s.id AS supplier_id
    FROM public.suppliers s
    WHERE s.organization_id = p_org_id
      AND s.deleted_at IS NULL
      AND s.linked_organization_id IN (SELECT id FROM base_candidates)
  ),
  trip_counts AS (
    SELECT org_id, sum(cnt)::int AS trip_count FROM (
      -- trips via client link
      SELECT lc.linked_org AS org_id, count(*)::int AS cnt
      FROM linked_clients lc
      JOIN public.trips t ON t.client_id = lc.client_id AND t.organization_id = p_org_id AND t.deleted_at IS NULL
      GROUP BY lc.linked_org

      UNION ALL

      -- trips via supplier link
      SELECT ls.linked_org AS org_id, count(*)::int AS cnt
      FROM linked_suppliers ls
      JOIN public.trips t ON t.supplier_id = ls.supplier_id AND t.organization_id = p_org_id AND t.deleted_at IS NULL
      GROUP BY ls.linked_org

      UNION ALL

      -- trips the candidate org ran themselves (carrier view)
      SELECT bc.id AS org_id, count(*)::int AS cnt
      FROM base_candidates bc
      JOIN public.trips t ON t.organization_id = bc.id AND t.deleted_at IS NULL
      GROUP BY bc.id
    ) sub
    GROUP BY org_id
  ),

  -- ── 7. Average rating: one scan of ratings ───────────────────────────────
  -- Linked entity ids per candidate (clients + suppliers)
  linked_entity_ids AS (
    SELECT lc.linked_org AS org_id, lc.client_id AS entity_id   FROM linked_clients  lc
    UNION ALL
    SELECT ls.linked_org AS org_id, ls.supplier_id AS entity_id FROM linked_suppliers ls
  ),
  avg_ratings AS (
    SELECT lei.org_id, round(avg(r.score)::numeric, 2)::numeric(3,2) AS average_rating
    FROM linked_entity_ids lei
    JOIN public.ratings r
      ON r.organization_id = p_org_id
     AND r.rated_id = lei.entity_id
    GROUP BY lei.org_id
  ),

  -- ── 8. Enrich: join all aggregations once ───────────────────────────────
  enriched AS (
    SELECT
      bc.*,
      coalesce(mc.mutual_count,    0) AS mutual_count,
      ar.average_rating,
      coalesce(tc.trip_count,      0) AS trip_count,
      (
        SELECT count(*)::int
        FROM unnest(coalesce(cpc.cities, ARRAY[]::text[])) AS cc(city)
        WHERE cc.city IN (SELECT uc.city FROM user_cities uc)
      ) AS lane_overlap_count,
      (public.discover_extract_city(bc.city) IN (SELECT uc.city FROM user_cities uc)) AS org_city_in_user_lanes
    FROM base_candidates bc
    LEFT JOIN mutual_counts      mc  ON mc.org_id  = bc.id
    LEFT JOIN trip_counts        tc  ON tc.org_id  = bc.id
    LEFT JOIN avg_ratings        ar  ON ar.org_id  = bc.id
    LEFT JOIN candidate_post_cities cpc ON cpc.org_id = bc.id
  ),

  -- ── 9. Score ─────────────────────────────────────────────────────────────
  scored AS (
    SELECT
      e.*,
      CASE
        WHEN e.mutual_count > 0 OR e.lane_overlap_count > 0 OR e.org_city_in_user_lanes THEN
          (CASE WHEN e.mutual_count    > 0                              THEN 2 ELSE 0 END)
          + (CASE WHEN e.lane_overlap_count >= 1 OR e.org_city_in_user_lanes THEN 2 ELSE 0 END)
          + (CASE WHEN e.lane_overlap_count >= 2                        THEN 1 ELSE 0 END)
        ELSE -1
      END AS recommendation_score,
      (e.lane_overlap_count >= 1 OR e.org_city_in_user_lanes) AS is_in_user_trip_city
    FROM enriched e
  )

  SELECT
    s.id,
    s.name,
    s.avatar_seed,                  -- fixed: was NULL::text
    s.connection_status,
    s.address_line,
    s.city,
    s.state,
    s.profile_role,
    s.mutual_count,
    s.average_rating,
    s.trip_count,
    s.lane_overlap_count,
    s.recommendation_score,
    s.is_in_user_trip_city
  FROM scored s
  ORDER BY
    s.recommendation_score DESC,
    CASE
      WHEN s.recommendation_score >= 4 THEN 0
      ELSE abs(hashtext(s.id::text || statement_timestamp()::text))
    END DESC,
    s.mutual_count      DESC,
    s.is_in_user_trip_city DESC,
    s.trip_count        DESC,
    s.average_rating    DESC NULLS LAST,
    s.name              ASC
  LIMIT  GREATEST(1, LEAST(coalesce(p_limit,  20), 100))
  OFFSET GREATEST(0,        coalesce(p_offset,  0));
$$;


ALTER FUNCTION "public"."discover_organizations"("p_org_id" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dismiss_driver_signup_match"("p_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_count integer := 0;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.drivers WHERE id = p_driver_id;
  IF v_org_id IS NULL OR NOT public.is_org_member(v_org_id) THEN
    RAISE EXCEPTION 'Not allowed';
  END IF;

  UPDATE public.driver_signup_matches
  SET state = 'ignored',
      acted_at = now(),
      acted_by = auth.uid(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('reason', 'owner_dismissed')
  WHERE driver_id = p_driver_id
    AND state = 'pending_owner_action';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'dismissed', v_count);
END;
$$;


ALTER FUNCTION "public"."dismiss_driver_signup_match"("p_driver_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dismiss_driver_signup_match"("p_driver_id" "uuid") IS 'Fleet user ignores pending signup match for a manual driver row.';



CREATE OR REPLACE FUNCTION "public"."dispatch_push_notifications"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lock_key CONSTANT bigint := hashtextextended('dispatch_push_notifications', 0);
BEGIN
  -- Transaction-scoped: auto-released at end of txn / on backend death.
  IF NOT pg_try_advisory_xact_lock(v_lock_key) THEN
    RETURN;
  END IF;

  SET LOCAL statement_timeout = '10s';

  PERFORM net.http_post(
    url := 'https://nafxpivddesgsrthmosv.supabase.co/functions/v1/send-push-notifications',
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key'),
      'Content-Type', 'application/json'
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 5000
  );
END;
$$;


ALTER FUNCTION "public"."dispatch_push_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_verification_workers"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lock_key CONSTANT bigint := hashtextextended('dispatch_verification_workers', 0);
  v_service_role_key text;
BEGIN
  IF NOT pg_try_advisory_xact_lock(v_lock_key) THEN
    -- Another invocation is already running; exit immediately, no overlap.
    RETURN;
  END IF;

  SET LOCAL statement_timeout = '10s';

  SELECT decrypted_secret INTO v_service_role_key
  FROM vault.decrypted_secrets
  WHERE name = 'service_role_key';

  PERFORM net.http_post(
    url := 'https://nafxpivddesgsrthmosv.supabase.co/functions/v1/verification-worker',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_role_key
    ),
    body := jsonb_build_object('job_id', j.id, 'organization_id', j.organization_id),
    timeout_milliseconds := 5000
  )
  FROM public.verification_jobs j
  WHERE j.status IN ('QUEUED', 'PARTIAL_REVIEW')
    AND j.attempts < 4
    AND j.next_attempt_at <= now()
  LIMIT 5;
END;
$$;


ALTER FUNCTION "public"."dispatch_verification_workers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."driver_has_assigned_trip_for_supplier"("p_supplier_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.trips t
    INNER JOIN public.drivers d ON d.id = t.driver_id AND d.user_id = auth.uid()
    WHERE t.supplier_id = p_supplier_id
  );
$$;


