CREATE OR REPLACE FUNCTION "public"."driver_has_other_active_trip"("p_driver_id" "uuid", "p_current_trip_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.trips t
    WHERE t.driver_id = p_driver_id
      AND (p_current_trip_id IS NULL OR t.id <> p_current_trip_id)
      AND lower(trim(coalesce(t.status::text, ''))) NOT IN ('completed', 'cancelled', 'done', 'delivered')
  );
$$;


ALTER FUNCTION "public"."driver_has_other_active_trip"("p_driver_id" "uuid", "p_current_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."driver_has_other_active_trip"("p_driver_id" "uuid", "p_current_trip_id" "uuid") IS 'True if driver has another non-terminal trip besides the provided trip id.';



CREATE OR REPLACE FUNCTION "public"."driver_phone_has_other_active_trip"("p_driver_id" "uuid", "p_current_trip_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.trips t
    JOIN public.drivers d ON d.id = t.driver_id
    WHERE (p_current_trip_id IS NULL OR t.id <> p_current_trip_id)
      AND lower(trim(coalesce(t.status::text, ''))) NOT IN ('completed', 'cancelled', 'done', 'delivered')
      AND right(regexp_replace(coalesce(d.phone, ''), '\D', '', 'g'), 10) <> ''
      AND right(regexp_replace(coalesce(d.phone, ''), '\D', '', 'g'), 10) = (
        SELECT right(regexp_replace(coalesce(d_self.phone, ''), '\D', '', 'g'), 10)
        FROM public.drivers d_self
        WHERE d_self.id = p_driver_id
      )
  );
$$;


ALTER FUNCTION "public"."driver_phone_has_other_active_trip"("p_driver_id" "uuid", "p_current_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."driver_phone_has_other_active_trip"("p_driver_id" "uuid", "p_current_trip_id" "uuid") IS 'True if any driver row with same last-10 phone has another non-terminal trip.';



CREATE OR REPLACE FUNCTION "public"."driver_reject_trip"("p_trip_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver_id_prev uuid;
  v_vehicle_id_prev uuid;
  v_vehicle_id_new uuid;
BEGIN
  SELECT t.driver_id, t.vehicle_id
  INTO v_driver_id_prev, v_vehicle_id_prev
  FROM public.trips t
  INNER JOIN public.drivers d ON d.id = t.driver_id AND d.user_id = auth.uid()
  WHERE t.id = p_trip_id;

  IF v_driver_id_prev IS NULL THEN
    RAISE EXCEPTION 'Trip not found or you are not the assigned driver';
  END IF;

  UPDATE public.trips
  SET driver_id = null, updated_at = now()
  WHERE id = p_trip_id;

  v_vehicle_id_new := v_vehicle_id_prev;

  BEGIN
    INSERT INTO public.trip_assignment_audit (
      trip_id,
      event_type,
      driver_id_prev,
      driver_id_new,
      vehicle_id_prev,
      vehicle_id_new,
      changed_by
    ) VALUES (
      p_trip_id,
      'reassignment',
      v_driver_id_prev,
      null,
      v_vehicle_id_prev,
      v_vehicle_id_new,
      auth.uid()
    );
  EXCEPTION
    WHEN undefined_table THEN
      NULL;
  END;
END;
$$;


ALTER FUNCTION "public"."driver_reject_trip"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."driver_reject_trip"("p_trip_id" "uuid") IS 'Driver unassigns themselves from a trip; records reassignment audit for dispatcher.';



CREATE OR REPLACE FUNCTION "public"."driver_update_trip_status"("p_trip_id" "uuid", "p_status" "text", "p_started_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_completed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Verify caller is the assigned driver for this trip
  IF NOT EXISTS (
    SELECT 1 FROM public.trips t
    JOIN public.drivers d ON d.id = t.driver_id
    WHERE t.id = p_trip_id
      AND d.user_id = (SELECT auth.uid())
      AND t.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'access_denied: not assigned driver for trip';
  END IF;

  UPDATE public.trips
  SET
    status       = p_status,
    started_at   = COALESCE(p_started_at, started_at),
    completed_at = COALESCE(p_completed_at, completed_at)
  WHERE id = p_trip_id;
END;
$$;


ALTER FUNCTION "public"."driver_update_trip_status"("p_trip_id" "uuid", "p_status" "text", "p_started_at" timestamp with time zone, "p_completed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_event"("p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_caused_by" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_id  uuid;
  v_version   bigint;
BEGIN
  -- Optimistic versioning: next version = count of existing events for this aggregate
  SELECT coalesce(max(version), 0) + 1
  INTO v_version
  FROM public.event_store
  WHERE aggregate_id = p_aggregate_id;

  INSERT INTO public.event_store
    (event_type, aggregate_type, aggregate_id, org_id, user_id,
     payload, metadata, version, caused_by, correlation_id)
  VALUES
    (p_event_type, p_aggregate_type, p_aggregate_id, p_org_id, p_user_id,
     p_payload, p_metadata, v_version, p_caused_by, p_correlation_id)
  RETURNING id INTO v_event_id;

  -- Queue for outbox delivery (Kafka-first; webhook secondary)
  INSERT INTO public.event_outbox (event_id, destination, topic, payload)
  VALUES
    (v_event_id, 'kafka',
     'pulse.events.' || p_aggregate_type,
     jsonb_build_object(
       'id',             v_event_id,
       'type',           p_event_type,
       'aggregate_type', p_aggregate_type,
       'aggregate_id',   p_aggregate_id,
       'version',        v_version,
       'payload',        p_payload,
       'emitted_at',     now(),
       'correlation_id', p_correlation_id
     )
    );

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."emit_event"("p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_org_id" "uuid", "p_user_id" "uuid", "p_caused_by" "uuid", "p_correlation_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_indent_draft_broadcast_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'broadcast' AND NEW.shared_at IS NULL THEN
      NEW.shared_at := now();
    END IF;
    IF NEW.status = 'draft' AND NEW.last_saved_at IS NULL THEN
      NEW.last_saved_at := now();
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'broadcast' AND NEW.status = 'draft' THEN
    RAISE EXCEPTION 'Broadcast indents cannot be reverted to draft'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.status = 'broadcast' AND (
    NEW.pickup_area IS DISTINCT FROM OLD.pickup_area OR
    NEW.drop_location IS DISTINCT FROM OLD.drop_location OR
    NEW.client_name IS DISTINCT FROM OLD.client_name OR
    NEW.client_price IS DISTINCT FROM OLD.client_price OR
    NEW.supplier_target IS DISTINCT FROM OLD.supplier_target OR
    NEW.vehicle_type IS DISTINCT FROM OLD.vehicle_type OR
    NEW.load_type IS DISTINCT FROM OLD.load_type OR
    NEW.pickup_date IS DISTINCT FROM OLD.pickup_date OR
    NEW.circulation_target IS DISTINCT FROM OLD.circulation_target
  ) THEN
    RAISE EXCEPTION 'This indent has been shared and cannot be edited'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.status <> 'broadcast' AND NEW.status = 'broadcast' AND NEW.shared_at IS NULL THEN
    NEW.shared_at := now();
  END IF;

  IF NEW.status = 'draft' THEN
    NEW.last_saved_at := now();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_indent_draft_broadcast_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_rpc_rate_limit"("p_scope" "text", "p_max_requests" integer, "p_window" interval) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_count integer;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF coalesce(p_scope, '') = '' THEN
    RAISE EXCEPTION 'Rate limit scope required';
  END IF;

  IF coalesce(p_max_requests, 0) <= 0 THEN
    RAISE EXCEPTION 'Invalid rate limit max requests';
  END IF;

  IF p_window IS NULL OR p_window <= interval '0 seconds' THEN
    RAISE EXCEPTION 'Invalid rate limit window';
  END IF;

  SELECT count(*)::integer
    INTO v_count
  FROM public.rpc_rate_limits
  WHERE scope = p_scope
    AND user_id = v_uid
    AND created_at > now() - p_window;

  IF v_count >= p_max_requests THEN
    RAISE EXCEPTION 'Rate limit exceeded';
  END IF;

  INSERT INTO public.rpc_rate_limits (user_id, scope)
  VALUES (v_uid, p_scope);
END;
$$;


ALTER FUNCTION "public"."enforce_rpc_rate_limit"("p_scope" "text", "p_max_requests" integer, "p_window" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_single_active_trip_per_driver"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  v_old_status text;
BEGIN
  IF NEW.driver_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_status := lower(trim(coalesce(NEW.status::text, '')));
  IF v_status IN ('completed', 'cancelled', 'done', 'delivered') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_old_status := lower(trim(coalesce(OLD.status::text, '')));

    -- No-op assignment/activity change.
    IF NEW.driver_id IS NOT DISTINCT FROM OLD.driver_id
       AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
      RETURN NEW;
    END IF;

    -- Critical: keep first active trip moving even if legacy overlap exists.
    -- When this row already had same driver + active status, allow progression updates.
    IF NEW.driver_id IS NOT DISTINCT FROM OLD.driver_id
       AND v_old_status NOT IN ('completed', 'cancelled', 'done', 'delivered') THEN
      RETURN NEW;
    END IF;
  END IF;

  IF public.driver_has_other_active_trip(NEW.driver_id, NEW.id)
     OR public.driver_phone_has_other_active_trip(NEW.driver_id, NEW.id) THEN
    RAISE EXCEPTION 'Driver is already assigned to another active trip. Complete or unassign that trip first.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_single_active_trip_per_driver"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_single_active_trip_per_driver"() IS 'Blocks new overlapping active assignments per driver/phone, while allowing status progression for an already-active assignment.';



CREATE OR REPLACE FUNCTION "public"."enforce_verification_freeze"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only block if the row is currently frozen (pending or verified)
  IF OLD.verification_status IN ('pending', 'verified') THEN
    -- Allow admin procedures running as service_role to bypass
    IF current_setting('role', true) = 'service_role' THEN
      RETURN NEW;
    END IF;

    -- Block changes to KYC identity fields from authenticated client
    IF (NEW.business_pan   IS DISTINCT FROM OLD.business_pan   OR
        NEW.gstin          IS DISTINCT FROM OLD.gstin          OR
        NEW.cin            IS DISTINCT FROM OLD.cin            OR
        NEW.registration_type IS DISTINCT FROM OLD.registration_type OR
        NEW.address_proof_path IS DISTINCT FROM OLD.address_proof_path) THEN
      RAISE EXCEPTION
        'PROFILE_FROZEN: Verification fields are locked while status is %. Contact support.',
        OLD.verification_status;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_verification_freeze"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_driver_signup_matches"("p_user_id" "uuid", "p_phone" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last10 text;
  v_affected integer := 0;
BEGIN
  v_last10 := public.normalize_phone_last10(p_phone);
  IF length(v_last10) < 10 THEN
    RETURN 0;
  END IF;

  INSERT INTO public.driver_signup_matches (
    organization_id, driver_id, matched_user_id, phone_canonical, state, source
  )
  SELECT
    d.organization_id,
    d.id,
    p_user_id,
    v_last10,
    'pending_owner_action',
    'signup_phone_match'
  FROM public.drivers d
  WHERE d.user_id IS NULL
    AND d.left_at IS NULL
    AND d.phone IS NOT NULL
    AND public.normalize_phone_last10(d.phone) = v_last10
  ON CONFLICT (driver_id, matched_user_id) DO UPDATE SET
    phone_canonical = EXCLUDED.phone_canonical,
    state = CASE
      WHEN public.driver_signup_matches.state IN ('ignored', 'declined', 'expired')
      THEN 'pending_owner_action'
      ELSE public.driver_signup_matches.state
    END,
    detected_at = CASE
      WHEN public.driver_signup_matches.state IN ('ignored', 'declined', 'expired')
      THEN now()
      ELSE public.driver_signup_matches.detected_at
    END,
    metadata = public.driver_signup_matches.metadata
      || jsonb_build_object('reactivated_from_profile_trigger', now())
  WHERE public.driver_signup_matches.state IN ('ignored', 'declined', 'expired');

  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected;
END;
$$;


ALTER FUNCTION "public"."enqueue_driver_signup_matches"("p_user_id" "uuid", "p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_driver_signup_matches"("p_user_id" "uuid", "p_phone" "text") IS 'Create or re-open pending signup matches for manual driver rows vs signed-up driver phone (last 10 digits). Idempotent.';



