    "message_count" integer DEFAULT 0 NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "legacy_trip_conversation_id" "uuid",
    "legacy_network_conversation_id" "uuid",
