    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chat_conversations_conversation_type_check" CHECK (("conversation_type" = ANY (ARRAY['direct'::"text", 'direct_org'::"text", 'trip'::"text", 'trip_lane'::"text", 'customer'::"text", 'supplier'::"text", 'channel'::"text", 'system'::"text"])))
);


