COMMENT ON TABLE "public"."chat_conversations" IS 'Pulse Chat Platform unified conversation registry. Types: direct (user↔user), direct_org (legacy network), trip (unified room, Phase 2), trip_lane (legacy 1:1 lane bridge), customer, supplier, channel (group), system (auto feed).';



CREATE OR REPLACE FUNCTION "public"."ensure_chat_channel"("p_organization_id" "uuid", "p_channel_key" "text", "p_title" "text" DEFAULT NULL::"text") RETURNS "public"."chat_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key text := lower(trim(p_channel_key));
  v_row public.chat_conversations%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key IS NULL OR v_key = '' OR v_key LIKE 'dm:%' THEN
    RAISE EXCEPTION 'Invalid channel key';
  END IF;
  IF NOT public.fn_chat_is_org_member(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized for organization' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row
  FROM chat_conversations
  WHERE organization_id = p_organization_id AND channel_key = v_key;
  IF FOUND THEN RETURN v_row; END IF;

  INSERT INTO chat_conversations (organization_id, conversation_type, channel_key, title, created_by)
  VALUES (p_organization_id, 'channel', v_key, coalesce(p_title, initcap(replace(v_key, '_', ' '))), auth.uid())
  ON CONFLICT (organization_id, channel_key) WHERE channel_key IS NOT NULL
  DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row
    FROM chat_conversations
    WHERE organization_id = p_organization_id AND channel_key = v_key;
  END IF;

  INSERT INTO chat_participants (conversation_id, user_id, participant_role)
  VALUES (v_row.id, auth.uid(), 'admin')
  ON CONFLICT DO NOTHING;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."ensure_chat_channel"("p_organization_id" "uuid", "p_channel_key" "text", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_direct_chat"("p_organization_id" "uuid", "p_peer_user_id" "uuid") RETURNS "public"."chat_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_self uuid := auth.uid();
  v_key  text;
  v_row  public.chat_conversations%ROWTYPE;
BEGIN
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_peer_user_id = v_self THEN
    RAISE EXCEPTION 'Cannot open a DM with yourself';
  END IF;
  IF NOT public.fn_chat_is_org_member(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized for organization' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM organization_members om
    WHERE om.organization_id = p_organization_id AND om.user_id = p_peer_user_id
  ) THEN
    RAISE EXCEPTION 'Peer is not a member of this organization';
  END IF;

  v_key := 'dm:' || least(v_self, p_peer_user_id)::text
        || ':' || greatest(v_self, p_peer_user_id)::text;

  SELECT * INTO v_row
  FROM chat_conversations
  WHERE organization_id = p_organization_id AND channel_key = v_key;
  IF FOUND THEN RETURN v_row; END IF;

  INSERT INTO chat_conversations (organization_id, conversation_type, channel_key, created_by)
  VALUES (p_organization_id, 'direct', v_key, v_self)
  ON CONFLICT (organization_id, channel_key) WHERE channel_key IS NOT NULL
  DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row
    FROM chat_conversations
    WHERE organization_id = p_organization_id AND channel_key = v_key;
  END IF;

  INSERT INTO chat_participants (conversation_id, user_id)
  VALUES (v_row.id, v_self), (v_row.id, p_peer_user_id)
  ON CONFLICT DO NOTHING;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."ensure_direct_chat"("p_organization_id" "uuid", "p_peer_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_driver_signup_matches_for_driver"("p_driver_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver public.drivers;
  v_last10 text;
  v_inserted integer := 0;
  v_org_id uuid;
BEGIN
  SELECT * INTO v_driver FROM public.drivers WHERE id = p_driver_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  v_org_id := v_driver.organization_id;
  IF NOT public.is_org_member(v_org_id) THEN
    RETURN 0;
  END IF;

  IF v_driver.user_id IS NOT NULL OR v_driver.left_at IS NOT NULL THEN
    RETURN 0;
  END IF;
  IF coalesce(trim(v_driver.phone), '') = '' THEN
    RETURN 0;
  END IF;

  v_last10 := public.normalize_phone_last10(v_driver.phone);
  IF length(v_last10) < 10 THEN
    RETURN 0;
  END IF;

  INSERT INTO public.driver_signup_matches (
    organization_id, driver_id, matched_user_id, phone_canonical, state, source
  )
  SELECT
    v_driver.organization_id,
    v_driver.id,
    p.id,
    v_last10,
    'pending_owner_action',
    'signup_phone_match'
  FROM public.profiles p
  WHERE p.role = 'driver'
    AND coalesce(trim(p.phone), '') <> ''
    AND public.normalize_phone_last10(p.phone) = v_last10
  ON CONFLICT (driver_id, matched_user_id) DO UPDATE SET
    phone_canonical = EXCLUDED.phone_canonical,
    state = CASE
      WHEN public.driver_signup_matches.state IN ('ignored', 'declined', 'expired')
      THEN 'pending_owner_action'
      ELSE public.driver_signup_matches.state
    END,
    detected_at = CASE
      WHEN public.driver_signup_matches.state IN ('ignored', 'declined', 'expired')
      THEN now()
      ELSE public.driver_signup_matches.detected_at
    END,
    metadata = public.driver_signup_matches.metadata
      || jsonb_build_object('reactivated_at', now())
  WHERE public.driver_signup_matches.state IN ('ignored', 'declined', 'expired');

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."ensure_driver_signup_matches_for_driver"("p_driver_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_driver_signup_matches_for_driver"("p_driver_id" "uuid") IS 'Idempotent: create pending signup matches for unlinked driver row vs all driver profiles with same phone (last 10). Org members only (checked).';



CREATE TABLE IF NOT EXISTS "public"."trip_conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "trip_id" "uuid" NOT NULL,
    "party_type" "text" NOT NULL,
    "party_name" "text" NOT NULL,
    "client_id" "uuid",
    "supplier_id" "uuid",
    "driver_id" "uuid",
    "last_message_at" timestamp with time zone,
    "last_message_preview" "text",
    "unread_dispatcher_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "party_ref_consistent" CHECK (((("party_type" = 'client'::"text") AND ("client_id" IS NOT NULL) AND ("supplier_id" IS NULL) AND ("driver_id" IS NULL)) OR (("party_type" = 'supplier'::"text") AND ("supplier_id" IS NOT NULL) AND ("client_id" IS NULL) AND ("driver_id" IS NULL)) OR (("party_type" = 'driver'::"text") AND ("driver_id" IS NOT NULL) AND ("client_id" IS NULL) AND ("supplier_id" IS NULL)))),
    CONSTRAINT "trip_conversations_party_type_check" CHECK (("party_type" = ANY (ARRAY['client'::"text", 'supplier'::"text", 'driver'::"text"])))
);


