COMMENT ON TABLE "public"."trip_conversations" IS 'One commercial/operational lane per (trip_id, party_type). Sub-contract work must use a new trip_id so Party A is not a participant in Party B↔C threads; trip_messages RLS ties reads to org + conversation.';



CREATE OR REPLACE FUNCTION "public"."ensure_driver_trip_conversation"("p_trip_id" "uuid", "p_driver_id" "uuid", "p_party_name" "text") RETURNS "public"."trip_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip public.trips%ROWTYPE;
  v_row  public.trip_conversations%ROWTYPE;
  v_name text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Trip not found';
  END IF;

  IF v_trip.driver_id IS NULL OR v_trip.driver_id <> p_driver_id THEN
    RAISE EXCEPTION 'Driver does not match this trip';
  END IF;

  -- Authorized: fleet member | linked supplier for trip | assigned driver (driver app)
  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_members om
    WHERE om.user_id = auth.uid()
      AND om.organization_id = v_trip.organization_id
      AND om.status = 'active'
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.trips t
    INNER JOIN public.suppliers s ON s.id = t.supplier_id
    INNER JOIN public.organization_members om
      ON om.organization_id = s.linked_organization_id
     AND om.user_id = auth.uid()
     AND om.status = 'active'
    WHERE t.id = p_trip_id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.trips t
    INNER JOIN public.indents i ON i.id = t.indent_id
    INNER JOIN public.organization_members om
      ON om.organization_id = i.assigned_supplier_id
     AND om.user_id = auth.uid()
     AND om.status = 'active'
    WHERE t.id = p_trip_id
      AND t.supplier_id IS NULL
      AND t.indent_id IS NOT NULL
      AND i.assigned_supplier_id IS NOT NULL
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.drivers d
    WHERE d.user_id = auth.uid()
      AND d.id = p_driver_id
      AND EXISTS (
        SELECT 1 FROM public.trips t2
        WHERE t2.id = p_trip_id AND t2.driver_id = d.id AND t2.organization_id = v_trip.organization_id
      )
  ) THEN
    RAISE EXCEPTION 'Not authorized to manage trip chat for this trip' USING ERRCODE = '42501';
  END IF;

  v_name := coalesce(nullif(trim(p_party_name), ''), 'Driver');

  INSERT INTO public.trip_conversations (
    organization_id,
    trip_id,
    party_type,
    party_name,
    driver_id
  )
  VALUES (
    v_trip.organization_id,
    p_trip_id,
    'driver',
    v_name,
    p_driver_id
  )
  ON CONFLICT (trip_id, party_type) DO UPDATE SET
    party_name = coalesce(
      nullif(trim(excluded.party_name), ''),
      trip_conversations.party_name
    ),
    driver_id = coalesce(excluded.driver_id, trip_conversations.driver_id),
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."ensure_driver_trip_conversation"("p_trip_id" "uuid", "p_driver_id" "uuid", "p_party_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_driver_trip_conversation"("p_trip_id" "uuid", "p_driver_id" "uuid", "p_party_name" "text") IS 'Idempotent driver party row for trip chat; bypasses RLS under validated fleet, linked supplier (trips.supplier_id), indent assigned org (indents.assigned_supplier_id when trip.supplier_id null), or assigned driver.';



CREATE OR REPLACE FUNCTION "public"."ensure_network_identity"("p_identity_type" "text", "p_primary_entity" "text", "p_primary_id" "uuid", "p_org_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  CROCKFORD constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  v_prefix  text;
  v_num     bigint;
  v_suffix  text := '';
  v_ref     text;
  v_i       int;
  v_attempts int := 0;
BEGIN
  -- Return existing if already created
  SELECT network_ref INTO v_ref
  FROM public.network_identities
  WHERE primary_entity = p_primary_entity
    AND primary_id     = p_primary_id
    AND identity_type  = p_identity_type;
  IF FOUND THEN RETURN v_ref; END IF;

  v_prefix := CASE p_identity_type
    WHEN 'booking'           THEN 'BKG'
    WHEN 'shared_load'       THEN 'SHR'
    WHEN 'collaboration'     THEN 'COL'
    WHEN 'marketplace_order' THEN 'MKT'
    ELSE upper(left(p_identity_type, 3))
  END;

  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > 20 THEN
      RAISE EXCEPTION 'Cannot generate unique network reference after 20 attempts';
    END IF;

    v_num    := (nextval('public.global_ref_suffix_seq') + (random() * 999999)::bigint)
                % (32::bigint ^ 6);
    v_suffix := '';
    FOR v_i IN 1..6 LOOP
      v_suffix := substr(CROCKFORD, (v_num % 32)::int + 1, 1) || v_suffix;
      v_num    := v_num / 32;
    END LOOP;
    v_ref := v_prefix || '-' || v_suffix;

    BEGIN
      INSERT INTO public.network_identities
             (network_ref, identity_type, primary_entity, primary_id, participant_orgs)
      VALUES (v_ref, p_identity_type, p_primary_entity, p_primary_id, ARRAY[p_org_id]);
      RETURN v_ref;
    EXCEPTION WHEN unique_violation THEN
      CONTINUE;
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ensure_network_identity"("p_identity_type" "text", "p_primary_entity" "text", "p_primary_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_organization_operational_code"("p_org_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_code text;
  v_name text;
  v_candidate text;
  v_salt integer;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization is required';
  END IF;

  SELECT operational_code, name
  INTO v_code, v_name
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization not found: %', p_org_id;
  END IF;

  IF v_code IS NOT NULL AND btrim(v_code) <> '' THEN
    RETURN upper(btrim(v_code));
  END IF;

  v_salt := 0;
  LOOP
    v_candidate := public.make_operational_org_code(v_name, p_org_id, v_salt);
    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM public.organizations o
      WHERE o.operational_code = v_candidate
        AND o.id <> p_org_id
    );
    v_salt := v_salt + 1;
    IF v_salt > 100 THEN
      RAISE EXCEPTION 'Unable to allocate unique operational_code for org %', p_org_id;
    END IF;
  END LOOP;

  UPDATE public.organizations
  SET operational_code = v_candidate
  WHERE id = p_org_id;

  RETURN v_candidate;
END;
$$;


ALTER FUNCTION "public"."ensure_organization_operational_code"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_trip_chat_room"("p_trip_id" "uuid") RETURNS "public"."chat_conversations"
    LANGUAGE "sql" SECURITY DEFINER
