CREATE OR REPLACE FUNCTION "public"."entity_documents_audit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action  text;
  v_old     text;
  v_new     text;
BEGIN
  IF (TG_OP = 'INSERT') THEN
    v_action := 'created';
    v_old    := NULL;
    v_new    := NEW.status;
    INSERT INTO public.document_audit_log
      (document_id, organization_id, entity_type, entity_id,
       action, actor_id, old_status, new_status)
    VALUES
      (NEW.id, NEW.organization_id, NEW.entity_type, NEW.entity_id,
       v_action, NEW.created_by, v_old, v_new);
    RETURN NEW;

  ELSIF (TG_OP = 'UPDATE') THEN
    -- Choose the most specific action label based on what changed.
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      v_action := CASE NEW.status
        WHEN 'verified' THEN 'verified'
        WHEN 'rejected' THEN 'rejected'
        WHEN 'replaced' THEN 'replaced'
        ELSE 'updated'
      END;
    ELSE
      v_action := 'updated';
    END IF;

    INSERT INTO public.document_audit_log
      (document_id, organization_id, entity_type, entity_id,
       action, actor_id, old_status, new_status,
       notes, metadata)
    VALUES
      (NEW.id, NEW.organization_id, NEW.entity_type, NEW.entity_id,
       v_action, auth.uid(), OLD.status, NEW.status,
       NEW.notes,
       jsonb_build_object(
         'doc_type',     NEW.doc_type,
         'expiry_date',  NEW.expiry_date,
         'storage_path', NEW.storage_path
       ));
    RETURN NEW;

  ELSIF (TG_OP = 'DELETE') THEN
    INSERT INTO public.document_audit_log
      (document_id, organization_id, entity_type, entity_id,
       action, actor_id, old_status, new_status)
    VALUES
      (OLD.id, OLD.organization_id, OLD.entity_type, OLD.entity_id,
       'deleted', auth.uid(), OLD.status, NULL);
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."entity_documents_audit_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_b2b_update"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Normalise caller-facing aliases before forwarding to the canonical function.
  -- system_log → system   |  payment → ledger   |  feedback → feedback_request
  SELECT public.process_b2b_event(
    p_organization_id,
    p_trip_id,
    CASE p_event_type
      WHEN 'system_log' THEN 'system'
      WHEN 'payment'    THEN 'ledger'
      WHEN 'feedback'   THEN 'feedback_request'
      ELSE p_event_type
    END,
    p_payload
  );
$$;


ALTER FUNCTION "public"."execute_b2b_update"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_b2b_update"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_payload" "jsonb") IS 'Canonical B2B event writer. Thin alias for process_b2b_event with normalised event_type aliases (system_log→system, payment→ledger, etc.). One DB round-trip: updates trips state + inserts message with full trip_state snapshot so clients never need a follow-up fetch.';



CREATE OR REPLACE FUNCTION "public"."expire_old_posts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE public.posts SET is_active = false, updated_at = now()
  WHERE expires_at < now() AND is_active = true;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


