CREATE OR REPLACE FUNCTION "public"."expire_stale_team_invitations"("p_phone" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canon text;
  v_count integer;
BEGIN
  v_canon := public.normalize_phone_canon(p_phone);
  UPDATE public.organization_team_invites
  SET status = 'expired', updated_at = now()
  WHERE invitee_phone_canon = v_canon
    AND status = 'pending'
    AND expires_at <= now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


