CREATE OR REPLACE FUNCTION "public"."fill_driver_commission"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_commission_percent NUMERIC;
  v_commission_per_km  NUMERIC;
BEGIN
  IF NEW.driver_id IS NULL OR COALESCE(NEW.driver_commission, 0) != 0 THEN
    RETURN NEW;
  END IF;

  SELECT commission_percent, commission_per_km
  INTO v_commission_percent, v_commission_per_km
  FROM drivers
  WHERE id = NEW.driver_id
  LIMIT 1;

  IF COALESCE(v_commission_percent, 0) > 0 AND COALESCE(NEW.client_price, 0) > 0 THEN
    NEW.driver_commission := ROUND(NEW.client_price * v_commission_percent / 100, 2);
  ELSIF COALESCE(v_commission_per_km, 0) > 0 AND COALESCE(NEW.distance, 0) > 0 THEN
    NEW.driver_commission := ROUND(CAST(NEW.distance AS NUMERIC) * v_commission_per_km, 2);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fill_driver_commission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_org_matches_for_counterparty"("p_name" "text", "p_min_similarity" double precision DEFAULT 0.55, "p_phone" "text" DEFAULT NULL::"text") RETURNS TABLE("org_id" "uuid", "org_name" "text", "similarity_score" double precision, "org_city" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH normalized_input AS (
    SELECT
      TRIM(
        REGEXP_REPLACE(
          LOWER(TRIM(p_name)),
          '\s+(pvt\.?\s*ltd\.?|private limited|llp|llc|and\b|&|co\.?)$',
          '',
          'i'
        )
      ) AS n
  ),
  scored AS (
    SELECT
      o.id   AS org_id,
      o.name AS org_name,
      GREATEST(
        similarity(o.name, p_name),
        similarity(
          TRIM(REGEXP_REPLACE(LOWER(TRIM(o.name)), '\s+(pvt\.?\s*ltd\.?|private limited|llp|llc|and\b|&|co\.?)$', '', 'i')),
          (SELECT n FROM normalized_input)
        )
      )      AS name_score,
      o.city AS org_city
    FROM organizations o
    WHERE o.deleted_at IS NULL
      AND similarity(o.name, p_name) >= (p_min_similarity * 0.7)
  )
  SELECT
    org_id,
    org_name,
    name_score::float AS similarity_score,
    org_city
  FROM scored
  WHERE name_score >= p_min_similarity
  ORDER BY name_score DESC
  LIMIT 5;
$_$;


ALTER FUNCTION "public"."find_org_matches_for_counterparty"("p_name" "text", "p_min_similarity" double precision, "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_pending_sent_connection_to_partner_owner"("p_from_org_id" "uuid", "p_to_org_id" "uuid") RETURNS TABLE("request_id" "uuid", "same_pair" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT cr.id AS request_id,
         (cr.to_organization_id = p_to_org_id) AS same_pair
  FROM public.connection_requests cr
  JOIN public.organizations to_org ON to_org.id = cr.to_organization_id
  JOIN public.organizations target ON target.id = p_to_org_id
  WHERE cr.from_organization_id = p_from_org_id
    AND cr.status = 'pending'
    AND target.owner_id IS NOT NULL
    AND to_org.owner_id = target.owner_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members om
      WHERE om.organization_id = p_from_org_id
        AND om.user_id = auth.uid()
        AND om.status = 'active'
    )
  ORDER BY cr.created_at DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."find_pending_sent_connection_to_partner_owner"("p_from_org_id" "uuid", "p_to_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_pending_sent_connection_to_partner_owner"("p_from_org_id" "uuid", "p_to_org_id" "uuid") IS 'Returns an existing pending sent connection request to the same partner owner (if any). Caller must be active member of p_from_org_id.';



CREATE OR REPLACE FUNCTION "public"."fn_broadcast_transactions_ledger_chat"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ct            text;
  v_linked_org    uuid;
  v_party_label   text;
  v_sender_name   text;
  v_recv_name     text;
  v_conv_id       uuid;
  v_amount        numeric;
  v_flow          text;
  v_category      text;
  v_mode          text := 'Cash';
  v_meta          jsonb;
  v_content       text;
  v_amount_plain  text;
BEGIN
  v_ct := lower(coalesce(NEW.contact_type, ''));

  IF NEW.trip_id IS NULL OR NEW.contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_ct NOT IN ('client', 'supplier') THEN
    RETURN NEW;
  END IF;

  IF coalesce(NEW.amount_in, 0) <= 0 AND coalesce(NEW.amount_out, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.trip_messages tm
    WHERE tm.message_type = 'ledger_event'
      AND coalesce(tm.metadata->>'transaction_id', '') = NEW.id::text
    LIMIT 1
  ) THEN
    RETURN NEW;
  END IF;

  BEGIN
    IF v_ct = 'client' THEN
      SELECT c.linked_organization_id,
             trim(coalesce(nullif(trim(c.name), ''), ''))
        INTO v_linked_org, v_party_label
      FROM public.clients c
      WHERE c.id = NEW.contact_id
      LIMIT 1;
    ELSE
      SELECT s.linked_organization_id,
             trim(coalesce(
               nullif(trim(s.company_name), ''),
               nullif(trim(s.name), ''),
               ''
             ))
        INTO v_linked_org, v_party_label
      FROM public.suppliers s
      WHERE s.id = NEW.contact_id
      LIMIT 1;
    END IF;

    IF v_linked_org IS NULL THEN
      RETURN NEW;
    END IF;

    SELECT trim(coalesce(o.name, '')) INTO v_sender_name
    FROM public.organizations o
    WHERE o.id = NEW.organization_id
    LIMIT 1;

    SELECT trim(coalesce(o.name, '')) INTO v_recv_name
    FROM public.organizations o
    WHERE o.id = v_linked_org
    LIMIT 1;

    IF v_sender_name = '' THEN
      v_sender_name := NEW.organization_id::text;
    END IF;

    IF v_recv_name = '' THEN
      v_recv_name := coalesce(nullif(v_party_label, ''), v_linked_org::text);
    END IF;

    IF coalesce(NEW.amount_in, 0) > 0 THEN
      v_flow := 'in';
      v_amount := NEW.amount_in;
    ELSE
      v_flow := 'out';
      v_amount := NEW.amount_out;
    END IF;

    v_category := trim(coalesce(nullif(trim(NEW.ledger_category), ''), 'Payment'));

    IF NEW.description ILIKE '%Mode: Cash%' THEN
      v_mode := 'Cash';
    ELSIF NEW.description ILIKE '%Mode: UPI%' THEN
      v_mode := 'UPI';
    ELSIF NEW.description ILIKE '%Mode: Bank Transfer%' THEN
      v_mode := 'Bank Transfer';
    ELSIF NEW.description ILIKE '%Mode: Cheque%' THEN
      v_mode := 'Cheque';
    END IF;

    v_amount_plain := trim(to_char(round(v_amount, 2), 'FM999999999999990999999'));

    IF v_flow = 'in' THEN
      v_content :=
        format('%s received ₹%s · %s', v_sender_name, v_amount_plain, v_category);
    ELSE
      v_content :=
        format('%s paid ₹%s to %s · %s', v_sender_name, v_amount_plain, v_recv_name, v_category);
    END IF;

    v_meta := jsonb_build_object(
      'transaction_id', NEW.id::text,
      'amount', round(v_amount::numeric, 2),
      'flow', v_flow,
      'category', v_category,
      'payment_mode', v_mode,
      'reference_number', NULL,
      'notes', NULL,
      'sender_org_id', NEW.organization_id::text,
      'sender_org_name', v_sender_name,
      'receiver_org_id', v_linked_org::text,
      'receiver_org_name', v_recv_name,
      'acknowledged_at', NULL::text,
      'disputed', false
    );

    IF v_ct = 'client' THEN
      SELECT tc.id INTO v_conv_id
      FROM public.trip_conversations tc
      WHERE tc.organization_id = NEW.organization_id
        AND tc.trip_id = NEW.trip_id
        AND tc.party_type = 'client'
        AND tc.client_id = NEW.contact_id
      LIMIT 1;
    ELSE
      SELECT tc.id INTO v_conv_id
      FROM public.trip_conversations tc
      WHERE tc.organization_id = NEW.organization_id
        AND tc.trip_id = NEW.trip_id
        AND tc.party_type = 'supplier'
        AND tc.supplier_id = NEW.contact_id
      LIMIT 1;
    END IF;

    IF v_conv_id IS NULL THEN
      INSERT INTO public.trip_conversations (
        organization_id,
        trip_id,
        party_type,
        party_name,
        client_id,
        supplier_id,
        driver_id
      )
      VALUES (
        NEW.organization_id,
        NEW.trip_id,
        CASE WHEN v_ct = 'client' THEN 'client' ELSE 'supplier' END::text,
        coalesce(nullif(v_party_label, ''), 'Partner'),
        CASE WHEN v_ct = 'client' THEN NEW.contact_id ELSE NULL END,
        CASE WHEN v_ct = 'supplier' THEN NEW.contact_id ELSE NULL END,
        NULL
      )
      ON CONFLICT (trip_id, party_type) DO UPDATE SET
        organization_id = EXCLUDED.organization_id,
        party_name      = coalesce(EXCLUDED.party_name, trip_conversations.party_name),
        client_id       = CASE
                           WHEN trip_conversations.party_type::text = 'client'
                             THEN EXCLUDED.client_id
                           ELSE trip_conversations.client_id
                         END,
        supplier_id     = CASE
                           WHEN trip_conversations.party_type::text = 'supplier'
                             THEN EXCLUDED.supplier_id
                           ELSE trip_conversations.supplier_id
                         END,
        updated_at      = now();

      IF v_ct = 'client' THEN
        SELECT tc.id INTO v_conv_id
        FROM public.trip_conversations tc
        WHERE tc.organization_id = NEW.organization_id
          AND tc.trip_id = NEW.trip_id
          AND tc.party_type = 'client'
          AND tc.client_id = NEW.contact_id
        LIMIT 1;

        IF v_conv_id IS NULL THEN
          SELECT tc.id INTO v_conv_id
          FROM public.trip_conversations tc
          WHERE tc.trip_id = NEW.trip_id
            AND tc.party_type = 'client'
          LIMIT 1;
        END IF;
      ELSE
        SELECT tc.id INTO v_conv_id
        FROM public.trip_conversations tc
        WHERE tc.organization_id = NEW.organization_id
          AND tc.trip_id = NEW.trip_id
          AND tc.party_type = 'supplier'
          AND tc.supplier_id = NEW.contact_id
        LIMIT 1;

        IF v_conv_id IS NULL THEN
          SELECT tc.id INTO v_conv_id
          FROM public.trip_conversations tc
          WHERE tc.trip_id = NEW.trip_id
            AND tc.party_type = 'supplier'
          LIMIT 1;
        END IF;
      END IF;
    END IF;

    IF v_conv_id IS NULL THEN
      RAISE WARNING 'ledger_chat: could not resolve conversation trip % party % contact % org %',
        NEW.trip_id, v_ct, NEW.contact_id, NEW.organization_id;
      RETURN NEW;
    END IF;

    PERFORM public.send_trip_chat_message(
      v_conv_id,
      v_content,
      'system',
      'Payment System',
      NULL,
      'ledger_event',
      v_meta
    );
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'ledger_chat trigger failed tx %:%', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_broadcast_transactions_ledger_chat"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_broadcast_transactions_ledger_chat"() IS 'Posts ledger_event after transactions insert; creates trip_conversation when missing + mirrors via send_trip_chat_message.';



CREATE OR REPLACE FUNCTION "public"."fn_broadcast_trip_status_to_chat"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_msg       text;
  v_terminal  boolean;
  v_simulated boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  v_msg := public.fn_trip_status_chat_message_body(NEW);
  IF v_msg IS NULL THEN
    RETURN NEW;
  END IF;

  v_simulated := coalesce(NEW.status_change_origin, '') = 'business_simulated';
  IF v_simulated THEN
    v_msg := v_msg || ' (simulated)';
  END IF;

  v_terminal := NEW.status IN ('completed', 'delivered', 'done', 'cancelled');

  IF NOT EXISTS (SELECT 1 FROM public.trip_conversations WHERE trip_id = NEW.id LIMIT 1) THEN
    PERFORM public.fn_ensure_trip_party_conversations(NEW.id);
  END IF;

  IF EXISTS (SELECT 1 FROM public.trip_conversations WHERE trip_id = NEW.id LIMIT 1) THEN
    PERFORM public.fn_post_system_message_to_trip_chats(
      NEW.id,
      v_msg,
      NEW.status::text,
      v_simulated
    );
  END IF;

  IF v_simulated THEN
    UPDATE public.trips
    SET status_change_origin = NULL
    WHERE id = NEW.id;
  END IF;

  IF v_terminal THEN
    PERFORM public.fn_post_trip_feedback_prompt_to_chats(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_broadcast_trip_status_to_chat"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_build_chat_lanes"("p_unified" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH expanded AS (
    SELECT
      nullif(trim(c->>'trip_id'), '') AS trip_id,
      CASE
        WHEN nullif(trim(c->>'indent_id'), '') IS NOT NULL
          THEN trim(c->>'indent_id')::uuid
      END AS indent_id,
      nullif(trim(m->>'id'), '') AS msg_id,
      coalesce(trim(m->>'message_type'), '') AS msg_type
    FROM jsonb_array_elements(coalesce(p_unified, '[]'::jsonb)) AS c
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(c->'messages', '[]'::jsonb)) AS m
  ),
  commercial AS (
    SELECT indent_id::text AS k, jsonb_agg(to_jsonb(msg_id) ORDER BY msg_id) AS v
    FROM expanded
    WHERE indent_id IS NOT NULL
      AND msg_type IN ('ledger_event', 'ledger', 'payment', 'ledger_update')
    GROUP BY indent_id
  ),
  operational AS (
    SELECT trip_id AS k, jsonb_agg(to_jsonb(msg_id) ORDER BY msg_id) AS v
    FROM expanded
    WHERE trip_id IS NOT NULL
      AND msg_type NOT IN ('ledger_event', 'ledger', 'payment', 'ledger_update')
    GROUP BY trip_id
  )
  SELECT jsonb_build_object(
    'commercial_by_indent',
      COALESCE((SELECT jsonb_object_agg(k, v) FROM commercial), '{}'::jsonb),
    'operational_by_trip',
      COALESCE((SELECT jsonb_object_agg(k, v) FROM operational), '{}'::jsonb)
  );
$$;


