COMMENT ON FUNCTION "public"."fn_driver_locations_after_insert"() IS 'After INSERT on driver_locations: rate-limited location pings + LATE alerts with scheduled (original) and updated ETA at 350 km/day pace.';



CREATE OR REPLACE FUNCTION "public"."fn_enqueue_chat_push_outbox"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_title text;
  v_body  text;
  v_part  record;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.sender_type = 'system' AND NEW.message_type = 'action_card' THEN
    v_title := coalesce(NEW.content, 'Trip update');
    v_body := coalesce(NEW.metadata->>'body', '');
  ELSE
    v_title := coalesce(nullif(trim(NEW.sender_name), ''), 'New message');
    v_body := left(coalesce(NEW.content, ''), 180);
  END IF;

  FOR v_part IN
    SELECT cp.user_id
    FROM public.chat_participants cp
    WHERE cp.conversation_id = NEW.conversation_id
      AND cp.user_id IS DISTINCT FROM NEW.sender_user_id
      AND EXISTS (
        SELECT 1 FROM public.user_push_tokens upt WHERE upt.user_id = cp.user_id
      )
  LOOP
    INSERT INTO public.chat_push_outbox (
      user_id, organization_id, conversation_id, message_id,
      title, body,
      payload
    )
    VALUES (
      v_part.user_id, NEW.organization_id, NEW.conversation_id, NEW.id,
      v_title, v_body,
      jsonb_build_object(
        'conversation_id', NEW.conversation_id,
        'message_id', NEW.id,
        'trip_id', (SELECT trip_id FROM chat_conversations WHERE id = NEW.conversation_id),
        'message_type', NEW.message_type
      )
    );
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_enqueue_chat_push_outbox"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ensure_trip_chat_room"("p_trip_id" "uuid") RETURNS "public"."chat_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.chat_conversations%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT public.fn_can_access_trip_for_chat(p_trip_id) THEN
    RAISE EXCEPTION 'Not authorized for trip chat room' USING ERRCODE = '42501';
  END IF;

  v_row := public.fn_ensure_trip_chat_room_core(p_trip_id, auth.uid());

  INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
  VALUES (v_row.id, auth.uid(), 'member')
  ON CONFLICT (conversation_id, user_id) DO NOTHING;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."fn_ensure_trip_chat_room"("p_trip_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ensure_trip_chat_room_core"("p_trip_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."chat_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip public.trips%ROWTYPE;
  v_row  public.chat_conversations%ROWTYPE;
  v_key  text;
BEGIN
  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Trip not found: %', p_trip_id;
  END IF;

  SELECT * INTO v_row
  FROM public.chat_conversations
  WHERE trip_id = p_trip_id AND conversation_type = 'trip';
  IF FOUND THEN
    PERFORM public.fn_sync_trip_room_participants(v_row.id, p_trip_id);
    RETURN v_row;
  END IF;

  v_key := 'trip:' || p_trip_id::text;

  INSERT INTO public.chat_conversations (
    organization_id, conversation_type, title, trip_id,
    client_id, supplier_id, driver_id, channel_key,
    metadata, created_by
  )
  VALUES (
    v_trip.organization_id,
    'trip',
    coalesce(
      'Trip ' || nullif(trim(v_trip.trip_number), ''),
      'Trip Chat'
    ),
    p_trip_id,
    v_trip.client_id,
    v_trip.supplier_id,
    v_trip.driver_id,
    v_key,
    jsonb_build_object(
      'trip_number', v_trip.trip_number,
      'trip_status', v_trip.status
    ),
    p_created_by
  )
  ON CONFLICT (trip_id) WHERE conversation_type = 'trip' AND trip_id IS NOT NULL
  DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row
    FROM public.chat_conversations
    WHERE trip_id = p_trip_id AND conversation_type = 'trip';
  END IF;

  PERFORM public.fn_sync_trip_room_participants(v_row.id, p_trip_id);
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."fn_ensure_trip_chat_room_core"("p_trip_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ensure_trip_party_conversations"("p_trip_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip public.trips%ROWTYPE;
  v_client_name  text;
  v_supplier_name text;
  v_driver_name  text;
BEGIN
  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip_id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;

  IF v_trip.client_id IS NOT NULL THEN
    v_client_name := coalesce(
      (SELECT nullif(trim(coalesce(c.name, '')), '')
       FROM public.clients c WHERE c.id = v_trip.client_id LIMIT 1),
      nullif(trim(v_trip.client_name), ''),
      'Client'
    );
    INSERT INTO public.trip_conversations (
      organization_id, trip_id, party_type, party_name,
      client_id, supplier_id, driver_id
    )
    VALUES (
      v_trip.organization_id, p_trip_id, 'client', v_client_name,
      v_trip.client_id, NULL, NULL
    )
    ON CONFLICT (trip_id, party_type) DO UPDATE SET
      organization_id = excluded.organization_id,
      party_name      = coalesce(excluded.party_name, trip_conversations.party_name),
      client_id       = excluded.client_id,
      updated_at      = now();
  END IF;

  IF v_trip.supplier_id IS NOT NULL THEN
    v_supplier_name := coalesce(
      (SELECT nullif(trim(coalesce(nullif(s.company_name, ''), nullif(s.name, ''), '')), '')
       FROM public.suppliers s WHERE s.id = v_trip.supplier_id LIMIT 1),
      'Supplier'
    );
    INSERT INTO public.trip_conversations (
      organization_id, trip_id, party_type, party_name,
      client_id, supplier_id, driver_id
    )
    VALUES (
      v_trip.organization_id, p_trip_id, 'supplier', v_supplier_name,
      NULL, v_trip.supplier_id, NULL
    )
    ON CONFLICT (trip_id, party_type) DO UPDATE SET
      organization_id = excluded.organization_id,
      party_name      = coalesce(excluded.party_name, trip_conversations.party_name),
      supplier_id     = excluded.supplier_id,
      updated_at      = now();
  END IF;

  IF v_trip.driver_id IS NOT NULL THEN
    v_driver_name := coalesce(
      (SELECT nullif(trim(d.name), '') FROM public.drivers d WHERE d.id = v_trip.driver_id LIMIT 1),
      'Driver'
    );
    INSERT INTO public.trip_conversations (
      organization_id, trip_id, party_type, party_name,
      client_id, supplier_id, driver_id
    )
    VALUES (
      v_trip.organization_id, p_trip_id, 'driver', v_driver_name,
      NULL, NULL, v_trip.driver_id
    )
    ON CONFLICT (trip_id, party_type) DO UPDATE SET
      organization_id = excluded.organization_id,
      party_name      = coalesce(excluded.party_name, trip_conversations.party_name),
      driver_id       = excluded.driver_id,
      updated_at      = now();
  END IF;

  -- Phase 2: unified room alongside legacy lanes (no-op when already exists).
  BEGIN
    PERFORM public.fn_ensure_trip_chat_room_core(p_trip_id);
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'fn_ensure_trip_chat_room_core trip %:%', p_trip_id, SQLERRM;
  END;
END;
$$;


ALTER FUNCTION "public"."fn_ensure_trip_party_conversations"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ensure_trip_party_conversations"("p_trip_id" "uuid") IS 'Creates trip_conversations for client/supplier/driver on this trip when missing (idempotent upsert).';



CREATE OR REPLACE FUNCTION "public"."fn_expire_workspace_products"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Trial → suspended when trial_ends_at has passed and not yet active
  UPDATE public.workspace_products
  SET
    status = 'suspended',
    updated_at = now()
  WHERE status = 'trial'
    AND trial_ends_at IS NOT NULL
    AND trial_ends_at < now();

  -- Active → suspended when expires_at has passed (missed renewal)
  UPDATE public.workspace_products
  SET
    status = 'suspended',
    updated_at = now()
  WHERE status = 'active'
    AND expires_at IS NOT NULL
    AND expires_at < now() - interval '3 days';  -- 3-day grace period
END;
$$;


