CREATE OR REPLACE FUNCTION "public"."fn_post_system_log_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_metadata" "jsonb", "p_priority_weight" integer DEFAULT 40) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv         record;
  v_source_trip  record;
  v_partner_org  uuid;
  v_partner_trip record;
  v_partner_conv uuid;
BEGIN
  SELECT id, organization_id, trip_number, client_id, supplier_id
  INTO   v_source_trip
  FROM   public.trips
  WHERE  id = p_trip_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  FOR v_conv IN
    SELECT id, party_type, organization_id, client_id, supplier_id
    FROM   public.trip_conversations
    WHERE  trip_id = p_trip_id
  LOOP
    INSERT INTO public.trip_messages (
      conversation_id,
      organization_id,
      sender_user_id,
      sender_role,
      sender_name,
      content,
      message_type,
      is_read,
      metadata,
      priority_weight
    ) VALUES (
      v_conv.id,
      v_conv.organization_id,
      NULL,
      'system',
      'Trip System',
      p_content,
      'system_log',
      FALSE,
      p_metadata,
      COALESCE(p_priority_weight, 40)
    );

    v_partner_org := NULL;

    IF v_conv.party_type = 'client' AND v_conv.client_id IS NOT NULL THEN
      SELECT linked_organization_id
      INTO   v_partner_org
      FROM   public.clients
      WHERE  id = v_conv.client_id;

    ELSIF v_conv.party_type = 'supplier' AND v_conv.supplier_id IS NOT NULL THEN
      SELECT linked_organization_id
      INTO   v_partner_org
      FROM   public.suppliers
      WHERE  id = v_conv.supplier_id;
    END IF;

    IF v_partner_org IS NULL THEN
      CONTINUE;
    END IF;

    SELECT id, organization_id
    INTO   v_partner_trip
    FROM   public.trips
    WHERE  organization_id = v_partner_org
      AND  trip_number = v_source_trip.trip_number
    ORDER BY created_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    SELECT id
    INTO   v_partner_conv
    FROM   public.trip_conversations
    WHERE  trip_id = v_partner_trip.id
      AND  party_type = v_conv.party_type
    LIMIT 1;

    IF v_partner_conv IS NULL THEN
      CONTINUE;
    END IF;

    INSERT INTO public.trip_messages (
      conversation_id,
      organization_id,
      sender_user_id,
      sender_role,
      sender_name,
      content,
      message_type,
      is_read,
      metadata,
      priority_weight
    ) VALUES (
      v_partner_conv,
      v_partner_trip.organization_id,
      NULL,
      'system',
      'Trip System',
      p_content,
      'system_log',
      FALSE,
      p_metadata,
      COALESCE(p_priority_weight, 40)
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_post_system_log_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_metadata" "jsonb", "p_priority_weight" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_post_system_log_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_metadata" "jsonb", "p_priority_weight" integer) IS 'SECURITY DEFINER: inserts system_log into all trip_conversations for a trip + linked partner trip threads.';



CREATE OR REPLACE FUNCTION "public"."fn_post_system_message_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_dedupe_status" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv          RECORD;
  v_meta          JSONB;
  v_source_trip   RECORD;
  v_partner_org   UUID;
  v_partner_trip  RECORD;
  v_partner_conv  UUID;
BEGIN
  v_meta := jsonb_build_object(
    'trip_status_broadcast', '1',
    'status', COALESCE(p_dedupe_status, ''),
    'event_payload', jsonb_build_object(
      'new_status', NULLIF(trim(COALESCE(p_dedupe_status, '')), ''),
      'trip_id', p_trip_id
    )
  );

  SELECT id, organization_id, trip_number, client_id, supplier_id
  INTO   v_source_trip
  FROM   public.trips
  WHERE  id = p_trip_id;

  IF NOT FOUND THEN RETURN; END IF;

  FOR v_conv IN
    SELECT id, party_type, organization_id, client_id, supplier_id
    FROM   public.trip_conversations
    WHERE  trip_id = p_trip_id
  LOOP

    IF p_dedupe_status IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.trip_messages tm
      WHERE  tm.conversation_id = v_conv.id
        AND  tm.message_type IN ('system', 'system_log', 'update')
        AND  (tm.metadata->>'trip_status_broadcast') = '1'
        AND  (
          (tm.metadata->>'status') = trim(p_dedupe_status)
          OR (tm.metadata->'event_payload'->>'new_status') = trim(p_dedupe_status)
        )
      LIMIT 1
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.trip_messages (
      conversation_id,  organization_id,     sender_user_id,
      sender_role,      sender_name,         content,
      message_type,     is_read,             metadata
    ) VALUES (
      v_conv.id,        v_conv.organization_id, NULL,
      'system',         'Trip System',          p_content,
      'system',         FALSE,                  v_meta
    );

    v_partner_org := NULL;

    IF v_conv.party_type = 'client' AND v_conv.client_id IS NOT NULL THEN
      SELECT linked_organization_id INTO v_partner_org
      FROM   public.clients
      WHERE  id = v_conv.client_id;

    ELSIF v_conv.party_type = 'supplier' AND v_conv.supplier_id IS NOT NULL THEN
      SELECT linked_organization_id INTO v_partner_org
      FROM   public.suppliers
      WHERE  id = v_conv.supplier_id;
    END IF;

    IF v_partner_org IS NULL THEN
      CONTINUE;
    END IF;

    SELECT id, organization_id INTO v_partner_trip
    FROM   public.trips
    WHERE  organization_id = v_partner_org
      AND  trip_number     = v_source_trip.trip_number
    ORDER BY created_at DESC
    LIMIT 1;

    IF NOT FOUND THEN CONTINUE; END IF;

    SELECT id INTO v_partner_conv
    FROM   public.trip_conversations
    WHERE  trip_id    = v_partner_trip.id
      AND  party_type = v_conv.party_type
    LIMIT 1;

    IF v_partner_conv IS NULL THEN CONTINUE; END IF;

    IF p_dedupe_status IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.trip_messages tm
      WHERE  tm.conversation_id = v_partner_conv
        AND  tm.message_type IN ('system', 'system_log', 'update')
        AND  (tm.metadata->>'trip_status_broadcast') = '1'
        AND  (
          (tm.metadata->>'status') = trim(p_dedupe_status)
          OR (tm.metadata->'event_payload'->>'new_status') = trim(p_dedupe_status)
        )
      LIMIT 1
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.trip_messages (
      conversation_id,  organization_id,           sender_user_id,
      sender_role,      sender_name,               content,
      message_type,     is_read,                   metadata
    ) VALUES (
      v_partner_conv,   v_partner_trip.organization_id, NULL,
      'system',         'Trip System',                  p_content,
      'system',         FALSE,                          v_meta
    );

  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_post_system_message_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_dedupe_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_post_system_message_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_dedupe_status" "text") IS 'Writes a system message to every trip_conversations row for this trip. Org-local only — cross-org mirror removed (trip_number is org-scoped, not globally unique; mirroring by trip_number wrote events into unrelated trips in other orgs).';



CREATE OR REPLACE FUNCTION "public"."fn_post_system_message_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_dedupe_status" "text" DEFAULT NULL::"text", "p_simulated" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv          record;
  v_meta          jsonb;
  v_source_trip   record;
  v_partner_org   uuid;
  v_partner_trip  record;
  v_partner_conv  uuid;
BEGIN
  v_meta := jsonb_build_object(
    'trip_status_broadcast', '1',
    'status', coalesce(p_dedupe_status, ''),
    'event_payload', jsonb_build_object(
      'new_status', nullif(trim(coalesce(p_dedupe_status, '')), ''),
      'trip_id', p_trip_id,
      'simulated', case when p_simulated then true else null end
    )
  );

  SELECT id, organization_id, trip_number, client_id, supplier_id
  INTO   v_source_trip
  FROM   public.trips
  WHERE  id = p_trip_id;

  IF NOT FOUND THEN RETURN; END IF;

  FOR v_conv IN
    SELECT id, party_type, organization_id, client_id, supplier_id
    FROM   public.trip_conversations
    WHERE  trip_id = p_trip_id
  LOOP

    IF p_dedupe_status IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.trip_messages tm
      WHERE  tm.conversation_id = v_conv.id
        AND  tm.message_type IN ('system', 'system_log', 'update')
        AND  (tm.metadata->>'trip_status_broadcast') = '1'
        AND  (
          (tm.metadata->>'status') = trim(p_dedupe_status)
          OR (tm.metadata->'event_payload'->>'new_status') = trim(p_dedupe_status)
        )
      LIMIT  1
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.trip_messages (
      conversation_id,  organization_id,     sender_user_id,
      sender_role,      sender_name,         content,
      message_type,     is_read,             metadata
    ) VALUES (
      v_conv.id,        v_conv.organization_id, null,
      'system',         'Trip System',          p_content,
      'system',         false,                  v_meta
    );

    v_partner_org := null;

    IF v_conv.party_type = 'client' AND v_conv.client_id IS NOT NULL THEN
      SELECT linked_organization_id INTO v_partner_org
      FROM   public.clients
      WHERE  id = v_conv.client_id;

    ELSIF v_conv.party_type = 'supplier' AND v_conv.supplier_id IS NOT NULL THEN
      SELECT linked_organization_id INTO v_partner_org
      FROM   public.suppliers
      WHERE  id = v_conv.supplier_id;
    END IF;

    IF v_partner_org IS NULL THEN
      CONTINUE;
    END IF;

    SELECT id, organization_id INTO v_partner_trip
    FROM   public.trips
    WHERE  organization_id = v_partner_org
      AND  trip_number     = v_source_trip.trip_number
    ORDER BY created_at DESC
    LIMIT  1;

    IF NOT FOUND THEN CONTINUE; END IF;

    SELECT id INTO v_partner_conv
    FROM   public.trip_conversations
    WHERE  trip_id    = v_partner_trip.id
      AND  party_type = v_conv.party_type
    LIMIT  1;

    IF v_partner_conv IS NULL THEN CONTINUE; END IF;

    IF p_dedupe_status IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.trip_messages tm
      WHERE  tm.conversation_id = v_partner_conv
        AND  tm.message_type IN ('system', 'system_log', 'update')
        AND  (tm.metadata->>'trip_status_broadcast') = '1'
        AND  (
          (tm.metadata->>'status') = trim(p_dedupe_status)
          OR (tm.metadata->'event_payload'->>'new_status') = trim(p_dedupe_status)
        )
      LIMIT  1
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.trip_messages (
      conversation_id,  organization_id,           sender_user_id,
      sender_role,      sender_name,               content,
      message_type,     is_read,                   metadata
    ) VALUES (
      v_partner_conv,   v_partner_trip.organization_id, null,
      'system',         'Trip System',                  p_content,
      'system',         false,                          v_meta
    );

  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_post_system_message_to_trip_chats"("p_trip_id" "uuid", "p_content" "text", "p_dedupe_status" "text", "p_simulated" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_post_trip_feedback_prompt_to_chats"("p_trip_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv public.trip_conversations%ROWTYPE;
  v_body text := 'Trip completed — rate this partner to close the mission debrief.';
  v_meta jsonb;
BEGIN
  FOR v_conv IN
    SELECT *
    FROM public.trip_conversations
    WHERE trip_id = p_trip_id
  LOOP
    IF EXISTS (
      SELECT 1
      FROM public.trip_messages tm
      WHERE tm.conversation_id = v_conv.id
        AND tm.message_type = 'feedback_request'
    ) THEN
      CONTINUE;
    END IF;

    IF v_conv.party_type = 'client' AND v_conv.client_id IS NOT NULL THEN
      v_meta := jsonb_build_object(
        'feedback_version', 1,
        'rated_party_type', 'client',
        'rated_id', v_conv.client_id::text,
        'rated_display_name', v_conv.party_name
      );
    ELSIF v_conv.party_type = 'supplier' AND v_conv.supplier_id IS NOT NULL THEN
      v_meta := jsonb_build_object(
        'feedback_version', 1,
        'rated_party_type', 'supplier',
        'rated_id', v_conv.supplier_id::text,
        'rated_display_name', v_conv.party_name
      );
    ELSIF v_conv.party_type = 'driver' AND v_conv.driver_id IS NOT NULL THEN
      v_meta := jsonb_build_object(
        'feedback_version', 1,
        'rated_party_type', 'driver',
        'rated_id', v_conv.driver_id::text,
        'rated_display_name', v_conv.party_name
      );
    ELSE
      CONTINUE;
    END IF;

    INSERT INTO public.trip_messages (
      conversation_id,
      organization_id,
      sender_user_id,
      sender_role,
      sender_name,
      content,
      message_type,
      is_read,
      metadata
    )
    VALUES (
      v_conv.id,
      v_conv.organization_id,
      NULL,
      'system',
      'Trip System',
      v_body,
      'feedback_request',
      FALSE,
      v_meta
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_post_trip_feedback_prompt_to_chats"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_post_trip_feedback_prompt_to_chats"("p_trip_id" "uuid") IS 'After completion, inserts one feedback_request row per party thread (direct insert; not mirrored).';



CREATE OR REPLACE FUNCTION "public"."fn_post_trip_room_action_card"("p_trip_id" "uuid", "p_event_type" "text", "p_title" "text", "p_body" "text" DEFAULT ''::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_legacy_msg_id" "uuid" DEFAULT NULL::"uuid", "p_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_room public.chat_conversations%ROWTYPE;
  v_meta jsonb;
  v_created timestamptz;
  v_body text;
BEGIN
  SELECT * INTO v_room
  FROM public.chat_conversations
  WHERE trip_id = p_trip_id AND conversation_type = 'trip';
  IF NOT FOUND THEN RETURN; END IF;

  IF p_legacy_msg_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.chat_messages m
    WHERE m.conversation_id = v_room.id
      AND m.metadata->>'legacy_trip_message_id' = p_legacy_msg_id::text
  ) THEN
    RETURN;
  END IF;

  v_created := coalesce(p_created_at, now());
  v_body := left(coalesce(p_metadata->>'body', p_body, ''), 160);

  -- Same operational event mirrored from another lane (client/supplier/driver).
  IF EXISTS (
    SELECT 1 FROM public.chat_messages m
    WHERE m.conversation_id = v_room.id
      AND m.message_type = 'action_card'
      AND coalesce(m.metadata->>'event_type', '') = coalesce(p_event_type, '')
      AND left(coalesce(m.metadata->>'body', m.content, ''), 160) = v_body
      AND date_trunc('minute', m.created_at) = date_trunc('minute', v_created)
  ) THEN
    RETURN;
  END IF;

  v_meta := coalesce(p_metadata, '{}'::jsonb)
    || jsonb_build_object(
      'event_type', p_event_type,
      'trip_id', p_trip_id,
      'trip_room_mirror', '1'
    );
  IF p_legacy_msg_id IS NOT NULL THEN
    v_meta := v_meta || jsonb_build_object('legacy_trip_message_id', p_legacy_msg_id::text);
  END IF;

  INSERT INTO public.chat_messages (
    conversation_id, organization_id,
    sender_user_id, sender_type, sender_name,
    message_type, content, metadata, legacy_source, created_at
  )
  VALUES (
    v_room.id, v_room.organization_id,
    NULL, 'system', 'Pulse',
    'action_card',
    coalesce(p_title, ''),
    v_meta || jsonb_build_object('body', coalesce(p_body, '')),
    'trip',
    v_created
  );
END;
$$;


