COMMENT ON FUNCTION "public"."fn_post_trip_room_action_card"("p_trip_id" "uuid", "p_event_type" "text", "p_title" "text", "p_body" "text", "p_metadata" "jsonb", "p_legacy_msg_id" "uuid", "p_created_at" timestamp with time zone) IS 'Posts a system action_card into the unified trip room (deduped per legacy message id and cross-lane event fingerprint).';



CREATE OR REPLACE FUNCTION "public"."fn_reconcile_trip_conversation_unread"("p_conversation_id" "uuid") RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT COUNT(*)::int
    FROM   public.trip_messages tm
    WHERE  tm.conversation_id = p_conversation_id
      AND  tm.is_read = FALSE
      AND  public.fn_trip_message_counts_as_dispatcher_unread(tm.sender_role, tm.message_type)
  ), 0);
$$;


