CREATE OR REPLACE FUNCTION "public"."fn_storage_trip_doc_access"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'storage'
    AS $$
DECLARE
  v_folder  TEXT;
  v_trip_id UUID;
BEGIN
  -- Extract the first directory component (trip_id) from the storage path.
  -- storage.foldername('/abc-uuid/filename.jpg') → '{abc-uuid}'
  v_folder := (storage.foldername(p_name))[1];
  IF v_folder IS NULL OR length(v_folder) < 32 THEN
    RETURN FALSE;
  END IF;

  -- Guard: return FALSE for non-UUID folder names (system files, avatars, etc.)
  -- without touching any app tables.
  BEGIN
    v_trip_id := v_folder::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN FALSE;
  END;

  -- Is the calling user an active member of the trip's owning organisation?
  -- Execution plan:
  --   1. trips PK scan: trips(id = v_trip_id)               → 1 row, O(1)
  --   2. org_members index scan: (user_id, organization_id) → 1 row, O(1)
  -- (SELECT auth.uid()) is evaluated once as an initplan, not per-row.
  RETURN EXISTS (
    SELECT 1
    FROM   public.trips t
    JOIN   public.organization_members om
             ON om.organization_id = t.organization_id
            AND om.user_id         = (SELECT auth.uid())
            AND (om.status = 'active' OR om.status IS NULL)
    WHERE  t.id = v_trip_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_storage_trip_doc_access"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_storage_trip_doc_access"("p_name" "text") IS 'Storage RLS helper: checks that the calling user is an active org member of the trip that owns the file. SECURITY DEFINER + STABLE = plan-cacheable and evaluated once per query rather than once per row.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_trip_room_on_trip_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_room_id uuid;
BEGIN
  IF NEW.driver_id IS NOT DISTINCT FROM OLD.driver_id
     AND NEW.client_id IS NOT DISTINCT FROM OLD.client_id
     AND NEW.supplier_id IS NOT DISTINCT FROM OLD.supplier_id
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_room_id
  FROM public.chat_conversations
  WHERE trip_id = NEW.id AND conversation_type = 'trip';

  IF v_room_id IS NOT NULL THEN
    UPDATE public.chat_conversations
    SET
      client_id   = NEW.client_id,
      supplier_id = NEW.supplier_id,
      driver_id   = NEW.driver_id,
      organization_id = NEW.organization_id,
      metadata = metadata || jsonb_build_object('trip_status', NEW.status),
      updated_at = now()
    WHERE id = v_room_id;

    PERFORM public.fn_sync_trip_room_participants(v_room_id, NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_trip_room_on_trip_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_trip_room_participants"("p_conversation_id" "uuid", "p_trip_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip public.trips%ROWTYPE;
BEGIN
  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip_id;
  IF NOT FOUND THEN RETURN; END IF;

  -- Fleet org: dispatchers, ops, finance, owner.
  INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
  SELECT p_conversation_id, om.user_id,
         CASE WHEN om.role IN ('owner', 'admin') THEN 'admin' ELSE 'member' END
  FROM public.organization_members om
  WHERE om.organization_id = v_trip.organization_id
    AND om.status = 'active'
    AND om.user_id IS NOT NULL
  ON CONFLICT (conversation_id, user_id) DO NOTHING;

  -- Assigned driver (driver app JWT).
  IF v_trip.driver_id IS NOT NULL THEN
    INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
    SELECT p_conversation_id, d.user_id, 'driver'
    FROM public.drivers d
    WHERE d.id = v_trip.driver_id
      AND d.user_id IS NOT NULL
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
  END IF;

  -- Linked customer org members.
  IF v_trip.client_id IS NOT NULL THEN
    INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
    SELECT p_conversation_id, om.user_id, 'client'
    FROM public.clients c
    JOIN public.organization_members om
      ON om.organization_id = c.linked_organization_id
    WHERE c.id = v_trip.client_id
      AND c.linked_organization_id IS NOT NULL
      AND om.status = 'active'
      AND om.user_id IS NOT NULL
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
  END IF;

  -- Linked supplier org members.
  IF v_trip.supplier_id IS NOT NULL THEN
    INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
    SELECT p_conversation_id, om.user_id, 'supplier'
    FROM public.suppliers s
    JOIN public.organization_members om
      ON om.organization_id = s.linked_organization_id
    WHERE s.id = v_trip.supplier_id
      AND s.linked_organization_id IS NOT NULL
      AND om.status = 'active'
      AND om.user_id IS NOT NULL
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
  END IF;

  -- Trip owner / assigner when present on the row.
  IF v_trip.owner_user_id IS NOT NULL THEN
    INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
    VALUES (p_conversation_id, v_trip.owner_user_id, 'member')
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
  END IF;

  IF v_trip.assigned_by_user_id IS NOT NULL THEN
    INSERT INTO public.chat_participants (conversation_id, user_id, participant_role)
    VALUES (p_conversation_id, v_trip.assigned_by_user_id, 'member')
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_sync_trip_room_participants"("p_conversation_id" "uuid", "p_trip_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trip_location_city_hint"("p_trip_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  v_pickup text;
  v_drop   text;
BEGIN
  SELECT lower(trim(coalesce(t.status, ''))),
         nullif(trim(t.pickup_area), ''),
         nullif(trim(t.drop_location), '')
  INTO   v_status, v_pickup, v_drop
  FROM   public.trips t
  WHERE  t.id = p_trip_id;

  IF NOT FOUND THEN
    RETURN 'En route';
  END IF;

  IF v_status IN ('at_drop', 'completed', 'delivered', 'done') THEN
    RETURN coalesce(v_drop, v_pickup, 'En route');
  END IF;

  IF v_status IN ('picked_up', 'in_transit', 'in_progress') THEN
    RETURN coalesce(v_pickup, v_drop, 'En route');
  END IF;

  RETURN coalesce(v_pickup, v_drop, 'En route');
END;
$$;


