CREATE OR REPLACE FUNCTION "public"."generate_enterprise_operational_code"("p_org_id" "uuid", "p_entity_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_code text;
  v_org_name text;
  v_org_short text;
  v_entity text := lower(trim(p_entity_type));
  v_prefix text;
  v_seq bigint;
BEGIN
  v_org_code := public.ensure_organization_operational_code(p_org_id);

  SELECT coalesce(name, '')
  INTO v_org_name
  FROM public.organizations
  WHERE id = p_org_id;

  v_org_short := upper(substr(regexp_replace(v_org_name, '[^A-Za-z]', '', 'g') || 'ORG', 1, 3));

  CASE v_entity
    WHEN 'trip' THEN v_prefix := 'TRIP';
    WHEN 'indent' THEN v_prefix := 'IND';
    WHEN 'vehicle' THEN v_prefix := 'VEH';
    WHEN 'driver' THEN v_prefix := 'DRV';
    WHEN 'invoice' THEN v_prefix := 'INV';
    WHEN 'pod' THEN v_prefix := 'POD';
    WHEN 'maintenance' THEN v_prefix := 'MNT';
    ELSE
      RAISE EXCEPTION 'Unsupported entity_type: %', p_entity_type;
  END CASE;

  v_seq := public.allocate_operational_sequence(p_org_id, v_entity);
  RETURN v_org_code || v_org_short || v_prefix || lpad(v_seq::text, 6, '0');
END;
$$;


ALTER FUNCTION "public"."generate_enterprise_operational_code"("p_org_id" "uuid", "p_entity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_global_reference"("p_entity_type" "text", "p_entity_id" "uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  CROCKFORD  constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  v_year     smallint;
  v_prefix   text;
  v_num      bigint;
  v_suffix   text := '';
  v_ref      text;
  v_attempts int := 0;
  v_i        int;
BEGIN
  v_year := extract(year from now())::smallint;

  -- Entity-type to prefix mapping
  v_prefix := CASE lower(p_entity_type)
    WHEN 'trip'          THEN 'TRP'
    WHEN 'indent'        THEN 'IND'
    WHEN 'driver'        THEN 'DRV'
    WHEN 'fleet'         THEN 'FLT'
    WHEN 'invoice'       THEN 'INV'
    WHEN 'booking'       THEN 'BKG'
    WHEN 'shared_load'   THEN 'SHR'
    WHEN 'collaboration' THEN 'COL'
    WHEN 'vehicle'       THEN 'VEH'
    WHEN 'pod'           THEN 'POD'
    WHEN 'transaction'   THEN 'TXN'
    WHEN 'organization'  THEN 'ORG'
    ELSE upper(left(p_entity_type, 3))
  END;

  -- Check if reference already exists for this entity
  SELECT reference INTO v_ref
  FROM public.global_references
  WHERE entity_type = lower(p_entity_type)
    AND entity_id   = p_entity_id;
  IF FOUND THEN RETURN v_ref; END IF;

  -- Generate collision-free 6-char Crockford base32 suffix
  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > 20 THEN
      RAISE EXCEPTION 'Could not generate unique global reference after 20 attempts';
    END IF;

    -- Mix: sequence value + random + entity_id hash for locality avoidance
    v_num := (
      nextval('public.global_ref_suffix_seq') * 1000000 +
      (random() * 999999)::bigint +
      abs(hashtext(p_entity_id::text)) % 100000
    ) % (32::bigint ^ 6);

    v_suffix := '';
    FOR v_i IN 1..6 LOOP
      v_suffix := substr(CROCKFORD, (v_num % 32)::int + 1, 1) || v_suffix;
      v_num    := v_num / 32;
    END LOOP;

    v_ref := v_prefix || '-' || (v_year % 100)::text || '-' || v_suffix;

    -- Insert; skip on collision and retry
    BEGIN
      INSERT INTO public.global_references
             (entity_type, entity_id, reference, year, issued_by_org)
      VALUES (lower(p_entity_type), p_entity_id, v_ref, v_year, p_org_id);
      RETURN v_ref;
    EXCEPTION WHEN unique_violation THEN
      CONTINUE; -- retry with a new random suffix
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_global_reference"("p_entity_type" "text", "p_entity_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_global_reference"("p_entity_type" "text", "p_entity_id" "uuid", "p_org_id" "uuid") IS 'Issue or retrieve a globally unique short reference (TRP-26-AB4K7F) for any entity.
   Idempotent: calling twice for the same entity_id returns the same reference.';



CREATE OR REPLACE FUNCTION "public"."generate_operational_code"("org_id" "uuid", "entity_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_code text;
  v_entity text := lower(trim(entity_type));
  v_seq bigint;
  v_prefix text;
BEGIN
  v_org_code := public.ensure_organization_operational_code(org_id);

  v_prefix := public.operational_prefix_for_entity(v_entity);
  v_seq := public.next_operational_sequence_value(org_id, v_entity);

  RETURN upper(v_org_code) || '-' || v_prefix || '-' || lpad(v_seq::text, 3, '0');
END;
$$;


ALTER FUNCTION "public"."generate_operational_code"("org_id" "uuid", "entity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_trip_otp"("p_trip_id" "uuid", "p_ttl_minutes" integer DEFAULT 15) RETURNS TABLE("code" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_code text;
  v_expires_at timestamptz;
  v_ttl int;
  v_trip_org uuid;
  v_supplier_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT t.organization_id, t.supplier_id
  INTO v_trip_org, v_supplier_id
  FROM public.trips t
  WHERE t.id = p_trip_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Trip not found';
  END IF;

  IF NOT (
    public.is_org_member(v_trip_org)
    OR (
      v_supplier_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.suppliers s
        WHERE s.id = v_supplier_id
          AND s.linked_organization_id IS NOT NULL
          AND public.is_org_member(s.linked_organization_id)
      )
    )
  ) THEN
    RAISE EXCEPTION 'Access denied for trip %', p_trip_id;
  END IF;

  v_ttl := greatest(1, least(coalesce(p_ttl_minutes, 15), 1440));

  LOOP
    v_code := lpad(floor(random() * 1000000)::text, 6, '0');
    v_expires_at := now() + (v_ttl || ' minutes')::interval;
    INSERT INTO public.trip_otps (trip_id, code, expires_at, used_at, failed_attempts)
    VALUES (p_trip_id, v_code, v_expires_at, NULL, 0)
    ON CONFLICT (trip_id) DO UPDATE
    SET code = EXCLUDED.code,
        expires_at = EXCLUDED.expires_at,
        used_at = NULL,
        failed_attempts = 0,
        created_at = now();
    RETURN QUERY SELECT v_code, v_expires_at;
    RETURN;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_trip_otp"("p_trip_id" "uuid", "p_ttl_minutes" integer) OWNER TO "postgres";


