CREATE OR REPLACE FUNCTION "public"."get_audit_log_for_org"("p_org_id" "uuid", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "event_type" "text", "actor_name" "text", "actor_email" "text", "payload" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    al.id,
    al.event_type,
    coalesce(p.full_name, au.email, 'System')  AS actor_name,
    au.email                                    AS actor_email,
    al.payload,
    al.created_at
  FROM public.workspace_audit_log al
  LEFT JOIN auth.users au ON au.id = al.actor_id
  LEFT JOIN public.profiles p ON p.id = al.actor_id
  WHERE al.org_id = p_org_id
    AND al.org_id IN (
      SELECT om.organization_id FROM public.organization_members om
      WHERE om.user_id = auth.uid() AND om.role IN ('owner', 'admin')
    )
  ORDER BY al.created_at DESC
  LIMIT p_limit OFFSET p_offset;
$$;


