CREATE OR REPLACE FUNCTION "public"."get_chat_inbox"("p_organization_id" "uuid", "p_limit" integer DEFAULT 30, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "conversation_type" "text", "title" "text", "trip_id" "uuid", "client_id" "uuid", "supplier_id" "uuid", "driver_id" "uuid", "channel_key" "text", "is_archived" boolean, "last_message_at" timestamp with time zone, "last_message_preview" "text", "message_count" integer, "metadata" "jsonb", "created_at" timestamp with time zone, "my_last_read_at" timestamp with time zone, "unread_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    cc.id, cc.organization_id, cc.conversation_type, cc.title,
    cc.trip_id, cc.client_id, cc.supplier_id, cc.driver_id,
    cc.channel_key, cc.is_archived,
    cc.last_message_at, cc.last_message_preview, cc.message_count,
    cc.metadata, cc.created_at,
    cp.last_read_at AS my_last_read_at,
    coalesce(unread.n, 0) AS unread_count
  FROM chat_conversations cc
  LEFT JOIN chat_participants cp
    ON cp.conversation_id = cc.id AND cp.user_id = auth.uid()
  LEFT JOIN LATERAL (
    SELECT count(*) AS n
    FROM chat_messages m
    WHERE m.conversation_id = cc.id
      AND m.deleted_at IS NULL
      AND m.sender_user_id IS DISTINCT FROM auth.uid()
      AND m.created_at > coalesce(cp.last_read_at, 'epoch'::timestamptz)
  ) unread ON true
  WHERE cc.organization_id = p_organization_id
    AND cc.is_archived = false
    AND (p_before IS NULL OR cc.last_message_at < p_before)
  ORDER BY cc.last_message_at DESC NULLS LAST, cc.id
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100);
$$;


ALTER FUNCTION "public"."get_chat_inbox"("p_organization_id" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


