CREATE OR REPLACE FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 30) RETURNS SETOF "public"."chat_messages"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT m.*
  FROM chat_messages m
  WHERE m.conversation_id = p_conversation_id
    AND (p_before IS NULL OR m.created_at < p_before)
  ORDER BY m.created_at DESC, m.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100);
$$;


