CREATE OR REPLACE FUNCTION "public"."get_client_detail_bundle"("p_org_id" "uuid", "p_client_id" "uuid") RETURNS json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'client', (
      SELECT row_to_json(c)
      FROM clients c
      WHERE c.id = p_client_id
      LIMIT 1
    ),
    'ratings', (
      SELECT COALESCE(json_agg(r ORDER BY r.created_at DESC), '[]'::json)
      FROM ratings r
      WHERE r.rated_type = 'client'
        AND r.rated_id = p_client_id
    ),
    'warehouses', (
      SELECT COALESCE(json_agg(w), '[]'::json)
      FROM client_warehouses w
      WHERE w.organization_id = p_org_id
        AND w.client_id = p_client_id
    ),
    'contracts', (
      SELECT COALESCE(json_agg(cc ORDER BY cc.created_at ASC), '[]'::json)
      FROM client_contracts cc
      WHERE cc.organization_id = p_org_id
        AND cc.client_id = p_client_id
        AND (cc.valid_to IS NULL OR cc.valid_to >= CURRENT_DATE)
    )
  );
$$;


ALTER FUNCTION "public"."get_client_detail_bundle"("p_org_id" "uuid", "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_details"("p_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_row record;
  v_org_name text;
  v_owner_id uuid;
  v_full_name text;
  v_phone text;
  v_email text;
  v_authorized boolean;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT c.id, c.organization_id, c.name, c.contact_person, c.phone, c.email, c.address,
         c.gstin, c.pan_number, c.status, c.notes, c.is_integrated, c.linked_organization_id,
         c.created_by, c.created_at, c.updated_at, c.display_id
  INTO v_row
  FROM public.clients c
  WHERE c.id = p_client_id;

  IF v_row.id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Caller must be active member or owner of the client's org
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = v_row.organization_id AND om.user_id = v_uid AND om.status = 'active'
  ) OR EXISTS (
    SELECT 1 FROM public.organizations o
    WHERE o.id = v_row.organization_id AND o.owner_id = v_uid
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RETURN NULL;
  END IF;

  -- Integrated (linked_organization_id set): merge display from linked org's owner profile
  IF v_row.linked_organization_id IS NOT NULL THEN
    SELECT o.name, o.owner_id INTO v_org_name, v_owner_id
    FROM public.organizations o
    WHERE o.id = v_row.linked_organization_id;

    IF v_owner_id IS NOT NULL THEN
      SELECT trim(coalesce(p.full_name, '')), trim(coalesce(p.phone, '')), trim(coalesce(p.email, ''))
      INTO v_full_name, v_phone, v_email
      FROM public.profiles p
      WHERE p.id = v_owner_id;
    END IF;

    RETURN jsonb_build_object(
      'id', v_row.id,
      'organization_id', v_row.organization_id,
      'name', coalesce(nullif(trim(v_row.name), ''), nullif(trim(v_org_name), ''), 'Client'),
      'contact_person', coalesce(nullif(trim(v_row.contact_person), ''), v_full_name),
      'phone', coalesce(nullif(trim(v_row.phone), ''), v_phone),
      'email', coalesce(nullif(trim(v_row.email), ''), v_email),
      'address', v_row.address,
      'gstin', v_row.gstin,
      'pan_number', v_row.pan_number,
      'status', v_row.status,
      'notes', v_row.notes,
      'is_integrated', v_row.is_integrated,
      'linked_organization_id', v_row.linked_organization_id,
      'created_by', v_row.created_by,
      'created_at', v_row.created_at,
      'updated_at', v_row.updated_at,
      'display_id', v_row.display_id
    );
  END IF;

  -- Non-integrated: return local row as-is
  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."get_client_details"("p_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_client_details"("p_client_id" "uuid") IS 'Returns client row for detail/edit. When linked_organization_id is set, name/contact_person/phone/email are COALESCE from linked org owner profile. Caller must be member or owner of client.organization_id.';



CREATE OR REPLACE FUNCTION "public"."get_client_management_bundle"("p_org_id" "uuid", "p_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_client jsonb;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT to_jsonb(c.*) INTO v_client
  FROM public.clients c
  WHERE c.id = p_client_id
    AND c.organization_id = p_org_id
    AND c.deleted_at IS NULL;

  IF v_client IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'client', v_client,
    'contacts', COALESCE((
      SELECT jsonb_agg(to_jsonb(cc.*) ORDER BY cc.is_primary DESC, cc.created_at)
      FROM public.client_contacts cc
      WHERE cc.client_id = p_client_id AND cc.organization_id = p_org_id AND cc.deleted_at IS NULL
    ), '[]'::jsonb),
    'kyc_documents', COALESCE((
      SELECT jsonb_agg(to_jsonb(k.*) ORDER BY k.doc_type, k.version_number DESC)
      FROM public.client_kyc_documents k
      WHERE k.client_id = p_client_id AND k.organization_id = p_org_id AND k.deleted_at IS NULL
    ), '[]'::jsonb),
    'warehouses', COALESCE((
      SELECT jsonb_agg(to_jsonb(w.*) ORDER BY w.created_at)
      FROM public.client_warehouses w
      WHERE w.client_id = p_client_id AND w.organization_id = p_org_id
        AND (w.deleted_at IS NULL)
    ), '[]'::jsonb),
    'agreements', COALESCE((
      SELECT jsonb_agg(to_jsonb(a.*) ORDER BY a.effective_date DESC NULLS LAST)
      FROM public.client_contract_agreements a
      WHERE a.client_id = p_client_id AND a.organization_id = p_org_id AND a.deleted_at IS NULL
    ), '[]'::jsonb),
    'lane_rates', COALESCE((
      SELECT jsonb_agg(to_jsonb(lr.*) ORDER BY lr.valid_from DESC NULLS LAST)
      FROM public.client_lane_rates lr
      WHERE lr.client_id = p_client_id AND lr.organization_id = p_org_id AND lr.deleted_at IS NULL
    ), '[]'::jsonb),
    'legacy_contracts', COALESCE((
      SELECT jsonb_agg(to_jsonb(ct.*) ORDER BY ct.created_at)
      FROM public.client_contracts ct
      WHERE ct.client_id = p_client_id AND ct.organization_id = p_org_id
    ), '[]'::jsonb),
    'finance_profile', (
      SELECT to_jsonb(fp.*)
      FROM public.client_finance_profiles fp
      WHERE fp.client_id = p_client_id AND fp.organization_id = p_org_id
      LIMIT 1
    ),
    'documents', COALESCE((
      SELECT jsonb_agg(to_jsonb(d.*) ORDER BY d.folder, d.created_at DESC)
      FROM public.client_documents d
      WHERE d.client_id = p_client_id AND d.organization_id = p_org_id AND d.deleted_at IS NULL
    ), '[]'::jsonb),
    'audit_log', COALESCE((
      SELECT jsonb_agg(to_jsonb(al.*) ORDER BY al.created_at DESC)
      FROM (
        SELECT * FROM public.client_audit_log
        WHERE client_id = p_client_id AND organization_id = p_org_id
        ORDER BY created_at DESC
        LIMIT 100
      ) al
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_client_management_bundle"("p_org_id" "uuid", "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_monthly_analytics"("p_org_id" "uuid", "p_client_id" "uuid", "p_months_back" integer DEFAULT 12) RETURNS TABLE("period" "text", "revenue" numeric, "margin" numeric, "margin_pct" numeric, "trip_count" bigint, "km_driven" numeric, "collected" numeric, "outstanding" numeric, "avg_payment_delay_days" numeric, "on_time_pct" numeric, "cancellation_rate_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH _period_start AS (
    SELECT date_trunc('month', now() - (p_months_back - 1 || ' months')::interval) AS start_dt
  ),
  _client_trips AS (
    SELECT
      t.id          AS trip_id,
      t.client_price,
      t.margin,
      t.distance,
      t.status,
      t.pickup_date,
      t.completed_at,
      COALESCE(t.pickup_date, t.created_at) AS trip_date
    FROM public.trips t
    WHERE t.client_id = p_client_id
      AND t.organization_id = p_org_id
      AND COALESCE(t.pickup_date, t.created_at) >= (SELECT start_dt FROM _period_start)
      AND public.is_org_member(p_org_id)
  ),
  _client_credits AS (
    SELECT
      to_char(date_trunc('month', COALESCE(tx.transaction_date, tx.created_at)::date), 'YYYY-MM') AS period,
      SUM(COALESCE(tx.amount_in, 0))                                AS collected,
      AVG(NULLIF(
        (COALESCE(tx.transaction_date, tx.created_at::date)
         - ct.pickup_date), 0
      ))                                                            AS avg_delay
    FROM public.transactions tx
    JOIN _client_trips ct ON ct.trip_id = tx.trip_id
    WHERE tx.organization_id = p_org_id
      AND COALESCE(tx.amount_in, 0) > 0
      AND ct.pickup_date IS NOT NULL
      AND public.is_org_member(p_org_id)
    GROUP BY 1
  ),
  _monthly AS (
    SELECT
      to_char(date_trunc('month', ct.trip_date), 'YYYY-MM') AS period,
      SUM(COALESCE(ct.client_price, 0))                     AS revenue,
      SUM(COALESCE(ct.margin, 0))                           AS margin,
      COUNT(*)                                              AS trip_count,
      SUM(COALESCE(ct.distance, 0))                         AS km_driven,
      -- On-time: completed within +1 day of pickup_date (proxy until SLA exists)
      AVG(
        CASE
          WHEN ct.completed_at IS NOT NULL AND ct.pickup_date IS NOT NULL
            THEN CASE
              WHEN ct.completed_at::date <= ct.pickup_date + INTERVAL '1 day'
                THEN 100.0
              ELSE 0.0
            END
          ELSE NULL
        END
      )                                                     AS on_time_pct,
      -- Cancellation rate
      ROUND(
        COUNT(*) FILTER (WHERE ct.status = 'cancelled')::numeric
        / NULLIF(COUNT(*), 0) * 100, 2
      )                                                     AS cancellation_rate_pct
    FROM _client_trips ct
    GROUP BY 1
  )
  SELECT
    m.period,
    m.revenue,
    m.margin,
    CASE WHEN m.revenue > 0
      THEN ROUND((m.margin / m.revenue) * 100, 2)
      ELSE 0
    END                                                     AS margin_pct,
    m.trip_count,
    m.km_driven,
    COALESCE(cc.collected, 0)                               AS collected,
    GREATEST(m.revenue - COALESCE(cc.collected, 0), 0)      AS outstanding,
    ROUND(COALESCE(cc.avg_delay, 0)::numeric, 1)            AS avg_payment_delay_days,
    ROUND(COALESCE(m.on_time_pct, 0)::numeric, 1)           AS on_time_pct,
    COALESCE(m.cancellation_rate_pct, 0)                    AS cancellation_rate_pct
  FROM _monthly m
  LEFT JOIN _client_credits cc ON cc.period = m.period
  ORDER BY m.period ASC;
$$;


ALTER FUNCTION "public"."get_client_monthly_analytics"("p_org_id" "uuid", "p_client_id" "uuid", "p_months_back" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_clients_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_deleted   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(c) ORDER BY c.updated_at) FILTER (WHERE c.deleted_at IS NULL), '[]'),
    COALESCE(jsonb_agg(c.id::TEXT)                           FILTER (WHERE c.deleted_at IS NOT NULL), '[]'),
    MAX(c.updated_at)::TEXT
  INTO v_changed, v_deleted, v_next
  FROM (
    SELECT * FROM clients
    WHERE organization_id = p_org_id
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) c;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  v_deleted,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


ALTER FUNCTION "public"."get_clients_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_clients_with_profiles"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "name" "text", "contact_person" "text", "phone" "text", "email" "text", "address" "text", "gstin" "text", "pan_number" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "is_integrated" boolean, "linked_organization_id" "uuid", "avatar_url" "text", "avatar_seed" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.organization_id,
    c.name,
    c.contact_person,
    c.phone,
    c.email,
    c.address,
    c.gstin,
    c.pan_number,
    c.status,
    c.created_at,
    c.updated_at,
    c.is_integrated,
    c.linked_organization_id,
    -- Prefer the linked org's branding logo; fall back to the owner's
    -- personal profile avatar so unbranded orgs still show a face.
    COALESCE(NULLIF(TRIM(o.logo_url), ''), p.avatar_url) AS avatar_url,
    p.avatar_seed
  FROM public.clients c
  LEFT JOIN public.organizations o ON o.id = c.linked_organization_id
  LEFT JOIN public.profiles      p ON p.id = o.owner_id
  WHERE c.organization_id = p_org_id
    AND c.status = 'active'
  ORDER BY c.name ASC;
END;
$$;


ALTER FUNCTION "public"."get_clients_with_profiles"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_clients_with_profiles"("p_org_id" "uuid") IS 'Returns clients for an org. avatar_url resolves to organizations.logo_url first, then profiles.avatar_url from linked org owner. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_compliance_summary"("p_org_id" "uuid") RETURNS TABLE("entity_type" "text", "total_docs" bigint, "active_docs" bigint, "expired_docs" bigint, "expiring_7d" bigint, "expiring_30d" bigint, "pending_docs" bigint, "verified_docs" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    entity_type,
    COUNT(*)                                                            AS total_docs,
    COUNT(*) FILTER (WHERE status = 'active' OR status = 'verified')    AS active_docs,
    COUNT(*) FILTER (
      WHERE status = 'expired'
         OR (expiry_date IS NOT NULL AND expiry_date < CURRENT_DATE)
    )                                                                   AS expired_docs,
    COUNT(*) FILTER (
      WHERE expiry_date IS NOT NULL
        AND expiry_date >= CURRENT_DATE
        AND expiry_date <= CURRENT_DATE + INTERVAL '7 days'
        AND status NOT IN ('replaced', 'rejected')
    )                                                                   AS expiring_7d,
    COUNT(*) FILTER (
      WHERE expiry_date IS NOT NULL
        AND expiry_date >= CURRENT_DATE
        AND expiry_date <= CURRENT_DATE + INTERVAL '30 days'
        AND status NOT IN ('replaced', 'rejected')
    )                                                                   AS expiring_30d,
    COUNT(*) FILTER (WHERE status = 'pending')                          AS pending_docs,
    COUNT(*) FILTER (WHERE status = 'verified')                         AS verified_docs
  FROM public.entity_documents
  WHERE organization_id = p_org_id
    AND public.is_org_member(p_org_id)
  GROUP BY entity_type;
$$;


ALTER FUNCTION "public"."get_compliance_summary"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_connection_partner_display"("p_linked_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'organizationName', o.name,
    'contactPerson',    p.full_name,
    'phone',            p.phone,
    'email',            p.email,
    'avatarUrl',        COALESCE(NULLIF(TRIM(o.logo_url), ''), p.avatar_url),
    'avatarSeed',       p.avatar_seed,
    'gstin',            o.gstin,
    'address',          NULLIF(TRIM(
                          COALESCE(NULLIF(TRIM(o.address_line), ''), '')
                          || CASE WHEN NULLIF(TRIM(o.city),  '') IS NOT NULL THEN ', ' || TRIM(o.city)  ELSE '' END
                          || CASE WHEN NULLIF(TRIM(o.state), '') IS NOT NULL THEN ', ' || TRIM(o.state) ELSE '' END
                        ), ''),
    'website',          o.profile_website,
    'orgCreatedAt',     o.created_at,
    'ownerSignedUpAt',  p.created_at
  )
  FROM  public.organizations o
  JOIN  public.profiles p ON p.id = o.owner_id
  WHERE o.id = p_linked_organization_id;
$$;


