COMMENT ON FUNCTION "public"."get_connection_partner_display"("p_linked_organization_id" "uuid") IS 'Linked org display profile including orgCreatedAt and ownerSignedUpAt for tenure. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_connection_partner_display_batch"("p_linked_organization_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT coalesce(
    jsonb_object_agg(
      o.id::text,
      jsonb_build_object(
        'organizationName', o.name,
        'contactPerson',    p.full_name,
        'phone',            p.phone,
        'email',            p.email,
        'logoUrl',          NULLIF(TRIM(o.logo_url), ''),
        'ownerAvatarUrl',   NULLIF(TRIM(p.avatar_url), ''),
        'orgAvatarSeed',    NULLIF(TRIM(p.avatar_seed), ''),
        'avatarUrl',        COALESCE(NULLIF(TRIM(o.logo_url), ''), p.avatar_url),
        'avatarSeed',       NULLIF(TRIM(p.avatar_seed), ''),
        'ownerId',          o.owner_id,
        'orgCreatedAt',     o.created_at,
        'ownerSignedUpAt',  p.created_at,
        'tripCount',        coalesce(trip_stats.trip_count, 0),
        'averageRating',    rating_stats.average_rating,
        'ratingCount',      coalesce(rating_stats.rating_count, 0)
      )
    ),
    '{}'::jsonb
  )
  FROM public.organizations o
  JOIN public.profiles p ON p.id = o.owner_id
  LEFT JOIN LATERAL (
    SELECT count(*)::int AS trip_count
    FROM public.trips t
    WHERE t.organization_id = o.id
      AND t.deleted_at IS NULL
  ) trip_stats ON true
  LEFT JOIN LATERAL (
    SELECT
      round(avg(r.score)::numeric, 2)::numeric(3, 2) AS average_rating,
      count(*)::int AS rating_count
    FROM public.ratings r
    WHERE r.rated_id = o.id
  ) rating_stats ON true
  WHERE o.id = ANY(p_linked_organization_ids);
$$;


ALTER FUNCTION "public"."get_connection_partner_display_batch"("p_linked_organization_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_connection_partner_display_batch"("p_linked_organization_ids" "uuid"[]) IS 'Batch partner display: branding, trip_count, average_rating, org tenure, owner signup. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_connection_requests_received_with_names"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "from_organization_id" "uuid", "to_organization_id" "uuid", "request_shipper_client" boolean, "request_carrier_supplier" boolean, "status" "text", "created_at" timestamp with time zone, "responded_at" timestamp with time zone, "responded_by" "uuid", "from_org_name" "text", "to_org_name" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    cr.id, cr.from_organization_id, cr.to_organization_id,
    cr.request_shipper_client, cr.request_carrier_supplier,
    cr.status, cr.created_at, cr.responded_at, cr.responded_by,
    coalesce(nullif(trim(fo.name),    ''), 'Unknown organization'),
    coalesce(nullif(trim(to_o.name),  ''), 'Unknown organization')
  FROM public.connection_requests cr
  LEFT JOIN public.organizations fo   ON fo.id  = cr.from_organization_id
  LEFT JOIN public.organizations to_o ON to_o.id = cr.to_organization_id
  WHERE cr.to_organization_id = p_org_id
    AND (
      EXISTS (
        SELECT 1 FROM public.organization_members om
        WHERE om.organization_id = p_org_id AND om.user_id = auth.uid()
      )
      OR EXISTS (
        SELECT 1 FROM public.organizations o
        WHERE o.id = p_org_id AND o.owner_id = auth.uid()
      )
    )
  ORDER BY cr.created_at DESC;
$$;


