CREATE OR REPLACE FUNCTION "public"."get_driver_coalesced_email_for_org"("p_org_id" "uuid", "p_driver_id" "uuid") RETURNS TABLE("email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(
      NULLIF(BTRIM(COALESCE(d.email, '')::text), ''),
      NULLIF(BTRIM(COALESCE(p.email, '')::text), '')
    )::text AS email
  FROM public.drivers d
  LEFT JOIN public.profiles p ON p.id = d.user_id
  WHERE d.organization_id = p_org_id
    AND d.id = p_driver_id
  LIMIT 1;
END;
$$;


