COMMENT ON FUNCTION "public"."get_driver_invitee_by_phone"("p_phone" "text") IS 'Returns driver profile by normalized phone: profile fields plus is_in_fleet (active drivers row with left_at IS NULL, tracking_only false, excluding their own default org).';



CREATE OR REPLACE FUNCTION "public"."get_driver_invites_received"() RETURNS TABLE("id" "uuid", "from_organization_id" "uuid", "to_user_id" "uuid", "status" "text", "created_at" timestamp with time zone, "responded_at" timestamp with time zone, "responded_by" "uuid", "from_org_name" "text", "payable_amount" numeric, "commission_percent" numeric, "commission_per_km" numeric, "from_org_logo_url" "text", "from_org_avatar_url" "text", "from_org_avatar_seed" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    di.id,
    di.from_organization_id,
    di.to_user_id,
    di.status,
    di.created_at,
    di.responded_at,
    di.responded_by,
    coalesce(nullif(trim(di.from_org_name), ''), nullif(trim(o.name), ''), 'Company'),
    di.payable_amount,
    di.commission_percent,
    di.commission_per_km,
    o.logo_url,
    p.avatar_url,
    p.avatar_seed
  FROM public.driver_invites di
  LEFT JOIN public.organizations o ON o.id = di.from_organization_id
  LEFT JOIN public.organization_members om
    ON om.organization_id = di.from_organization_id AND om.role = 'owner'
  LEFT JOIN public.profiles p ON p.id = om.user_id
  WHERE di.to_user_id = auth.uid()
  ORDER BY di.created_at DESC;
$$;


ALTER FUNCTION "public"."get_driver_invites_received"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_driver_invites_sent"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "from_org_name" "text", "driver_name" "text", "status" "text", "created_at" timestamp with time zone, "to_user_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    di.id,
    coalesce(nullif(trim(di.from_org_name), ''), o.name, 'Company') AS from_org_name,
    coalesce(
      nullif(trim(di.invitee_name), ''),
      nullif(trim(p.full_name), ''),
      nullif(trim(u.raw_user_meta_data->>'full_name'), ''),
      nullif(trim(u.raw_user_meta_data->>'name'), ''),
      nullif(trim(u.raw_user_meta_data->>'phone'), ''),
      nullif(trim(p.phone), ''),
      'Driver'
    ) AS driver_name,
    di.status,
    di.created_at,
    di.to_user_id
  FROM public.driver_invites di
  LEFT JOIN public.organizations o ON o.id = di.from_organization_id
  LEFT JOIN auth.users u ON u.id = di.to_user_id
  LEFT JOIN public.profiles p ON p.id = di.to_user_id
  WHERE di.from_organization_id = p_org_id
  ORDER BY di.created_at DESC;
$$;


