CREATE OR REPLACE FUNCTION "public"."get_driver_latest_location"("p_driver_id" "uuid") RETURNS TABLE("latitude" double precision, "longitude" double precision, "accuracy" double precision, "recorded_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT latitude, longitude, accuracy, recorded_at
  FROM public.driver_locations
  WHERE driver_id = p_driver_id
  ORDER BY recorded_at DESC LIMIT 1;
$$;


ALTER FUNCTION "public"."get_driver_latest_location"("p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_driver_location_history_for_trip"("p_trip_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("latitude" double precision, "longitude" double precision, "recorded_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver_id uuid;
  v_org_id    uuid;
BEGIN
  IF NOT public.can_access_trip_location(p_trip_id) THEN
    RETURN;
  END IF;

  SELECT driver_id, organization_id INTO v_driver_id, v_org_id
    FROM public.trips WHERE id = p_trip_id LIMIT 1;

  RETURN QUERY
  SELECT dl.latitude::double precision, dl.longitude::double precision, dl.recorded_at
    FROM public.driver_locations dl
   WHERE dl.trip_id = p_trip_id
   ORDER BY dl.recorded_at ASC
   LIMIT p_limit;

  IF v_driver_id IS NOT NULL AND v_org_id IS NOT NULL AND NOT FOUND THEN
    RETURN QUERY
    SELECT dl.latitude::double precision, dl.longitude::double precision, dl.recorded_at
      FROM public.driver_locations dl
     WHERE dl.driver_id = v_driver_id
       AND dl.organization_id = v_org_id
     ORDER BY dl.recorded_at ASC
     LIMIT p_limit;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_driver_location_history_for_trip"("p_trip_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_driver_location_history_for_trip"("p_trip_id" "uuid", "p_limit" integer) IS 'Location history for a trip ordered by time. Accessible by fleet, client, and supplier org members. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_driver_monthly_analytics"("p_org_id" "uuid", "p_driver_id" "uuid", "p_months_back" integer DEFAULT 12) RETURNS TABLE("period" "text", "revenue" numeric, "earnings" numeric, "paid" numeric, "trip_count" bigint, "km_driven" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH _period_start AS (
    SELECT date_trunc('month', now() - (p_months_back - 1 || ' months')::interval) AS start_dt
  ),
  _driver_trips AS (
    SELECT
      t.client_price,
      t.driver_commission,
      t.supplier_rate,
      t.distance,
      COALESCE(t.pickup_date, t.created_at) AS trip_date
    FROM public.trips t
    WHERE t.driver_id = p_driver_id
      AND t.organization_id = p_org_id
      AND COALESCE(t.pickup_date, t.created_at) >= (SELECT start_dt FROM _period_start)
      AND public.is_org_member(p_org_id)
  ),
  _driver_payments AS (
    SELECT
      to_char(date_trunc('month', COALESCE(tx.transaction_date, tx.created_at)::date), 'YYYY-MM') AS period,
      SUM(COALESCE(tx.amount_out, 0)) AS paid
    FROM public.transactions tx
    WHERE tx.contact_id = p_driver_id
      AND tx.organization_id = p_org_id
      AND tx.contact_type = 'driver'
      AND COALESCE(tx.amount_out, 0) > 0
      AND COALESCE(tx.transaction_date, tx.created_at::date) >= (SELECT start_dt FROM _period_start)
      AND public.is_org_member(p_org_id)
    GROUP BY 1
  ),
  _monthly AS (
    SELECT
      to_char(date_trunc('month', dt.trip_date), 'YYYY-MM') AS period,
      SUM(COALESCE(dt.client_price, 0))                     AS revenue,
      SUM(
        CASE
          WHEN dt.driver_commission IS NOT NULL AND dt.driver_commission > 0
            THEN dt.driver_commission
          WHEN dt.supplier_rate IS NOT NULL AND dt.supplier_rate > 0
            THEN dt.supplier_rate * 0.10
          ELSE COALESCE(dt.client_price, 0) * 0.10
        END
      )                                                    AS earnings,
      COUNT(*)                                             AS trip_count,
      SUM(COALESCE(dt.distance, 0))                        AS km_driven
    FROM _driver_trips dt
    GROUP BY 1
  )
  SELECT
    m.period, m.revenue, m.earnings,
    COALESCE(p.paid, 0) AS paid,
    m.trip_count, m.km_driven
  FROM _monthly m
  LEFT JOIN _driver_payments p ON p.period = m.period
  ORDER BY m.period ASC;
$$;


ALTER FUNCTION "public"."get_driver_monthly_analytics"("p_org_id" "uuid", "p_driver_id" "uuid", "p_months_back" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_driver_phone_active_trip"("p_phone" "text", "p_exclude_trip_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last10 text;
  v_trip_id uuid;
  v_trip_number text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('is_busy', false);
  END IF;

  v_last10 := right(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), 10);
  IF length(v_last10) < 10 THEN
    RETURN jsonb_build_object('is_busy', false);
  END IF;

  SELECT t.id, coalesce(nullif(trim((to_jsonb(t) ->> 'display_trip_id')), ''), t.trip_number)
  INTO v_trip_id, v_trip_number
  FROM public.trips t
  JOIN public.drivers d ON d.id = t.driver_id
  WHERE (p_exclude_trip_id IS NULL OR t.id <> p_exclude_trip_id)
    AND right(regexp_replace(coalesce(d.phone, ''), '\D', '', 'g'), 10) = v_last10
    AND lower(trim(coalesce(t.status::text, ''))) NOT IN ('completed', 'cancelled', 'done', 'delivered')
  ORDER BY t.updated_at DESC
  LIMIT 1;

  IF v_trip_id IS NULL THEN
    RETURN jsonb_build_object('is_busy', false);
  END IF;

  RETURN jsonb_build_object(
    'is_busy', true,
    'trip_id', v_trip_id,
    'trip_label', coalesce(v_trip_number, 'another active trip')
  );
END;
$$;


ALTER FUNCTION "public"."get_driver_phone_active_trip"("p_phone" "text", "p_exclude_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_driver_phone_active_trip"("p_phone" "text", "p_exclude_trip_id" "uuid") IS 'Returns whether a phone (last-10 digits) is on another non-terminal trip; SECURITY DEFINER for aggregate allocation busy checks. Compatible with schemas that omit trips.display_trip_id.';



CREATE OR REPLACE FUNCTION "public"."get_driver_previous_rows_by_identity"("p_org_id" "uuid", "p_driver_id" "uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "phone" "text", "name" "text", "left_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT d2.id, d2.user_id, d2.phone, d2.name, d2.left_at, d2.created_at
  FROM   public.drivers d1
  JOIN   public.drivers d2
         ON  d2.organization_id = d1.organization_id
         AND d2.id             <> d1.id
         AND d2.left_at        IS NOT NULL
         AND (
               -- same linked account
               (d1.user_id IS NOT NULL AND d1.user_id = d2.user_id)
               OR
               -- same normalized phone
               (
                 d1.phone IS NOT NULL AND d2.phone IS NOT NULL
                 AND RIGHT(REGEXP_REPLACE(d1.phone, '[^0-9]', '', 'g'), 10)
                   = RIGHT(REGEXP_REPLACE(d2.phone, '[^0-9]', '', 'g'), 10)
               )
             )
  WHERE  d1.id             = p_driver_id
    AND  d1.organization_id = p_org_id
    AND  d1.organization_id IN (
           SELECT om.organization_id
           FROM   public.organization_members om
           WHERE  om.user_id = auth.uid()
         )
  ORDER BY d2.left_at DESC;
$$;


ALTER FUNCTION "public"."get_driver_previous_rows_by_identity"("p_org_id" "uuid", "p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_driver_profile_display"("p_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_res jsonb;
BEGIN
  SELECT d.user_id INTO v_user_id FROM public.drivers d WHERE d.id = p_driver_id;
  IF v_user_id IS NULL THEN RETURN NULL; END IF;

  SELECT jsonb_build_object(
    'fullName', coalesce(p.full_name, ''),
    'avatarUrl', coalesce(p.avatar_url, ''),
    'avatarSeed', coalesce(p.avatar_seed, '')
  ) INTO v_res
  FROM public.profiles p
  WHERE p.id = v_user_id;

  RETURN v_res;
END;
$$;


