CREATE OR REPLACE FUNCTION "public"."get_drivers_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_deleted   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(d) ORDER BY d.updated_at) FILTER (WHERE d.deleted_at IS NULL), '[]'),
    COALESCE(jsonb_agg(d.id::TEXT)                           FILTER (WHERE d.deleted_at IS NOT NULL), '[]'),
    MAX(d.updated_at)::TEXT
  INTO v_changed, v_deleted, v_next
  FROM (
    SELECT * FROM drivers
    WHERE organization_id = p_org_id
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) d;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  v_deleted,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


ALTER FUNCTION "public"."get_drivers_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_drivers_with_profiles"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "user_id" "uuid", "name" "text", "phone" "text", "email" "text", "status" "text", "assigned_vehicle_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "left_at" timestamp with time zone, "tracking_only" boolean, "payable_amount" numeric, "commission_percent" numeric, "commission_per_km" numeric, "avatar_url" "text", "avatar_seed" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    d.id,
    d.organization_id,
    d.user_id,
    d.name,
    d.phone,
    COALESCE(
      NULLIF(BTRIM(COALESCE(d.email, '')::text), ''),
      NULLIF(BTRIM(COALESCE(p.email, '')::text), '')
    ) AS email,
    d.status,
    d.assigned_vehicle_id,
    d.created_at,
    d.updated_at,
    d.left_at,
    d.tracking_only,
    d.payable_amount,
    d.commission_percent,
    d.commission_per_km,
    p.avatar_url,
    p.avatar_seed
  FROM public.drivers d
  LEFT JOIN public.profiles p ON p.id = d.user_id
  WHERE d.organization_id = p_org_id
  ORDER BY d.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_drivers_with_profiles"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_by_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_normalized text;
  v_email text;
BEGIN
  v_normalized := regexp_replace(coalesce(trim(p_phone), ''), '\s+', '', 'g');
  v_normalized := regexp_replace(v_normalized, '\D', '', 'g');
  IF length(v_normalized) >= 12 AND left(v_normalized, 2) = '91' THEN
    v_normalized := right(v_normalized, 10);
  ELSIF length(v_normalized) >= 10 THEN
    v_normalized := right(v_normalized, 10);
  END IF;
  IF v_normalized = '' OR length(v_normalized) < 10 THEN
    RETURN NULL;
  END IF;

  SELECT trim(pr.email) INTO v_email
  FROM public.profiles pr,
       LATERAL (
         SELECT
           CASE
             WHEN length(d) >= 12 AND left(d, 2) = '91' THEN right(d, 10)
             WHEN length(d) >= 10 THEN right(d, 10)
             ELSE d
           END AS norm
         FROM (
           SELECT regexp_replace(regexp_replace(coalesce(trim(pr.phone), ''), '\s+', '', 'g'), '\D', '', 'g') AS d
         ) x
       ) y
  WHERE pr.phone IS NOT NULL
    AND trim(pr.phone) <> ''
    AND trim(coalesce(pr.email, '')) <> ''
    AND y.norm = v_normalized
  LIMIT 1;

  RETURN v_email;
END;
$$;


ALTER FUNCTION "public"."get_email_by_phone"("p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_email_by_phone"("p_phone" "text") IS 'Returns email for a profile with the given phone (normalized to 10 digits). Used for sign-up inline "already registered" check. Anon can call.';



CREATE OR REPLACE FUNCTION "public"."get_expiring_documents"("p_org_id" "uuid", "p_days_ahead" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "entity_type" "text", "entity_id" "uuid", "doc_type" "text", "doc_label" "text", "doc_number" "text", "expiry_date" "date", "days_until" integer, "status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    id, entity_type, entity_id, doc_type, doc_label, doc_number, expiry_date,
    (expiry_date - CURRENT_DATE)::int AS days_until,
    status
  FROM public.entity_documents
  WHERE organization_id = p_org_id
    AND expiry_date IS NOT NULL
    AND expiry_date >= CURRENT_DATE - INTERVAL '1 day'
    AND expiry_date <= CURRENT_DATE + (p_days_ahead || ' days')::interval
    AND status NOT IN ('replaced', 'rejected')
    AND public.is_org_member(p_org_id)
  ORDER BY expiry_date ASC;
$$;


ALTER FUNCTION "public"."get_expiring_documents"("p_org_id" "uuid", "p_days_ahead" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_global_app_bootstrap"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_active_trips   JSONB;
  v_global_alerts  JSONB;
  v_notifications  JSONB;
  v_network_status JSONB;
BEGIN

  -- ── 1. Active trips ─────────────────────────────────────────────────────────
  -- LATERAL JOIN pattern: PostgreSQL stops scanning trip_messages after LIMIT 50
  -- per trip — O(50 × trips) instead of O(all_messages) with ROW_NUMBER().
  -- The inner subquery fetches DESC (newest first, cheapest with a btree index),
  -- then the outer jsonb_agg re-orders ASC for chronological display.

  SELECT COALESCE(jsonb_agg(trip_obj ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_active_trips
  FROM (
    SELECT
      id, trip_number, display_trip_id, status,
      pickup_area, drop_location,
      driver_display_name, vehicle_display_number,
      driver_id, supplier_id, client_id, created_at
    FROM trips
    WHERE organization_id = p_org_id
      AND status NOT IN ('completed', 'cancelled')
    ORDER BY created_at DESC
    LIMIT 100
  ) t
  LEFT JOIN LATERAL (
    SELECT
      COALESCE(SUM(tc.unread_dispatcher_count), 0) AS total_unread,
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'conversation_id',     tc.id,
            'party_type',          tc.party_type,
            'party_name',          tc.party_name,
            'organization_id',     tc.organization_id,
            'unread_count',        COALESCE(tc.unread_dispatcher_count, 0),
            'client_id',           tc.client_id,
            'supplier_id',         tc.supplier_id,
            'driver_id',           tc.driver_id,
            'last_message_at',     tc.last_message_at,
            'last_message_preview', tc.last_message_preview
          )
        ),
        '[]'::jsonb
      ) AS conversations
    FROM trip_conversations tc
    WHERE tc.trip_id = t.id
      AND tc.organization_id = p_org_id
  ) convs ON true
  LEFT JOIN LATERAL (
    -- Fetch the 50 most-recent messages for this trip across all party lanes,
    -- then re-aggregate them in ASC order for the frontend event_stream.
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id',              ranked.id,
          'conversation_id', ranked.conversation_id,
          'party_type',      ranked.party_type,
          'content',         ranked.content,
          'message_type',    ranked.message_type,
          'sender_role',     ranked.sender_role,
          'sender_name',     ranked.sender_name,
          'metadata',        ranked.metadata,
          'visibility_tags', COALESCE(ranked.visibility_tags, '[]'::jsonb),
          'is_read',         ranked.is_read,
          'created_at',      ranked.created_at
        )
        ORDER BY ranked.created_at ASC
      ),
      '[]'::jsonb
    ) AS recent_events
    FROM (
      SELECT
        m.id,
        m.conversation_id,
        tc_m.party_type,
        m.content,
        m.message_type,
        m.sender_role,
        m.sender_name,
        m.metadata,
        m.visibility_tags,
        m.is_read,
        m.created_at
      FROM trip_messages m
      INNER JOIN trip_conversations tc_m
        ON tc_m.id = m.conversation_id
        AND tc_m.trip_id = t.id
        AND tc_m.organization_id = p_org_id
      WHERE (
        -- No tags → legacy broadcast, always include
        m.visibility_tags IS NULL
        OR jsonb_array_length(m.visibility_tags) = 0
        -- Tagged → at least one tag must reference a conversation owned by p_org_id
        OR EXISTS (
          SELECT 1
          FROM trip_conversations tc_vis
          WHERE tc_vis.trip_id = t.id
            AND tc_vis.organization_id = p_org_id
            AND m.visibility_tags @> to_jsonb(tc_vis.id::text)
        )
      )
      ORDER BY m.created_at DESC
      LIMIT 50
    ) ranked
  ) msgs ON true
  CROSS JOIN LATERAL (
    SELECT jsonb_build_object(
      'trip_id',                t.id,
      'trip_number',            t.trip_number,
      'display_trip_id',        t.display_trip_id,
      'status',                 t.status,
      'pickup_area',            t.pickup_area,
      'drop_location',          t.drop_location,
      'driver_display_name',    t.driver_display_name,
      'vehicle_display_number', t.vehicle_display_number,
      'driver_id',              t.driver_id,
      'supplier_id',            t.supplier_id,
      'client_id',              t.client_id,
      'created_at',             t.created_at,
      'total_unread',           COALESCE(convs.total_unread, 0),
      'conversations',          COALESCE(convs.conversations, '[]'::jsonb),
      'recent_events',          msgs.recent_events
    ) AS trip_obj
  ) build;


  -- ── 2. Global alerts ─────────────────────────────────────────────────────────
  -- Unchanged from v1.

  WITH alert_rows AS (
    SELECT
      'salary_' || sr.id::text               AS id,
      'salary_request'                        AS source,
      sr.id::text                             AS source_id,
      'salary_request_pending'                AS alert_type,
      'warning'                               AS severity,
      'Pending Salary Request'                AS title,
      'Amount: ₹' || sr.amount::text          AS body,
      sr.amount                               AS amount,
      sr.driver_id                            AS driver_id,
      NULL::uuid                              AS trip_id,
      sr.created_at
    FROM driver_salary_requests sr
    WHERE sr.organization_id = p_org_id
      AND sr.status = 'pending'
      AND sr.created_at < NOW() - INTERVAL '2 hours'

    UNION ALL

    SELECT
      'dispute_' || d.id::text                          AS id,
      'dispute'                                         AS source,
      d.id::text                                        AS source_id,
      'dispute_received'                                AS alert_type,
      'critical'                                        AS severity,
      'Dispute Received'                                AS title,
      'Partner raised a dispute. Amount: ₹' || d.partner_snapshot::text AS body,
      d.partner_snapshot                                AS amount,
      NULL::uuid                                        AS driver_id,
      NULL::uuid                                        AS trip_id,
      d.created_at
    FROM dispute d
    WHERE d.partner_org_id = p_org_id
      AND d.status = 'OPEN'
  )
  SELECT COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id',         ar.id,
          'source',     ar.source,
          'source_id',  ar.source_id,
          'alert_type', ar.alert_type,
          'severity',   ar.severity,
          'title',      ar.title,
          'body',       ar.body,
          'amount',     ar.amount,
          'driver_id',  ar.driver_id,
          'trip_id',    ar.trip_id,
          'created_at', ar.created_at
        )
      )
      FROM (
        SELECT * FROM alert_rows
        ORDER BY created_at DESC
        LIMIT 25
      ) ar
    ),
    '[]'::jsonb
  )
  INTO v_global_alerts;


  -- ── 3. Notifications ─────────────────────────────────────────────────────────
  -- Cap raised from 10 → 25.

  WITH notif_rows AS (
    SELECT
      'salary_' || sr.id::text                          AS id,
      'salary_request'                                  AS source,
      sr.id::text                                       AS source_id,
      'Salary Request'                                  AS title,
      INITCAP(sr.request_type)                          AS subtitle,
      sr.amount                                         AS amount_meta,
      (sr.status <> 'pending')                          AS is_read,
      sr.created_at
    FROM driver_salary_requests sr
    WHERE sr.organization_id = p_org_id

    UNION ALL

    SELECT
      'dispute_' || d.id::text                          AS id,
      'dispute'                                         AS source,
      d.id::text                                        AS source_id,
      CASE
        WHEN d.raised_by_org_id = p_org_id THEN 'Dispute Raised'
        ELSE 'Dispute Received'
      END                                               AS title,
      'Status: ' || d.status                            AS subtitle,
      d.partner_snapshot                                AS amount_meta,
      (d.status <> 'OPEN')                              AS is_read,
      d.created_at
    FROM dispute d
    WHERE d.raised_by_org_id = p_org_id
       OR d.partner_org_id   = p_org_id
  ),
  notif_agg AS (
    SELECT
      COUNT(*) FILTER (WHERE NOT is_read)  AS unread_count,
      jsonb_agg(
        jsonb_build_object(
          'id',          n.id,
          'source',      n.source,
          'source_id',   n.source_id,
          'title',       n.title,
          'subtitle',    n.subtitle,
          'amount_meta', n.amount_meta,
          'is_read',     n.is_read,
          'created_at',  n.created_at
        )
        ORDER BY n.created_at DESC
      ) AS all_rows
    FROM notif_rows n
  )
  SELECT jsonb_build_object(
    'unread_count', COALESCE(na.unread_count, 0),
    'rows',         COALESCE(
      (
        SELECT jsonb_agg(r)
        FROM (
          SELECT jsonb_array_elements(na.all_rows) AS r
          LIMIT 25
        ) sub
      ),
      '[]'::jsonb
    )
  )
  INTO v_notifications
  FROM notif_agg na;


  -- ── 4. Network status ────────────────────────────────────────────────────────
  -- Unchanged from v1.

  WITH link_counts AS (
    SELECT
      COUNT(*)                                          AS total_links,
      COUNT(*) FILTER (WHERE link_type = 'client')     AS client_links,
      COUNT(*) FILTER (WHERE link_type = 'supplier')   AS supplier_links
    FROM organization_links
    WHERE owner_org_id = p_org_id
  ),
  partner_list AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'org_id',    o.id,
        'org_name',  o.name,
        'link_type', ol.link_type
      )
      ORDER BY o.name ASC
    ) AS partner_orgs
    FROM organization_links ol
    JOIN organizations o ON o.id = ol.linked_org_id
    WHERE ol.owner_org_id = p_org_id
  )
  SELECT jsonb_build_object(
    'total_links',    COALESCE(lc.total_links, 0),
    'client_links',   COALESCE(lc.client_links, 0),
    'supplier_links', COALESCE(lc.supplier_links, 0),
    'partner_orgs',   COALESCE(pl.partner_orgs, '[]'::jsonb)
  )
  INTO v_network_status
  FROM link_counts lc
  CROSS JOIN partner_list pl;


  -- ── Result ───────────────────────────────────────────────────────────────────

  RETURN jsonb_build_object(
    'active_trips',   COALESCE(v_active_trips,   '[]'::jsonb),
    'global_alerts',  COALESCE(v_global_alerts,  '[]'::jsonb),
    'notifications',  COALESCE(v_notifications,  '{"unread_count":0,"rows":[]}'::jsonb),
    'network_status', COALESCE(v_network_status, '{"total_links":0,"client_links":0,"supplier_links":0,"partner_orgs":[]}'::jsonb)
  );

END;
$$;


ALTER FUNCTION "public"."get_global_app_bootstrap"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_global_app_bootstrap"("p_org_id" "uuid") IS 'Global single-shot bootstrap RPC v2. Returns active trips (up to 100) each with conversations[] (per-party metadata) and recent_events[] (up to 50 messages, LATERAL JOIN for O(50×trips) efficiency). Visibility filter applied at SQL level. Also returns operational alerts, notification feed (25 rows), and network status. After this call the frontend uses only Realtime — no further SELECT queries.';



CREATE OR REPLACE FUNCTION "public"."get_identity_health"("p_since" timestamp with time zone DEFAULT ("now"() - '01:00:00'::interval)) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'window_start',       p_since,
    'window_end',         now(),
    'total_generated',    count(*),
    'fallback_count',     count(*) FILTER (WHERE path != 'trigger'),
    'fallback_pct',       round(
                            100.0 * count(*) FILTER (WHERE path != 'trigger') /
                            nullif(count(*), 0), 2
                          ),
    'avg_latency_ms',     round(avg(latency_ms)::numeric, 3),
    'p99_latency_ms',     round(percentile_cont(0.99) WITHIN GROUP (ORDER BY latency_ms)::numeric, 3),
    'by_entity_type',     (
      SELECT jsonb_object_agg(entity_type, cnt)
      FROM (
        SELECT entity_type, count(*) AS cnt
        FROM public.id_generation_log
        WHERE created_at >= p_since
        GROUP BY entity_type
      ) t
    ),
    'uuidv7_enabled',     true,
    'global_refs_issued', (SELECT count(*) FROM public.global_references WHERE issued_at >= p_since),
    'network_ids_issued', (SELECT count(*) FROM public.network_identities WHERE created_at >= p_since)
  )
  FROM public.id_generation_log
  WHERE created_at >= p_since;
$$;


ALTER FUNCTION "public"."get_identity_health"("p_since" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_identity_health"("p_since" timestamp with time zone) IS 'Lightweight identity monitoring snapshot — call every 60s from health checker.';



CREATE OR REPLACE FUNCTION "public"."get_indents_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_deleted   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(i) ORDER BY i.updated_at) FILTER (WHERE i.deleted_at IS NULL), '[]'),
    COALESCE(jsonb_agg(i.id::TEXT)                           FILTER (WHERE i.deleted_at IS NOT NULL), '[]'),
    MAX(i.updated_at)::TEXT
  INTO v_changed, v_deleted, v_next
  FROM (
    SELECT * FROM indents
    WHERE organization_id = p_org_id
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) i;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  v_deleted,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


ALTER FUNCTION "public"."get_indents_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_initial_chat_state"("p_organization_id" "uuid", "p_message_limit" integer DEFAULT 50, "p_trip_limit" integer DEFAULT NULL::integer, "p_trip_offset" integer DEFAULT 0, "p_hub_trip_bucket" "text" DEFAULT 'active'::"text", "p_include_message_bodies" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bucket text;
BEGIN
  v_bucket := lower(trim(coalesce(p_hub_trip_bucket, 'active')));
  IF v_bucket NOT IN ('active', 'history', 'all') THEN
    v_bucket := 'active';
  END IF;

  RETURN (
    SELECT COALESCE(
      jsonb_agg(c ORDER BY (c->>'last_message_at') DESC NULLS LAST),
      '[]'::jsonb
    )
    FROM (
      SELECT jsonb_build_object(
        'id',                      tc.id,
        'organization_id',         tc.organization_id,
        'trip_organization_id',    t.organization_id,
        'trip_organization_name',  o_trip.name,
        'indent_creator_organization_name',
          (
            COALESCE(
              (
                SELECT o_ind.name::text
                FROM public.indents ind
                JOIN public.organizations o_ind ON o_ind.id = ind.organization_id
                WHERE ind.id = t.indent_id
              ),
              (
                SELECT o_ship.name::text
                FROM public.trips t_ship
                JOIN public.indents ind2 ON ind2.id = t_ship.indent_id
                JOIN public.organizations o_ship ON o_ship.id = ind2.organization_id
                WHERE t_ship.trip_number = t.trip_number
                  AND t_ship.indent_id IS NOT NULL
                  AND ind2.organization_id IS DISTINCT FROM p_organization_id
                LIMIT 1
              )
            )
          ),
        'trip_id',                 tc.trip_id,
        'indent_id',               t.indent_id,
        'party_type',              tc.party_type,
        'party_name',              tc.party_name,
        'client_id',               tc.client_id,
        'supplier_id',             tc.supplier_id,
        'driver_id',               tc.driver_id,
        'last_message_at',         tc.last_message_at,
        'last_message_preview',    tc.last_message_preview,
        'unread_dispatcher_count', COALESCE(tc.unread_dispatcher_count, 0),
        'created_at',              tc.created_at,
        'updated_at',              tc.updated_at,
        'trip_number',             t.trip_number,
        'display_trip_id',         t.display_trip_id,
        'trip_status',             t.status,
        'trip_driver_id',          t.driver_id,
        'trip_supplier_id',        t.supplier_id,
        'trip_created_at',         t.created_at,
        'trip_source',             COALESCE(t.source::text, ''),
        'pickup_area',             t.pickup_area,
        'drop_location',           t.drop_location,
        'trip_feedback_status', (
          CASE
            WHEN EXISTS (
              SELECT 1
              FROM   public.trip_messages m
              WHERE  m.conversation_id = tc.id
                AND  m.message_type IN ('feedback_request', 'feedback')
                AND  (m.metadata->>'submitted_at') IS NOT NULL
            )
            THEN 'rated'
            WHEN EXISTS (
              SELECT 1
              FROM   public.trip_messages m
              WHERE  m.conversation_id = tc.id
                AND  m.message_type IN ('feedback_request', 'feedback')
                AND  (m.metadata->>'submitted_at') IS NULL
                AND  COALESCE(m.metadata->>'rating_status', '') <> 'rated'
            )
            THEN 'pending'
            ELSE 'none'
          END
        ),
        'messages', CASE WHEN p_include_message_bodies THEN COALESCE((
          SELECT jsonb_agg(msg_row ORDER BY msg_row->>'created_at' ASC)
          FROM (
            SELECT jsonb_build_object(
              'id',                 tm.id,
              'conversation_id',    tm.conversation_id,
              'organization_id',    tm.organization_id,
              'sender_user_id',     tm.sender_user_id,
              'sender_role',        tm.sender_role,
              'sender_name',        tm.sender_name,
              'content',            tm.content,
              'message_type',       tm.message_type,
              'metadata',           tm.metadata,
              'is_read',            tm.is_read,
              'read_at',            tm.read_at,
              'created_at',         tm.created_at,
              'sender_avatar_seed', tm.sender_avatar_seed,
              'is_delivered',       COALESCE(tm.is_delivered, FALSE),
              'delivered_at',       tm.delivered_at,
              'reactions',          COALESCE(tm.reactions, '{}'::jsonb),
              'reply_to_id',        tm.reply_to_id,
              'reply_to_preview',   tm.reply_to_preview,
              'edited_at',          tm.edited_at
            ) AS msg_row
            FROM (
              SELECT *
              FROM   public.trip_messages m
              WHERE  m.conversation_id = tc.id
                AND  (
                  m.message_type NOT IN ('ledger_event', 'ledger', 'payment', 'ledger_update')
                  OR COALESCE(
                    nullif(trim(m.metadata->>'sender_org_id'), ''),
                    nullif(trim(m.metadata->'event_payload'->>'sender_org_id'), '')
                  ) = p_organization_id::text
                  OR COALESCE(
                    nullif(trim(m.metadata->>'receiver_org_id'), ''),
                    nullif(trim(m.metadata->'event_payload'->>'receiver_org_id'), '')
                  ) = p_organization_id::text
                )
              ORDER  BY m.created_at DESC
              LIMIT  p_message_limit
            ) tm
          ) sub
        ), '[]'::jsonb) ELSE '[]'::jsonb END
      ) AS c
      FROM  public.trip_conversations tc
      JOIN  public.trips              t ON t.id = tc.trip_id
      LEFT  JOIN public.organizations o_trip ON o_trip.id = t.organization_id
      WHERE (
        tc.organization_id = p_organization_id
        OR tc.trip_id IN (
          SELECT tr.id
          FROM   public.trips tr
          WHERE  tr.status NOT IN ('cancelled')
            AND  EXISTS (
              SELECT 1 FROM public.suppliers s
              WHERE  s.id = tr.supplier_id
                AND  s.linked_organization_id = p_organization_id
            )
          LIMIT 500
        )
      )
        AND t.status <> 'cancelled'
        AND (
          v_bucket = 'all'
          OR (
            v_bucket = 'active'
            AND lower(trim(coalesce(t.status::text, ''))) NOT IN ('completed', 'delivered', 'done')
          )
          OR (
            v_bucket = 'history'
            AND lower(trim(coalesce(t.status::text, ''))) IN ('completed', 'delivered', 'done')
          )
        )
        AND (
          p_trip_limit IS NULL
          OR tc.trip_id IN (
            SELECT r.trip_id
            FROM (
              SELECT
                agg.trip_id,
                ROW_NUMBER() OVER (
                  ORDER BY
                    CASE WHEN agg.max_unread > 0 THEN 0 ELSE 1 END,
                    agg.late_flag DESC,
                    agg.last_at DESC NULLS LAST
                ) AS rn
              FROM (
                SELECT
                  base.trip_id,
                  MAX(COALESCE(tc2.unread_dispatcher_count, 0))::int AS max_unread,
                  MAX(tc2.last_message_at) AS last_at,
                  MAX(
                    CASE
                      WHEN h.health_status IN ('LATE_RISK', 'CRITICAL_DELAY')
                      THEN 1
                      ELSE 0
                    END
                  )::int AS late_flag
                FROM (
                  SELECT DISTINCT tc0.trip_id AS trip_id
                  FROM   public.trip_conversations tc0
                  JOIN   public.trips t0 ON t0.id = tc0.trip_id
                  WHERE (
                    tc0.organization_id = p_organization_id
                    OR tc0.trip_id IN (
                      SELECT tr2.id
                      FROM   public.trips tr2
                      WHERE  tr2.status NOT IN ('cancelled')
                        AND  EXISTS (
                          SELECT 1 FROM public.suppliers s2
                          WHERE  s2.id = tr2.supplier_id
                            AND  s2.linked_organization_id = p_organization_id
                        )
                      LIMIT 500
                    )
                  )
                    AND t0.status <> 'cancelled'
                    AND (
                      v_bucket = 'all'
                      OR (
                        v_bucket = 'active'
                        AND lower(trim(coalesce(t0.status::text, ''))) NOT IN ('completed', 'delivered', 'done')
                      )
                      OR (
                        v_bucket = 'history'
                        AND lower(trim(coalesce(t0.status::text, ''))) IN ('completed', 'delivered', 'done')
                      )
                    )
                ) base
                JOIN public.trip_conversations tc2 ON tc2.trip_id = base.trip_id
                LEFT JOIN public.v_long_haul_health h ON h.trip_id = base.trip_id
                GROUP BY base.trip_id
              ) agg
            ) r
            WHERE r.rn > p_trip_offset
              AND r.rn <= p_trip_offset + p_trip_limit
          )
        )
    ) rows
  );
END;
$$;


ALTER FUNCTION "public"."get_initial_chat_state"("p_organization_id" "uuid", "p_message_limit" integer, "p_trip_limit" integer, "p_trip_offset" integer, "p_hub_trip_bucket" "text", "p_include_message_bodies" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_initial_chat_state"("p_organization_id" "uuid", "p_message_limit" integer, "p_trip_limit" integer, "p_trip_offset" integer, "p_hub_trip_bucket" "text", "p_include_message_bodies" boolean) IS 'Bootstrap conversations + messages; includes reactions/replies/edits on embedded message rows.';



CREATE OR REPLACE FUNCTION "public"."get_integrated_partners"("p_org_id" "uuid") RETURNS json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'suppliers', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'company_name', s.company_name,
          'name', s.name,
          'linked_organization_id', s.linked_organization_id
        )
      ), '[]'::json)
      FROM suppliers s
      WHERE s.organization_id = p_org_id
        AND s.linked_organization_id IS NOT NULL
      LIMIT 500
    ),
    'clients', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'name', c.name,
          'linked_organization_id', c.linked_organization_id
        )
      ), '[]'::json)
      FROM clients c
      WHERE c.organization_id = p_org_id
        AND c.linked_organization_id IS NOT NULL
      LIMIT 500
    )
  );
$$;


ALTER FUNCTION "public"."get_integrated_partners"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invitee_by_phone"("p_phone" "text") RETURNS TABLE("organization_id" "uuid", "full_name" "text", "phone" "text", "organization_name" "text", "profile_company_name" "text", "profile_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_uid uuid;
  v_caller_has_active_org boolean;
  v_user_id uuid;
  v_org_id uuid;
  v_name text;
  v_phone text;
  v_normalized text;
  v_stored_normalized text;
  v_meta jsonb;
  v_phone_elem text;
  v_org_name text;
  v_profile_company text;
  v_profile_role text;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.organization_members om
    WHERE om.user_id = v_uid
      AND om.status = 'active'
  )
  INTO v_caller_has_active_org;

  IF NOT v_caller_has_active_org THEN
    RAISE EXCEPTION 'No active organization membership';
  END IF;

  PERFORM public.enforce_rpc_rate_limit('get_invitee_by_phone', 10, interval '1 minute');

  v_normalized := regexp_replace(coalesce(trim(p_phone), ''), '\s+', '', 'g');
  v_normalized := regexp_replace(v_normalized, '\D', '', 'g');
  IF length(v_normalized) >= 12 AND left(v_normalized, 2) = '91' THEN
    v_normalized := right(v_normalized, 10);
  ELSIF length(v_normalized) >= 10 THEN
    v_normalized := right(v_normalized, 10);
  END IF;
  IF v_normalized = '' THEN
    RETURN;
  END IF;

  FOR v_user_id, v_name, v_phone, v_profile_role IN
    SELECT
      pr.id,
      trim(coalesce(pr.full_name, '')),
      trim(coalesce(pr.phone, '')),
      lower(trim(coalesce(pr.role, '')))
    FROM public.profiles pr
    WHERE pr.phone IS NOT NULL AND trim(pr.phone) <> ''
  LOOP
    v_stored_normalized := regexp_replace(regexp_replace(v_phone, '\s+', '', 'g'), '\D', '', 'g');
    IF length(v_stored_normalized) >= 12 AND left(v_stored_normalized, 2) = '91' THEN
      v_stored_normalized := right(v_stored_normalized, 10);
    ELSIF length(v_stored_normalized) >= 10 THEN
      v_stored_normalized := right(v_stored_normalized, 10);
    END IF;
    IF v_stored_normalized = v_normalized THEN
      v_org_id := NULL;
      SELECT om.organization_id INTO v_org_id
      FROM public.organization_members om
      WHERE om.user_id = v_user_id AND om.status = 'active'
      LIMIT 1;
      IF v_org_id IS NULL THEN
        SELECT o.id INTO v_org_id
        FROM public.organizations o
        WHERE o.owner_id = v_user_id
        LIMIT 1;
      END IF;
      IF v_org_id IS NOT NULL THEN
        SELECT trim(coalesce(o.name, '')) INTO v_org_name FROM public.organizations o WHERE o.id = v_org_id LIMIT 1;
        SELECT trim(coalesce(pr.company_name, '')) INTO v_profile_company FROM public.profiles pr WHERE pr.id = v_user_id LIMIT 1;
        organization_id := v_org_id;
        full_name := CASE WHEN v_name <> '' THEN v_name ELSE v_phone END;
        phone := v_phone;
        organization_name := coalesce(v_org_name, '');
        profile_company_name := nullif(v_profile_company, '');
        profile_role := coalesce(nullif(v_profile_role, ''), '');
        RETURN NEXT;
      END IF;
      RETURN;
    END IF;
  END LOOP;

  FOR v_user_id, v_meta IN
    SELECT u.id, u.raw_user_meta_data
    FROM auth.users u
    WHERE u.raw_user_meta_data IS NOT NULL
  LOOP
    v_name := trim(coalesce(v_meta->>'full_name', v_meta->>'name', ''));
    v_phone := trim(coalesce(v_meta->>'phone', ''));

    v_stored_normalized := regexp_replace(regexp_replace(v_phone, '\s+', '', 'g'), '\D', '', 'g');
    IF length(v_stored_normalized) >= 10 THEN v_stored_normalized := right(v_stored_normalized, 10); END IF;
    IF v_stored_normalized = v_normalized THEN
      v_org_id := NULL;
      SELECT om.organization_id INTO v_org_id
      FROM public.organization_members om
      WHERE om.user_id = v_user_id AND om.status = 'active'
      LIMIT 1;
      IF v_org_id IS NULL THEN
        SELECT o.id INTO v_org_id
        FROM public.organizations o
        WHERE o.owner_id = v_user_id
        LIMIT 1;
      END IF;
      IF v_org_id IS NOT NULL THEN
        SELECT trim(coalesce(o.name, '')) INTO v_org_name FROM public.organizations o WHERE o.id = v_org_id LIMIT 1;
        SELECT
          trim(coalesce(pr.company_name, '')),
          lower(trim(coalesce(pr.role, '')))
        INTO v_profile_company, v_profile_role
        FROM public.profiles pr
        WHERE pr.id = v_user_id
        LIMIT 1;
        organization_id := v_org_id;
        full_name := CASE WHEN v_name <> '' THEN v_name ELSE v_phone END;
        phone := v_phone;
        organization_name := coalesce(v_org_name, '');
        profile_company_name := nullif(v_profile_company, '');
        profile_role := coalesce(nullif(v_profile_role, ''), '');
        RETURN NEXT;
      END IF;
      RETURN;
    END IF;

    IF jsonb_typeof(v_meta->'phone_numbers') = 'array' THEN
      FOR v_phone_elem IN SELECT jsonb_array_elements_text(v_meta->'phone_numbers')
      LOOP
        v_stored_normalized := regexp_replace(regexp_replace(trim(v_phone_elem), '\s+', '', 'g'), '\D', '', 'g');
        IF length(v_stored_normalized) >= 10 THEN v_stored_normalized := right(v_stored_normalized, 10); END IF;
        IF v_stored_normalized = v_normalized THEN
          v_org_id := NULL;
          SELECT om.organization_id INTO v_org_id
          FROM public.organization_members om
          WHERE om.user_id = v_user_id AND om.status = 'active'
          LIMIT 1;
          IF v_org_id IS NULL THEN
            SELECT o.id INTO v_org_id
            FROM public.organizations o
            WHERE o.owner_id = v_user_id
            LIMIT 1;
          END IF;
          IF v_org_id IS NOT NULL THEN
            SELECT trim(coalesce(o.name, '')) INTO v_org_name FROM public.organizations o WHERE o.id = v_org_id LIMIT 1;
            SELECT
              trim(coalesce(pr.company_name, '')),
              lower(trim(coalesce(pr.role, '')))
            INTO v_profile_company, v_profile_role
            FROM public.profiles pr
            WHERE pr.id = v_user_id
            LIMIT 1;
            organization_id := v_org_id;
            full_name := CASE WHEN v_name <> '' THEN v_name ELSE v_phone_elem END;
            phone := v_phone_elem;
            organization_name := coalesce(v_org_name, '');
            profile_company_name := nullif(v_profile_company, '');
            profile_role := coalesce(nullif(v_profile_role, ''), '');
            RETURN NEXT;
          END IF;
          RETURN;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."get_invitee_by_phone"("p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_invitee_by_phone"("p_phone" "text") IS 'Network invite by phone: profiles.phone then auth metadata. Returns org id, person name, phone, organizations.name, profiles.company_name, profiles.role (lowercase) for form prefill and driver-aware UI.';



CREATE OR REPLACE FUNCTION "public"."get_invitees_by_phones"("p_phones" "text"[]) RETURNS TABLE("phone" "text", "organization_id" "uuid", "full_name" "text", "organization_name" "text", "profile_company_name" "text", "profile_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_uid     uuid;
  v_has_org boolean;
BEGIN
  -- Auth guard (mirrors get_invitee_by_phone)
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.user_id = v_uid AND om.status = 'active'
  ) INTO v_has_org;

  IF NOT v_has_org THEN
    RAISE EXCEPTION 'No active organization membership';
  END IF;

  -- One rate-limit token per batch call (not per phone).
  -- 6 batches / minute is generous for contact-sync (typically runs once per session).
  PERFORM public.enforce_rpc_rate_limit('get_invitees_by_phones', 6, interval '1 minute');

  RETURN QUERY
  WITH
  -- 1. Normalize each input to the canonical last-10-digit form used by the DB.
  --    The same normalization is applied to stored phones below so both sides match.
  inputs AS (
    SELECT
      raw_p                                                                              AS raw,
      right(
        regexp_replace(regexp_replace(raw_p, '\s+', '', 'g'), '\D', '', 'g'),
        10
      )                                                                                  AS norm
    FROM unnest(p_phones) AS raw_p
    WHERE length(
        regexp_replace(regexp_replace(raw_p, '\s+', '', 'g'), '\D', '', 'g')
      ) >= 8  -- skip obviously invalid / too-short strings
  ),

  -- 2. Normalize profiles.phone for set-join comparison (avoids per-row loop).
  prof AS (
    SELECT
      pr.id                                                                              AS uid,
      trim(coalesce(pr.full_name, ''))                                                  AS p_name,
      trim(coalesce(pr.phone, ''))                                                      AS p_phone,
      lower(trim(coalesce(pr.role, '')))                                                AS p_role,
      trim(coalesce(pr.company_name, ''))                                               AS p_company,
      right(
        regexp_replace(regexp_replace(trim(coalesce(pr.phone, '')), '\s+', '', 'g'), '\D', '', 'g'),
        10
      )                                                                                  AS p_norm
    FROM public.profiles pr
    WHERE pr.phone IS NOT NULL
      AND trim(pr.phone) <> ''
      AND length(
            regexp_replace(regexp_replace(trim(pr.phone), '\s+', '', 'g'), '\D', '', 'g')
          ) >= 8
  ),

  -- 3. Match inputs to profiles (one profile per normalized input phone).
  profile_hits AS (
    SELECT DISTINCT ON (i.norm)
      i.raw, i.norm,
      p.uid, p.p_name, p.p_phone, p.p_role, p.p_company
    FROM inputs i
    JOIN prof p ON p.p_norm = i.norm
    ORDER BY i.norm, p.uid
  ),

  -- 4. Resolve organization for each profile-hit user.
  --    Prefer organization_members (active) over organizations.owner_id fallback.
  profile_orgs AS (
    SELECT
      ph.raw, ph.norm, ph.p_name, ph.p_phone, ph.p_role, ph.p_company,
      COALESCE(
        (SELECT om.organization_id
           FROM public.organization_members om
          WHERE om.user_id = ph.uid AND om.status = 'active'
          LIMIT 1),
        (SELECT o2.id
           FROM public.organizations o2
          WHERE o2.owner_id = ph.uid
          LIMIT 1)
      ) AS org_id
    FROM profile_hits ph
  ),

  -- 5. FALLBACK: auth metadata for inputs not resolved via profiles.phone.
  auth_hits AS (
    SELECT DISTINCT ON (i.norm)
      i.raw, i.norm,
      au.id                                                                             AS uid,
      trim(coalesce(au.raw_user_meta_data->>'full_name',
                    au.raw_user_meta_data->>'name', ''))                               AS a_name,
      trim(coalesce(au.raw_user_meta_data->>'phone', ''))                              AS a_phone
    FROM inputs i
    JOIN auth.users au
      ON right(
           regexp_replace(regexp_replace(
             coalesce(au.raw_user_meta_data->>'phone', ''), '\s+', '', 'g'), '\D', '', 'g'),
           10
         ) = i.norm
     AND length(
           regexp_replace(regexp_replace(
             coalesce(au.raw_user_meta_data->>'phone', ''), '\s+', '', 'g'), '\D', '', 'g')
         ) >= 8
    WHERE i.norm NOT IN (SELECT ph.norm FROM profile_hits)
    ORDER BY i.norm, au.id
  ),

  -- 6. Resolve org for auth-fallback hits; pull role and company from profiles if present.
  auth_orgs AS (
    SELECT
      ah.raw, ah.norm, ah.a_name, ah.a_phone,
      lower(trim(coalesce(pr.role, '')))                                                AS p_role,
      trim(coalesce(pr.company_name, ''))                                               AS p_company,
      COALESCE(
        (SELECT om.organization_id
           FROM public.organization_members om
          WHERE om.user_id = ah.uid AND om.status = 'active'
          LIMIT 1),
        (SELECT o2.id
           FROM public.organizations o2
          WHERE o2.owner_id = ah.uid
          LIMIT 1)
      ) AS org_id
    FROM auth_hits ah
    LEFT JOIN public.profiles pr ON pr.id = ah.uid
  )

  -- Profile-based results
  SELECT
    po.raw                                                                               AS phone,
    o.id                                                                                AS organization_id,
    CASE WHEN po.p_name <> '' THEN po.p_name ELSE po.p_phone END                       AS full_name,
    trim(coalesce(o.name, ''))                                                          AS organization_name,
    nullif(po.p_company, '')                                                            AS profile_company_name,
    po.p_role                                                                           AS profile_role
  FROM profile_orgs po
  JOIN public.organizations o ON o.id = po.org_id
  WHERE po.org_id IS NOT NULL

  UNION ALL

  -- Auth-metadata-based results (no profile.phone match)
  SELECT
    ao.raw                                                                               AS phone,
    o.id                                                                                AS organization_id,
    CASE WHEN ao.a_name <> '' THEN ao.a_name ELSE ao.a_phone END                       AS full_name,
    trim(coalesce(o.name, ''))                                                          AS organization_name,
    nullif(ao.p_company, '')                                                            AS profile_company_name,
    ao.p_role                                                                           AS profile_role
  FROM auth_orgs ao
  JOIN public.organizations o ON o.id = ao.org_id
  WHERE ao.org_id IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."get_invitees_by_phones"("p_phones" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_invitees_by_phones"("p_phones" "text"[]) IS 'Batch phone-to-org lookup for contact-sync recommendations. Accepts any phone format; normalizes to last-10-digit form internally. Matches profiles.phone first, then auth metadata. Returns one row per matched active-org user. Rate-limited to 6 calls/minute per user (one token covers the entire batch).';



CREATE OR REPLACE FUNCTION "public"."get_last_n_locations_for_trip"("p_trip_id" "uuid", "p_n" integer DEFAULT 3) RETURNS TABLE("latitude" double precision, "longitude" double precision, "recorded_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver_id uuid;
  v_org_id    uuid;
BEGIN
  IF NOT public.can_access_trip_location(p_trip_id) THEN
    RETURN;
  END IF;

  SELECT driver_id, organization_id INTO v_driver_id, v_org_id
    FROM public.trips WHERE id = p_trip_id LIMIT 1;

  -- Return newest-first so callers can take top 3 without extra sorting
  RETURN QUERY
  SELECT dl.latitude::double precision, dl.longitude::double precision, dl.recorded_at
    FROM public.driver_locations dl
   WHERE dl.trip_id = p_trip_id
   ORDER BY dl.recorded_at DESC
   LIMIT p_n;

  IF v_driver_id IS NOT NULL AND v_org_id IS NOT NULL AND NOT FOUND THEN
    RETURN QUERY
    SELECT dl.latitude::double precision, dl.longitude::double precision, dl.recorded_at
      FROM public.driver_locations dl
     WHERE dl.driver_id = v_driver_id
       AND dl.organization_id = v_org_id
     ORDER BY dl.recorded_at DESC
     LIMIT p_n;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_last_n_locations_for_trip"("p_trip_id" "uuid", "p_n" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_last_n_locations_for_trip"("p_trip_id" "uuid", "p_n" integer) IS 'Returns the last N driver location pings (newest first) for a trip. Accessible by fleet, client, and supplier org members. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_last_trip_location"("p_trip_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT tm.metadata -> 'event_payload' -> 'location_data'
  FROM public.trip_messages tm
  INNER JOIN public.trip_conversations tc ON tc.id = tm.conversation_id
  WHERE tc.trip_id = p_trip_id
    AND tm.message_type = 'system_log'
    AND (tm.metadata -> 'event_payload') ? 'location_data'
  ORDER BY tm.created_at DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_last_trip_location"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_last_trip_location"("p_trip_id" "uuid") IS 'Returns the most recent system_log location_data JSON for bootstrap / map header.';



CREATE OR REPLACE FUNCTION "public"."get_latest_assignment_audit_by_trip_ids"("p_trip_ids" "uuid"[]) RETURNS TABLE("trip_id" "uuid", "changed_by" "uuid", "changed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT ON (a.trip_id)
    a.trip_id,
    a.changed_by,
    a.changed_at
  FROM public.trip_assignment_audit a
  WHERE p_trip_ids IS NOT NULL
    AND cardinality(p_trip_ids) > 0
    AND a.trip_id = ANY (p_trip_ids)
    AND a.event_type IN ('assignment', 'reassignment')
    AND EXISTS (
      SELECT 1
      FROM public.trips t
      WHERE t.id = a.trip_id
        AND (
          public.is_org_member(t.organization_id)
          OR EXISTS (
            SELECT 1
            FROM public.drivers d
            WHERE d.id = t.driver_id
              AND d.user_id = auth.uid()
          )
        )
    )
  ORDER BY a.trip_id, a.changed_at DESC;
$$;


ALTER FUNCTION "public"."get_latest_assignment_audit_by_trip_ids"("p_trip_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_latest_assignment_audit_by_trip_ids"("p_trip_ids" "uuid"[]) IS 'One latest assignment/reassignment audit row per trip_id. Caller must be org member or assigned driver (same as trip_assignment_audit SELECT RLS).';



CREATE OR REPLACE FUNCTION "public"."get_latest_driver_location_for_trip"("p_trip_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver_id uuid;
  v_org_id    uuid;
  v_row       json;
BEGIN
  IF NOT public.can_access_trip_location(p_trip_id) THEN
    RETURN NULL;
  END IF;

  SELECT driver_id, organization_id INTO v_driver_id, v_org_id
    FROM public.trips WHERE id = p_trip_id LIMIT 1;

  -- Prefer by trip_id
  SELECT json_build_object(
    'latitude',    dl.latitude,
    'longitude',   dl.longitude,
    'accuracy',    dl.accuracy,
    'recorded_at', dl.recorded_at
  ) INTO v_row
  FROM public.driver_locations dl
  WHERE dl.trip_id = p_trip_id
  ORDER BY dl.recorded_at DESC
  LIMIT 1;

  IF v_row IS NOT NULL THEN RETURN v_row; END IF;

  -- Fallback: by driver_id + org when driver_locations.trip_id was null on insert
  IF v_driver_id IS NOT NULL AND v_org_id IS NOT NULL THEN
    SELECT json_build_object(
      'latitude',    dl.latitude,
      'longitude',   dl.longitude,
      'accuracy',    dl.accuracy,
      'recorded_at', dl.recorded_at
    ) INTO v_row
    FROM public.driver_locations dl
    WHERE dl.driver_id = v_driver_id
      AND dl.organization_id = v_org_id
    ORDER BY dl.recorded_at DESC
    LIMIT 1;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."get_latest_driver_location_for_trip"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_latest_driver_location_for_trip"("p_trip_id" "uuid") IS 'Latest driver location for a trip. Accessible by fleet, client, and supplier org members. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_multi_lane_bootstrap"("p_organization_id" "uuid", "p_message_limit" integer DEFAULT 50, "p_trip_limit" integer DEFAULT NULL::integer, "p_trip_offset" integer DEFAULT 0, "p_hub_trip_bucket" "text" DEFAULT 'active'::"text", "p_include_message_bodies" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_wrap JSONB;
  v_conv JSONB;
BEGIN
  v_wrap := public.get_unified_b2b_bootstrap(
    p_organization_id,
    p_message_limit,
    p_trip_limit,
    p_trip_offset,
    p_hub_trip_bucket,
    p_include_message_bodies
  );

  IF jsonb_typeof(v_wrap) = 'array' THEN
    v_conv := v_wrap;
    RETURN jsonb_build_object(
      'conversations', v_conv,
      'lanes', public.fn_build_chat_lanes(v_conv),
      'messages_by_context', '[]'::jsonb
    );
  END IF;

  v_conv := coalesce(v_wrap->'conversations', '[]'::jsonb);

  RETURN jsonb_build_object(
    'conversations', coalesce(v_conv, '[]'::jsonb),
    'lanes', public.fn_build_chat_lanes(v_conv),
    'messages_by_context', coalesce(v_wrap->'messages_by_context', '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_multi_lane_bootstrap"("p_organization_id" "uuid", "p_message_limit" integer, "p_trip_limit" integer, "p_trip_offset" integer, "p_hub_trip_bucket" "text", "p_include_message_bodies" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_multi_lane_bootstrap"("p_organization_id" "uuid", "p_message_limit" integer, "p_trip_limit" integer, "p_trip_offset" integer, "p_hub_trip_bucket" "text", "p_include_message_bodies" boolean) IS 'Multi-lane bootstrap: conversations + lanes + messages_by_context; optional trip window; hub bucket.';



CREATE OR REPLACE FUNCTION "public"."get_mutual_connections"("p_viewer_org_id" "uuid", "p_target_org_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "avatar_seed" "text", "avatar_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_org_member(p_viewer_org_id) THEN
    RAISE EXCEPTION 'Access denied for organization %', p_viewer_org_id;
  END IF;

  IF p_viewer_org_id IS NULL OR p_target_org_id IS NULL OR p_viewer_org_id = p_target_org_id THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH viewer_peers AS (
    SELECT
      CASE
        WHEN cr.from_organization_id = p_viewer_org_id THEN cr.to_organization_id
        ELSE cr.from_organization_id
      END AS peer_org_id
    FROM public.connection_requests cr
    WHERE cr.status = 'approved'
      AND (
        cr.from_organization_id = p_viewer_org_id
        OR cr.to_organization_id = p_viewer_org_id
      )
  ),
  mutual_ids AS (
    SELECT vp.peer_org_id AS mutual_org_id
    FROM viewer_peers vp
    WHERE EXISTS (
      SELECT 1
      FROM public.connection_requests cr2
      WHERE cr2.status = 'approved'
        AND (
          (
            cr2.from_organization_id = p_target_org_id
            AND cr2.to_organization_id = vp.peer_org_id
          )
          OR (
            cr2.from_organization_id = vp.peer_org_id
            AND cr2.to_organization_id = p_target_org_id
          )
        )
    )
  )
  SELECT
    o.id,
    o.name,
    o.avatar_seed,
    COALESCE(NULLIF(TRIM(o.logo_url), ''), p.avatar_url) AS avatar_url
  FROM mutual_ids m
  JOIN public.organizations o ON o.id = m.mutual_org_id
  LEFT JOIN public.profiles p ON p.id = o.owner_id
  WHERE o.deleted_at IS NULL
  ORDER BY o.name ASC;
END;
$$;


ALTER FUNCTION "public"."get_mutual_connections"("p_viewer_org_id" "uuid", "p_target_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_mutual_connections"("p_viewer_org_id" "uuid", "p_target_org_id" "uuid") IS 'Organizations connected to both viewer and target (approved org-to-org links). Bypasses connection_requests RLS for cross-org mutual resolution.';



CREATE OR REPLACE FUNCTION "public"."get_my_team_invites"() RETURNS TABLE("id" "uuid", "organization_id" "uuid", "role" "text", "joined_at" timestamp with time zone, "org_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    om.id,
    om.organization_id,
    om.role,
    om.joined_at,
    coalesce(o.name, 'Organization')
  FROM public.organization_members om
  LEFT JOIN public.organizations o ON o.id = om.organization_id
  WHERE om.user_id = (SELECT auth.uid())
    AND om.status = 'invited'
  ORDER BY om.joined_at DESC;
$$;


ALTER FUNCTION "public"."get_my_team_invites"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_network_conversations_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(nc) ORDER BY nc.updated_at), '[]'),
    MAX(nc.updated_at)::TEXT
  INTO v_changed, v_next
  FROM (
    SELECT * FROM network_conversations
    WHERE (org_a_id = p_org_id OR org_b_id = p_org_id)
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) nc;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  '[]'::JSONB,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


ALTER FUNCTION "public"."get_network_conversations_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_network_feed"("p_org_id" "uuid", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "org_name" "text", "org_avatar_seed" "text", "author_user_id" "uuid", "type" "text", "content" "text", "origin" "text", "destination" "text", "load_date" "date", "vehicle_type" "text", "weight_tonnes" numeric, "rate_offer" numeric, "material" "text", "expires_at" timestamp with time zone, "is_active" boolean, "view_count" integer, "bid_count" bigint, "created_at" timestamp with time zone, "source_indent_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p.id,
    p.organization_id,
    o.name AS org_name,
    NULL::text AS org_avatar_seed,
    p.author_user_id,
    p.type,
    p.content,
    p.origin,
    p.destination,
    p.load_date,
    p.vehicle_type,
    p.weight_tonnes,
    p.rate_offer,
    p.material,
    p.expires_at,
    p.is_active,
    p.view_count,
    COALESCE(b.cnt, 0) AS bid_count,
    p.created_at,
    p.source_indent_id
  FROM public.posts p
  JOIN public.organizations o ON o.id = p.organization_id
  LEFT JOIN (
    SELECT post_id, count(*) AS cnt FROM public.bids GROUP BY post_id
  ) b ON b.post_id = p.id
  WHERE p.is_active = true
    AND (
      p.organization_id = p_org_id
      OR p.organization_id IN (
        SELECT cr.to_organization_id
        FROM public.connection_requests cr
        WHERE cr.from_organization_id = p_org_id AND cr.status = 'approved'
        UNION
        SELECT cr.from_organization_id
        FROM public.connection_requests cr
        WHERE cr.to_organization_id = p_org_id AND cr.status = 'approved'
      )
    )
  ORDER BY p.created_at DESC
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."get_network_feed"("p_org_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_next_trip_sequence_for_org"("p_org_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_op_seq  bigint;
  v_org_seq bigint;
  v_max_seq bigint;
BEGIN
  -- Read from operational_sequences (Phase 1+) — authoritative counter
  SELECT current_value INTO v_op_seq
  FROM   public.operational_sequences
  WHERE  organization_id = p_org_id
    AND  entity_type     = 'trip';

  -- Fallback: read from legacy organization_counters
  SELECT trip_seq INTO v_org_seq
  FROM   public.organization_counters
  WHERE  organization_id = p_org_id;

  -- Return max of both counters + 1 (next value to be issued)
  v_max_seq := GREATEST(COALESCE(v_op_seq, 0), COALESCE(v_org_seq, 0));
  RETURN v_max_seq + 1;
END;
$$;


ALTER FUNCTION "public"."get_next_trip_sequence_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ocr_metrics"("p_org_id" "uuid", "p_days" integer DEFAULT 30) RETURNS TABLE("jobs_today" bigint, "jobs_this_month" bigint, "jobs_in_window" bigint, "avg_duration_ms" numeric, "avg_confidence" numeric, "failed_count" bigint, "duplicate_count" bigint, "quota_used" bigint, "quota_limit" bigint, "quota_remaining" bigint, "quota_tier" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_quota jsonb;
  v_limit bigint;
  v_used bigint;
  v_tier text;
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN;
  END IF;

  v_quota := public.check_ocr_scan_quota(p_org_id);
  v_used := COALESCE((v_quota ->> 'used')::bigint, 0);
  v_tier := COALESCE(v_quota ->> 'tier', 'pulse_core');
  v_limit := CASE
    WHEN v_quota ->> 'limit' IS NULL THEN NULL::bigint
    ELSE (v_quota ->> 'limit')::bigint
  END;

  RETURN QUERY
  SELECT
    (
      SELECT count(*)::bigint
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= date_trunc('day', now())
    ) AS jobs_today,
    (
      SELECT count(*)::bigint
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= date_trunc('month', now())
        AND NOT j.is_duplicate
        AND j.status IN ('pending', 'processing', 'completed')
    ) AS jobs_this_month,
    (
      SELECT count(*)::bigint
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= now() - make_interval(days => greatest(p_days, 1))
    ) AS jobs_in_window,
    (
      SELECT round(avg(j.processing_duration_ms), 2)
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= now() - make_interval(days => greatest(p_days, 1))
        AND j.status = 'completed'
    ) AS avg_duration_ms,
    (
      SELECT round(avg(j.confidence_score), 4)
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= now() - make_interval(days => greatest(p_days, 1))
        AND j.status = 'completed'
        AND j.confidence_score IS NOT NULL
    ) AS avg_confidence,
    (
      SELECT count(*)::bigint
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= now() - make_interval(days => greatest(p_days, 1))
        AND j.status = 'failed'
    ) AS failed_count,
    (
      SELECT count(*)::bigint
      FROM public.ocr_jobs j
      WHERE j.organization_id = p_org_id
        AND j.created_at >= now() - make_interval(days => greatest(p_days, 1))
        AND j.is_duplicate
    ) AS duplicate_count,
    v_used AS quota_used,
    v_limit AS quota_limit,
    CASE
      WHEN v_limit IS NULL THEN NULL::bigint
      ELSE greatest(v_limit - v_used, 0)::bigint
    END AS quota_remaining,
    v_tier AS quota_tier;
END;
$$;


ALTER FUNCTION "public"."get_ocr_metrics"("p_org_id" "uuid", "p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ocr_metrics"("p_org_id" "uuid", "p_days" integer) IS 'Pulse Scan dashboard: scans today/month, failures, dedup savings, avg confidence, quota.';



CREATE OR REPLACE FUNCTION "public"."get_org_active_products"("p_org_id" "uuid") RETURNS TABLE("product_id" "text", "status" "text", "activated_at" timestamp with time zone, "trial_ends_at" timestamp with time zone, "expires_at" timestamp with time zone, "billing_cycle" "text", "seats" integer, "days_remaining" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Enforce auth: caller must be member of this org
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = p_org_id
      AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    wp.product_id,
    wp.status,
    wp.activated_at,
    wp.trial_ends_at,
    wp.expires_at,
    wp.billing_cycle,
    wp.seats,
    CASE
      WHEN wp.status = 'trial' AND wp.trial_ends_at IS NOT NULL
        THEN greatest(0, extract(day FROM (wp.trial_ends_at - now()))::int)
      WHEN wp.status = 'active' AND wp.expires_at IS NOT NULL
        THEN greatest(0, extract(day FROM (wp.expires_at - now()))::int)
      ELSE NULL
    END AS days_remaining
  FROM public.workspace_products wp
  WHERE wp.org_id = p_org_id
    AND wp.status IN ('active', 'trial')
  ORDER BY wp.product_id;
END;
$$;


ALTER FUNCTION "public"."get_org_active_products"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_ledger_summary"("p_org_id" "uuid", "p_from" "date" DEFAULT ((CURRENT_DATE - '30 days'::interval))::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("total_in" numeric, "total_out" numeric, "net_balance" numeric, "receivables" numeric, "payables" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(SUM(amount_in), 0),
    COALESCE(SUM(amount_out), 0),
    COALESCE(SUM(amount_in) - SUM(amount_out), 0),
    COALESCE(SUM(CASE WHEN ledger_flow_type = 'receivable' THEN amount_in  ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ledger_flow_type = 'payable'    THEN amount_out ELSE 0 END), 0)
  FROM public.transactions
  WHERE organization_id = p_org_id
    AND transaction_date BETWEEN p_from AND p_to;
$$;


ALTER FUNCTION "public"."get_org_ledger_summary"("p_org_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_members_with_profiles"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "user_id" "uuid", "role" "text", "status" "text", "permissions" "jsonb", "joined_at" timestamp with time zone, "full_name" "text", "email" "text", "avatar_url" "text", "avatar_seed" "text", "phone" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    om.id,
    om.organization_id,
    om.user_id,
    om.role,
    om.status,
    om.permissions,
    om.joined_at,
    p.full_name,
    p.email,
    p.avatar_url,
    p.avatar_seed,
    p.phone
  FROM public.organization_members om
  LEFT JOIN public.profiles p ON p.id = om.user_id
  WHERE om.organization_id = p_org_id
    AND om.status <> 'inactive'
    AND EXISTS (
      SELECT 1 FROM public.organization_members caller
      WHERE caller.organization_id = p_org_id
        AND caller.user_id = (SELECT auth.uid())
        AND caller.status IN ('active', 'invited')
    )
  ORDER BY om.joined_at ASC NULLS LAST;
$$;


