CREATE OR REPLACE FUNCTION "public"."get_org_team_pending_invites"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "invitee_name" "text", "invitee_phone" "text", "invitee_email" "text", "role" "text", "permissions" "jsonb", "status" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "email_conflict" boolean, "conflict_org_names" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    ti.id,
    ti.organization_id,
    ti.invitee_name,
    ti.invitee_phone,
    ti.invitee_email,
    ti.role,
    ti.permissions,
    ti.status,
    ti.created_at,
    ti.expires_at,
    (
      ti.invitee_email IS NOT NULL
      AND trim(ti.invitee_email) <> ''
      AND EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE lower(trim(p.email)) = lower(trim(ti.invitee_email))
      )
    ) AS email_conflict,
    coalesce((
      SELECT array_agg(DISTINCT coalesce(o.name, 'Organization'))
      FROM public.profiles p
      JOIN public.organization_members om ON om.user_id = p.id AND om.status = 'active'
      JOIN public.organizations o ON o.id = om.organization_id
      WHERE ti.invitee_email IS NOT NULL
        AND lower(trim(p.email)) = lower(trim(ti.invitee_email))
        AND om.organization_id <> p_org_id
    ), ARRAY[]::text[]) AS conflict_org_names
  FROM public.organization_team_invites ti
  WHERE ti.organization_id = p_org_id
    AND ti.status = 'pending'
    AND ti.expires_at > now()
    AND public.is_org_member(p_org_id)
  ORDER BY ti.created_at ASC;
$$;


