CREATE OR REPLACE FUNCTION "public"."get_organizations_for_user"() RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "owner_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT o.id, o.name, o.slug, o.owner_id
  FROM public.organizations o
  WHERE EXISTS (
    SELECT 1
    FROM public.organization_members om
    WHERE om.organization_id = o.id
      AND om.user_id = v_uid
      AND om.status = 'active'
  );

  IF FOUND THEN
    RETURN;
  END IF;

  INSERT INTO public.organization_members (organization_id, user_id, role, status)
  SELECT o.id, o.owner_id, 'owner', 'active'
  FROM public.organizations o
  WHERE o.owner_id = v_uid
    AND NOT EXISTS (
      SELECT 1
      FROM public.organization_members om
      WHERE om.organization_id = o.id
        AND om.user_id = o.owner_id
    )
  ON CONFLICT (organization_id, user_id) DO UPDATE
  SET status = 'active', role = 'owner';

  RETURN QUERY
  SELECT o.id, o.name, o.slug, o.owner_id
  FROM public.organizations o
  WHERE o.owner_id = v_uid;
END;
$$;


ALTER FUNCTION "public"."get_organizations_for_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_organizations_for_user"() IS 'Orgs for current user (memberships or owned); backfills owner organization_members when missing.';



CREATE OR REPLACE FUNCTION "public"."get_partner_trip_ids_for_shared_ledger_focus"("org_id" "uuid", "partner_key" "uuid", "viewer_trip_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  partner_org_id_val uuid;
  indent_id_val uuid;
BEGIN
  IF NOT public.is_org_member(org_id) THEN
    RETURN ARRAY[]::uuid[];
  END IF;

  SELECT COALESCE(
    (SELECT c.linked_organization_id FROM public.clients c WHERE c.id = partner_key AND c.organization_id = org_id AND c.linked_organization_id IS NOT NULL LIMIT 1),
    (SELECT s.linked_organization_id FROM public.suppliers s WHERE s.id = partner_key AND s.organization_id = org_id AND s.linked_organization_id IS NOT NULL LIMIT 1)
  ) INTO partner_org_id_val;

  IF partner_org_id_val IS NULL THEN
    RETURN ARRAY[]::uuid[];
  END IF;

  SELECT t.indent_id INTO indent_id_val
  FROM public.trips t
  WHERE t.id = viewer_trip_id
    AND t.organization_id = org_id
  LIMIT 1;

  IF indent_id_val IS NULL THEN
    RETURN ARRAY[]::uuid[];
  END IF;

  RETURN COALESCE(
    ARRAY(
      SELECT t2.id
      FROM public.trips t2
      WHERE t2.organization_id = partner_org_id_val
        AND t2.indent_id = indent_id_val
    ),
    ARRAY[]::uuid[]
  );
END;
$$;


ALTER FUNCTION "public"."get_partner_trip_ids_for_shared_ledger_focus"("org_id" "uuid", "partner_key" "uuid", "viewer_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_partner_trip_ids_for_shared_ledger_focus"("org_id" "uuid", "partner_key" "uuid", "viewer_trip_id" "uuid") IS 'Shared Ledger Compare: partner trip ids sharing indent with viewer trip (cross-org TRP labels).';



CREATE OR REPLACE FUNCTION "public"."get_pending_otp_claim_count"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_phone text;
  v_normalized text;
  v_count int;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('count', 0);
  END IF;

  SELECT coalesce(
    nullif(trim(p.phone), ''),
    nullif(trim(u.phone::text), ''),
    nullif(trim(u.raw_user_meta_data->>'phone'), '')
  )
  INTO v_phone
  FROM auth.users u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = v_uid;

  v_normalized := public.normalise_phone(v_phone);
  IF length(coalesce(v_normalized, '')) < 10 THEN
    RETURN jsonb_build_object('count', 0);
  END IF;

  SELECT count(*)::int INTO v_count
  FROM public.trips t
  JOIN public.drivers d ON d.id = t.driver_id
  WHERE d.user_id IS NULL
    AND d.phone_normalised IS NOT NULL
    AND length(d.phone_normalised) >= 10
    AND d.phone_normalised = v_normalized
    AND lower(coalesce(t.status, '')) IN ('assigned', 'pending', 'scheduled')
    AND NOT (t.source = 'direct_quote' AND t.driver_id IS NOT NULL AND t.vehicle_id IS NOT NULL);

  RETURN jsonb_build_object('count', coalesce(v_count, 0));
END;
$$;


ALTER FUNCTION "public"."get_pending_otp_claim_count"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_pending_otp_claim_count"() IS 'Driver app: count of phone-assigned pending trips awaiting OTP claim (self-healing list logic alignment). Excludes roster-from-LoadHub trips.';



CREATE OR REPLACE FUNCTION "public"."get_pending_otp_trips"() RETURNS SETOF "public"."trips"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_phone text;
  v_normalized text;
  v_trip_id uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  SELECT coalesce(
    nullif(trim(p.phone), ''),
    nullif(trim(u.phone::text), ''),
    nullif(trim(u.raw_user_meta_data->>'phone'), '')
  )
  INTO v_phone
  FROM auth.users u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = v_uid;

  v_normalized := public.normalise_phone(v_phone);
  IF length(coalesce(v_normalized, '')) < 10 THEN
    RETURN;
  END IF;

  FOR v_trip_id IN
    SELECT t.id
    FROM public.trips t
    JOIN public.drivers d ON d.id = t.driver_id
    WHERE d.user_id IS NULL
      AND d.phone_normalised IS NOT NULL
      AND length(d.phone_normalised) >= 10
      AND d.phone_normalised = v_normalized
      AND lower(coalesce(t.status, '')) IN ('assigned', 'pending', 'scheduled')
      AND NOT (t.source = 'direct_quote' AND t.driver_id IS NOT NULL AND t.vehicle_id IS NOT NULL)
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.trip_otps o
      WHERE o.trip_id = v_trip_id
        AND o.used_at IS NULL
        AND o.expires_at > now()
    ) THEN
      PERFORM public.ensure_trip_otp_for_phone_assigned_driver(v_trip_id, 15);
    END IF;
  END LOOP;

  RETURN QUERY
  SELECT t.*
  FROM public.trip_otps o
  JOIN public.trips t ON t.id = o.trip_id
  JOIN public.drivers d ON d.id = t.driver_id
  WHERE o.used_at IS NULL
    AND o.expires_at > now()
    AND d.user_id IS NULL
    AND d.phone_normalised IS NOT NULL
    AND length(d.phone_normalised) >= 10
    AND d.phone_normalised = v_normalized
    AND lower(coalesce(t.status, '')) IN ('assigned', 'pending', 'scheduled')
    AND NOT (t.source = 'direct_quote' AND t.driver_id IS NOT NULL AND t.vehicle_id IS NOT NULL)
  ORDER BY t.pickup_date ASC NULLS LAST, t.created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_pending_otp_trips"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_pending_otp_trips"() IS 'Driver app: phone-preassigned trips waiting for OTP claim; self-heals via ensure_trip_otp_for_phone_assigned_driver.';



CREATE OR REPLACE FUNCTION "public"."get_platform_health"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'identity', (SELECT public.get_identity_health(now() - interval '1 hour')),
    'events', jsonb_build_object(
      'total_24h',        (SELECT count(*) FROM public.event_store WHERE emitted_at > now() - interval '24 hours'),
      'outbox_pending',   (SELECT count(*) FROM public.event_outbox WHERE status = 'pending'),
      'outbox_failed',    (SELECT count(*) FROM public.event_outbox WHERE status = 'failed'),
      'dead_letter_24h',  (SELECT count(*) FROM public.event_dead_letter WHERE created_at > now() - interval '24 hours')
    ),
    'idempotency', jsonb_build_object(
      'pending_keys',     (SELECT count(*) FROM public.idempotency_keys WHERE status = 'pending'),
      'completed_24h',    (SELECT count(*) FROM public.idempotency_keys WHERE status = 'completed' AND completed_at > now() - interval '24 hours'),
      'failed_24h',       (SELECT count(*) FROM public.idempotency_keys WHERE status = 'failed' AND created_at > now() - interval '24 hours')
    ),
    'search', jsonb_build_object(
      'indexed_entities', (SELECT count(*) FROM public.search_index),
      'by_type',          (SELECT jsonb_object_agg(entity_type, cnt) FROM (
                             SELECT entity_type, count(*) AS cnt FROM public.search_index GROUP BY entity_type
                           ) t)
    ),
    'activity', jsonb_build_object(
      'events_24h',       (SELECT count(*) FROM public.activity_stream WHERE created_at > now() - interval '24 hours'),
      'public_events_24h',(SELECT count(*) FROM public.activity_stream WHERE is_public AND created_at > now() - interval '24 hours')
    ),
    'generated_at', now()
  );
$$;


ALTER FUNCTION "public"."get_platform_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pod_reconciliation_summary"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("pod_pending_count" bigint, "pod_pending_sum" numeric, "received_count" bigint, "received_sum" numeric, "approved_count" bigint, "approved_sum" numeric, "invoiced_count" bigint, "invoiced_sum" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  v_org := COALESCE(
    p_organization_id,
    (SELECT organization_id FROM public.profiles WHERE id = auth.uid() LIMIT 1)
  );

  RETURN QUERY
  SELECT
    COUNT(t.id) FILTER (
      WHERE (t.invoice_no IS NULL OR t.invoice_no = '')
        AND (t.invoice_status_1 IS NULL OR t.invoice_status_1 != 'Raised')
        AND (
          t.pod_status ILIKE '%pending%'
          OR t.pod_status ILIKE '%i-bond%'
          OR t.pod_status = ''
          OR t.pod_status IS NULL
          OR t.pod_status = 'partial'
        )
    ) AS pod_pending_count,
    COALESCE(
      SUM(COALESCE(t.total_client_value, t.client_price, 0)) FILTER (
        WHERE (t.invoice_no IS NULL OR t.invoice_no = '')
          AND (t.invoice_status_1 IS NULL OR t.invoice_status_1 != 'Raised')
          AND (
            t.pod_status ILIKE '%pending%'
            OR t.pod_status ILIKE '%i-bond%'
            OR t.pod_status = ''
            OR t.pod_status IS NULL
            OR t.pod_status = 'partial'
          )
      ),
      0
    ) AS pod_pending_sum,

    COUNT(t.id) FILTER (
      WHERE (t.invoice_no IS NULL OR t.invoice_no = '')
        AND (t.invoice_status_1 IS NULL OR t.invoice_status_1 != 'Raised')
        AND t.pod_status ILIKE '%received%'
        AND (
          t.invoice_status_1 IS NULL
          OR (
            t.invoice_status_1 NOT ILIKE '%pending%'
            AND t.invoice_status_1 NOT ILIKE '%data shared%'
          )
        )
    ) AS received_count,
    COALESCE(
      SUM(COALESCE(t.total_client_value, t.client_price, 0)) FILTER (
        WHERE (t.invoice_no IS NULL OR t.invoice_no = '')
          AND (t.invoice_status_1 IS NULL OR t.invoice_status_1 != 'Raised')
          AND t.pod_status ILIKE '%received%'
          AND (
            t.invoice_status_1 IS NULL
            OR (
              t.invoice_status_1 NOT ILIKE '%pending%'
              AND t.invoice_status_1 NOT ILIKE '%data shared%'
            )
          )
      ),
      0
    ) AS received_sum,

    COUNT(t.id) FILTER (
      WHERE (t.invoice_no IS NULL OR t.invoice_no = '')
        AND (t.invoice_status_1 IS NULL OR t.invoice_status_1 != 'Raised')
        AND t.pod_status ILIKE '%received%'
        AND (
          t.invoice_status_1 ILIKE '%pending%'
          OR t.invoice_status_1 ILIKE '%data shared%'
        )
    ) AS approved_count,
    COALESCE(
      SUM(COALESCE(t.total_client_value, t.client_price, 0)) FILTER (
        WHERE (t.invoice_no IS NULL OR t.invoice_no = '')
          AND (t.invoice_status_1 IS NULL OR t.invoice_status_1 != 'Raised')
          AND t.pod_status ILIKE '%received%'
          AND (
            t.invoice_status_1 ILIKE '%pending%'
            OR t.invoice_status_1 ILIKE '%data shared%'
          )
      ),
      0
    ) AS approved_sum,

    COUNT(t.id) FILTER (
      WHERE (t.invoice_no IS NOT NULL AND t.invoice_no != '')
        OR t.invoice_status_1 = 'Raised'
    ) AS invoiced_count,
    COALESCE(
      SUM(COALESCE(t.total_client_value, t.client_price, 0)) FILTER (
        WHERE (t.invoice_no IS NOT NULL AND t.invoice_no != '')
          OR t.invoice_status_1 = 'Raised'
      ),
      0
    ) AS invoiced_sum
  FROM public.trips t
  WHERE t.organization_id = v_org
     OR (
       t.indent_id IS NOT NULL
       AND EXISTS (
         SELECT 1
         FROM public.suppliers s
         WHERE s.id = t.supplier_id
           AND s.linked_organization_id IS NOT NULL
           AND s.linked_organization_id = v_org
       )
     );
END;
$$;


