CREATE OR REPLACE FUNCTION "public"."get_shared_ledger_trip_summary"("org_id" "uuid", "partner_key" "uuid") RETURNS TABLE("trip_id" "uuid", "partner_sales" numeric, "partner_paid" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  partner_org_id_val uuid;
  counterparty_contact_id uuid;
  is_partner_client boolean := false;
BEGIN
  IF NOT public.is_org_member(org_id) THEN
    RETURN;
  END IF;

  SELECT COALESCE(
    (SELECT c.linked_organization_id FROM public.clients c WHERE c.id = partner_key AND c.organization_id = org_id AND c.linked_organization_id IS NOT NULL LIMIT 1),
    (SELECT s.linked_organization_id FROM public.suppliers s WHERE s.id = partner_key AND s.organization_id = org_id AND s.linked_organization_id IS NOT NULL LIMIT 1)
  ) INTO partner_org_id_val;

  IF partner_org_id_val IS NULL THEN
    RETURN;
  END IF;

  is_partner_client := EXISTS (
    SELECT 1 FROM public.clients c
    WHERE c.id = partner_key
      AND c.organization_id = org_id
    LIMIT 1
  );

  IF is_partner_client THEN
    SELECT s.id INTO counterparty_contact_id
    FROM public.suppliers s
    WHERE s.organization_id = partner_org_id_val
      AND s.linked_organization_id = org_id
    LIMIT 1;
  ELSE
    SELECT c.id INTO counterparty_contact_id
    FROM public.clients c
    WHERE c.organization_id = partner_org_id_val
      AND c.linked_organization_id = org_id
    LIMIT 1;
  END IF;

  RETURN QUERY
  WITH shared_viewer_trips AS (
    SELECT DISTINCT tr.trip_id AS trip_id
    FROM public.transactions tr
    WHERE tr.organization_id = org_id
      AND tr.contact_id = partner_key
      AND tr.trip_id IS NOT NULL

    UNION

    SELECT t.id AS trip_id
    FROM public.trips t
    WHERE t.organization_id = org_id
      AND (
        (is_partner_client AND t.client_id = partner_key)
        OR (NOT is_partner_client AND t.supplier_id = partner_key)
      )
  ),
  shared_with_indent AS (
    SELECT svt.trip_id, vt.indent_id
    FROM shared_viewer_trips svt
    LEFT JOIN public.trips vt ON vt.id = svt.trip_id
  ),
  partner_txn_by_trip AS (
    SELECT
      swi.trip_id,
      t.id AS txn_id,
      CASE
        WHEN is_partner_client THEN COALESCE(t.amount_out, 0)
        ELSE COALESCE(t.amount_in, 0)
      END AS paid_amount
    FROM public.transactions t
    LEFT JOIN public.trips pt ON pt.id = t.trip_id
    JOIN shared_with_indent swi
      ON t.trip_id = swi.trip_id
    WHERE t.organization_id = partner_org_id_val
      AND t.trip_id IS NOT NULL
      AND counterparty_contact_id IS NOT NULL
      AND t.contact_id = counterparty_contact_id
  ),
  partner_txn_by_indent AS (
    SELECT
      swi.trip_id,
      t.id AS txn_id,
      CASE
        WHEN is_partner_client THEN COALESCE(t.amount_out, 0)
        ELSE COALESCE(t.amount_in, 0)
      END AS paid_amount
    FROM public.transactions t
    LEFT JOIN public.trips pt ON pt.id = t.trip_id
    JOIN shared_with_indent swi
      ON pt.indent_id IS NOT NULL
     AND swi.indent_id IS NOT NULL
     AND pt.indent_id = swi.indent_id
    WHERE t.organization_id = partner_org_id_val
      AND t.trip_id IS NOT NULL
      AND counterparty_contact_id IS NOT NULL
      AND t.contact_id = counterparty_contact_id
  ),
  partner_txn AS (
    SELECT DISTINCT ON (u.txn_id)
      u.trip_id,
      u.txn_id,
      u.paid_amount
    FROM (
      SELECT * FROM partner_txn_by_trip
      UNION ALL
      SELECT * FROM partner_txn_by_indent
    ) u
    ORDER BY u.txn_id, u.trip_id NULLS LAST
  ),
  partner_paid_map AS (
    SELECT
      p.trip_id,
      SUM(p.paid_amount) AS amount_sum
    FROM partner_txn p
    GROUP BY p.trip_id
  )
  SELECT
    swi.trip_id,
    COALESCE(vt.supplier_rate, 0)::numeric AS partner_sales,
    COALESCE(ppm.amount_sum, 0)::numeric AS partner_paid
  FROM shared_with_indent swi
  LEFT JOIN public.trips vt
    ON vt.id = swi.trip_id
   AND vt.organization_id = org_id
  LEFT JOIN partner_paid_map ppm
    ON ppm.trip_id = swi.trip_id;
END;
$$;


ALTER FUNCTION "public"."get_shared_ledger_trip_summary"("org_id" "uuid", "partner_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_shared_ledger_trip_summary"("org_id" "uuid", "partner_key" "uuid") IS 'Per-trip partner sales/paid for shared ledger. Includes linked trips before viewer local tx exists; maps partner paid by bilateral rows via trip_id or shared indent_id. sales remains supplier_rate.';



CREATE OR REPLACE FUNCTION "public"."get_shared_trip_finance_adjustments"("org_id" "uuid", "partner_key" "uuid") RETURNS TABLE("id" "uuid", "trip_id" "uuid", "organization_id" "uuid", "type" "text", "impact" "text", "amount" numeric, "reason" "text", "mission_key" "text", "created_at" timestamp with time zone, "voided_at" timestamp with time zone, "void_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  partner_org_id_val uuid;
  counterparty_contact_id uuid;
  is_partner_client boolean := false;
BEGIN
  IF NOT public.is_org_member(org_id) THEN
    RETURN;
  END IF;

  SELECT COALESCE(
    (SELECT c.linked_organization_id FROM public.clients c WHERE c.id = partner_key AND c.organization_id = org_id AND c.linked_organization_id IS NOT NULL LIMIT 1),
    (SELECT s.linked_organization_id FROM public.suppliers s WHERE s.id = partner_key AND s.organization_id = org_id AND s.linked_organization_id IS NOT NULL LIMIT 1)
  ) INTO partner_org_id_val;

  IF partner_org_id_val IS NULL THEN
    RETURN;
  END IF;

  is_partner_client := EXISTS (
    SELECT 1 FROM public.clients c
    WHERE c.id = partner_key AND c.organization_id = org_id
    LIMIT 1
  );

  IF is_partner_client THEN
    SELECT s.id INTO counterparty_contact_id
    FROM public.suppliers s
    WHERE s.organization_id = partner_org_id_val AND s.linked_organization_id = org_id
    LIMIT 1;
  ELSE
    SELECT c.id INTO counterparty_contact_id
    FROM public.clients c
    WHERE c.organization_id = partner_org_id_val AND c.linked_organization_id = org_id
    LIMIT 1;
  END IF;

  RETURN QUERY
  WITH shared_trip_ids AS (
    SELECT DISTINCT tr.trip_id AS tid
    FROM public.transactions tr
    WHERE tr.organization_id = org_id
      AND tr.contact_id = partner_key
      AND tr.trip_id IS NOT NULL
  ),
  partner_trip_ids AS (
    SELECT DISTINCT tr.trip_id AS tid
    FROM public.transactions tr
    WHERE tr.organization_id = partner_org_id_val
      AND counterparty_contact_id IS NOT NULL
      AND tr.contact_id = counterparty_contact_id
      AND tr.trip_id IS NOT NULL
  ),
  mission_keys AS (
    SELECT DISTINCT upper(trim(both FROM COALESCE(z.mk_raw, ''))) AS mk
    FROM (
      SELECT COALESCE((to_jsonb(t) ->> 'display_trip_id')::text, t.trip_number::text, '') AS mk_raw
      FROM public.trips t
      WHERE t.id IN (SELECT tid FROM shared_trip_ids)
      UNION ALL
      SELECT COALESCE((to_jsonb(t) ->> 'display_trip_id')::text, t.trip_number::text, '') AS mk_raw
      FROM public.trips t
      WHERE t.id IN (SELECT tid FROM partner_trip_ids)
    ) z
    WHERE trim(both FROM COALESCE(z.mk_raw, '')) <> ''
  )
  SELECT
    a.id,
    a.trip_id,
    a.organization_id,
    a.type,
    a.impact,
    a.amount,
    a.reason,
    a.mission_key,
    a.created_at,
    a.voided_at,
    a.void_reason
  FROM public.trip_finance_adjustments a
  WHERE (
    a.organization_id = org_id
    AND a.trip_id IN (SELECT tid FROM shared_trip_ids)
  )
  OR (
    a.organization_id = partner_org_id_val
    AND (
      a.trip_id IN (SELECT tid FROM partner_trip_ids)
      OR (
        a.mission_key IS NOT NULL
        AND trim(both FROM a.mission_key) <> ''
        AND upper(trim(both FROM a.mission_key)) IN (SELECT mk FROM mission_keys)
      )
    )
  )
  ORDER BY a.created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_shared_trip_finance_adjustments"("org_id" "uuid", "partner_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_shared_trip_finance_adjustments"("org_id" "uuid", "partner_key" "uuid") IS 'Compare & Verify: adjustments for caller org trips + partner org trips (bilateral tx) + mission_key from both books. Compatible with schemas that omit trips.display_trip_id.';



CREATE OR REPLACE FUNCTION "public"."get_shipper_display_names_for_supplier_trips"("p_org_id" "uuid") RETURNS TABLE("trip_id" "uuid", "shipper_display_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT t.id AS trip_id,
         coalesce(nullif(trim(o.name), ''), 'Client') AS shipper_display_name
  FROM public.trips t
  JOIN public.suppliers s ON s.id = t.supplier_id
  JOIN public.organizations o ON o.id = t.organization_id
  WHERE s.linked_organization_id = p_org_id
    AND public.is_org_member(p_org_id)
  ORDER BY t.created_at DESC;
$$;


ALTER FUNCTION "public"."get_shipper_display_names_for_supplier_trips"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_shipper_display_names_for_supplier_trips"("p_org_id" "uuid") IS 'Returns trip_id and shipper (trip owner) display name for trips where p_org_id is the supplier. Used so supplier sees their client (shipper) name in Trips Control, not the end customer.';



