CREATE OR REPLACE FUNCTION "public"."get_supplier_details"("p_supplier_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_row record;
  v_org_name text;
  v_owner_id uuid;
  v_full_name text;
  v_phone text;
  v_email text;
  v_authorized boolean;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT s.id, s.organization_id, s.name, s.contact, s.company_name, s.contact_person,
         s.phone, s.email, s.address, s.gst_number, s.is_active, s.is_verified,
         s.operating_areas, s.vehicle_types, s.supplier_type, s.linked_organization_id,
         s.created_at, s.updated_at
  INTO v_row
  FROM public.suppliers s
  WHERE s.id = p_supplier_id;

  IF v_row.id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Caller must be active member or owner of the supplier's org
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = v_row.organization_id AND om.user_id = v_uid AND om.status = 'active'
  ) OR EXISTS (
    SELECT 1 FROM public.organizations o
    WHERE o.id = v_row.organization_id AND o.owner_id = v_uid
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RETURN NULL;
  END IF;

  -- Integrated: merge display from linked org's owner profile
  IF v_row.supplier_type = 'integrated' AND v_row.linked_organization_id IS NOT NULL THEN
    SELECT o.name, o.owner_id INTO v_org_name, v_owner_id
    FROM public.organizations o
    WHERE o.id = v_row.linked_organization_id;

    IF v_owner_id IS NOT NULL THEN
      SELECT trim(coalesce(p.full_name, '')), trim(coalesce(p.phone, '')), trim(coalesce(p.email, ''))
      INTO v_full_name, v_phone, v_email
      FROM public.profiles p
      WHERE p.id = v_owner_id;
    END IF;

    RETURN jsonb_build_object(
      'id', v_row.id,
      'organization_id', v_row.organization_id,
      'name', coalesce(nullif(trim(v_row.name), ''), nullif(trim(v_org_name), ''), v_row.company_name),
      'contact', coalesce(nullif(trim(v_row.contact), ''), v_full_name),
      'company_name', coalesce(nullif(trim(v_row.company_name), ''), nullif(trim(v_org_name), ''), 'Connected'),
      'contact_person', coalesce(nullif(trim(v_row.contact_person), ''), v_full_name),
      'phone', coalesce(nullif(trim(v_row.phone), ''), v_phone),
      'email', coalesce(nullif(trim(v_row.email), ''), v_email),
      'address', v_row.address,
      'gst_number', v_row.gst_number,
      'is_active', v_row.is_active,
      'is_verified', v_row.is_verified,
      'operating_areas', v_row.operating_areas,
      'vehicle_types', v_row.vehicle_types,
      'supplier_type', v_row.supplier_type,
      'linked_organization_id', v_row.linked_organization_id,
      'created_at', v_row.created_at,
      'updated_at', v_row.updated_at
    );
  END IF;

  -- Non-integrated: return local row as-is
  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."get_supplier_details"("p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_supplier_details"("p_supplier_id" "uuid") IS 'Returns supplier row for detail/edit. When supplier_type=integrated, name/company_name/contact_person/phone/email are COALESCE from linked org owner profile. Caller must be member or owner of supplier.organization_id.';



CREATE OR REPLACE FUNCTION "public"."get_supplier_management_bundle"("p_org_id" "uuid", "p_supplier_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'supplier',        row_to_json(s.*),
    'contacts',        COALESCE(
                         (SELECT jsonb_agg(c ORDER BY c.created_at)
                          FROM supplier_contacts c
                          WHERE c.supplier_id = p_supplier_id
                            AND c.organization_id = p_org_id
                            AND c.deleted_at IS NULL),
                         '[]'::jsonb),
    'kyc_documents',   COALESCE(
                         (SELECT jsonb_agg(k ORDER BY k.created_at)
                          FROM supplier_kyc_documents k
                          WHERE k.supplier_id = p_supplier_id
                            AND k.organization_id = p_org_id
                            AND k.deleted_at IS NULL),
                         '[]'::jsonb),
    'compliance_docs', COALESCE(
                         (SELECT jsonb_agg(d ORDER BY d.expiry_date NULLS LAST)
                          FROM supplier_compliance_documents d
                          WHERE d.supplier_id = p_supplier_id
                            AND d.organization_id = p_org_id
                            AND d.deleted_at IS NULL),
                         '[]'::jsonb),
    'contracts',       COALESCE(
                         (SELECT jsonb_agg(ct ORDER BY ct.created_at DESC)
                          FROM supplier_contract_agreements ct
                          WHERE ct.supplier_id = p_supplier_id
                            AND ct.organization_id = p_org_id
                            AND ct.deleted_at IS NULL),
                         '[]'::jsonb),
    'fleet',           COALESCE(
                         (SELECT jsonb_agg(f ORDER BY f.created_at)
                          FROM supplier_fleet f
                          WHERE f.supplier_id = p_supplier_id
                            AND f.organization_id = p_org_id
                            AND f.deleted_at IS NULL),
                         '[]'::jsonb),
    'warehouses',      COALESCE(
                         (SELECT jsonb_agg(w ORDER BY w.created_at)
                          FROM supplier_warehouses w
                          WHERE w.supplier_id = p_supplier_id
                            AND w.organization_id = p_org_id
                            AND w.deleted_at IS NULL),
                         '[]'::jsonb)
  )
  INTO v_result
  FROM public.suppliers s
  WHERE s.id = p_supplier_id
    AND s.organization_id = p_org_id;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_supplier_management_bundle"("p_org_id" "uuid", "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_supplier_management_bundle"("p_org_id" "uuid", "p_supplier_id" "uuid") IS 'Returns supplier row + contacts + kyc_documents + compliance_docs + contracts + fleet + warehouses in a single JSONB payload. Mirrors get_client_management_bundle.';



CREATE OR REPLACE FUNCTION "public"."get_supplier_monthly_analytics"("p_org_id" "uuid", "p_supplier_id" "uuid", "p_months_back" integer DEFAULT 12) RETURNS TABLE("period" "text", "revenue_handled" numeric, "supplier_payable" numeric, "margin_contribution" numeric, "margin_contribution_pct" numeric, "trip_count" bigint, "km_driven" numeric, "paid" numeric, "outstanding" numeric, "avg_settlement_days" numeric, "on_time_pct" numeric, "cancellation_rate_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH _period_start AS (
    SELECT date_trunc('month', now() - (p_months_back - 1 || ' months')::interval) AS start_dt
  ),
  _supplier_trips AS (
    SELECT
      t.id          AS trip_id,
      t.client_price,
      t.supplier_rate,
      t.margin,
      t.distance,
      t.status,
      t.pickup_date,
      t.completed_at,
      COALESCE(t.pickup_date, t.created_at) AS trip_date
    FROM public.trips t
    WHERE t.supplier_id = p_supplier_id
      AND t.organization_id = p_org_id
      AND COALESCE(t.pickup_date, t.created_at) >= (SELECT start_dt FROM _period_start)
      AND public.is_org_member(p_org_id)
  ),
  _supplier_payments AS (
    SELECT
      to_char(date_trunc('month', COALESCE(tx.transaction_date, tx.created_at)::date), 'YYYY-MM') AS period,
      SUM(COALESCE(tx.amount_out, 0))                                AS paid,
      AVG(NULLIF(
        (COALESCE(tx.transaction_date, tx.created_at::date)
         - st.pickup_date), 0
      ))                                                             AS avg_delay
    FROM public.transactions tx
    JOIN _supplier_trips st ON st.trip_id = tx.trip_id
    WHERE tx.organization_id = p_org_id
      AND tx.contact_type = 'supplier'
      AND COALESCE(tx.amount_out, 0) > 0
      AND st.pickup_date IS NOT NULL
      AND public.is_org_member(p_org_id)
    GROUP BY 1
  ),
  _monthly AS (
    SELECT
      to_char(date_trunc('month', st.trip_date), 'YYYY-MM') AS period,
      SUM(COALESCE(st.client_price, 0))                     AS revenue_handled,
      SUM(COALESCE(st.supplier_rate, 0))                    AS supplier_payable,
      SUM(COALESCE(st.margin, 0))                           AS margin_contribution,
      COUNT(*)                                              AS trip_count,
      SUM(COALESCE(st.distance, 0))                         AS km_driven,
      AVG(
        CASE
          WHEN st.completed_at IS NOT NULL AND st.pickup_date IS NOT NULL
            THEN CASE
              WHEN st.completed_at::date <= st.pickup_date + INTERVAL '1 day'
                THEN 100.0
              ELSE 0.0
            END
          ELSE NULL
        END
      )                                                     AS on_time_pct,
      ROUND(
        COUNT(*) FILTER (WHERE st.status = 'cancelled')::numeric
        / NULLIF(COUNT(*), 0) * 100, 2
      )                                                     AS cancellation_rate_pct
    FROM _supplier_trips st
    GROUP BY 1
  )
  SELECT
    m.period,
    m.revenue_handled,
    m.supplier_payable,
    m.margin_contribution,
    CASE WHEN m.revenue_handled > 0
      THEN ROUND((m.margin_contribution / m.revenue_handled) * 100, 2)
      ELSE 0
    END                                                       AS margin_contribution_pct,
    m.trip_count,
    m.km_driven,
    COALESCE(sp.paid, 0)                                      AS paid,
    GREATEST(m.supplier_payable - COALESCE(sp.paid, 0), 0)    AS outstanding,
    ROUND(COALESCE(sp.avg_delay, 0)::numeric, 1)              AS avg_settlement_days,
    ROUND(COALESCE(m.on_time_pct, 0)::numeric, 1)             AS on_time_pct,
    COALESCE(m.cancellation_rate_pct, 0)                      AS cancellation_rate_pct
  FROM _monthly m
  LEFT JOIN _supplier_payments sp ON sp.period = m.period
  ORDER BY m.period ASC;
$$;


ALTER FUNCTION "public"."get_supplier_monthly_analytics"("p_org_id" "uuid", "p_supplier_id" "uuid", "p_months_back" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_trip_ids_for_org"("p_org_id" "uuid") RETURNS json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(json_agg(
    json_build_object('trip_id', tr.id, 'supplier_id', tr.supplier_id)
  ), '[]'::json)
  FROM (
    SELECT tr.id, tr.supplier_id
    FROM trips tr
    WHERE tr.status NOT IN ('cancelled')
      AND EXISTS (
        SELECT 1 FROM suppliers s
        WHERE s.id = tr.supplier_id
          AND s.linked_organization_id = p_org_id
      )
    ORDER BY tr.created_at DESC
    LIMIT 500
  ) tr;
$$;


ALTER FUNCTION "public"."get_supplier_trip_ids_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_suppliers_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_deleted   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(s) ORDER BY s.updated_at) FILTER (WHERE s.deleted_at IS NULL), '[]'),
    COALESCE(jsonb_agg(s.id::TEXT)                           FILTER (WHERE s.deleted_at IS NOT NULL), '[]'),
    MAX(s.updated_at)::TEXT
  INTO v_changed, v_deleted, v_next
  FROM (
    SELECT * FROM suppliers
    WHERE organization_id = p_org_id
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) s;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  v_deleted,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


ALTER FUNCTION "public"."get_suppliers_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_suppliers_with_profiles"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "name" "text", "contact" "text", "company_name" "text", "contact_person" "text", "phone" "text", "email" "text", "address" "text", "gst_number" "text", "is_active" boolean, "is_verified" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "supplier_type" "text", "linked_organization_id" "uuid", "avatar_url" "text", "avatar_seed" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id,
    s.organization_id,
    s.name,
    s.contact,
    s.company_name,
    s.contact_person,
    s.phone,
    s.email,
    s.address,
    s.gst_number,
    s.is_active,
    s.is_verified,
    s.created_at,
    s.updated_at,
    s.supplier_type::text,
    s.linked_organization_id,
    -- Prefer the linked org's branding logo; fall back to the owner's
    -- personal profile avatar so unbranded orgs still show a face.
    COALESCE(NULLIF(TRIM(o.logo_url), ''), p.avatar_url) AS avatar_url,
    p.avatar_seed
  FROM public.suppliers s
  LEFT JOIN public.organizations o ON o.id = s.linked_organization_id
  LEFT JOIN public.profiles      p ON p.id = o.owner_id
  WHERE s.organization_id = p_org_id
  ORDER BY s.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_suppliers_with_profiles"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_suppliers_with_profiles"("p_org_id" "uuid") IS 'Returns suppliers for an org. avatar_url resolves to organizations.logo_url first, then profiles.avatar_url from linked org owner. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_tier_capabilities"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE o.verification_tier
    WHEN 'TIER_0_SANDBOX' THEN jsonb_build_object(
      'tier',               'TIER_0_SANDBOX',
      'label',              'Sandbox Access',
      'can_bid',            false,
      'can_post_trips',     false,
      'can_join_matching',  false,
      'can_clear_escrow',   false,
      'transaction_cap',    0,
      'description', 'Explore the platform. Complete business verification to unlock marketplace access.'
    )
    WHEN 'TIER_1_PARTIAL' THEN jsonb_build_object(
      'tier',               'TIER_1_PARTIAL',
      'label',              'Partial Activation',
      'can_bid',            true,
      'can_post_trips',     true,
      'can_join_matching',  true,
      'can_clear_escrow',   false,
      'transaction_cap',    20000000,
      'description', 'Basic marketplace access up to ₹2,00,000 GTV. Complete bank and biometric verification to unlock full access.'
    )
    WHEN 'TIER_2_FULL' THEN jsonb_build_object(
      'tier',               'TIER_2_FULL',
      'label',              'Full Marketplace Activation',
      'can_bid',            true,
      'can_post_trips',     true,
      'can_join_matching',  true,
      'can_clear_escrow',   true,
      'transaction_cap',    null,
      'description', 'Unlimited enterprise GTV. Full escrow and referral payouts enabled.'
    )
  END
  FROM public.organizations o
  JOIN public.organization_members om
    ON om.organization_id = o.id
   AND om.user_id = auth.uid()
   AND om.status  = 'active'
  WHERE o.id = p_org_id;
$$;


ALTER FUNCTION "public"."get_tier_capabilities"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_transactions_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(tx) ORDER BY tx.created_at), '[]'),
    MAX(tx.created_at)::TEXT
  INTO v_changed, v_next
  FROM (
    SELECT * FROM transactions
    WHERE organization_id = p_org_id
      AND created_at > v_since
    ORDER BY created_at
    LIMIT p_limit
  ) tx;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  '[]'::JSONB,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


