CREATE OR REPLACE FUNCTION "public"."get_trigger_coverage"() RETURNS TABLE("tbl" "text", "has_rls" boolean, "trg_count" bigint, "trg_names" "text"[])
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT
    t.tablename::text,
    c.relrowsecurity,
    COUNT(tr.tgname)::bigint,
    ARRAY_AGG(tr.tgname::text ORDER BY tr.tgname)
      FILTER (WHERE tr.tgname IS NOT NULL AND tr.tgisinternal = false)
  FROM pg_tables t
  JOIN pg_class c
    ON c.relname = t.tablename
   AND c.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public')
  LEFT JOIN pg_trigger tr
    ON tr.tgrelid = c.oid
   AND tr.tgisinternal = false
  WHERE t.schemaname = 'public'
    AND t.tablename IN (
      'trips', 'trip_assignment_audit', 'trip_workflow_events',
      'trip_status_audit', 'workspace_audit_log', 'trip_location_checkpoints',
      'trip_otps', 'transactions', 'indents', 'network_bids',
      'organizations', 'organization_members', 'drivers',
      'vehicles', 'trip_documents', 'trip_messages'
    )
  GROUP BY t.tablename, c.relrowsecurity;
$$;


ALTER FUNCTION "public"."get_trigger_coverage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trip_assigner_displays_for_driver"("p_trip_ids" "uuid"[]) RETURNS TABLE("trip_id" "uuid", "display_name" "text", "assigner_user_id" "uuid", "assigning_organization_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH
  -- Caller identity + normalized phone, each computed exactly once per call
  -- (not per row) via a single-row CTE, referenced by plain joins below
  -- instead of repeated scalar subqueries, so the plan can't regress into
  -- re-evaluating them per candidate trip under a different query shape.
  caller AS (
    SELECT (SELECT auth.uid()) AS uid
  ),
  caller_phone AS (
    SELECT
      c.uid,
      right(
        regexp_replace(
          coalesce(p.phone, u.raw_user_meta_data->>'phone', ''),
          '\D', '', 'g'
        ),
        10
      ) AS normalized
    FROM caller c
    LEFT JOIN auth.users u ON u.id = c.uid
    LEFT JOIN public.profiles p ON p.id = c.uid
  ),
  requested AS (
    SELECT rt.trip_id
    FROM unnest(p_trip_ids) AS rt(trip_id)
  ),
  trip_base AS (
    SELECT
      t.id AS trip_id,
      t.driver_id,
      t.created_by_user_id,
      t.owner_user_id,
      t.assigned_by_user_id,
      t.organization_id,
      t.source,
      t.vehicle_id
    FROM requested r
    JOIN public.trips t ON t.id = r.trip_id
  ),
  visibility AS (
    SELECT
      tb.trip_id,
      (
        EXISTS (
          SELECT 1 FROM public.drivers d
          WHERE d.id = tb.driver_id
            AND d.user_id = cp.uid
        )
        OR (
          length(cp.normalized) >= 10
          AND EXISTS (
            SELECT 1
            FROM public.trip_otps o
            JOIN public.drivers d ON d.id = tb.driver_id
            WHERE o.trip_id = tb.trip_id
              AND o.used_at IS NULL
              AND o.expires_at > now()
              AND d.user_id IS NULL
              AND length(right(regexp_replace(coalesce(d.phone, ''), '\D', '', 'g'), 10)) >= 10
              AND right(regexp_replace(coalesce(d.phone, ''), '\D', '', 'g'), 10) = cp.normalized
              AND NOT (tb.source = 'direct_quote' AND tb.driver_id IS NOT NULL AND tb.vehicle_id IS NOT NULL)
          )
        )
      ) AS can_see
    FROM trip_base tb
    CROSS JOIN caller_phone cp
    WHERE cp.uid IS NOT NULL
  ),
  visible_trips AS (
    SELECT tb.*
    FROM trip_base tb
    JOIN visibility v ON v.trip_id = tb.trip_id AND v.can_see
  ),
  latest_audit AS (
    SELECT DISTINCT ON (a.trip_id)
      a.trip_id,
      a.changed_by
    FROM public.trip_assignment_audit a
    JOIN visible_trips vt ON vt.trip_id = a.trip_id
    WHERE a.changed_by IS NOT NULL
      AND a.event_type IN ('assignment', 'reassignment')
    ORDER BY a.trip_id, a.changed_at DESC
  ),
  resolved_assigner AS (
    SELECT
      vt.trip_id,
      vt.organization_id,
      coalesce(
        la.changed_by,
        vt.assigned_by_user_id,
        vt.created_by_user_id,
        vt.owner_user_id
      ) AS assigner_uid
    FROM visible_trips vt
    LEFT JOIN latest_audit la ON la.trip_id = vt.trip_id
  ),
  -- Mirrors the original's exact branching:
  --   profiles row exists  -> coalesce(full_name, email_prefix, 'Dispatcher')   [public.users NEVER consulted]
  --   no profiles row      -> public.users.name, else 'Dispatcher'
  -- (SELECT INTO on a non-matching row leaves the target NULL in the original,
  --  so "no profiles row" and "profiles row with blank name" take different paths.)
  name_resolved AS (
    SELECT
      ra.trip_id,
      ra.organization_id,
      ra.assigner_uid,
      CASE
        WHEN ra.assigner_uid IS NULL THEN NULL
        WHEN p.id IS NOT NULL THEN
          coalesce(
            nullif(trim(p.full_name), ''),
            nullif(split_part(trim(p.email), '@', 1), ''),
            'Dispatcher'
          )
        ELSE
          coalesce(nullif(trim(pu.name), ''), 'Dispatcher')
      END AS display_name
    FROM resolved_assigner ra
    LEFT JOIN public.profiles p ON p.id = ra.assigner_uid
    LEFT JOIN public.users pu ON pu.id = ra.assigner_uid
  )
  SELECT
    nr.trip_id,
    nr.display_name,
    nr.assigner_uid AS assigner_user_id,
    nullif(trim(o.name), '') AS assigning_organization_name
  FROM name_resolved nr
  LEFT JOIN public.organizations o ON o.id = nr.organization_id;
$$;


ALTER FUNCTION "public"."get_trip_assigner_displays_for_driver"("p_trip_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_trip_assigner_displays_for_driver"("p_trip_ids" "uuid"[]) IS 'Driver app: for trips visible to this driver, return assigner person (audit → assigned_by_user_id → created_by/owner), assigner user id, and trips.organization_id fleet name. SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."get_trip_chat_room"("p_trip_id" "uuid") RETURNS "public"."chat_conversations"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT cc.*
  FROM public.chat_conversations cc
  WHERE cc.trip_id = p_trip_id
    AND cc.conversation_type = 'trip'
    AND public.fn_can_access_trip_for_chat(p_trip_id)
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_trip_chat_room"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_trip_chat_room"("p_trip_id" "uuid") IS 'Read-only lookup of the unified trip room; null when not created yet.';



CREATE OR REPLACE FUNCTION "public"."get_trip_detail_bundle"("p_trip_id" "uuid", "p_viewer_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip_org_id        UUID;
  v_supplier_linked_id UUID;

  v_trip_id                    UUID;
  v_trip_organization_id       UUID;
  v_trip_number                TEXT;
  v_indent_id                  UUID;
  v_source                     TEXT;
  v_pickup_area                TEXT;
  v_drop_location              TEXT;
  v_distance                   NUMERIC;
  v_estimated_duration         INTERVAL;
  v_client_id                  UUID;
  v_client_name                TEXT;
  v_supplier_id                UUID;
  v_driver_id                  UUID;
  v_vehicle_id                 UUID;
  v_client_price               NUMERIC;
  v_supplier_rate              NUMERIC;
  v_margin                     NUMERIC;
  v_platform_fee               NUMERIC;
  v_driver_commission          NUMERIC;
  v_is_guaranteed              BOOLEAN;
  v_payment_status             TEXT;
  v_amount_paid                NUMERIC;
  v_advance_paid               NUMERIC;
  v_status                     TEXT;
  v_pickup_date                DATE;
  v_started_at                 TIMESTAMPTZ;
  v_completed_at               TIMESTAMPTZ;
  v_load_type                  TEXT;
  v_load_tons                  NUMERIC;
  v_notes                      TEXT;
  v_created_at                 TIMESTAMPTZ;
  v_updated_at                 TIMESTAMPTZ;
  v_driver_display_name        TEXT;
  v_vehicle_display_number     TEXT;
  v_pickup_lat                 NUMERIC;
  v_pickup_lon                 NUMERIC;
  v_drop_lat                   NUMERIC;
  v_drop_lon                   NUMERIC;
  v_owner_user_id              UUID;
  v_created_by_user_id         UUID;
  v_assigned_by_user_id        UUID;
  v_trip_payout_mode           TEXT;
  v_driver_display_trip_id     TEXT;
  v_deleted_at                 TIMESTAMPTZ;
  v_display_trip_id            TEXT;
  v_last_location_at           TIMESTAMPTZ;
  v_actual_distance_km         NUMERIC;
  v_last_location_chat_at      TIMESTAMPTZ;
BEGIN

  IF NOT EXISTS (
    SELECT 1
    FROM organization_members om
    WHERE om.organization_id = p_viewer_org_id
      AND om.user_id = (SELECT auth.uid())
      AND om.status = 'active'
  ) THEN
    RETURN NULL;
  END IF;

  SELECT
    t.id, t.organization_id, t.trip_number, t.indent_id, t.source,
    t.pickup_area, t.drop_location, t.distance, t.estimated_duration,
    t.client_id, t.client_name, t.supplier_id, t.driver_id, t.vehicle_id,
    t.client_price, t.supplier_rate, t.margin, t.platform_fee, t.driver_commission,
    t.is_guaranteed, t.payment_status, t.amount_paid, t.advance_paid, t.status,
    t.pickup_date, t.started_at, t.completed_at, t.load_type, t.load_tons, t.notes,
    t.created_at, t.updated_at, t.driver_display_name, t.vehicle_display_number,
    t.pickup_lat, t.pickup_lon, t.drop_lat, t.drop_lon,
    t.owner_user_id, t.created_by_user_id, t.assigned_by_user_id,
    t.trip_payout_mode, t.driver_display_trip_id, t.deleted_at, t.display_trip_id,
    t.last_location_at, t.actual_distance_traveled_km, t.last_location_chat_at
  INTO
    v_trip_id, v_trip_organization_id, v_trip_number, v_indent_id, v_source,
    v_pickup_area, v_drop_location, v_distance, v_estimated_duration,
    v_client_id, v_client_name, v_supplier_id, v_driver_id, v_vehicle_id,
    v_client_price, v_supplier_rate, v_margin, v_platform_fee, v_driver_commission,
    v_is_guaranteed, v_payment_status, v_amount_paid, v_advance_paid, v_status,
    v_pickup_date, v_started_at, v_completed_at, v_load_type, v_load_tons, v_notes,
    v_created_at, v_updated_at, v_driver_display_name, v_vehicle_display_number,
    v_pickup_lat, v_pickup_lon, v_drop_lat, v_drop_lon,
    v_owner_user_id, v_created_by_user_id, v_assigned_by_user_id,
    v_trip_payout_mode, v_driver_display_trip_id, v_deleted_at, v_display_trip_id,
    v_last_location_at, v_actual_distance_km, v_last_location_chat_at
  FROM trips t
  WHERE t.id = p_trip_id
    AND t.deleted_at IS NULL
    AND (
      t.organization_id = p_viewer_org_id
      OR EXISTS (
        SELECT 1 FROM suppliers s
        WHERE s.id = t.supplier_id AND s.linked_organization_id = p_viewer_org_id
      )
      OR EXISTS (
        SELECT 1 FROM clients c
        WHERE c.id = t.client_id AND c.linked_organization_id = p_viewer_org_id
      )
    )
  LIMIT 1;

  IF v_trip_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_trip_org_id := v_trip_organization_id;

  IF v_supplier_id IS NOT NULL THEN
    SELECT s.linked_organization_id INTO v_supplier_linked_id
    FROM suppliers s WHERE s.id = v_supplier_id LIMIT 1;
  END IF;

  RETURN jsonb_build_object(

    'trip', jsonb_build_object(
      'id',                          v_trip_id,
      'organization_id',             v_trip_org_id,
      'trip_number',                 v_trip_number,
      'display_trip_id',             v_display_trip_id,
      'driver_display_trip_id',      v_driver_display_trip_id,
      'indent_id',                   v_indent_id,
      'source',                      v_source,
      'pickup_area',                 v_pickup_area,
      'drop_location',               v_drop_location,
      'distance',                    v_distance,
      'estimated_duration',          v_estimated_duration,
      'client_id',                   v_client_id,
      'client_name',                 v_client_name,
      'supplier_id',                 v_supplier_id,
      'driver_id',                   v_driver_id,
      'vehicle_id',                  v_vehicle_id,
      'driver_display_name',         v_driver_display_name,
      'vehicle_display_number',      v_vehicle_display_number,
      'client_price',                v_client_price,
      'supplier_rate',               v_supplier_rate,
      'margin',                      v_margin,
      'platform_fee',                v_platform_fee,
      'driver_commission',           v_driver_commission,
      'is_guaranteed',               v_is_guaranteed,
      'payment_status',              v_payment_status,
      'amount_paid',                 v_amount_paid,
      'advance_paid',                v_advance_paid,
      'status',                      v_status,
      'pickup_date',                 v_pickup_date,
      'started_at',                  v_started_at,
      'completed_at',                v_completed_at,
      'load_type',                   v_load_type,
      'load_tons',                   v_load_tons,
      'notes',                       v_notes,
      'created_at',                  v_created_at,
      'updated_at',                  v_updated_at,
      'pickup_lat',                  v_pickup_lat,
      'pickup_lon',                  v_pickup_lon,
      'drop_lat',                    v_drop_lat,
      'drop_lon',                    v_drop_lon,
      'owner_user_id',               v_owner_user_id,
      'created_by_user_id',          v_created_by_user_id,
      'assigned_by_user_id',         v_assigned_by_user_id,
      'trip_payout_mode',            v_trip_payout_mode,
      'last_location_at',            v_last_location_at,
      'actual_distance_traveled_km', v_actual_distance_km,
      'last_location_chat_at',       v_last_location_chat_at
    ),

    'assignment_audit', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id',               aa.id,
          'trip_id',          aa.trip_id,
          'event_type',       aa.event_type,
          'driver_id_prev',   aa.driver_id_prev,
          'driver_id_new',    aa.driver_id_new,
          'vehicle_id_prev',  aa.vehicle_id_prev,
          'vehicle_id_new',   aa.vehicle_id_new,
          'changed_at',       aa.changed_at,
          'changed_by',       aa.changed_by,
          'driver_new_name', (
            SELECT COALESCE(d.name, d.phone)
            FROM drivers d
            WHERE d.id = aa.driver_id_new
              AND d.organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id, v_supplier_linked_id])
            ORDER BY (d.organization_id = v_trip_org_id) DESC
            LIMIT 1
          ),
          'driver_prev_name', (
            SELECT COALESCE(d.name, d.phone)
            FROM drivers d
            WHERE d.id = aa.driver_id_prev
              AND d.organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id, v_supplier_linked_id])
            ORDER BY (d.organization_id = v_trip_org_id) DESC
            LIMIT 1
          ),
          'vehicle_new_label', (
            SELECT v.vehicle_number ||
                   CASE WHEN v.vehicle_type IS NOT NULL THEN ' · ' || v.vehicle_type ELSE '' END
            FROM vehicles v
            WHERE v.id = aa.vehicle_id_new
              AND v.organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id, v_supplier_linked_id])
            ORDER BY (v.organization_id = v_trip_org_id) DESC
            LIMIT 1
          ),
          'vehicle_prev_label', (
            SELECT v.vehicle_number ||
                   CASE WHEN v.vehicle_type IS NOT NULL THEN ' · ' || v.vehicle_type ELSE '' END
            FROM vehicles v
            WHERE v.id = aa.vehicle_id_prev
              AND v.organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id, v_supplier_linked_id])
            ORDER BY (v.organization_id = v_trip_org_id) DESC
            LIMIT 1
          )
        ) ORDER BY aa.changed_at DESC
      ), '[]'::jsonb)
      FROM (
        SELECT id, trip_id, event_type, driver_id_prev, driver_id_new,
               vehicle_id_prev, vehicle_id_new, changed_at, changed_by
        FROM trip_assignment_audit
        WHERE trip_id = p_trip_id
        ORDER BY changed_at DESC
        LIMIT 20
      ) aa
    ),

    'driver', (
      SELECT jsonb_build_object(
        'id',              d.id,
        'name',            d.name,
        'phone',           d.phone,
        'avatar_url',      d.avatar_url,
        'avatar_seed',     d.avatar_seed,
        'user_id',         d.user_id,
        'organization_id', d.organization_id
      )
      FROM drivers d
      WHERE d.id = v_driver_id
        AND d.organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id, v_supplier_linked_id])
      ORDER BY (d.organization_id = v_trip_org_id) DESC
      LIMIT 1
    ),

    'vehicle', (
      SELECT jsonb_build_object(
        'id',                v.id,
        'vehicle_number',    v.vehicle_number,
        'vehicle_type',      v.vehicle_type,
        'capacity',          v.capacity,
        'vehicle_brand',     v.vehicle_brand,
        'vehicle_body_type', v.vehicle_body_type,
        'organization_id',   v.organization_id,
        'supplier_id',       v.supplier_id,
        'status',            v.status,
        'documents',         v.documents
      )
      FROM vehicles v
      WHERE v.id = v_vehicle_id
        AND v.organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id, v_supplier_linked_id])
      ORDER BY (v.organization_id = v_trip_org_id) DESC
      LIMIT 1
    ),

    'client_detail', (
      SELECT jsonb_build_object(
        'client', jsonb_build_object(
          'id',                     c.id,
          'name',                   c.name,
          'phone',                  c.phone,
          'avatar_url',             c.avatar_url,
          'avatar_seed',            c.avatar_seed,
          'linked_organization_id', c.linked_organization_id,
          'organization_id',        c.organization_id,
          'status',                 c.status
        ),
        'linked_org', CASE WHEN c.linked_organization_id IS NOT NULL THEN (
          SELECT jsonb_build_object(
            'id',       o.id,
            'logo_url', o.logo_url
          )
          FROM organizations o
          WHERE o.id = c.linked_organization_id
        ) ELSE NULL END
      )
      FROM clients c
      WHERE c.id = v_client_id
      LIMIT 1
    ),

    'supplier_detail', (
      SELECT jsonb_build_object(
        'supplier', jsonb_build_object(
          'id',                     s.id,
          'company_name',           s.company_name,
          'phone',                  s.phone,
          'avatar_url',             s.avatar_url,
          'avatar_seed',            s.avatar_seed,
          'linked_organization_id', s.linked_organization_id,
          'organization_id',        s.organization_id
        ),
        'linked_org', CASE WHEN s.linked_organization_id IS NOT NULL THEN (
          SELECT jsonb_build_object(
            'id',       o.id,
            'logo_url', o.logo_url
          )
          FROM organizations o
          WHERE o.id = s.linked_organization_id
        ) ELSE NULL END
      )
      FROM suppliers s
      WHERE s.id = v_supplier_id
      LIMIT 1
    ),

    'transactions', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id',                 tx.id,
          'organization_id',    tx.organization_id,
          'trip_id',            tx.trip_id,
          'party_name',         tx.party_name,
          'description',        tx.description,
          'amount_in',          tx.amount_in,
          'amount_out',         tx.amount_out,
          'transaction_date',   tx.transaction_date,
          'created_at',         tx.created_at,
          'contact_id',         tx.contact_id,
          'contact_type',       tx.contact_type,
          'ledger_entity_type', tx.ledger_entity_type,
          'ledger_flow_type',   tx.ledger_flow_type,
          'ledger_category',    tx.ledger_category
        ) ORDER BY tx.transaction_date DESC, tx.created_at DESC
      ), '[]'::jsonb)
      FROM (
        SELECT id, organization_id, trip_id, party_name, description,
               amount_in, amount_out, transaction_date, created_at,
               contact_id, contact_type, ledger_entity_type, ledger_flow_type, ledger_category
        FROM transactions
        WHERE trip_id = p_trip_id
          AND organization_id = ANY(ARRAY[v_trip_org_id, p_viewer_org_id])
        ORDER BY transaction_date DESC, created_at DESC
        LIMIT 50
      ) tx
    ),

    'adjustments', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id',              a.id,
          'trip_id',         a.trip_id,
          'organization_id', a.organization_id,
          'type',            a.type,
          'impact',          a.impact,
          'amount',          a.amount,
          'reason',          a.reason,
          'mission_key',     a.mission_key,
          'created_at',      a.created_at,
          'created_by',      a.created_by,
          'voided_at',       a.voided_at,
          'void_reason',     a.void_reason
        ) ORDER BY a.created_at DESC
      ), '[]'::jsonb)
      FROM (
        SELECT id, trip_id, organization_id, type, impact, amount, reason,
               mission_key, created_at, created_by, voided_at, void_reason
        FROM trip_finance_adjustments
        WHERE trip_id = p_trip_id
        ORDER BY created_at DESC
        LIMIT 50
      ) a
    ),

    'documents', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id',            td.id,
          'trip_id',       td.trip_id,
          'file_name',     td.file_name,
          'storage_path',  td.storage_path,
          'mime_type',     td.mime_type,
          'size_bytes',    td.size_bytes,
          'uploaded_at',   td.uploaded_at,
          'uploaded_by',   td.uploaded_by,
          'document_type', td.document_type
        ) ORDER BY td.uploaded_at DESC
      ), '[]'::jsonb)
      FROM (
        SELECT id, trip_id, file_name, storage_path, mime_type, size_bytes,
               uploaded_at, uploaded_by, document_type
        FROM trip_documents
        WHERE trip_id = p_trip_id
        ORDER BY uploaded_at DESC
        LIMIT 20
      ) td
    ),

    'otp', (
      SELECT jsonb_build_object(
        'code',       o.code,
        'expires_at', o.expires_at
      )
      FROM trip_otps o
      WHERE o.trip_id = p_trip_id
        AND o.expires_at > NOW()
        AND o.used_at IS NULL
      LIMIT 1
    ),

    'latest_driver_location', (
      SELECT jsonb_build_object(
        'latitude',    dl.latitude,
        'longitude',   dl.longitude,
        'accuracy',    dl.accuracy,
        'recorded_at', dl.recorded_at
      )
      FROM driver_locations dl
      WHERE dl.trip_id = p_trip_id
      ORDER BY dl.recorded_at DESC
      LIMIT 1
    )

  );
END;
$$;


ALTER FUNCTION "public"."get_trip_detail_bundle"("p_trip_id" "uuid", "p_viewer_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trip_otp"("p_trip_id" "uuid") RETURNS TABLE("code" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip_org uuid;
  v_supplier_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT t.organization_id, t.supplier_id
  INTO v_trip_org, v_supplier_id
  FROM public.trips t
  WHERE t.id = p_trip_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT (
    public.is_org_member(v_trip_org)
    OR (
      v_supplier_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.suppliers s
        WHERE s.id = v_supplier_id
          AND s.linked_organization_id IS NOT NULL
          AND public.is_org_member(s.linked_organization_id)
      )
    )
  ) THEN
    RAISE EXCEPTION 'Access denied for trip %', p_trip_id;
  END IF;

  RETURN QUERY
  SELECT o.code, o.expires_at
  FROM public.trip_otps o
  WHERE o.trip_id = p_trip_id
    AND o.used_at IS NULL
    AND o.expires_at > now();
END;
$$;


ALTER FUNCTION "public"."get_trip_otp"("p_trip_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_trip_otp"("p_trip_id" "uuid") IS 'Return current valid OTP for trip (display UI). Same caller scope as generate_trip_otp.';



CREATE OR REPLACE FUNCTION "public"."get_trip_status_summary"("p_org_id" "uuid") RETURNS TABLE("status" "text", "count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT status::text, COUNT(*) AS count
  FROM public.trips
  WHERE organization_id = p_org_id AND deleted_at IS NULL
  GROUP BY status ORDER BY status;
$$;


ALTER FUNCTION "public"."get_trip_status_summary"("p_org_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."trip_subcontracts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "viewer_org_id" "uuid" NOT NULL,
    "trip_id" "uuid" NOT NULL,
    "supplier_id" "uuid",
    "rate" numeric DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sub_supplier_on_platform" boolean DEFAULT false NOT NULL,
    "sub_supplier_name" "text",
    "sub_supplier_phone" "text",
    "sub_trip_code" "text",
    "sub_supplier_org_id" "uuid",
    "sub_driver_id" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    CONSTRAINT "chk_sub_supplier_identity" CHECK (((("sub_supplier_on_platform" = true) AND ("sub_supplier_org_id" IS NOT NULL)) OR (("sub_supplier_on_platform" = false) AND ("sub_supplier_name" IS NOT NULL)))),
    CONSTRAINT "chk_trip_subcontracts_status" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'completed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."trip_subcontracts" OWNER TO "postgres";


COMMENT ON TABLE "public"."trip_subcontracts" IS 'Carrier-org downstream subcontract for a trip they can see (load-based / supplier view). Not visible to shipper.';



COMMENT ON COLUMN "public"."trip_subcontracts"."viewer_org_id" IS 'Sourcing carrier org (Thameem) that created this subcontract row.';



COMMENT ON COLUMN "public"."trip_subcontracts"."trip_id" IS 'Parent trip owned by shipper org.';



COMMENT ON COLUMN "public"."trip_subcontracts"."sub_trip_code" IS 'Auto-generated {operational_code}-SUB-{sqids} when NULL on INSERT.';



COMMENT ON COLUMN "public"."trip_subcontracts"."sub_supplier_org_id" IS 'Linked organization of on-platform downstream supplier.';



CREATE OR REPLACE FUNCTION "public"."get_trip_subcontracts"("p_viewer_org_id" "uuid", "p_trip_ids" "uuid"[]) RETURNS SETOF "public"."trip_subcontracts"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT ts.*
  FROM public.trip_subcontracts ts
  WHERE ts.viewer_org_id = p_viewer_org_id
    AND public.is_org_member(p_viewer_org_id)
    AND (p_trip_ids IS NULL OR cardinality(p_trip_ids) = 0 OR ts.trip_id = ANY(p_trip_ids));
$$;


ALTER FUNCTION "public"."get_trip_subcontracts"("p_viewer_org_id" "uuid", "p_trip_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trips_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_deleted   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.updated_at) FILTER (WHERE t.deleted_at IS NULL), '[]'),
    COALESCE(jsonb_agg(t.id::TEXT)                           FILTER (WHERE t.deleted_at IS NOT NULL), '[]'),
    MAX(t.updated_at)::TEXT
  INTO v_changed, v_deleted, v_next
  FROM (
    SELECT * FROM trips
    WHERE organization_id = p_org_id
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) t;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  v_deleted,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


ALTER FUNCTION "public"."get_trips_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trips_for_org"("p_org_id" "uuid") RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT row_to_json(q)
  FROM (
    SELECT DISTINCT ON (tr.id)
      tr.*,
      i.indent_number
    FROM trips tr
    LEFT JOIN indents i ON i.id = tr.indent_id
    WHERE tr.organization_id = p_org_id
       OR EXISTS (
         SELECT 1 FROM suppliers s
         WHERE s.id = tr.supplier_id
           AND s.linked_organization_id = p_org_id
       )
    ORDER BY tr.id, tr.created_at DESC
  ) q
  ORDER BY q.created_at DESC
  LIMIT 400;
$$;


ALTER FUNCTION "public"."get_trips_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trips_for_pod_org"("p_org_id" "uuid") RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT row_to_json(q)
  FROM (
    SELECT DISTINCT ON (tr.id)
      tr.*
    FROM trips tr
    WHERE tr.organization_id = p_org_id
       OR EXISTS (
         SELECT 1 FROM suppliers s
         WHERE s.id = tr.supplier_id
           AND s.linked_organization_id = p_org_id
       )
       OR EXISTS (
         SELECT 1 FROM clients c
         WHERE c.id = tr.client_id
           AND c.organization_id = p_org_id
       )
    ORDER BY tr.id, tr.created_at DESC
  ) q
  ORDER BY q.created_at DESC
  LIMIT 5000;
$$;


ALTER FUNCTION "public"."get_trips_for_pod_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trips_where_org_is_client"("p_org_id" "uuid") RETURNS SETOF "public"."trips"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT t.*
  FROM public.trips t
  JOIN public.clients c ON c.id = t.client_id
  WHERE c.linked_organization_id = p_org_id
    AND t.indent_id IS NOT NULL
    AND public.is_org_member(p_org_id)
  ORDER BY t.created_at DESC;
$$;


ALTER FUNCTION "public"."get_trips_where_org_is_client"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_trips_where_org_is_client"("p_org_id" "uuid") IS 'Returns load-based trips where the client represents p_org_id (linked_organization_id). Caller must be member of p_org_id. Used for Compare & Verify.';



