    "tan_number" "text",
    "iec_number" "text",
    "gst_number" "text" GENERATED ALWAYS AS ("gstin") STORED,
    CONSTRAINT "suppliers_onboarding_agreement_status_check" CHECK (("onboarding_agreement_status" = ANY (ARRAY['pending'::"text", 'draft'::"text", 'signed'::"text", 'expired'::"text", 'terminated'::"text"]))),
    CONSTRAINT "suppliers_supplier_type_check" CHECK (("supplier_type" = ANY (ARRAY['integrated'::"text", 'offline'::"text", 'marketplace'::"text"])))
);


