COMMENT ON TABLE "public"."suppliers" IS 'Supplier companies (asset-based or marketplace). Soft-delete via deleted_at.';



COMMENT ON COLUMN "public"."suppliers"."linked_organization_id" IS 'When set, this supplier is another platform org; use organization_links for two-way connection';



COMMENT ON COLUMN "public"."suppliers"."contact" IS 'DEPRECATED: use suppliers.contact_person + suppliers.phone';



COMMENT ON COLUMN "public"."suppliers"."company_name" IS 'DEPRECATED: use suppliers.name';



COMMENT ON COLUMN "public"."suppliers"."gstin" IS 'GST Identification Number (15-char alphanumeric). Canonical column name, consistent with organizations.gstin and clients.gstin.';



COMMENT ON COLUMN "public"."suppliers"."pan_number" IS 'Permanent Account Number — 10-char alphanumeric issued by Income Tax Dept of India';



COMMENT ON COLUMN "public"."suppliers"."cin" IS 'Company Identification Number — 21-char identifier issued by Ministry of Corporate Affairs';



COMMENT ON COLUMN "public"."suppliers"."msme_number" IS 'MSME/Udyam Registration Number — issued to Micro/Small/Medium Enterprises by Ministry of MSME';



COMMENT ON COLUMN "public"."suppliers"."tan_number" IS 'Tax Deduction and Collection Account Number — 10-char alphanumeric issued by Income Tax Dept';



COMMENT ON COLUMN "public"."suppliers"."iec_number" IS 'Importer Exporter Code — 10-digit code issued by DGFT, required for cross-border trade';



COMMENT ON COLUMN "public"."suppliers"."gst_number" IS 'ALIAS — backward-compat read-only alias for gstin. Remove this column after all app code is updated to use gstin.';



CREATE OR REPLACE VIEW "public"."trips_supplier_view" WITH ("security_invoker"='true') AS
 SELECT "id",
    "booking_ref",
    "source_indent_code",
    "supplier_trip_sequence",
    "status",
    "pickup_area" AS "pickup_location",
    "pickup_area" AS "pickup_address",
    "pickup_date" AS "pickup_scheduled_at",
    "drop_location" AS "dropoff_location",
    "drop_location" AS "dropoff_address",
    NULL::timestamp with time zone AS "dropoff_scheduled_at",
    "driver_id" AS "assigned_driver_id",
    "driver_display_trip_id",
    "vehicle_id",
    "notes" AS "instructions",
    "created_at",
    "updated_at"
   FROM "public"."trips" "t"
  WHERE (("indent_id" IS NOT NULL) AND ((("public"."auth_org_id"() IS NOT NULL) AND ("supplier_id" IN ( SELECT "s"."id"
           FROM "public"."suppliers" "s"
          WHERE ("s"."linked_organization_id" = "public"."auth_org_id"())))) OR (("public"."auth_org_id"() IS NULL) AND ((EXISTS ( SELECT 1
           FROM ("public"."suppliers" "s"
             JOIN "public"."organization_members" "om" ON (("om"."organization_id" = "s"."linked_organization_id")))
          WHERE (("s"."id" = "t"."supplier_id") AND ("om"."user_id" = "auth"."uid"()) AND ("om"."status" = 'active'::"text")))) OR (EXISTS ( SELECT 1
           FROM ("public"."direct_quotes" "dq"
             JOIN "public"."organization_members" "om" ON (("om"."organization_id" = "dq"."bidder_organization_id")))
          WHERE (("dq"."indent_id" = "t"."indent_id") AND ("lower"(TRIM(BOTH FROM COALESCE("dq"."status", ''::"text"))) = 'accepted'::"text") AND ("om"."user_id" = "auth"."uid"()) AND ("om"."status" = 'active'::"text"))))))));


ALTER VIEW "public"."trips_supplier_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."trips_supplier_view" IS 'Supplier-facing trip projection: hides trip_number, trip_code, trip_operational_code, organization_id.';



CREATE OR REPLACE FUNCTION "public"."get_trips_where_org_is_supplier"("p_org_id" "uuid") RETURNS SETOF "public"."trips_supplier_view"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT ON (v.id) v.*
  FROM public.trips_supplier_view v
  INNER JOIN public.trips t ON t.id = v.id
  WHERE t.indent_id IS NOT NULL
    AND public.is_org_member(p_org_id)
    AND (
      EXISTS (
        SELECT 1
        FROM public.suppliers s
        WHERE s.id = t.supplier_id
          AND s.linked_organization_id = p_org_id
      )
      OR EXISTS (
        SELECT 1
        FROM public.direct_quotes dq
        WHERE dq.indent_id = t.indent_id
          AND lower(trim(coalesce(dq.status, ''))) = 'accepted'
          AND dq.bidder_organization_id = p_org_id
      )
    )
  ORDER BY v.id, v.created_at DESC NULLS LAST;
$$;


ALTER FUNCTION "public"."get_trips_where_org_is_supplier"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_trips_where_org_is_supplier"("p_org_id" "uuid") IS 'Indent/load trips for supplier org (safe columns via trips_supplier_view).';



CREATE OR REPLACE FUNCTION "public"."get_unified_b2b_bootstrap"("p_organization_id" "uuid", "p_message_limit" integer DEFAULT 50, "p_trip_limit" integer DEFAULT NULL::integer, "p_trip_offset" integer DEFAULT 0, "p_hub_trip_bucket" "text" DEFAULT 'active'::"text", "p_include_message_bodies" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_base       JSONB;
  v_augmented  JSONB;
  v_result     JSONB;
  v_by_context JSONB;
BEGIN
  v_base := public.get_b2b_chat_bootstrap(
    p_organization_id,
    p_message_limit,
    p_trip_limit,
    p_trip_offset,
    p_hub_trip_bucket,
    p_include_message_bodies
  );

  SELECT COALESCE(
    jsonb_agg(
      jsonb_set(
        e.elem,
        '{indent_status}',
        coalesce(to_jsonb(NULLIF(trim(ix.status::text), '')), 'null'::jsonb)
      )
      ORDER BY e.ord
    ),
    '[]'::jsonb
  )
  INTO v_augmented
  FROM jsonb_array_elements(
    CASE WHEN jsonb_typeof(v_base) = 'array' THEN v_base ELSE '[]'::jsonb END
  ) WITH ORDINALITY AS e(elem, ord)
  CROSS JOIN LATERAL (
    SELECT i.status
    FROM   public.trips t
    LEFT JOIN public.indents i ON i.id = t.indent_id
    WHERE  t.id = NULLIF(TRIM(e.elem->>'trip_id'), '')::uuid
  ) ix;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_set(
        jsonb_set(
          conv_row,
          '{conversation_type}',
          CASE
            WHEN nullif(trim(conv_row->>'indent_id'), '') IS NOT NULL THEN to_jsonb('integrated_group'::text)
            ELSE to_jsonb('private_trip'::text)
          END
        ),
        '{messages}',
        COALESCE(
          (
            SELECT jsonb_agg(
              CASE
                WHEN (msg->>'message_type') IN ('status_change', 'system', 'system_log', 'update', 'location_log') THEN
                  jsonb_set(
                    jsonb_set(
                      jsonb_set(msg, '{visibility_tags}', tx.tags_all_parties),
                      '{routing_context_kind}', to_jsonb('trip'::text)
                    ),
                    '{routing_context_id}', to_jsonb(trim(conv_row->>'trip_id'))
                  )
                WHEN (msg->>'message_type') IN ('ledger_event', 'ledger', 'payment', 'ledger_update') THEN
                  jsonb_set(
                    jsonb_set(
                      jsonb_set(
                        jsonb_set(
                          msg,
                          '{visibility_tags}',
                          tx.tags_client_supplier
                        ),
                        '{metadata}',
                        coalesce(msg->'metadata', '{}'::jsonb)
                          || jsonb_build_object('visible_to', jsonb_build_array('client', 'supplier'))
                      ),
                      '{routing_context_kind}',
                      CASE
                        WHEN nullif(trim(conv_row->>'indent_id'), '') IS NOT NULL
                          THEN to_jsonb('indent'::text)
                        ELSE to_jsonb('trip'::text)
                      END
                    ),
                    '{routing_context_id}',
                    CASE
                      WHEN nullif(trim(conv_row->>'indent_id'), '') IS NOT NULL
                        THEN to_jsonb(trim(conv_row->>'indent_id'))
                      ELSE to_jsonb(trim(conv_row->>'trip_id'))
                    END
                  )
                WHEN (msg->>'message_type') = 'tracking' THEN
                  jsonb_set(
                    jsonb_set(
                      jsonb_set(msg, '{visibility_tags}', tx.tags_driver_lanes),
                      '{routing_context_kind}', to_jsonb('trip'::text)
                    ),
                    '{routing_context_id}', to_jsonb(trim(conv_row->>'trip_id'))
                  )
                ELSE
                  jsonb_set(
                    jsonb_set(
                      msg,
                      '{routing_context_kind}', to_jsonb('trip'::text)
                    ),
                    '{routing_context_id}', to_jsonb(trim(conv_row->>'trip_id'))
                  )
              END
              ORDER BY (msg->>'created_at')
            )
            FROM jsonb_array_elements(conv_row->'messages') AS msg
          ),
          '[]'::jsonb
        )
      )
      ORDER BY (conv_row->>'last_message_at') DESC NULLS LAST
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM jsonb_array_elements(v_augmented) AS conv_row
  CROSS JOIN LATERAL (
    SELECT
      COALESCE(
        (
          SELECT jsonb_agg(tc2.id::text ORDER BY tc2.id)
          FROM public.trip_conversations tc2
          WHERE tc2.trip_id = (conv_row->>'trip_id')::uuid
        ),
        '[]'::jsonb
      ) AS tags_all_parties,
      COALESCE(
        (
          SELECT jsonb_agg(tc2.id::text ORDER BY tc2.id)
          FROM public.trip_conversations tc2
          WHERE tc2.trip_id = (conv_row->>'trip_id')::uuid
            AND tc2.party_type IN ('client', 'supplier')
        ),
        '[]'::jsonb
      ) AS tags_client_supplier,
      COALESCE(
        (
          SELECT jsonb_agg(tc2.id::text ORDER BY tc2.id)
          FROM public.trip_conversations tc2
          WHERE tc2.trip_id = (conv_row->>'trip_id')::uuid
            AND tc2.party_type = 'driver'
        ),
        '[]'::jsonb
      ) AS tags_driver_lanes
  ) AS tx;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'context_kind', g.context_kind,
        'context_id',   g.context_id,
        'message_ids',  g.ids
      )
      ORDER BY g.context_kind, g.context_id
    ),
    '[]'::jsonb
  )
  INTO v_by_context
  FROM (
    SELECT
      trim(both '"' from (m->>'routing_context_kind')) AS context_kind,
      trim(both '"' from (m->>'routing_context_id'))   AS context_id,
      jsonb_agg(DISTINCT to_jsonb(m->>'id') ORDER BY to_jsonb(m->>'id')) AS ids
    FROM jsonb_array_elements(COALESCE(v_result, '[]'::jsonb)) AS c
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c->'messages', '[]'::jsonb)) AS m
    WHERE coalesce(trim(m->>'routing_context_id'), '') <> ''
      AND coalesce(trim(m->>'routing_context_kind'), '') <> ''
      AND coalesce(trim(m->>'id'), '') <> ''
    GROUP BY 1, 2
  ) AS g;

  RETURN jsonb_build_object(
    'conversations',         COALESCE(v_result, '[]'::jsonb),
    'messages_by_context',   COALESCE(v_by_context, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_unified_b2b_bootstrap"("p_organization_id" "uuid", "p_message_limit" integer, "p_trip_limit" integer, "p_trip_offset" integer, "p_hub_trip_bucket" "text", "p_include_message_bodies" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_unified_b2b_bootstrap"("p_organization_id" "uuid", "p_message_limit" integer, "p_trip_limit" integer, "p_trip_offset" integer, "p_hub_trip_bucket" "text", "p_include_message_bodies" boolean) IS 'Unified bootstrap: conversations + messages_by_context; indent_status; optional trip window; hub bucket.';



CREATE OR REPLACE FUNCTION "public"."get_unlinked_counterparties"("p_org_id" "uuid") RETURNS TABLE("counterparty_name" "text", "counterparty_type" "text", "trip_count" bigint, "last_trip_date" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH membership_check AS (
    SELECT 1 FROM organization_members
    WHERE organization_id = p_org_id
      AND user_id = auth.uid()
    LIMIT 1
  ),
  unlinked_clients AS (
    SELECT
      TRIM(client_name)   AS counterparty_name,
      'client'::text      AS counterparty_type,
      COUNT(*)            AS trip_count,
      MAX(created_at)     AS last_trip_date
    FROM trips
    WHERE organization_id = p_org_id
      AND client_id IS NULL
      AND client_name IS NOT NULL
      AND TRIM(client_name) <> ''
      AND EXISTS (SELECT 1 FROM membership_check)
    GROUP BY TRIM(client_name)
  )
  SELECT counterparty_name, counterparty_type, trip_count, last_trip_date
  FROM unlinked_clients
  ORDER BY trip_count DESC, last_trip_date DESC
  LIMIT 50;
$$;


ALTER FUNCTION "public"."get_unlinked_counterparties"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_profile_by_email"("p_email" "text") RETURNS TABLE("user_id" "uuid", "full_name" "text", "phone" "text", "email" "text", "avatar_url" "text", "role" "text")
