CREATE OR REPLACE FUNCTION "public"."get_vehicle_monthly_analytics"("p_org_id" "uuid", "p_vehicle_id" "uuid", "p_months_back" integer DEFAULT 12) RETURNS TABLE("period" "text", "revenue" numeric, "expense" numeric, "profit" numeric, "margin_pct" numeric, "trip_count" bigint, "km_driven" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH _period_start AS (
    SELECT date_trunc('month', now() - (p_months_back - 1 || ' months')::interval) AS start_dt
  ),
  _vehicle_trips AS (
    SELECT
      t.id                                   AS trip_id,
      t.client_price                         AS client_price,
      t.supplier_rate                        AS supplier_rate,
      t.driver_commission                    AS driver_commission,
      t.distance                             AS distance,
      COALESCE(t.pickup_date, t.created_at)  AS trip_date
    FROM public.trips t
    WHERE
      (t.vehicle_id = p_vehicle_id)
      AND t.organization_id = p_org_id
      AND COALESCE(t.pickup_date, t.created_at) >= (SELECT start_dt FROM _period_start)
      AND public.is_org_member(p_org_id)
  ),
  _ledger_expense AS (
    SELECT
      to_char(date_trunc('month', COALESCE(tx.transaction_date, tx.created_at)::date), 'YYYY-MM') AS period,
      SUM(COALESCE(tx.amount_out, 0)) AS expense
    FROM public.transactions tx
    WHERE tx.organization_id = p_org_id
      AND tx.trip_id IN (SELECT trip_id FROM _vehicle_trips)
      AND COALESCE(tx.amount_out, 0) > 0
      -- Exclude driver compensation; that's reported on the driver tab.
      AND (tx.contact_type IS DISTINCT FROM 'driver')
      AND public.is_org_member(p_org_id)
    GROUP BY 1
  ),
  _monthly AS (
    SELECT
      to_char(date_trunc('month', vt.trip_date), 'YYYY-MM') AS period,
      SUM(COALESCE(vt.client_price, 0)  - COALESCE(vt.supplier_rate, 0)) AS gross_profit,
      SUM(COALESCE(vt.client_price, 0))  AS revenue,
      COUNT(*)                            AS trip_count,
      SUM(COALESCE(vt.distance, 0))      AS km_driven
    FROM _vehicle_trips vt
    GROUP BY 1
  )
  SELECT
    m.period,
    m.revenue                                            AS revenue,
    COALESCE(le.expense, 0)                              AS expense,
    m.revenue - COALESCE(le.expense, 0)                  AS profit,
    CASE WHEN m.revenue > 0
      THEN ROUND(((m.revenue - COALESCE(le.expense, 0)) / m.revenue) * 100, 2)
      ELSE 0
    END                                                  AS margin_pct,
    m.trip_count,
    m.km_driven
  FROM _monthly m
  LEFT JOIN _ledger_expense le ON le.period = m.period
  ORDER BY m.period ASC;
$$;


ALTER FUNCTION "public"."get_vehicle_monthly_analytics"("p_org_id" "uuid", "p_vehicle_id" "uuid", "p_months_back" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_vehicles_delta"("p_org_id" "uuid", "p_since" "text", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := p_since::TIMESTAMPTZ;
  v_changed   JSONB;
  v_deleted   JSONB;
  v_next      TEXT;
BEGIN
  SELECT
    COALESCE(jsonb_agg(row_to_json(v) ORDER BY v.updated_at) FILTER (WHERE v.deleted_at IS NULL), '[]'),
    COALESCE(jsonb_agg(v.id::TEXT)                           FILTER (WHERE v.deleted_at IS NOT NULL), '[]'),
    MAX(v.updated_at)::TEXT
  INTO v_changed, v_deleted, v_next
  FROM (
    SELECT * FROM vehicles
    WHERE organization_id = p_org_id
      AND updated_at > v_since
    ORDER BY updated_at
    LIMIT p_limit
  ) v;

  RETURN jsonb_build_object(
    'changed',      v_changed,
    'deleted_ids',  v_deleted,
    'next_cursor',  COALESCE(v_next, p_since)
  );
END;
$$;


