CREATE OR REPLACE FUNCTION "public"."global_search"("p_query" "text", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_types" "text"[] DEFAULT NULL::"text"[], "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "display_name" "text", "reference" "text", "secondary_ref" "text", "network_ref" "text", "org_id" "uuid", "rank" real)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    s.entity_type,
    s.entity_id,
    s.display_name,
    s.reference,
    s.secondary_ref,
    s.network_ref,
    s.org_id,
    (ts_rank(s.search_vector, query) * s.relevance_boost)::float4 AS rank
  FROM public.search_index s,
       to_tsquery('english', regexp_replace(trim(p_query), '\s+', ':* & ', 'g') || ':*') AS query
  WHERE
    (p_org_id IS NULL OR s.org_id = p_org_id OR s.org_id IS NULL) AND
    (p_types IS NULL OR s.entity_type = ANY(p_types)) AND
    (
      s.search_vector @@ query OR
      s.reference     ILIKE '%' || p_query || '%' OR
      s.secondary_ref ILIKE '%' || p_query || '%' OR
      s.vehicle_number ILIKE '%' || p_query || '%'
    )
  ORDER BY rank DESC, s.updated_at DESC
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."global_search"("p_query" "text", "p_org_id" "uuid", "p_types" "text"[], "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r                  text;
  onboarding_type      text;
  org_id             uuid;
  org_name           text;
  profile_exists     boolean;
  org_exists         boolean;
  membership_exists  boolean;
  display_name       text;
  signup_phone       text;
BEGIN
  r := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'role'), ''), 'user');

  onboarding_type := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data->>'onboarding_type'), ''),
    CASE
      WHEN COALESCE((NEW.raw_user_meta_data->>'skip_org_creation')::boolean, false) THEN 'member'
      ELSE 'owner'
    END
  );

  display_name := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data->>'full_name'), ''),
    NULLIF(TRIM(NEW.raw_user_meta_data->>'name'), ''),
    NULLIF(SPLIT_PART(NEW.email, '@', 1), ''),
    'User'
  );

  signup_phone := NULLIF(TRIM(NEW.raw_user_meta_data->>'phone'), '');

  INSERT INTO public.users (id, name)
  VALUES (NEW.id, display_name)
  ON CONFLICT (id) DO NOTHING;

  SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id = NEW.id) INTO profile_exists;
  IF NOT profile_exists THEN
    INSERT INTO public.profiles (id, email, full_name, role, aggregated, asset, company_name, phone)
    VALUES (
      NEW.id,
      NEW.email,
      display_name,
      CASE WHEN r IN ('user','driver') THEN r ELSE 'user' END,
      CASE WHEN r = 'driver' THEN false ELSE COALESCE((NEW.raw_user_meta_data->>'aggregated')::boolean, true) END,
      CASE WHEN r = 'driver' THEN false ELSE COALESCE((NEW.raw_user_meta_data->>'asset')::boolean, true) END,
      NULLIF(TRIM(NEW.raw_user_meta_data->>'company_name'), ''),
      signup_phone
    )
    ON CONFLICT (id) DO NOTHING;
    RAISE LOG 'handle_new_user: profile created for user % (role %, onboarding_type %)', NEW.id, r, onboarding_type;
  END IF;

  -- Only owner onboarding provisions a new organization + owner membership.
  IF r = 'user' AND onboarding_type = 'owner' THEN
    SELECT id INTO org_id FROM public.organizations WHERE owner_id = NEW.id LIMIT 1;
    org_exists := (org_id IS NOT NULL);

    IF NOT org_exists THEN
      org_name := COALESCE(
        NULLIF(TRIM(NEW.raw_user_meta_data->>'company_name'), ''),
        display_name || '''s Organization'
      );
      INSERT INTO public.organizations (
        owner_id, name, operating_model,
        address_line, locality, pincode, city, state, zone,
        business_type, employee_count
      ) VALUES (
        NEW.id,
        org_name,
        COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'operating_model'), ''), 'HYBRID'),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'address_line'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'locality'), ''),
        NULLIF(REGEXP_REPLACE(COALESCE(NEW.raw_user_meta_data->>'pincode', ''), '\D', '', 'g'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'city'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'state'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'zone'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'business_type'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'employee_count'), '')
      )
      RETURNING id INTO org_id;

      IF org_id IS NULL THEN
        RAISE EXCEPTION 'handle_new_user: organizations insert did not return id for user %', NEW.id;
      END IF;
      RAISE LOG 'handle_new_user: organization created % for user %', org_id, NEW.id;
    END IF;

    SELECT EXISTS(
      SELECT 1 FROM public.organization_members
      WHERE organization_id = org_id AND user_id = NEW.id
    ) INTO membership_exists;

    IF NOT membership_exists THEN
      INSERT INTO public.organization_members (organization_id, user_id, role, status)
      VALUES (org_id, NEW.id, 'owner', 'active')
      ON CONFLICT (organization_id, user_id) DO UPDATE SET status = 'active', role = 'owner';
      RAISE LOG 'handle_new_user: membership created for user % in org %', NEW.id, org_id;
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE LOG 'handle_new_user FAILED for user % (email %): %', NEW.id, NEW.email, SQLERRM;
    RAISE;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Auth signup trigger: provisions profile; owner onboarding_type creates org + owner membership; member/guest/etc. join via invitation accept.';



CREATE OR REPLACE FUNCTION "public"."idempotency_acquire"("p_key" "text", "p_entity_type" "text", "p_org_id" "uuid", "p_user_id" "uuid", "p_req_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.idempotency_keys%ROWTYPE;
BEGIN
  -- Try to read existing record
  SELECT * INTO v_row FROM public.idempotency_keys WHERE key = p_key;

  IF FOUND THEN
    -- Key exists — check for body mismatch (different request for same key)
    IF v_row.request_hash <> p_req_hash THEN
      RETURN jsonb_build_object(
        'status', 'conflict',
        'error', 'Idempotency key reused with different request body'
      );
    END IF;

    -- Already completed: return stored result
    IF v_row.status = 'completed' THEN
      RETURN jsonb_build_object(
        'status', 'completed',
        'entity_id', v_row.entity_id,
        'response_payload', v_row.response_payload,
        'replayed', true
      );
    END IF;

    -- Pending: still in-flight (or crashed mid-way)
    IF v_row.status = 'pending' AND v_row.created_at > now() - interval '30 seconds' THEN
      RETURN jsonb_build_object(
        'status', 'pending',
        'error', 'Request is still processing. Retry after 30 seconds.'
      );
    END IF;

    -- Failed or stale pending: allow retry
    UPDATE public.idempotency_keys
    SET status = 'pending', error_message = NULL,
        request_hash = p_req_hash, created_at = now(),
        expires_at = now() + interval '24 hours'
    WHERE key = p_key;

    RETURN jsonb_build_object('status', 'retry_allowed');
  END IF;

  -- New key: insert and claim the slot
  INSERT INTO public.idempotency_keys (key, entity_type, org_id, user_id, request_hash)
  VALUES (p_key, p_entity_type, p_org_id, p_user_id, p_req_hash)
  ON CONFLICT (key) DO NOTHING;

  RETURN jsonb_build_object('status', 'acquired');
END;
$$;


ALTER FUNCTION "public"."idempotency_acquire"("p_key" "text", "p_entity_type" "text", "p_org_id" "uuid", "p_user_id" "uuid", "p_req_hash" "text") OWNER TO "postgres";


