CREATE OR REPLACE FUNCTION "public"."invite_driver"("p_phone" "text", "p_name" "text", "p_org_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone_norm text := public.normalise_phone(p_phone);
  v_driver_id uuid;
  v_invite_id uuid;
  v_org_name text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  IF length(coalesce(v_phone_norm, '')) < 10 THEN
    RAISE EXCEPTION 'Valid phone required';
  END IF;

  SELECT id INTO v_driver_id
  FROM public.drivers
  WHERE phone_normalised = v_phone_norm
    AND organization_id = p_org_id
    AND left_at IS NULL
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_driver_id IS NULL THEN
    INSERT INTO public.drivers (name, phone, organization_id, status)
    VALUES (
      coalesce(nullif(trim(p_name), ''), 'Driver'),
      nullif(trim(p_phone), ''),
      p_org_id,
      'offline'
    )
    RETURNING id INTO v_driver_id;
  END IF;

  UPDATE public.driver_invites
  SET status = 'expired'
  WHERE driver_id = v_driver_id
    AND status = 'pending'
    AND to_user_id IS NULL;

  SELECT name INTO v_org_name FROM public.organizations WHERE id = p_org_id;

  INSERT INTO public.driver_invites (
    driver_id,
    from_organization_id,
    phone_normalised,
    invited_by,
    to_user_id,
    invitee_name,
    from_org_name,
    status,
    expires_at
  )
  VALUES (
    v_driver_id,
    p_org_id,
    v_phone_norm,
    auth.uid(),
    NULL,
    coalesce(nullif(trim(p_name), ''), 'Driver'),
    coalesce(v_org_name, 'Company'),
    'pending',
    now() + interval '7 days'
  )
  RETURNING id INTO v_invite_id;

  RETURN v_invite_id;
END;
$$;


ALTER FUNCTION "public"."invite_driver"("p_phone" "text", "p_name" "text", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invite_driver"("p_phone" "text", "p_name" "text", "p_org_id" "uuid") IS 'Dispatcher-led roster invite: find/create unlinked driver row and return invite UUID for deep link / OTP flows.';



