CREATE OR REPLACE FUNCTION "public"."kill_idle_in_transaction_sessions"("p_threshold" interval DEFAULT '00:05:00'::interval) RETURNS TABLE("pid" integer, "duration" interval, "query" "text", "terminated" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    a.pid,
    (now() - a.state_change)          AS duration,
    left(a.query, 200)                 AS query,
    pg_terminate_backend(a.pid)        AS terminated
  FROM pg_stat_activity a
  WHERE a.state = 'idle in transaction'
    AND (now() - a.state_change) > p_threshold
    -- Never terminate our own connection or system backends
    AND a.pid <> pg_backend_pid()
    AND a.backend_type = 'client backend';
END;
$$;


ALTER FUNCTION "public"."kill_idle_in_transaction_sessions"("p_threshold" interval) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."kill_idle_in_transaction_sessions"("p_threshold" interval) IS 'Terminates client sessions idle in transaction beyond threshold (default 5 min). Run manually or schedule via pg_cron.';



CREATE OR REPLACE FUNCTION "public"."leave_fleet"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated int;
BEGIN
  UPDATE public.drivers
  SET left_at = now()
  WHERE organization_id = p_organization_id
    AND user_id = auth.uid()
    AND left_at IS NULL;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'No active driver link found for this organization';
  END IF;
END;
$$;


