    s.entity_id     = (CASE WHEN p_ref ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                            THEN p_ref::uuid ELSE NULL END)
