CREATE OR REPLACE FUNCTION "public"."make_operational_org_code"("p_org_name" "text", "p_org_id" "uuid", "p_salt" integer DEFAULT 0) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_letters text;
  v_hash_input text;
  v_hash_num bigint;
  v_digits text;
BEGIN
  v_letters := upper(regexp_replace(coalesce(p_org_name, 'ORG'), '[^A-Za-z]', '', 'g'));
  IF length(v_letters) = 0 THEN
    v_letters := 'ORG';
  END IF;
  v_letters := substr(v_letters || 'XXX', 1, 3);

  v_hash_input := coalesce(p_org_id::text, '') || ':' || coalesce(p_salt::text, '0');
  v_hash_num := (
    ('x' || substr(md5(v_hash_input), 1, 8))::bit(32)::bigint
  );
  v_digits := lpad(((abs(v_hash_num) % 1000))::text, 3, '0');

  RETURN v_letters || v_digits;
END;
$$;


ALTER FUNCTION "public"."make_operational_org_code"("p_org_name" "text", "p_org_id" "uuid", "p_salt" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_chat_conversation_read"("p_conversation_id" "uuid", "p_up_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.fn_chat_can_access_conversation(p_conversation_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  INSERT INTO chat_participants (conversation_id, user_id, last_read_at)
  VALUES (p_conversation_id, auth.uid(), coalesce(p_up_to, now()))
  ON CONFLICT (conversation_id, user_id)
  DO UPDATE SET last_read_at = GREATEST(
    coalesce(chat_participants.last_read_at, 'epoch'::timestamptz),
    coalesce(EXCLUDED.last_read_at, now())
  );
END;
$$;


ALTER FUNCTION "public"."mark_chat_conversation_read"("p_conversation_id" "uuid", "p_up_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.trip_messages
  SET    is_read = TRUE,
         read_at = COALESCE(read_at, NOW())
  WHERE  conversation_id = p_conversation_id
    AND  is_read = FALSE
    AND  sender_role IS DISTINCT FROM 'dispatcher';

  UPDATE public.trip_conversations
  SET    unread_dispatcher_count = 0,
         updated_at = NOW()
  WHERE  id = p_conversation_id;
END;
$$;


ALTER FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid") IS 'Marks all non-dispatcher unread messages in the thread read and zeros unread_dispatcher_count. Keeps counters consistent with mark_messages_seen.';



CREATE OR REPLACE FUNCTION "public"."mark_delivered"("p_message_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE public.trip_messages
  SET    is_delivered = TRUE,
         delivered_at = now()
  WHERE  id = ANY(p_message_ids)
    AND  is_delivered = FALSE;   -- skip already-delivered; avoids no-op write amplification
$$;


ALTER FUNCTION "public"."mark_delivered"("p_message_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_delivered"("p_message_ids" "uuid"[]) IS 'Batch-marks messages as delivered. Called by the receiver device on Realtime INSERT event. The resulting UPDATE triggers a Realtime UPDATE event that the sender uses for delivery receipts (single → double tick).';



CREATE OR REPLACE FUNCTION "public"."mark_driver_signup_match_linked_from_invite"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'accepted' AND OLD.status IS DISTINCT FROM NEW.status THEN
    UPDATE public.driver_signup_matches
    SET state = 'linked',
        acted_at = now(),
        acted_by = coalesce(NEW.responded_by, auth.uid()),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('accepted_invite_id', NEW.id)
    WHERE organization_id = NEW.from_organization_id
      AND matched_user_id = NEW.to_user_id
      AND state IN ('pending_owner_action', 'invite_sent', 'ignored', 'declined');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."mark_driver_signup_match_linked_from_invite"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_messages_seen"("p_conversation_id" "uuid", "p_message_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Mark individual messages as read
  UPDATE public.trip_messages
  SET    is_read  = TRUE,
         read_at  = now()
  WHERE  id                = ANY(p_message_ids)
    AND  conversation_id   = p_conversation_id
    AND  is_read           = FALSE;

  -- Reset the unread counter on the parent conversation.
  -- Re-derive from the actual unread count rather than decrementing
  -- so bursts of simultaneous marks land correctly (no race on counter).
  UPDATE public.trip_conversations
  SET    unread_dispatcher_count = (
    SELECT COUNT(*)
    FROM   public.trip_messages tm
    WHERE  tm.conversation_id = p_conversation_id
      AND  tm.is_read         = FALSE
      AND  tm.sender_role     <> 'dispatcher'
  )
  WHERE  id = p_conversation_id;
END;
$$;


ALTER FUNCTION "public"."mark_messages_seen"("p_conversation_id" "uuid", "p_message_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_messages_seen"("p_conversation_id" "uuid", "p_message_ids" "uuid"[]) IS 'Per-message seen tracking for onViewableItemsChanged integration. Marks individual message rows as read and re-derives the conversation unread counter. More granular than mark_conversation_read.';



CREATE OR REPLACE FUNCTION "public"."mark_network_conversation_read"("p_conversation_id" "uuid", "p_reader_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_a uuid;
BEGIN
  SELECT org_a_id INTO v_org_a
  FROM public.network_conversations WHERE id = p_conversation_id;

  IF p_reader_org_id = v_org_a THEN
    UPDATE public.network_conversations SET unread_count_a = 0, updated_at = NOW() WHERE id = p_conversation_id;
  ELSE
    UPDATE public.network_conversations SET unread_count_b = 0, updated_at = NOW() WHERE id = p_conversation_id;
  END IF;

  UPDATE public.network_messages
  SET is_read_by_other = TRUE, read_at = NOW()
  WHERE conversation_id = p_conversation_id
    AND sender_org_id <> p_reader_org_id
    AND is_read_by_other = FALSE;
END;
$$;


ALTER FUNCTION "public"."mark_network_conversation_read"("p_conversation_id" "uuid", "p_reader_org_id" "uuid") OWNER TO "postgres";


