  UPDATE public.shared_ledger_notifications
  SET
    status = 'handled',
    handled_at = now(),
    handled_by_user_id = auth.uid(),
    updated_at = now()
  WHERE id = p_id
    AND organization_id = p_org_id
    AND status IN ('open', 'read');
END;
$$;


