CREATE OR REPLACE FUNCTION "public"."mark_shared_ledger_notification_read"("p_id" "uuid", "p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_org_member(p_org_id) THEN
    RETURN;
  END IF;
  UPDATE public.shared_ledger_notifications
  SET
    status = 'read',
    read_at = now(),
    updated_at = now()
  WHERE id = p_id
    AND organization_id = p_org_id
    AND status = 'open';
END;
$$;


