CREATE OR REPLACE FUNCTION "public"."normalise_phone"("raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  digits text;
BEGIN
  digits := regexp_replace(coalesce(raw, ''), '[^0-9]', '', 'g');
  RETURN right(digits, 10);
END;
$$;


