COMMENT ON FUNCTION "public"."normalise_phone"("raw" "text") IS 'Strip non-digits and return last 10 digits for roster/auth phone matching.';



CREATE OR REPLACE FUNCTION "public"."normalize_phone_canon"("p_phone" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN length(d) >= 12 AND left(d, 2) = '91' THEN right(d, 10)
    WHEN length(d) >= 10 THEN right(d, 10)
    ELSE d
  END
  FROM (SELECT regexp_replace(coalesce(p_phone, ''), '\D', '', 'g') AS d) s
  WHERE coalesce(p_phone, '') <> '';
$$;


ALTER FUNCTION "public"."normalize_phone_canon"("p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_phone_canon"("p_phone" "text") IS 'Normalize phone to 10-digit canon for Indian mobile matching.';



