CREATE OR REPLACE FUNCTION "public"."on_connection_request_approved"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_other_owner_id uuid;
  v_other_phone text;
  v_linked int := 0;
  v_already int;
  v_placeholder_phone text;
  v_org_id uuid;
  v_other_org_id uuid;
BEGIN
  IF new.status <> 'approved' OR old.status = 'approved' THEN
    RETURN new;
  END IF;

  IF new.request_carrier_supplier THEN
    INSERT INTO public.organization_relations (from_organization_id, to_organization_id, relation_type, status)
    VALUES (new.from_organization_id, new.to_organization_id, 'client_supplier', 'active')
    ON CONFLICT (from_organization_id, to_organization_id, relation_type)
    DO UPDATE SET status = 'active', updated_at = now();
  END IF;

  IF new.request_shipper_client THEN
    INSERT INTO public.organization_relations (from_organization_id, to_organization_id, relation_type, status)
    VALUES (new.from_organization_id, new.to_organization_id, 'supplier_client', 'active')
    ON CONFLICT (from_organization_id, to_organization_id, relation_type)
    DO UPDATE SET status = 'active', updated_at = now();
  END IF;

  -- request_shipper_client: from_org adds to_org as CLIENT; to_org adds from_org as SUPPLIER.
  IF new.request_shipper_client THEN
    v_linked := 0;
    SELECT 1 INTO v_already
    FROM public.clients
    WHERE organization_id = new.from_organization_id
      AND linked_organization_id = new.to_organization_id
    LIMIT 1;

    IF v_already IS NULL THEN
      v_org_id := new.from_organization_id;
      v_other_org_id := new.to_organization_id;
      v_placeholder_phone := 'linked-' || v_other_org_id::text;

      SELECT o.owner_id INTO v_other_owner_id
      FROM public.organizations o
      WHERE o.id = v_other_org_id;

      IF v_other_owner_id IS NOT NULL THEN
        SELECT trim(coalesce(p.phone, '')) INTO v_other_phone
        FROM public.profiles p
        WHERE p.id = v_other_owner_id;

        IF v_other_phone <> '' THEN
          UPDATE public.clients
          SET linked_organization_id = v_other_org_id,
              is_integrated = true,
              updated_at = now()
          WHERE organization_id = v_org_id
            AND linked_organization_id IS NULL
            AND phone IS NOT NULL
            AND (
              trim(regexp_replace(coalesce(phone, ''), '\s+', '', 'g')) =
                trim(regexp_replace(v_other_phone, '\s+', '', 'g'))
              OR (
                length(regexp_replace(coalesce(phone, ''), '\D', '', 'g')) >= 10
                AND length(regexp_replace(v_other_phone, '\D', '', 'g')) >= 10
                AND right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) =
                  right(regexp_replace(v_other_phone, '\D', '', 'g'), 10)
              )
            );
          GET DIAGNOSTICS v_linked = row_count;
        END IF;
      END IF;

      IF v_linked = 0 THEN
        UPDATE public.clients c
        SET name = coalesce(nullif(trim(o.name), ''), c.name, 'Connected'),
            linked_organization_id = v_other_org_id,
            is_integrated = true,
            updated_at = now()
        FROM public.organizations o
        WHERE o.id = v_other_org_id
          AND c.organization_id = v_org_id
          AND c.phone = v_placeholder_phone;
        GET DIAGNOSTICS v_linked = row_count;
      END IF;

      IF v_linked = 0 THEN
        INSERT INTO public.clients (organization_id, name, phone, email, linked_organization_id, is_integrated, updated_at)
        SELECT v_org_id,
               coalesce(nullif(trim(o.name), ''), 'Connected'),
               v_placeholder_phone,
               NULL,
               v_other_org_id,
               true,
               now()
        FROM public.organizations o
        WHERE o.id = v_other_org_id
        ON CONFLICT (organization_id, linked_organization_id)
          WHERE linked_organization_id IS NOT NULL
        DO UPDATE SET is_integrated = true, updated_at = now();

        IF NOT FOUND THEN
          INSERT INTO public.clients (organization_id, name, phone, linked_organization_id, is_integrated, updated_at)
          VALUES (v_org_id, 'Connected', v_placeholder_phone, v_other_org_id, true, now())
          ON CONFLICT (organization_id, linked_organization_id)
            WHERE linked_organization_id IS NOT NULL
          DO UPDATE SET is_integrated = true, updated_at = now();
        END IF;
      END IF;
    ELSE
      UPDATE public.clients
      SET is_integrated = true,
          linked_organization_id = new.to_organization_id,
          updated_at = now()
      WHERE organization_id = new.from_organization_id
        AND linked_organization_id = new.to_organization_id;
    END IF;

    v_linked := 0;
    SELECT 1 INTO v_already
    FROM public.suppliers
    WHERE organization_id = new.to_organization_id
      AND linked_organization_id = new.from_organization_id
    LIMIT 1;

    IF v_already IS NULL THEN
      v_org_id := new.to_organization_id;
      v_other_org_id := new.from_organization_id;

      SELECT o.owner_id INTO v_other_owner_id
      FROM public.organizations o
      WHERE o.id = v_other_org_id;

      IF v_other_owner_id IS NOT NULL THEN
        SELECT trim(coalesce(p.phone, '')) INTO v_other_phone
        FROM public.profiles p
        WHERE p.id = v_other_owner_id;

        IF v_other_phone <> '' THEN
          UPDATE public.suppliers
          SET linked_organization_id = v_other_org_id,
              supplier_type = 'integrated',
              updated_at = now()
          WHERE organization_id = v_org_id
            AND (linked_organization_id IS NULL OR linked_organization_id <> v_other_org_id)
            AND phone IS NOT NULL
            AND (
              trim(regexp_replace(coalesce(phone, ''), '\s+', '', 'g')) =
                trim(regexp_replace(v_other_phone, '\s+', '', 'g'))
              OR (
                length(regexp_replace(coalesce(phone, ''), '\D', '', 'g')) >= 10
                AND length(regexp_replace(v_other_phone, '\D', '', 'g')) >= 10
                AND right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) =
                  right(regexp_replace(v_other_phone, '\D', '', 'g'), 10)
              )
            );
          GET DIAGNOSTICS v_linked = row_count;
        END IF;
      END IF;

      IF v_linked = 0 THEN
        INSERT INTO public.suppliers (organization_id, name, phone, email, linked_organization_id, supplier_type, updated_at)
        SELECT v_org_id,
               coalesce(nullif(trim(o.name), ''), 'Connected'),
               NULL,
               NULL,
               v_other_org_id,
               'integrated',
               now()
        FROM public.organizations o
        WHERE o.id = v_other_org_id
        ON CONFLICT (organization_id, linked_organization_id)
          WHERE linked_organization_id IS NOT NULL
        DO UPDATE SET supplier_type = 'integrated', updated_at = now();

        IF NOT FOUND THEN
          INSERT INTO public.suppliers (organization_id, name, linked_organization_id, supplier_type, updated_at)
          VALUES (v_org_id, 'Connected', v_other_org_id, 'integrated', now())
          ON CONFLICT (organization_id, linked_organization_id)
            WHERE linked_organization_id IS NOT NULL
          DO UPDATE SET supplier_type = 'integrated', updated_at = now();
        END IF;
      END IF;
    ELSE
      UPDATE public.suppliers
      SET supplier_type = 'integrated',
          linked_organization_id = new.from_organization_id,
          updated_at = now()
      WHERE organization_id = new.to_organization_id
        AND linked_organization_id = new.from_organization_id;
    END IF;

  -- request_carrier_supplier: from_org adds to_org as SUPPLIER; to_org adds from_org as CLIENT.
  ELSIF new.request_carrier_supplier THEN
    v_linked := 0;
    SELECT 1 INTO v_already
    FROM public.suppliers
    WHERE organization_id = new.from_organization_id
      AND linked_organization_id = new.to_organization_id
    LIMIT 1;

    IF v_already IS NULL THEN
      v_org_id := new.from_organization_id;
      v_other_org_id := new.to_organization_id;

      SELECT o.owner_id INTO v_other_owner_id
      FROM public.organizations o
      WHERE o.id = v_other_org_id;

      IF v_other_owner_id IS NOT NULL THEN
        SELECT trim(coalesce(p.phone, '')) INTO v_other_phone
        FROM public.profiles p
        WHERE p.id = v_other_owner_id;

        IF v_other_phone <> '' THEN
          UPDATE public.suppliers
          SET linked_organization_id = v_other_org_id,
              supplier_type = 'integrated',
              updated_at = now()
          WHERE organization_id = v_org_id
            AND (linked_organization_id IS NULL OR linked_organization_id <> v_other_org_id)
            AND phone IS NOT NULL
            AND (
              trim(regexp_replace(coalesce(phone, ''), '\s+', '', 'g')) =
                trim(regexp_replace(v_other_phone, '\s+', '', 'g'))
              OR (
                length(regexp_replace(coalesce(phone, ''), '\D', '', 'g')) >= 10
                AND length(regexp_replace(v_other_phone, '\D', '', 'g')) >= 10
                AND right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) =
                  right(regexp_replace(v_other_phone, '\D', '', 'g'), 10)
              )
            );
          GET DIAGNOSTICS v_linked = row_count;
        END IF;
      END IF;

      IF v_linked = 0 THEN
        INSERT INTO public.suppliers (organization_id, name, phone, email, linked_organization_id, supplier_type, updated_at)
        SELECT v_org_id,
               coalesce(nullif(trim(o.name), ''), 'Connected'),
               NULL,
               NULL,
               v_other_org_id,
               'integrated',
               now()
        FROM public.organizations o
        WHERE o.id = v_other_org_id
        ON CONFLICT (organization_id, linked_organization_id)
          WHERE linked_organization_id IS NOT NULL
        DO UPDATE SET supplier_type = 'integrated', updated_at = now();

        IF NOT FOUND THEN
          INSERT INTO public.suppliers (organization_id, name, linked_organization_id, supplier_type, updated_at)
          VALUES (v_org_id, 'Connected', v_other_org_id, 'integrated', now())
          ON CONFLICT (organization_id, linked_organization_id)
            WHERE linked_organization_id IS NOT NULL
          DO UPDATE SET supplier_type = 'integrated', updated_at = now();
        END IF;
      END IF;
    ELSE
      UPDATE public.suppliers
      SET supplier_type = 'integrated',
          linked_organization_id = new.to_organization_id,
          updated_at = now()
      WHERE organization_id = new.from_organization_id
        AND linked_organization_id = new.to_organization_id;
    END IF;

    v_linked := 0;
    SELECT 1 INTO v_already
    FROM public.clients
    WHERE organization_id = new.to_organization_id
      AND linked_organization_id = new.from_organization_id
    LIMIT 1;

    IF v_already IS NULL THEN
      v_org_id := new.to_organization_id;
      v_other_org_id := new.from_organization_id;
      v_placeholder_phone := 'linked-' || v_other_org_id::text;

      SELECT o.owner_id INTO v_other_owner_id
      FROM public.organizations o
      WHERE o.id = v_other_org_id;

      IF v_other_owner_id IS NOT NULL THEN
        SELECT trim(coalesce(p.phone, '')) INTO v_other_phone
        FROM public.profiles p
        WHERE p.id = v_other_owner_id;

        IF v_other_phone <> '' THEN
          UPDATE public.clients
          SET linked_organization_id = v_other_org_id,
              is_integrated = true,
              updated_at = now()
          WHERE organization_id = v_org_id
            AND linked_organization_id IS NULL
            AND phone IS NOT NULL
            AND (
              trim(regexp_replace(coalesce(phone, ''), '\s+', '', 'g')) =
                trim(regexp_replace(v_other_phone, '\s+', '', 'g'))
              OR (
                length(regexp_replace(coalesce(phone, ''), '\D', '', 'g')) >= 10
                AND length(regexp_replace(v_other_phone, '\D', '', 'g')) >= 10
                AND right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) =
                  right(regexp_replace(v_other_phone, '\D', '', 'g'), 10)
              )
            );
          GET DIAGNOSTICS v_linked = row_count;
        END IF;
      END IF;

      IF v_linked = 0 THEN
        UPDATE public.clients c
        SET name = coalesce(nullif(trim(o.name), ''), c.name, 'Connected'),
            linked_organization_id = v_other_org_id,
            is_integrated = true,
            updated_at = now()
        FROM public.organizations o
        WHERE o.id = v_other_org_id
          AND c.organization_id = v_org_id
          AND c.phone = v_placeholder_phone;
        GET DIAGNOSTICS v_linked = row_count;
      END IF;

      IF v_linked = 0 THEN
        INSERT INTO public.clients (organization_id, name, phone, email, linked_organization_id, is_integrated, updated_at)
        SELECT v_org_id,
               coalesce(nullif(trim(o.name), ''), 'Connected'),
               v_placeholder_phone,
               NULL,
               v_other_org_id,
               true,
               now()
        FROM public.organizations o
        WHERE o.id = v_other_org_id
        ON CONFLICT (organization_id, linked_organization_id)
          WHERE linked_organization_id IS NOT NULL
        DO UPDATE SET is_integrated = true, updated_at = now();

        IF NOT FOUND THEN
          INSERT INTO public.clients (organization_id, name, phone, linked_organization_id, is_integrated, updated_at)
          VALUES (v_org_id, 'Connected', v_placeholder_phone, v_other_org_id, true, now())
          ON CONFLICT (organization_id, linked_organization_id)
            WHERE linked_organization_id IS NOT NULL
          DO UPDATE SET is_integrated = true, updated_at = now();
        END IF;
      END IF;
    ELSE
      UPDATE public.clients
      SET is_integrated = true,
          linked_organization_id = new.from_organization_id,
          updated_at = now()
      WHERE organization_id = new.to_organization_id
        AND linked_organization_id = new.from_organization_id;
    END IF;
  END IF;

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."on_connection_request_approved"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."on_organization_created_link_manual_clients"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner_phone text;
BEGIN
  SELECT trim(coalesce(p.phone, '')) INTO v_owner_phone
  FROM public.profiles p WHERE p.id = new.owner_id;

  IF coalesce(v_owner_phone, '') = '' THEN
    RETURN new;
  END IF;

  -- Link unlinked manual clients whose stored phone matches this new org's owner
  UPDATE public.clients
  SET linked_organization_id = new.id,
      updated_at = now()
  WHERE linked_organization_id IS NULL
    AND is_integrated = false
    AND phone IS NOT NULL
    AND trim(regexp_replace(phone, '\s+', '', 'g'))
      = trim(regexp_replace(v_owner_phone, '\s+', '', 'g'))
    AND organization_id <> new.id;  -- never self-link

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."on_organization_created_link_manual_clients"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."operational_prefix_for_entity"("p_entity_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  CASE lower(trim(p_entity_type))
    WHEN 'trip' THEN RETURN 'TRP';
    WHEN 'indent' THEN RETURN 'IND';
    WHEN 'vehicle' THEN RETURN 'VEH';
    WHEN 'driver' THEN RETURN 'DRV';
    WHEN 'invoice' THEN RETURN 'INV';
    WHEN 'pod' THEN RETURN 'POD';
    ELSE
      RAISE EXCEPTION 'Unsupported entity_type: %', p_entity_type;
  END CASE;
END;
$$;


ALTER FUNCTION "public"."operational_prefix_for_entity"("p_entity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ops_agent_rate_limit_try_consume"("p_user_id" "uuid", "p_max_per_window" integer DEFAULT 20, "p_window_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bucket timestamptz;
  v_lock bigint;
  v_count integer;
BEGIN
  IF p_user_id IS NULL OR coalesce(p_max_per_window, 0) < 1 OR coalesce(p_window_seconds, 0) < 1 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_args');
  END IF;

  v_bucket := to_timestamp(floor(extract(epoch from clock_timestamp()) / p_window_seconds) * p_window_seconds);

  v_lock := hashtextextended(p_user_id::text || '|' || extract(epoch from v_bucket)::text, 0);
  PERFORM pg_advisory_xact_lock(v_lock);

  SELECT r.request_count
    INTO v_count
    FROM public.ops_agent_rate_log AS r
   WHERE r.user_id = p_user_id
     AND r.window_start = v_bucket
   FOR UPDATE;

  IF v_count IS NULL THEN
    INSERT INTO public.ops_agent_rate_log (user_id, window_start, request_count)
    VALUES (p_user_id, v_bucket, 1);
    RETURN jsonb_build_object('allowed', true, 'count', 1);
  END IF;

  IF v_count >= p_max_per_window THEN
    RETURN jsonb_build_object('allowed', false, 'count', v_count);
  END IF;

  UPDATE public.ops_agent_rate_log AS r
     SET request_count = r.request_count + 1
   WHERE r.user_id = p_user_id
     AND r.window_start = v_bucket
  RETURNING r.request_count INTO v_count;

  IF random() < 0.02::double precision THEN
    DELETE FROM public.ops_agent_rate_log AS r
     WHERE r.window_start < (clock_timestamp() - interval '2 days');
  END IF;

  RETURN jsonb_build_object('allowed', true, 'count', v_count);
END;
$$;


ALTER FUNCTION "public"."ops_agent_rate_limit_try_consume"("p_user_id" "uuid", "p_max_per_window" integer, "p_window_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ops_agent_rate_limit_try_consume"("p_user_id" "uuid", "p_max_per_window" integer, "p_window_seconds" integer) IS 'Atomically increment ops-agent usage for p_user_id in the current time bucket; service_role only. Edge verifies JWT before calling.';



CREATE OR REPLACE FUNCTION "public"."organization_name_is_taken"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key text;
BEGIN
  v_key := lower(btrim(coalesce(p_name, '')));
  IF v_key = '' THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.organizations o
    WHERE lower(btrim(coalesce(o.name, ''))) = v_key
    LIMIT 1
  );
END;
$$;


ALTER FUNCTION "public"."organization_name_is_taken"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."organization_name_is_taken"("p_name" "text") IS 'True if organizations.name already equals the trimmed name (case-insensitive). Used before auth sign-up. Anon can call.';



