    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'platform', 'pg_catalog'
    AS $$
  SELECT platform.next_canonical_code(p_prefix, p_width);
$$;


ALTER FUNCTION "public"."platform_next_canonical_code"("p_prefix" "text", "p_width" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."precheck_team_invite_contact"("p_org_id" "uuid", "p_phone" "text", "p_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canon       text;
  v_email       text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_user_id     uuid;
  v_user_phone  text;
  v_user_email  text;
  v_user_name   text;
  v_target      text := 'none';
  v_other_orgs  jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  v_canon := public.normalize_phone_canon(p_phone);

  -- Resolve user by phone first
  IF v_canon IS NOT NULL AND length(v_canon) >= 10 THEN
    SELECT p.id, p.phone, p.email, p.full_name
    INTO v_user_id, v_user_phone, v_user_email, v_user_name
    FROM public.profiles p
    WHERE public.normalize_phone_canon(p.phone) = v_canon
    LIMIT 1;
  END IF;

  -- Resolve user by email if phone miss
  IF v_user_id IS NULL AND v_email IS NOT NULL THEN
    SELECT p.id, p.phone, p.email, p.full_name
    INTO v_user_id, v_user_phone, v_user_email, v_user_name
    FROM public.profiles p
    WHERE lower(trim(p.email)) = v_email
    LIMIT 1;
  END IF;

  IF v_user_id IS NOT NULL THEN
    SELECT om.status INTO v_target
    FROM public.organization_members om
    WHERE om.organization_id = p_org_id AND om.user_id = v_user_id
    LIMIT 1;

    SELECT coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'name', coalesce(o.name, 'Organization'))), '[]'::jsonb)
    INTO v_other_orgs
    FROM public.organization_members om
    JOIN public.organizations o ON o.id = om.organization_id
    WHERE om.user_id = v_user_id
      AND om.organization_id <> p_org_id
      AND om.status = 'active';

    IF v_target = 'active' THEN
      RETURN jsonb_build_object(
        'recommended_action', 'already_member',
        'user_id', v_user_id,
        'user_name', v_user_name,
        'user_email', v_user_email,
        'user_phone', v_user_phone,
        'other_orgs', v_other_orgs
      );
    END IF;

    IF v_target = 'invited' THEN
      RETURN jsonb_build_object(
        'recommended_action', 'already_invited',
        'user_id', v_user_id,
        'user_name', v_user_name,
        'user_email', v_user_email,
        'user_phone', v_user_phone,
        'other_orgs', v_other_orgs
      );
    END IF;

    RETURN jsonb_build_object(
      'recommended_action', 'invite_existing_user',
      'user_id', v_user_id,
      'user_name', v_user_name,
      'user_email', v_user_email,
      'user_phone', v_user_phone,
      'other_orgs', v_other_orgs,
      'phone_matches_invite',
      v_canon IS NOT NULL AND public.normalize_phone_canon(v_user_phone) = v_canon
    );
  END IF;

  -- No Pulse account — but email must not already be taken (stale phone on profile edge case)
  IF v_email IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM auth.users u WHERE lower(trim(u.email)) = v_email
    ) OR EXISTS (
      SELECT 1 FROM public.profiles p WHERE lower(trim(p.email)) = v_email
    ) THEN
      RETURN jsonb_build_object(
        'recommended_action', 'email_registered',
        'message', 'This email already has a Pulse account. Invite by signing them in, not as a new signup.'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'recommended_action', 'pending_invite',
    'other_orgs', '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."precheck_team_invite_contact"("p_org_id" "uuid", "p_phone" "text", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_operational_code_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.operational_code IS NOT NULL
     AND NEW.operational_code IS DISTINCT FROM OLD.operational_code THEN
    RAISE EXCEPTION 'organizations.operational_code is immutable once set';
  END IF;
  NEW.operational_code := upper(btrim(NEW.operational_code));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_operational_code_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_b2b_event"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_trip        RECORD;
  v_prev_status TEXT;
  v_new_status  TEXT;
  v_content     TEXT;
  v_user_id     UUID;
  v_user_name   TEXT;
  v_conv_id     UUID;
  v_new_id      UUID;
  v_message_ids UUID[]    := '{}';
  v_trip_state  JSONB;
  v_msg_meta    JSONB;
  v_sender_role TEXT;
  v_now         TIMESTAMPTZ;
  v_canonical   TEXT;
BEGIN
  SET LOCAL statement_timeout = '8s';
  v_now       := clock_timestamp();
  v_canonical := CASE p_event_type
    WHEN 'system_log'  THEN 'system'
    WHEN 'payment'     THEN 'ledger'
    WHEN 'feedback'    THEN 'feedback_request'
    ELSE p_event_type
  END;

  SELECT t.* INTO v_trip
  FROM   public.trips t
  WHERE  t.id = p_trip_id
    AND (
      t.organization_id = p_organization_id
      OR EXISTS (
        SELECT 1 FROM public.suppliers s
        WHERE  s.id                    = t.supplier_id
          AND  s.linked_organization_id = p_organization_id
      )
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'process_b2b_event: trip % not accessible for org %',
      p_trip_id, p_organization_id
    USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_prev_status := v_trip.status;
  v_new_status  := COALESCE(p_payload->>'new_status', v_prev_status);
  v_content     := COALESCE(NULLIF(trim(p_payload->>'content'), ''), 'System update');
  v_user_id     := NULLIF(p_payload->>'user_id', '')::UUID;
  v_user_name   := COALESCE(NULLIF(p_payload->>'user_name', ''), 'System');
  v_conv_id     := NULLIF(p_payload->>'conversation_id', '')::UUID;

  UPDATE public.trips
  SET
    status     = v_new_status,
    driver_id  = CASE WHEN p_payload ? 'driver_id'
                      THEN NULLIF(p_payload->>'driver_id', '')::UUID
                      ELSE driver_id  END,
    vehicle_id = CASE WHEN p_payload ? 'vehicle_id'
                      THEN NULLIF(p_payload->>'vehicle_id', '')::UUID
                      ELSE vehicle_id END,
    updated_at = v_now
  WHERE id = p_trip_id;

  SELECT t.* INTO v_trip FROM public.trips t WHERE t.id = p_trip_id;

  v_trip_state := jsonb_build_object(
    'id',                     v_trip.id,
    'trip_number',            v_trip.trip_number,
    'display_trip_id',        v_trip.display_trip_id,
    'status',                 v_trip.status,
    'driver_id',              v_trip.driver_id,
    'vehicle_id',             v_trip.vehicle_id,
    'supplier_id',            v_trip.supplier_id,
    'client_id',              v_trip.client_id,
    'driver_display_name',    v_trip.driver_display_name,
    'vehicle_display_number', v_trip.vehicle_display_number,
    'pickup_area',            v_trip.pickup_area,
    'drop_location',          v_trip.drop_location,
    'pickup_date',            v_trip.pickup_date,
    'payment_status',         v_trip.payment_status,
    'updated_at',             to_char(v_now AT TIME ZONE 'UTC',
                                      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );

  v_sender_role := CASE v_canonical
    WHEN 'tracking'     THEN 'driver'
    WHEN 'ledger'        THEN 'dispatcher'
    WHEN 'ledger_event'  THEN 'dispatcher'
    ELSE                   'system'
  END;

  v_msg_meta := jsonb_build_object(
    'event_type',      p_event_type,
    'previous_status', v_prev_status,
    'new_status',      v_new_status,
    'changed_by',      v_user_id,
    'changed_by_name', v_user_name,
    'changed_at',      to_char(v_now AT TIME ZONE 'UTC',
                               'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'trip_state',      v_trip_state
  ) || COALESCE(p_payload->'extra_meta', '{}');

  IF v_conv_id IS NOT NULL THEN
    INSERT INTO public.trip_messages (
      conversation_id, organization_id,
      sender_user_id, sender_role, sender_name,
      content, message_type, metadata, is_read, is_delivered
    ) VALUES (
      v_conv_id, p_organization_id,
      v_user_id, v_sender_role, v_user_name,
      v_content, v_canonical, v_msg_meta, TRUE, TRUE
    ) RETURNING id INTO v_new_id;
    v_message_ids := array_append(v_message_ids, v_new_id);

  ELSIF v_canonical IN ('ledger', 'ledger_event') THEN
    FOR v_new_id IN
      INSERT INTO public.trip_messages (
        conversation_id, organization_id,
        sender_user_id, sender_role, sender_name,
        content, message_type, metadata, is_read, is_delivered
      )
      SELECT tc.id, tc.organization_id,
             v_user_id, v_sender_role, v_user_name,
             v_content, v_canonical, v_msg_meta, TRUE, TRUE
      FROM   public.trip_conversations tc
      WHERE  tc.trip_id    = p_trip_id
        AND  tc.party_type IN ('client', 'supplier')
      RETURNING id
    LOOP
      v_message_ids := array_append(v_message_ids, v_new_id);
    END LOOP;

  ELSIF v_canonical = 'tracking' THEN
    FOR v_new_id IN
      INSERT INTO public.trip_messages (
        conversation_id, organization_id,
        sender_user_id, sender_role, sender_name,
        content, message_type, metadata, is_read, is_delivered
      )
      SELECT tc.id, tc.organization_id,
             v_user_id, v_sender_role, v_user_name,
             v_content, v_canonical, v_msg_meta, TRUE, TRUE
      FROM   public.trip_conversations tc
      WHERE  tc.trip_id    = p_trip_id
        AND  tc.party_type = 'driver'
      RETURNING id
    LOOP
      v_message_ids := array_append(v_message_ids, v_new_id);
    END LOOP;

  ELSE
    FOR v_new_id IN
      INSERT INTO public.trip_messages (
        conversation_id, organization_id,
        sender_user_id, sender_role, sender_name,
        content, message_type, metadata, is_read, is_delivered
      )
      SELECT tc.id, tc.organization_id,
             v_user_id, v_sender_role, v_user_name,
             v_content, v_canonical,
             v_msg_meta || jsonb_build_object('b2b_operational_broadcast', 'true'),
             TRUE, TRUE
      FROM   public.trip_conversations tc
      WHERE  tc.trip_id = p_trip_id
      RETURNING id
    LOOP
      v_message_ids := array_append(v_message_ids, v_new_id);
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok',          TRUE,
    'message_ids', v_message_ids,
    'trip_state',  v_trip_state,
    'prev_status', v_prev_status,
    'new_status',  v_new_status,
    'event_type',  v_canonical
  );
END;
$$;


ALTER FUNCTION "public"."process_b2b_event"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_b2b_event"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_payload" "jsonb") IS 'Atomic B2B event writer: locks trip, applies mutation, embeds full trip-state snapshot in message metadata, routes to correct conversation subset. Eliminates 3-4 round-trips; client extracts trip_state from the Realtime INSERT and updates in-memory store with no follow-up fetch.';



CREATE OR REPLACE FUNCTION "public"."process_tier_upgrades_and_caps"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_tier public.verification_tier_enum;
BEGIN
  -- Fetch the org's current tier from organizations (not from the job row)
  SELECT verification_tier INTO v_current_tier
  FROM public.organizations WHERE id = NEW.organization_id;

  -- ── Tier 1 Transition ─────────────────────────────────────────────────────
  -- Rule: OCR and Tax registry both passed; org is still at sandbox tier
  IF NEW.ocr_status          = 'PASSED'
  AND NEW.pillar_1_tax_status = 'PASSED'
  AND v_current_tier          = 'TIER_0_SANDBOX'
  AND (OLD.ocr_status != 'PASSED' OR OLD.pillar_1_tax_status != 'PASSED')
  THEN
    UPDATE public.organizations SET
      verification_tier    = 'TIER_1_PARTIAL',
      tier_1_unlocked_at   = now(),
      transaction_cap_paise = 20000000,   -- ₹2,00,000
      updated_at           = now()
    WHERE id = NEW.organization_id;

    INSERT INTO public.verification_audit_logs
      (org_id, changed_by, previous_status, new_status, notes)
    VALUES
      (NEW.organization_id, NULL, 'pending', 'pending',
       'System-automated progression to Tier 1: OCR and Tax Registry matches complete.');
  END IF;

  -- ── Tier 2 Notification ───────────────────────────────────────────────────
  -- Rule: all automated pillars cleared; flag for admin to finalise after
  -- penny-drop + biometric are also completed by the user
  IF NEW.ocr_status          = 'PASSED'
  AND NEW.pillar_1_tax_status = 'PASSED'
  AND NEW.pillar_2_mca_status IN ('PASSED', 'NOT_STARTED')
  AND NEW.status              = 'COMPLETED'
  AND v_current_tier          = 'TIER_1_PARTIAL'
  THEN
    INSERT INTO public.verification_audit_logs
      (org_id, changed_by, previous_status, new_status, notes)
    VALUES
      (NEW.organization_id, NULL, 'pending', 'pending',
       'System: Pillars 1 and 2 cleared by automated worker. Awaiting user bank and biometric verification for Tier 2.');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_tier_upgrades_and_caps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profiles_block_deprecated_driver_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (
    NEW.license_number IS DISTINCT FROM OLD.license_number OR
    NEW.license_type IS DISTINCT FROM OLD.license_type OR
    NEW.license_expiry IS DISTINCT FROM OLD.license_expiry OR
    NEW.license_photo_url IS DISTINCT FROM OLD.license_photo_url OR
    NEW.vehicle_registration IS DISTINCT FROM OLD.vehicle_registration OR
    NEW.vehicle_registration_photo_url IS DISTINCT FROM OLD.vehicle_registration_photo_url OR
    NEW.vehicle_registration_expiry IS DISTINCT FROM OLD.vehicle_registration_expiry OR
    NEW.insurance_photo_url IS DISTINCT FROM OLD.insurance_photo_url OR
    NEW.insurance_expiry IS DISTINCT FROM OLD.insurance_expiry OR
    NEW.years_of_experience IS DISTINCT FROM OLD.years_of_experience OR
    NEW.languages IS DISTINCT FROM OLD.languages OR
    NEW.preferred_vehicle_types IS DISTINCT FROM OLD.preferred_vehicle_types OR
    NEW.preferred_areas IS DISTINCT FROM OLD.preferred_areas OR
    NEW.emergency_contact_name IS DISTINCT FROM OLD.emergency_contact_name OR
    NEW.emergency_contact_phone IS DISTINCT FROM OLD.emergency_contact_phone
  ) THEN
    RAISE EXCEPTION
      'profiles: direct writes to deprecated driver KYC columns are blocked. Write to driver_profiles instead (join on user_id = profiles.id).';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."profiles_block_deprecated_driver_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_cron_job_run_details"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lock_key CONSTANT bigint := hashtextextended('prune_cron_job_run_details', 0);
  v_got_lock boolean;
BEGIN
  v_got_lock := pg_try_advisory_lock(v_lock_key);
  IF NOT v_got_lock THEN
    RETURN;
  END IF;

  BEGIN
    SET LOCAL statement_timeout = '30s';
    DELETE FROM cron.job_run_details
    WHERE start_time < now() - INTERVAL '3 days';
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_advisory_unlock(v_lock_key);
    RAISE;
  END;

  PERFORM pg_advisory_unlock(v_lock_key);
END;
$$;


ALTER FUNCTION "public"."prune_cron_job_run_details"() OWNER TO "postgres";


