CREATE OR REPLACE FUNCTION "public"."register_push_token"("p_token" "text", "p_platform" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF coalesce(trim(p_token), '') = '' THEN
    RAISE EXCEPTION 'Token required';
  END IF;
  IF p_platform NOT IN ('ios', 'android', 'web') THEN
    RAISE EXCEPTION 'Invalid platform';
  END IF;

  INSERT INTO public.user_push_tokens (user_id, token, platform, updated_at)
  VALUES (auth.uid(), trim(p_token), p_platform, now())
  ON CONFLICT (user_id, token)
  DO UPDATE SET platform = excluded.platform, updated_at = now();
END;
$$;


