CREATE OR REPLACE FUNCTION "public"."register_verification_document"("p_org_id" "uuid", "p_document_type" "public"."verification_document_type", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role      text;
  v_status    public.kyc_verification_status;
  v_doc_id    uuid;
BEGIN
  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_org_id
    AND user_id = auth.uid()
    AND status = 'active';

  IF v_role IS NULL OR v_role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'Only workspace owners or admins can upload verification documents.';
  END IF;

  SELECT verification_status INTO v_status
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF v_status IN ('pending', 'verified') THEN
    RAISE EXCEPTION 'PROFILE_FROZEN: Documents are locked while status is %.', v_status;
  END IF;

  IF p_size_bytes <= 0 OR p_size_bytes > 10485760 THEN
    RAISE EXCEPTION 'File size must be between 1 byte and 10 MB.';
  END IF;

  IF p_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif', 'application/pdf') THEN
    RAISE EXCEPTION 'Unsupported file type: %. Allowed: JPG, PNG, WEBP, HEIC, PDF.', p_mime_type;
  END IF;

  UPDATE public.verification_documents
  SET status = 'REPLACED', updated_at = now()
  WHERE org_id = p_org_id
    AND document_type = p_document_type
    AND status <> 'REPLACED';

  INSERT INTO public.verification_documents
    (org_id, document_type, storage_path, mime_type, size_bytes, uploaded_by)
  VALUES
    (p_org_id, p_document_type, p_storage_path, p_mime_type, p_size_bytes, auth.uid())
  RETURNING id INTO v_doc_id;

  RETURN jsonb_build_object('ok', true, 'document_id', v_doc_id);
END;
$$;


ALTER FUNCTION "public"."register_verification_document"("p_org_id" "uuid", "p_document_type" "public"."verification_document_type", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_driver_invite"("p_invite_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite public.driver_invites;
BEGIN
  SELECT * INTO v_invite
  FROM public.driver_invites
  WHERE id = p_invite_id
    AND to_user_id = auth.uid()
    AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invite not found or already responded';
  END IF;

  UPDATE public.driver_invites
  SET status = 'rejected',
      responded_at = now(),
      responded_by = auth.uid()
  WHERE id = p_invite_id;

  UPDATE public.driver_signup_matches
  SET state = 'declined',
      acted_at = now(),
      acted_by = auth.uid(),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('declined_invite_id', p_invite_id, 'declined_at', now())
  WHERE organization_id = v_invite.from_organization_id
    AND matched_user_id = auth.uid()
    AND state IN ('pending_owner_action', 'invite_sent');
END;
$$;


