CREATE OR REPLACE FUNCTION "public"."reopen_driver_invite"("p_org_id" "uuid", "p_to_user_id" "uuid", "p_from_org_name" "text" DEFAULT NULL::"text", "p_invitee_name" "text" DEFAULT NULL::"text", "p_payable_amount" numeric DEFAULT NULL::numeric, "p_commission_percent" numeric DEFAULT NULL::numeric, "p_commission_per_km" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id              uuid;
  v_existing_status text;
  v_org_name        text;
  v_invitee         text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_members om
    WHERE om.organization_id = p_org_id
      AND om.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  -- Resolve org name fallback
  SELECT coalesce(nullif(trim(p_from_org_name), ''), o.name)
  INTO v_org_name
  FROM public.organizations o
  WHERE o.id = p_org_id;

  v_invitee := nullif(trim(coalesce(p_invitee_name, '')), '');

  -- Find the most-relevant existing invite (pending first, then latest)
  SELECT di.status INTO v_existing_status
  FROM public.driver_invites di
  WHERE di.from_organization_id = p_org_id
    AND di.to_user_id = p_to_user_id
  ORDER BY
    (di.status = 'pending') DESC,
    di.created_at DESC
  LIMIT 1;

  IF v_existing_status = 'pending' THEN
    -- Pending already exists: just update pay terms, leave status as pending
    UPDATE public.driver_invites di
    SET
      from_org_name      = coalesce(nullif(trim(v_org_name), ''), di.from_org_name),
      invitee_name       = coalesce(v_invitee, di.invitee_name),
      payable_amount     = p_payable_amount,
      commission_percent = p_commission_percent,
      commission_per_km  = p_commission_per_km
    WHERE di.from_organization_id = p_org_id
      AND di.to_user_id = p_to_user_id
      AND di.status = 'pending'
    RETURNING di.id INTO v_id;
  ELSE
    -- accepted / rejected / no prior row: INSERT a fresh pending invite
    INSERT INTO public.driver_invites (
      from_organization_id,
      to_user_id,
      status,
      from_org_name,
      invitee_name,
      payable_amount,
      commission_percent,
      commission_per_km
    )
    VALUES (
      p_org_id,
      p_to_user_id,
      'pending',
      v_org_name,
      v_invitee,
      p_payable_amount,
      p_commission_percent,
      p_commission_per_km
    )
    RETURNING id INTO v_id;
  END IF;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('ok', false);
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$$;


ALTER FUNCTION "public"."reopen_driver_invite"("p_org_id" "uuid", "p_to_user_id" "uuid", "p_from_org_name" "text", "p_invitee_name" "text", "p_payable_amount" numeric, "p_commission_percent" numeric, "p_commission_per_km" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reopen_driver_invite"("p_org_id" "uuid", "p_to_user_id" "uuid", "p_from_org_name" "text", "p_invitee_name" "text", "p_payable_amount" numeric, "p_commission_percent" numeric, "p_commission_per_km" numeric) IS 'Re-invite a driver for reconnect. Inserts a fresh pending row when prior invite is accepted/rejected. Updates pay terms in-place when a pending invite already exists.';



CREATE OR REPLACE FUNCTION "public"."reset_driver_signup_invite"("p_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver public.drivers;
  v_match public.driver_signup_matches;
  v_invite public.driver_invites;
BEGIN
  SELECT * INTO v_driver FROM public.drivers WHERE id = p_driver_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Driver not found';
  END IF;
  IF NOT public.is_org_member(v_driver.organization_id) THEN
    RAISE EXCEPTION 'Not allowed';
  END IF;

  PERFORM public.ensure_driver_signup_matches_for_driver(p_driver_id);

  SELECT *
  INTO v_match
  FROM public.driver_signup_matches
  WHERE driver_id = p_driver_id
    AND state IN ('pending_owner_action', 'invite_sent', 'declined', 'ignored', 'expired')
  ORDER BY detected_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No signup match found');
  END IF;

  SELECT *
  INTO v_invite
  FROM public.driver_invites di
  WHERE di.from_organization_id = v_driver.organization_id
    AND di.to_user_id = v_match.matched_user_id
  LIMIT 1;

  IF FOUND AND v_invite.status = 'rejected' THEN
    UPDATE public.driver_invites
    SET status = 'pending',
        responded_at = null,
        responded_by = null,
        created_at = now()
    WHERE id = v_invite.id;
  END IF;

  UPDATE public.driver_signup_matches
  SET state = 'pending_owner_action',
      acted_at = now(),
      acted_by = auth.uid(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('reset_at', now())
  WHERE id = v_match.id;

  RETURN jsonb_build_object(
    'ok', true,
    'reset', true,
    'invite_status',
      CASE
        WHEN FOUND THEN (SELECT status FROM public.driver_invites WHERE id = v_invite.id)
        ELSE null
      END
  );
END;
$$;


ALTER FUNCTION "public"."reset_driver_signup_invite"("p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_dispute"("p_dispute_id" "uuid", "p_action" "text", "p_resolved_by_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_dispute public.dispute%ROWTYPE;
  v_contact_id uuid;
BEGIN
  IF p_action IS NULL OR p_resolved_by_org_id IS NULL THEN
    RETURN;
  END IF;
  IF NOT public.is_org_member(p_resolved_by_org_id) THEN
    RETURN;
  END IF;

  SELECT * INTO v_dispute
  FROM public.dispute d
  WHERE d.id = p_dispute_id
    AND d.partner_org_id = p_resolved_by_org_id
    AND d.status = 'OPEN';

  IF v_dispute.id IS NULL THEN
    RETURN;
  END IF;

  IF p_action = 'DECLINE' THEN
    UPDATE public.dispute
    SET status = 'RESOLVED', updated_at = now()
    WHERE id = p_dispute_id;
    RETURN;
  END IF;

  IF p_action = 'ACCEPT' THEN
    -- Resolve receiver's contact that represents the raiser (for accept_partner_view).
    SELECT c.id INTO v_contact_id
    FROM public.clients c
    WHERE c.organization_id = v_dispute.partner_org_id
      AND c.linked_organization_id = v_dispute.raised_by_org_id
    LIMIT 1;
    IF v_contact_id IS NULL THEN
      SELECT s.id INTO v_contact_id
      FROM public.suppliers s
      WHERE s.organization_id = v_dispute.partner_org_id
        AND s.linked_organization_id = v_dispute.raised_by_org_id
      LIMIT 1;
    END IF;

    -- Update receiver's ledger to match raiser's view (raised_sales, raised_paid).
    PERFORM public.accept_partner_view(
      v_dispute.partner_org_id,
      v_dispute.transaction_id,
      COALESCE(v_dispute.raised_sales, 0),
      COALESCE(v_dispute.raised_paid, 0),
      v_contact_id
    );

    UPDATE public.dispute
    SET status = 'RESOLVED', updated_at = now()
    WHERE id = p_dispute_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."resolve_dispute"("p_dispute_id" "uuid", "p_action" "text", "p_resolved_by_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_dispute"("p_dispute_id" "uuid", "p_action" "text", "p_resolved_by_org_id" "uuid") IS 'Resolve dispute: DECLINE only marks RESOLVED; ACCEPT updates receiver ledger to match raiser (raised_sales/raised_paid) then marks RESOLVED.';



CREATE OR REPLACE FUNCTION "public"."resolve_dispute"("p_dispute_id" "uuid", "p_actor_org_id" "uuid", "p_resolution" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.dispute
  SET status = p_resolution, resolved_at = now(), resolved_by = auth.uid(), updated_at = now()
  WHERE id = p_dispute_id
    AND (raised_by_org_id = p_actor_org_id OR partner_org_id = p_actor_org_id)
    AND status = 'OPEN';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dispute not found, not authorized, or already closed';
  END IF;
END;
$$;


ALTER FUNCTION "public"."resolve_dispute"("p_dispute_id" "uuid", "p_actor_org_id" "uuid", "p_resolution" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_ocr_scan_monthly_limit"("p_org_id" "uuid") RETURNS TABLE("tier" "text", "monthly_limit" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public.workspace_products wp
        WHERE wp.org_id = p_org_id
          AND wp.product_id IN ('pulse_invoice_pro', 'pulse_ai', 'pulse_fleet_pro')
          AND wp.status IN ('active', 'trial')
          AND (wp.expires_at IS NULL OR wp.expires_at > now())
      ) THEN 'invoice_pro'
      ELSE 'pulse_core'
    END AS tier,
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public.workspace_products wp
        WHERE wp.org_id = p_org_id
          AND wp.product_id IN ('pulse_invoice_pro', 'pulse_ai', 'pulse_fleet_pro')
          AND wp.status IN ('active', 'trial')
          AND (wp.expires_at IS NULL OR wp.expires_at > now())
          AND COALESCE((wp.metadata ->> 'ocr_unlimited')::boolean, false)
      ) THEN NULL::bigint
      WHEN EXISTS (
        SELECT 1 FROM public.workspace_products wp
        WHERE wp.org_id = p_org_id
          AND wp.product_id IN ('pulse_invoice_pro', 'pulse_ai', 'pulse_fleet_pro')
          AND wp.status IN ('active', 'trial')
          AND (wp.expires_at IS NULL OR wp.expires_at > now())
      ) THEN 500::bigint
      ELSE 50::bigint
    END AS monthly_limit;
$$;


ALTER FUNCTION "public"."resolve_ocr_scan_monthly_limit"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_pending_team_invitations_by_email"("p_email" "text") RETURNS TABLE("invitee_name" "text", "invite_id" "uuid", "organization_id" "uuid", "organization_name" "text", "invited_by_name" "text", "role" "text", "platform_role" "text", "business_unit_name" "text", "department_name" "text", "invitee_email" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "is_expired" boolean, "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
BEGIN
  IF v_email IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    ti.invitee_name,
    ti.id,
    ti.organization_id,
    coalesce(nullif(trim(o.name), ''), 'Organization'),
    coalesce(nullif(trim(inviter.full_name), ''), 'Team admin'),
    ti.role,
    coalesce(ti.permissions->>'platformRole', ti.role),
    NULL::text,
    NULL::text,
    ti.invitee_email,
    ti.created_at,
    ti.expires_at,
    (ti.status = 'pending' AND ti.expires_at <= now()) AS is_expired,
    ti.status
  FROM public.organization_team_invites ti
  JOIN public.organizations o ON o.id = ti.organization_id
  LEFT JOIN public.profiles inviter ON inviter.id = ti.invited_by
  WHERE lower(trim(ti.invitee_email)) = v_email
    AND ti.status IN ('pending', 'expired')
  ORDER BY
    CASE WHEN ti.status = 'pending' AND ti.expires_at > now() THEN 0 ELSE 1 END,
    ti.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."resolve_pending_team_invitations_by_email"("p_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_pending_team_invitations_by_email"("p_email" "text") IS 'Invitation resolver: list pending/expired email invites for onboarding (post-verification). Mirrors resolve_pending_team_invitations_by_phone.';



CREATE OR REPLACE FUNCTION "public"."resolve_pending_team_invitations_by_phone"("p_phone" "text") RETURNS TABLE("invitee_name" "text", "invite_id" "uuid", "organization_id" "uuid", "organization_name" "text", "invited_by_name" "text", "role" "text", "platform_role" "text", "business_unit_name" "text", "department_name" "text", "invitee_email" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "is_expired" boolean, "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canon text;
BEGIN
  v_canon := public.normalize_phone_canon(p_phone);
  IF v_canon IS NULL OR length(v_canon) < 10 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    ti.invitee_name,
    ti.id,
    ti.organization_id,
    coalesce(nullif(trim(o.name), ''), 'Organization'),
    coalesce(nullif(trim(inviter.full_name), ''), 'Team admin'),
    ti.role,
    coalesce(ti.permissions->>'platformRole', ti.role),
    NULL::text,
    NULL::text,
    ti.invitee_email,
    ti.created_at,
    ti.expires_at,
    (ti.status = 'pending' AND ti.expires_at <= now()) AS is_expired,
    ti.status
  FROM public.organization_team_invites ti
  JOIN public.organizations o ON o.id = ti.organization_id
  LEFT JOIN public.profiles inviter ON inviter.id = ti.invited_by
  WHERE ti.invitee_phone_canon = v_canon
    AND ti.status IN ('pending', 'expired')
  ORDER BY
    CASE WHEN ti.status = 'pending' AND ti.expires_at > now() THEN 0 ELSE 1 END,
    ti.created_at DESC;
END;
$$;


