CREATE OR REPLACE FUNCTION "public"."run_db_health_monitor"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_slack_url TEXT := 'https://hooks.slack.com/services/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';
  v_alerts TEXT := '';
  v_severity TEXT := 'high';

  v_cron_fail_count INT;
  v_cron_last_success TIMESTAMPTZ;
  v_cron_last_error TEXT;
  v_long_query_count INT;
  v_long_query_detail TEXT;
  v_idle_warn_count INT;
  v_idle_crit_count INT;
  v_conn_pct NUMERIC;
  v_conn_used INT;
  v_conn_max INT;
  v_conn_pressure BOOLEAN;
  v_lock_count INT;
  v_queue_depth INT;
  v_net_fail_count INT;
  v_net_fail_prev INT;

  v_db_bytes BIGINT;
  v_db_gb NUMERIC;
  v_timeout_delta BIGINT;
  v_timeout_prev BIGINT;
  v_timeout_now BIGINT;
  v_slot_inactive INT;
  v_slot_lag_mb NUMERIC;
BEGIN

  -- ── 0. HEARTBEAT (write only) ────────────────────────────────────────────
  -- We no longer self-report staleness here; a job cannot reliably detect its
  -- own downtime. The separate run_monitor_watchdog() job does that. We only
  -- record liveness for the watchdog to read.
  INSERT INTO public._monitor_heartbeat (job_name, last_run)
  VALUES ('run_db_health_monitor', NOW())
  ON CONFLICT (job_name) DO UPDATE SET last_run = EXCLUDED.last_run;

  -- ── 1. CRON CONSECUTIVE FAILURES ─────────────────────────────────────────
  -- Exclude transient 'server restarted' rows (NULL start_time): a DB restart
  -- is not a send-push failure and must not accumulate into the count.
  SELECT COUNT(*) INTO v_cron_fail_count
  FROM (
    SELECT status, ROW_NUMBER() OVER (ORDER BY start_time DESC) AS rn
    FROM cron.job_run_details
    WHERE jobid = 1
      AND start_time IS NOT NULL
      AND return_message IS DISTINCT FROM 'server restarted'
    ORDER BY start_time DESC LIMIT 10
  ) x WHERE status = 'failed' AND rn <= COALESCE(
    (SELECT MIN(rn)-1 FROM (
      SELECT status, ROW_NUMBER() OVER (ORDER BY start_time DESC) AS rn
      FROM cron.job_run_details
      WHERE jobid = 1
        AND start_time IS NOT NULL
        AND return_message IS DISTINCT FROM 'server restarted'
      ORDER BY start_time DESC LIMIT 10
    ) y WHERE status = 'succeeded'), 10
  );

  SELECT MAX(start_time) INTO v_cron_last_success
  FROM cron.job_run_details WHERE jobid = 1 AND status = 'succeeded';

  SELECT return_message INTO v_cron_last_error
  FROM cron.job_run_details
  WHERE jobid = 1 AND status = 'failed'
    AND return_message IS DISTINCT FROM 'server restarted'
    AND start_time IS NOT NULL
  ORDER BY start_time DESC LIMIT 1;

  IF v_cron_fail_count >= 3 THEN
    v_severity := 'critical';
    v_alerts := v_alerts
      || ':red_circle: *CRITICAL — `send-push-notifications` failed ' || v_cron_fail_count || 'x consecutively*' || E'\n'
      || '  • Last success: ' || COALESCE(v_cron_last_success::TEXT, 'never') || E'\n'
      || '  • Error: ' || LEFT(COALESCE(v_cron_last_error, 'unknown'), 200) || E'\n'
      || '  • Action: check Vault secret + Edge Function status' || E'\n\n';
  END IF;

  -- ── 2. CONNECTION SATURATION — moved up: cheap, and gates the expensive checks below ──
  SELECT COUNT(*) INTO v_conn_used FROM pg_stat_activity;
  SELECT setting::INT INTO v_conn_max FROM pg_settings WHERE name = 'max_connections';
  v_conn_pct := ROUND((v_conn_used::NUMERIC / NULLIF(v_conn_max, 0)) * 100, 1);
  v_conn_pressure := v_conn_pct >= 80;

  IF v_conn_pct >= 90 THEN
    v_severity := 'critical';
    v_alerts := v_alerts || ':red_circle: *CRITICAL — Connection saturation ' || v_conn_pct || '% (' || v_conn_used || '/' || v_conn_max || ')* — new connections may be refused' || E'\n\n';
  ELSIF v_conn_pct >= 85 THEN
    v_alerts := v_alerts || ':warning: *HIGH — Connection usage ' || v_conn_pct || '% (' || v_conn_used || '/' || v_conn_max || ')* — approaching limit' || E'\n\n';
  ELSIF v_conn_pressure THEN
    v_alerts := v_alerts || ':warning: *Connection usage ' || v_conn_pct || '% (' || v_conn_used || '/' || v_conn_max || ')* — elevated' || E'\n\n';
  END IF;

  IF v_conn_pressure THEN
    v_alerts := v_alerts
      || ':information_source: *Monitor running in degraded mode* — skipping long-running-query scan, pg_net queue/failure checks, and statement-timeout scan while connection usage is >= 80%, to avoid adding load to an already-pressured database.' || E'\n\n';
  END IF;

  -- ── 3. LONG RUNNING QUERIES >60s — skipped under connection pressure ──────
  IF NOT v_conn_pressure THEN
    SELECT COUNT(*), STRING_AGG(LEFT(query, 80) || ' [' || ROUND(EXTRACT(EPOCH FROM (NOW()-query_start))) || 's]', E'\n    ')
    INTO v_long_query_count, v_long_query_detail
    FROM (
      SELECT query, query_start FROM pg_stat_activity
      WHERE state = 'active'
        AND query_start < NOW() - INTERVAL '60 seconds'
        AND backend_type = 'client backend'
        AND query NOT ILIKE '%pg_stat_activity%'
        AND query NOT ILIKE '%run_db_health%'
        AND query NOT ILIKE 'START_REPLICATION%'
        AND query NOT ILIKE '%replication%'
      ORDER BY query_start LIMIT 3
    ) q;

    IF v_long_query_count > 0 THEN
      v_alerts := v_alerts
        || ':warning: *HIGH — ' || v_long_query_count || ' long-running quer' || CASE WHEN v_long_query_count = 1 THEN 'y' ELSE 'ies' END || ' (>60s)*' || E'\n'
        || '    ' || COALESCE(v_long_query_detail, '') || E'\n\n';
    END IF;
  END IF;

  -- ── 4. IDLE IN TRANSACTION ────────────────────────────────────────────────
  SELECT
    COUNT(*) FILTER (WHERE state_change < NOW() - INTERVAL '15 minutes'),
    COUNT(*) FILTER (WHERE state_change < NOW() - INTERVAL '30 minutes')
  INTO v_idle_warn_count, v_idle_crit_count
  FROM pg_stat_activity WHERE state = 'idle in transaction';

  IF v_idle_crit_count > 0 THEN
    v_severity := 'critical';
    v_alerts := v_alerts || ':red_circle: *CRITICAL — ' || v_idle_crit_count || ' session(s) idle-in-transaction >30 min*' || E'\n\n';
  ELSIF v_idle_warn_count > 0 THEN
    v_alerts := v_alerts || ':warning: *HIGH — ' || v_idle_warn_count || ' session(s) idle-in-transaction >15 min*' || E'\n\n';
  END IF;

  -- ── 5. LOCK WAITS >5 MIN ─────────────────────────────────────────────────
  SELECT COUNT(*) INTO v_lock_count
  FROM pg_stat_activity
  WHERE wait_event_type = 'Lock'
    AND state != 'idle'
    AND backend_type = 'client backend'
    AND query_start < NOW() - INTERVAL '5 minutes';

  IF v_lock_count > 0 THEN
    v_alerts := v_alerts || ':warning: *HIGH — ' || v_lock_count || ' session(s) blocked on lock waits >5 min*' || E'\n\n';
  END IF;

  -- ── 6. pg_net QUEUE DEPTH — skipped under connection pressure ─────────────
  IF NOT v_conn_pressure THEN
    SELECT COUNT(*) INTO v_queue_depth FROM net.http_request_queue;
    IF v_queue_depth > 50 THEN
      v_alerts := v_alerts || ':warning: *HIGH — pg_net queue depth: ' || v_queue_depth || ' pending requests*' || E'\n\n';
    END IF;
  END IF;

  -- ── 7. pg_net HTTP FAILURES (last 10 min) — skipped under connection pressure ──
  IF NOT v_conn_pressure THEN
    SELECT COUNT(*) INTO v_net_fail_count
    FROM net._http_response
    WHERE status_code >= 400 AND created > NOW() - INTERVAL '10 minutes';

    SELECT fail_count INTO v_net_fail_prev
    FROM public._monitor_net_fail_snapshot
    ORDER BY captured_at DESC LIMIT 1;

    INSERT INTO public._monitor_net_fail_snapshot (fail_count) VALUES (v_net_fail_count);
    DELETE FROM public._monitor_net_fail_snapshot
    WHERE captured_at < NOW() - INTERVAL '2 hours';

    IF v_net_fail_count > 10 AND COALESCE(v_net_fail_prev, 0) > 10 THEN
      v_alerts := v_alerts
        || ':warning: *HIGH — ' || v_net_fail_count || ' Edge Function HTTP errors (4xx/5xx) in last 10 min* — sustained across 2 consecutive checks' || E'\n'
        || '  • Note: pg_net does not retain per-request URLs after completion — check cron.job_run_details (jobid 1 = send-push-notifications, jobid 3 = dispatch_verification_workers) and Edge Function logs immediately for the failing endpoint.' || E'\n\n';
    END IF;
  END IF;

  -- ── 8. DISK USAGE ────────────────────────────────────────────────────────
  SELECT pg_database_size('postgres') INTO v_db_bytes;
  v_db_gb := ROUND(v_db_bytes::NUMERIC / 1073741824, 2);

  IF v_db_gb >= 2.0 THEN
    v_severity := 'critical';
    v_alerts := v_alerts || ':red_circle: *CRITICAL — Database size ' || v_db_gb || ' GB* — at or beyond free plan limit (2 GB), writes may fail' || E'\n\n';
  ELSIF v_db_gb >= 1.5 THEN
    v_alerts := v_alerts || ':warning: *HIGH — Database size ' || v_db_gb || ' GB* — approaching 2 GB free plan limit' || E'\n\n';
  END IF;

  -- ── 9. STATEMENT TIMEOUT SPIKE — skipped under connection pressure ────────
  IF NOT v_conn_pressure THEN
    SELECT COALESCE(SUM(calls), 0) INTO v_timeout_now
    FROM pg_stat_statements
    WHERE mean_exec_time >= 58000
      AND query NOT ILIKE '%SET statement_timeout%'
      AND query NOT ILIKE '%pg_stat%'
      AND query NOT ILIKE '%cron%';

    SELECT COALESCE(total_timeout_calls, 0) INTO v_timeout_prev
    FROM public._monitor_stmt_snapshot
    ORDER BY captured_at DESC LIMIT 1;

    v_timeout_delta := GREATEST(v_timeout_now - v_timeout_prev, 0);

    INSERT INTO public._monitor_stmt_snapshot (total_timeout_calls) VALUES (v_timeout_now);
    DELETE FROM public._monitor_stmt_snapshot
    WHERE captured_at < NOW() - INTERVAL '2 hours';

    IF v_timeout_delta >= 5 THEN
      v_alerts := v_alerts || ':warning: *HIGH — ' || v_timeout_delta || ' statement timeouts in last 10 min* — queries are hitting the timeout limit' || E'\n\n';
    END IF;
  END IF;

  -- ── 10. REPLICATION SLOT HEALTH ──────────────────────────────────────────
  SELECT COUNT(*) INTO v_slot_inactive
  FROM pg_replication_slots
  WHERE active = false;

  SELECT ROUND(MAX(GREATEST(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn), 0))::NUMERIC / 1048576, 1)
  INTO v_slot_lag_mb
  FROM pg_replication_slots
  WHERE active = true;

  IF v_slot_inactive > 0 THEN
    v_severity := 'critical';
    v_alerts := v_alerts || ':red_circle: *CRITICAL — ' || v_slot_inactive || ' replication slot(s) inactive* — WAL will accumulate and fill disk' || E'\n\n';
  END IF;

  IF v_slot_lag_mb > 100 THEN
    v_alerts := v_alerts || ':warning: *HIGH — Replication lag ' || v_slot_lag_mb || ' MB* — Realtime may be delayed' || E'\n\n';
  END IF;

  -- ── SEND TO SLACK ─────────────────────────────────────────────────────────
  IF v_alerts <> '' THEN
    PERFORM net.http_post(
      url := v_slack_url,
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object(
        'text',
        CASE WHEN v_severity = 'critical'
          THEN ':rotating_light: *SUPABASE DB — CRITICAL ALERT* :rotating_light:'
          ELSE ':large_yellow_circle: *SUPABASE DB — HIGH PRIORITY ALERT*'
        END
        || E'\n\n' || v_alerts
        || '_' || NOW()::TEXT || '_'
      )::jsonb
    );
  END IF;

END;
$$;


ALTER FUNCTION "public"."run_db_health_monitor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_db_health_monitor_guarded"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lock_key CONSTANT bigint := hashtextextended('run_db_health_monitor', 0);
BEGIN
  IF NOT pg_try_advisory_xact_lock(v_lock_key) THEN
    RETURN;
  END IF;

  SET LOCAL statement_timeout = '15s';
  PERFORM public.run_db_health_monitor();
END;
$$;


ALTER FUNCTION "public"."run_db_health_monitor_guarded"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_monitor_watchdog"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_slack_url TEXT := 'https://hooks.slack.com/services/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';
  v_last_run TIMESTAMPTZ;
  v_alerted_at TIMESTAMPTZ;
  v_is_stale BOOLEAN;
BEGIN
  SELECT last_run INTO v_last_run
  FROM public._monitor_heartbeat WHERE job_name = 'run_db_health_monitor';

  SELECT alerted_at INTO v_alerted_at
  FROM public._monitor_watchdog_state WHERE id = TRUE;

  v_is_stale := v_last_run IS NULL OR v_last_run < NOW() - INTERVAL '30 minutes';

  IF v_is_stale AND v_alerted_at IS NULL THEN
    -- Newly stale: page once and remember we did.
    PERFORM net.http_post(
      url := v_slack_url,
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object(
        'text',
        ':rotating_light: *SUPABASE DB — CRITICAL ALERT* :rotating_light:' || E'\n\n'
        || ':red_circle: *CRITICAL — Health monitor has not run in >30 min*' || E'\n'
        || '  • Last run: ' || COALESCE(v_last_run::TEXT, 'never') || E'\n'
        || '  • Action: check cron job 2 (cron-health-alert) in cron.job' || E'\n\n'
        || '_' || NOW()::TEXT || '_'
      )::jsonb
    );

    INSERT INTO public._monitor_watchdog_state (id, alerted_at)
    VALUES (TRUE, NOW())
    ON CONFLICT (id) DO UPDATE SET alerted_at = EXCLUDED.alerted_at;

  ELSIF NOT v_is_stale AND v_alerted_at IS NOT NULL THEN
    -- Recovered: clear the guard and post an all-clear.
    UPDATE public._monitor_watchdog_state SET alerted_at = NULL WHERE id = TRUE;

    PERFORM net.http_post(
      url := v_slack_url,
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object(
        'text',
        ':white_check_mark: *SUPABASE DB — RECOVERED* — health monitor is running again (last run '
        || v_last_run::TEXT || ')'
      )::jsonb
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."run_monitor_watchdog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_monitor_watchdog_guarded"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lock_key CONSTANT bigint := hashtextextended('run_monitor_watchdog', 0);
BEGIN
  IF NOT pg_try_advisory_xact_lock(v_lock_key) THEN
    RETURN;
  END IF;
  SET LOCAL statement_timeout = '10s';
  PERFORM public.run_monitor_watchdog();
END;
$$;


ALTER FUNCTION "public"."run_monitor_watchdog_guarded"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_chat_messages"("p_organization_id" "uuid", "p_query" "text", "p_limit" integer DEFAULT 25) RETURNS SETOF "public"."chat_messages"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT m.*
  FROM chat_messages m
  WHERE m.organization_id = p_organization_id
    AND m.deleted_at IS NULL
    AND to_tsvector('simple', coalesce(m.content, ''))
        @@ websearch_to_tsquery('simple', p_query)
  ORDER BY m.created_at DESC
  LIMIT least(greatest(coalesce(p_limit, 25), 1), 100);
$$;


ALTER FUNCTION "public"."search_chat_messages"("p_organization_id" "uuid", "p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_message_type" "text" DEFAULT 'text'::"text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb", "p_client_message_id" "uuid" DEFAULT NULL::"uuid", "p_reply_to_id" "uuid" DEFAULT NULL::"uuid", "p_mentions" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "public"."chat_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv    public.chat_conversations%ROWTYPE;
  v_row     public.chat_messages%ROWTYPE;
  v_name    text;
  v_mention uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_message_type NOT IN (
    'text','image','document','voice','location','action_card','reference','system'
  ) THEN
    RAISE EXCEPTION 'Invalid message_type: %', p_message_type;
  END IF;

  IF coalesce(char_length(p_content), 0) > 8000 THEN
    RAISE EXCEPTION 'Message too long';
  END IF;

  SELECT * INTO v_conv FROM chat_conversations WHERE id = p_conversation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found: %', p_conversation_id;
  END IF;

  IF NOT public.fn_chat_can_access_conversation(p_conversation_id) THEN
    RAISE EXCEPTION 'Not authorized for conversation' USING ERRCODE = '42501';
  END IF;

  -- Offline retry replay: return the already-persisted row.
  IF p_client_message_id IS NOT NULL THEN
    SELECT * INTO v_row
    FROM chat_messages
    WHERE conversation_id = p_conversation_id
      AND client_message_id = p_client_message_id;
    IF FOUND THEN RETURN v_row; END IF;
  END IF;

  SELECT coalesce(
    nullif(trim(p.full_name), ''),
    nullif(trim(p.email), ''),
    'Member'
  ) INTO v_name
  FROM profiles p WHERE p.id = auth.uid();

  INSERT INTO chat_messages (
    conversation_id, organization_id,
    sender_user_id, sender_type, sender_name,
    message_type, content, metadata,
    reply_to_id, client_message_id
  )
  VALUES (
    p_conversation_id, v_conv.organization_id,
    auth.uid(), 'user', coalesce(v_name, 'Member'),
    p_message_type, coalesce(p_content, ''), coalesce(p_metadata, '{}'::jsonb),
    p_reply_to_id, p_client_message_id
  )
  ON CONFLICT (conversation_id, client_message_id) WHERE client_message_id IS NOT NULL
  DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row
    FROM chat_messages
    WHERE conversation_id = p_conversation_id
      AND client_message_id = p_client_message_id;
    RETURN v_row;
  END IF;

  -- Mentions
  IF p_mentions IS NOT NULL THEN
    FOREACH v_mention IN ARRAY p_mentions LOOP
      INSERT INTO chat_mentions (message_id, user_id)
      VALUES (v_row.id, v_mention)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  -- Sender implicitly joins as participant (covers org-member senders).
  INSERT INTO chat_participants (conversation_id, user_id, participant_role, last_read_at)
  VALUES (p_conversation_id, auth.uid(), 'member', now())
  ON CONFLICT (conversation_id, user_id)
  DO UPDATE SET last_read_at = now();

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."send_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_message_type" "text", "p_metadata" "jsonb", "p_client_message_id" "uuid", "p_reply_to_id" "uuid", "p_mentions" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_message_type" "text", "p_metadata" "jsonb", "p_client_message_id" "uuid", "p_reply_to_id" "uuid", "p_mentions" "uuid"[]) IS 'Idempotent message send. Replaying the same client_message_id returns the original row instead of duplicating.';



CREATE OR REPLACE FUNCTION "public"."send_driver_signup_match_invite"("p_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.send_driver_signup_match_invite(
    p_driver_id,
    null::numeric,
    null::numeric,
    null::numeric
  );
$$;


ALTER FUNCTION "public"."send_driver_signup_match_invite"("p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_driver_signup_match_invite"("p_driver_id" "uuid", "p_payable_amount" numeric DEFAULT NULL::numeric, "p_commission_percent" numeric DEFAULT NULL::numeric, "p_commission_per_km" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_driver public.drivers;
  v_match public.driver_signup_matches;
  v_existing public.driver_invites;
  v_invite_id uuid;
  v_payable numeric;
  v_commission_percent numeric;
  v_commission_per_km numeric;
BEGIN
  SELECT * INTO v_driver FROM public.drivers WHERE id = p_driver_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Driver not found';
  END IF;
  IF NOT public.is_org_member(v_driver.organization_id) THEN
    RAISE EXCEPTION 'Not allowed';
  END IF;
  IF v_driver.user_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Driver already linked to an app account');
  END IF;

  v_payable := coalesce(p_payable_amount, v_driver.payable_amount);
  v_commission_percent := coalesce(p_commission_percent, v_driver.commission_percent);
  v_commission_per_km := coalesce(p_commission_per_km, v_driver.commission_per_km);

  PERFORM public.ensure_driver_signup_matches_for_driver(p_driver_id);

  SELECT *
  INTO v_match
  FROM public.driver_signup_matches
  WHERE driver_id = p_driver_id
    AND state IN ('pending_owner_action', 'invite_sent', 'declined', 'ignored', 'expired')
  ORDER BY
    CASE state
      WHEN 'pending_owner_action' THEN 0
      WHEN 'declined' THEN 1
      WHEN 'invite_sent' THEN 2
      WHEN 'ignored' THEN 3
      WHEN 'expired' THEN 4
      ELSE 5
    END,
    detected_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No signup match found');
  END IF;

  SELECT *
  INTO v_existing
  FROM public.driver_invites di
  WHERE di.from_organization_id = v_driver.organization_id
    AND di.to_user_id = v_match.matched_user_id
  LIMIT 1;

  IF FOUND THEN
    UPDATE public.driver_invites
    SET payable_amount = coalesce(v_payable, payable_amount),
        commission_percent = coalesce(v_commission_percent, commission_percent),
        commission_per_km = coalesce(v_commission_per_km, commission_per_km),
        status = CASE WHEN status = 'rejected' THEN 'pending' ELSE status END,
        responded_at = CASE WHEN status = 'rejected' THEN null ELSE responded_at END,
        responded_by = CASE WHEN status = 'rejected' THEN null ELSE responded_by END,
        created_at = CASE WHEN status = 'rejected' THEN now() ELSE created_at END
    WHERE id = v_existing.id;

    UPDATE public.driver_signup_matches
    SET state = 'invite_sent',
        acted_at = now(),
        acted_by = auth.uid(),
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object('invite_id', v_existing.id, 'terms_synced_at', now())
    WHERE id = v_match.id;

    RETURN jsonb_build_object(
      'ok', true,
      'already_exists', false,
      'invite_id', v_existing.id,
      'status', (SELECT status FROM public.driver_invites WHERE id = v_existing.id)
    );
  END IF;

  INSERT INTO public.driver_invites (
    from_organization_id,
    to_user_id,
    status,
    invitee_name,
    payable_amount,
    commission_percent,
    commission_per_km
  ) VALUES (
    v_driver.organization_id,
    v_match.matched_user_id,
    'pending',
    nullif(trim(coalesce(v_driver.name, '')), ''),
    v_payable,
    v_commission_percent,
    v_commission_per_km
  )
  RETURNING id INTO v_invite_id;

  UPDATE public.driver_signup_matches
  SET state = 'invite_sent',
      acted_at = now(),
      acted_by = auth.uid(),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('invite_id', v_invite_id)
  WHERE id = v_match.id;

  RETURN jsonb_build_object('ok', true, 'already_exists', false, 'invite_id', v_invite_id, 'status', 'pending');
END;
$$;


ALTER FUNCTION "public"."send_driver_signup_match_invite"("p_driver_id" "uuid", "p_payable_amount" numeric, "p_commission_percent" numeric, "p_commission_per_km" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."trip_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "sender_user_id" "uuid",
    "sender_role" "text" NOT NULL,
    "sender_name" "text" NOT NULL,
    "content" "text" NOT NULL,
    "message_type" "text" DEFAULT 'text'::"text" NOT NULL,
    "is_read" boolean DEFAULT false NOT NULL,
    "read_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb",
    "sender_avatar_seed" "text",
    "is_delivered" boolean DEFAULT false NOT NULL,
    "delivered_at" timestamp with time zone,
    "priority_weight" integer DEFAULT 40 NOT NULL,
    "context_trip_id" "uuid",
    "context_indent_id" "uuid",
    "visibility_tags" "jsonb" DEFAULT '[]'::"jsonb",
    "reactions" "jsonb" DEFAULT '{}'::"jsonb",
    "reply_to_id" "uuid",
    "reply_to_preview" "jsonb",
    "edited_at" timestamp with time zone,
    "is_deleted" boolean DEFAULT false NOT NULL,
    CONSTRAINT "trip_messages_content_check" CHECK ((("char_length"("content") >= 1) AND ("char_length"("content") <= 4000))),
    CONSTRAINT "trip_messages_message_type_check" CHECK (("message_type" = ANY (ARRAY['text'::"text", 'chat'::"text", 'update'::"text", 'question'::"text", 'challenge'::"text", 'system'::"text", 'system_log'::"text", 'ledger_event'::"text", 'ledger'::"text", 'payment'::"text", 'ledger_update'::"text", 'assignment_update'::"text", 'document_upload'::"text", 'document_share'::"text", 'feedback_request'::"text", 'feedback'::"text", 'image'::"text", 'status_change'::"text", 'tracking'::"text", 'location_log'::"text"]))),
    CONSTRAINT "trip_messages_sender_role_check" CHECK (("sender_role" = ANY (ARRAY['dispatcher'::"text", 'client'::"text", 'supplier'::"text", 'driver'::"text", 'system'::"text"])))
);


ALTER TABLE "public"."trip_messages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."trip_messages"."priority_weight" IS 'Optional per-row priority for global ops ranking; client also applies heuristics by message_type.';



CREATE OR REPLACE FUNCTION "public"."send_trip_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_sender_role" "text", "p_sender_name" "text", "p_sender_user_id" "uuid" DEFAULT NULL::"uuid", "p_message_type" "text" DEFAULT 'text'::"text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."trip_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv          public.trip_conversations%ROWTYPE;
  v_source_trip   public.trips%ROWTYPE;
  v_source_msg    public.trip_messages%ROWTYPE;

  v_target_org_id      uuid;
  v_target_trip        public.trips%ROWTYPE;
  v_target_party_type  text;
  v_target_party_id    uuid;
  v_target_party_name  text;
  v_target_conv_id     uuid;
  v_target_sender_role text;
BEGIN
  IF p_sender_role NOT IN ('dispatcher', 'client', 'supplier', 'driver', 'system') THEN
    RAISE EXCEPTION 'Invalid sender_role: %', p_sender_role;
  END IF;

  -- Allowlist matches trip_messages_message_type_check constraint (20260611160000).
  IF p_message_type NOT IN (
    'text', 'chat', 'update', 'question', 'challenge',
    'system', 'system_log',
    'ledger_event', 'ledger', 'payment', 'ledger_update',
    'assignment_update',
    'document_upload', 'document_share',
    'feedback_request', 'feedback',
    'image',
    'status_change', 'tracking'
  ) THEN
    RAISE EXCEPTION 'Invalid message_type: %', p_message_type;
  END IF;

  SELECT * INTO v_conv
  FROM public.trip_conversations
  WHERE id = p_conversation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found: %', p_conversation_id;
  END IF;

  IF p_sender_role <> 'system' THEN
    IF NOT EXISTS (
      -- Primary: caller is a member of the conversation's owning org.
      SELECT 1 FROM public.organization_members om
      WHERE om.user_id = auth.uid()
        AND om.organization_id = v_conv.organization_id
        AND om.status = 'active'
    ) AND NOT (
      -- Driver sending in their own driver-lane conversation.
      p_sender_role = 'driver'
      AND v_conv.party_type = 'driver'
      AND EXISTS (
        SELECT 1 FROM public.drivers d
        WHERE d.id = v_conv.driver_id
          AND d.user_id IS NOT DISTINCT FROM auth.uid()
      )
    ) AND NOT (
      -- Linked supplier (or their dispatcher) sending in the supplier-party lane.
      p_sender_role IN ('supplier', 'dispatcher')
      AND v_conv.party_type = 'supplier'
      AND EXISTS (
        SELECT 1
        FROM public.trips t
        INNER JOIN public.suppliers s
          ON s.id = t.supplier_id AND s.id = v_conv.supplier_id
        INNER JOIN public.organization_members om
          ON om.user_id = auth.uid()
         AND om.organization_id = s.linked_organization_id
         AND om.status = 'active'
        WHERE t.id = v_conv.trip_id
      )
    ) AND NOT (
      -- Linked supplier (or their dispatcher) sending in the driver lane (supplier_id set).
      p_sender_role IN ('supplier', 'dispatcher')
      AND v_conv.party_type = 'driver'
      AND EXISTS (
        SELECT 1
        FROM public.trips t
        INNER JOIN public.suppliers s ON s.id = t.supplier_id
        INNER JOIN public.organization_members om
          ON om.user_id = auth.uid()
         AND om.organization_id = s.linked_organization_id
         AND om.status = 'active'
        WHERE t.id = v_conv.trip_id
      )
    ) AND NOT (
      -- Linked supplier (or their dispatcher) sending in driver lane (indent-based, no supplier_id yet).
      p_sender_role IN ('supplier', 'dispatcher')
      AND v_conv.party_type = 'driver'
      AND EXISTS (
        SELECT 1
        FROM public.trips t
        INNER JOIN public.indents i ON i.id = t.indent_id
        INNER JOIN public.organization_members om
          ON om.organization_id = i.assigned_supplier_id
         AND om.user_id = auth.uid()
         AND om.status = 'active'
        WHERE t.id = v_conv.trip_id
          AND t.supplier_id IS NULL
          AND t.indent_id IS NOT NULL
          AND i.assigned_supplier_id IS NOT NULL
      )
    ) THEN
      RAISE EXCEPTION 'Not authorized for source organization';
    END IF;
  END IF;

  SELECT * INTO v_source_trip
  FROM public.trips
  WHERE id = v_conv.trip_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Source trip not found for conversation: %', p_conversation_id;
  END IF;

  INSERT INTO public.trip_messages (
    conversation_id, organization_id, sender_user_id, sender_role,
    sender_name, content, message_type, is_read, metadata
  )
  VALUES (
    v_conv.id, v_conv.organization_id, p_sender_user_id, p_sender_role,
    p_sender_name, p_content, p_message_type, FALSE, p_metadata
  )
  RETURNING * INTO v_source_msg;

  IF p_message_type = 'feedback_request' THEN
    RETURN v_source_msg;
  END IF;

  -- Mirror only dispatcher/system messages to linked partner org conversations.
  IF p_sender_role NOT IN ('dispatcher', 'system') THEN
    RETURN v_source_msg;
  END IF;

  -- Determine the linked partner org from the party lane.
  IF v_conv.party_type = 'client' THEN
    SELECT c.linked_organization_id INTO v_target_org_id
    FROM public.clients c WHERE c.id = v_conv.client_id;
  ELSIF v_conv.party_type = 'supplier' THEN
    SELECT s.linked_organization_id INTO v_target_org_id
    FROM public.suppliers s WHERE s.id = v_conv.supplier_id;
  ELSE
    RETURN v_source_msg;
  END IF;

  IF v_target_org_id IS NULL THEN RETURN v_source_msg; END IF;

  -- Only mirror host-org dispatchers to the linked partner, not the linked supplier's own
  -- dispatcher messages (they already landed in the host's conv above).
  IF v_conv.organization_id <> v_source_trip.organization_id THEN
    RETURN v_source_msg;
  END IF;

  SELECT * INTO v_target_trip
  FROM public.trips t
  WHERE t.organization_id = v_target_org_id
    AND t.trip_number = v_source_trip.trip_number
  ORDER BY t.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN RETURN v_source_msg; END IF;

  IF v_conv.party_type = 'client' THEN
    v_target_party_type  := 'supplier';
    v_target_sender_role := 'supplier';
    SELECT s.id, COALESCE(NULLIF(s.company_name,''), NULLIF(s.name,''), 'Supplier')
    INTO v_target_party_id, v_target_party_name
    FROM public.suppliers s
    WHERE s.organization_id = v_target_org_id
      AND s.linked_organization_id = v_conv.organization_id
    ORDER BY s.created_at DESC LIMIT 1;
  ELSE
    v_target_party_type  := 'client';
    v_target_sender_role := 'client';
    SELECT c.id, COALESCE(NULLIF(c.name,''), 'Client')
    INTO v_target_party_id, v_target_party_name
    FROM public.clients c
    WHERE c.organization_id = v_target_org_id
      AND c.linked_organization_id = v_conv.organization_id
    ORDER BY c.created_at DESC LIMIT 1;
  END IF;

  IF v_target_party_id IS NULL THEN RETURN v_source_msg; END IF;

  SELECT tc.id INTO v_target_conv_id
  FROM public.trip_conversations tc
  WHERE tc.trip_id = v_target_trip.id
    AND tc.party_type = v_target_party_type
  LIMIT 1;

  IF v_target_conv_id IS NULL THEN
    INSERT INTO public.trip_conversations (
      organization_id, trip_id, party_type, party_name,
      client_id, supplier_id, driver_id
    )
    VALUES (
      v_target_org_id, v_target_trip.id, v_target_party_type, v_target_party_name,
      CASE WHEN v_target_party_type = 'client' THEN v_target_party_id ELSE NULL END,
      CASE WHEN v_target_party_type = 'supplier' THEN v_target_party_id ELSE NULL END,
      NULL
    )
    ON CONFLICT (trip_id, party_type) DO UPDATE SET
      organization_id = excluded.organization_id,
      party_name      = coalesce(nullif(trim(excluded.party_name), ''), trip_conversations.party_name),
      client_id       = coalesce(excluded.client_id, trip_conversations.client_id),
      supplier_id     = coalesce(excluded.supplier_id, trip_conversations.supplier_id),
      updated_at      = now()
    RETURNING id INTO v_target_conv_id;
  END IF;

  INSERT INTO public.trip_messages (
    conversation_id, organization_id, sender_user_id, sender_role,
    sender_name, content, message_type, is_read, metadata
  )
  VALUES (
    v_target_conv_id, v_target_org_id, p_sender_user_id, v_target_sender_role,
    p_sender_name, p_content, p_message_type, FALSE, p_metadata
  );

  RETURN v_source_msg;
END;
$$;


ALTER FUNCTION "public"."send_trip_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_sender_role" "text", "p_sender_name" "text", "p_sender_user_id" "uuid", "p_message_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_trip_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_sender_role" "text", "p_sender_name" "text", "p_sender_user_id" "uuid", "p_message_type" "text", "p_metadata" "jsonb") IS 'Insert a trip chat message and optionally mirror to linked partner org conversation. Allowlist matches trip_messages_message_type_check constraint (20260611160000). Includes image, document_upload, document_share, ledger, tracking, status_change etc.';



