CREATE OR REPLACE FUNCTION "public"."set_driver_invite_from_org_name"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.from_org_name IS NULL OR trim(coalesce(NEW.from_org_name, '')) = '' THEN
    SELECT name INTO NEW.from_org_name FROM public.organizations WHERE id = NEW.from_organization_id;
    NEW.from_org_name := coalesce(nullif(trim(coalesce(NEW.from_org_name, '')), ''), 'Unknown');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_driver_invite_from_org_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_driver_operational_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.driver_code IS NULL OR btrim(NEW.driver_code) = '' THEN
    NEW.driver_code := public.generate_operational_code(NEW.organization_id, 'driver');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_driver_operational_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_indent_assigned_supplier_on_quote_accepted"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF new.status = 'accepted' THEN
    UPDATE public.indents
    SET
      assigned_supplier_id = new.bidder_organization_id,
      assigned_supplier_rate = new.amount,
      updated_at = now()
    WHERE id = new.indent_id;
  END IF;
  RETURN new;
END;
$$;


ALTER FUNCTION "public"."set_indent_assigned_supplier_on_quote_accepted"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_indent_assigned_supplier_on_quote_accepted"() IS 'On direct_quotes.status -> accepted: set indent.assigned_supplier_id and assigned_supplier_rate from quote amount.';



CREATE OR REPLACE FUNCTION "public"."set_indent_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  seq bigint;
BEGIN
  IF NEW.indent_number IS NULL OR trim(NEW.indent_number) = '' THEN
    INSERT INTO public.organization_counters (organization_id)
    VALUES (NEW.organization_id)
    ON CONFLICT (organization_id) DO NOTHING;

    UPDATE public.organization_counters
    SET indent_seq = indent_seq + 1
    WHERE organization_id = NEW.organization_id
    RETURNING indent_seq INTO seq;

    NEW.indent_number := 'IND' || lpad(seq::text, 3, '0');

    IF public.column_exists('public', 'indents', 'display_indent_id') THEN
      NEW.display_indent_id := NEW.indent_number;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_indent_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_indent_operational_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.indent_operational_code IS NULL OR btrim(NEW.indent_operational_code) = '' THEN
    NEW.indent_operational_code := public.generate_enterprise_operational_code(
      NEW.organization_id,
      'indent'
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_indent_operational_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_indent_operational_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_seq_text text;
  v_seq_int integer;
  v_legacy text;
BEGIN
  IF NEW.indent_code IS NULL OR btrim(NEW.indent_code) = '' THEN
    NEW.indent_code := public.generate_operational_code(NEW.organization_id, 'indent');
  END IF;

  v_seq_text := substring(NEW.indent_code FROM '([0-9]+)$');
  v_seq_int := CASE WHEN v_seq_text IS NULL THEN NULL ELSE v_seq_text::integer END;
  v_legacy := 'IND' || lpad(coalesce(v_seq_int, 1)::text, 3, '0');

  IF NEW.indent_number IS NULL OR btrim(NEW.indent_number) = '' THEN
    NEW.indent_number := v_legacy;
  END IF;
  IF NEW.display_indent_id IS NULL OR btrim(NEW.display_indent_id) = '' THEN
    NEW.display_indent_id := v_legacy;
  END IF;
  IF NEW.sequence_number IS NULL THEN
    NEW.sequence_number := coalesce(v_seq_int, 1);
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."set_indent_operational_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_indent_quoted_on_direct_quote"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM 'pending' THEN
    RETURN NEW;
  END IF;
  UPDATE public.indents i
  SET
    status = 'quoted',
    updated_at = now()
  WHERE i.id = NEW.indent_id
    AND lower(trim(i.status::text)) = ANY (
      ARRAY['pending', 'broadcast', 'open', 'draft']::text[]
    );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_indent_quoted_on_direct_quote"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_indent_quoted_on_direct_quote"() IS 'When a pending direct_quote is written, set owning indent to quoted if still in an open-ish status.';



CREATE OR REPLACE FUNCTION "public"."set_load_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  seq bigint;
BEGIN
  IF NEW.load_number IS NULL OR trim(NEW.load_number) = '' THEN
    -- Ensure counter exists for the owner_user_id
    INSERT INTO public.user_counters (user_id)
    VALUES (NEW.owner_user_id)
    ON CONFLICT (user_id) DO NOTHING;

    -- Atomically increment and retrieve the sequence
    UPDATE public.user_counters
    SET load_seq = load_seq + 1
    WHERE user_id = NEW.owner_user_id
    RETURNING load_seq INTO seq;

    NEW.load_number := 'LOAD' || lpad(seq::text, 3, '0');
    
    -- Also set display_load_id if it exists
    IF public.column_exists('public', 'loads', 'display_load_id') THEN
      NEW.display_load_id := NEW.load_number;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_load_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_organization_operational_code_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_candidate text;
  v_salt integer;
BEGIN
  IF NEW.operational_code IS NOT NULL AND btrim(NEW.operational_code) <> '' THEN
    NEW.operational_code := upper(btrim(NEW.operational_code));
    RETURN NEW;
  END IF;

  v_salt := 0;
  LOOP
    v_candidate := public.make_operational_org_code(NEW.name, NEW.id, v_salt);
    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM public.organizations o
      WHERE o.operational_code = v_candidate
        AND o.id IS DISTINCT FROM NEW.id
    );
    v_salt := v_salt + 1;
    IF v_salt > 100 THEN
      RAISE EXCEPTION 'Unable to allocate unique operational_code for org %', NEW.id;
    END IF;
  END LOOP;

  NEW.operational_code := v_candidate;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_organization_operational_code_on_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_trip_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  seq bigint;
BEGIN
  IF NEW.trip_number IS NULL OR trim(NEW.trip_number) = '' THEN
    INSERT INTO public.organization_counters (organization_id)
    VALUES (NEW.organization_id)
    ON CONFLICT (organization_id) DO NOTHING;

    UPDATE public.organization_counters
    SET trip_seq = trip_seq + 1
    WHERE organization_id = NEW.organization_id
    RETURNING trip_seq INTO seq;

    NEW.trip_number     := 'TRP' || lpad(seq::text, 3, '0');
    NEW.display_trip_id := NEW.trip_number;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_trip_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_trip_operational_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.trip_operational_code IS NULL OR btrim(NEW.trip_operational_code) = '' THEN
    NEW.trip_operational_code := public.generate_enterprise_operational_code(
      NEW.organization_id,
      'trip'
    );
  END IF;

  IF NEW.indent_id IS NOT NULL AND (NEW.indent_reference_code IS NULL OR btrim(NEW.indent_reference_code) = '') THEN
    SELECT coalesce(i.indent_operational_code, i.indent_code, i.display_indent_id, i.indent_number)
    INTO NEW.indent_reference_code
    FROM public.indents i
    WHERE i.id = NEW.indent_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_trip_operational_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_trip_operational_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_seq_text text;
  v_seq_int integer;
  v_legacy text;
BEGIN
  IF NEW.trip_code IS NULL OR btrim(NEW.trip_code) = '' THEN
    NEW.trip_code := public.generate_operational_code(NEW.organization_id, 'trip');
  END IF;

  v_seq_text := substring(NEW.trip_code FROM '([0-9]+)$');
  v_seq_int := CASE WHEN v_seq_text IS NULL THEN NULL ELSE v_seq_text::integer END;
  v_legacy := 'TRP' || lpad(coalesce(v_seq_int, 1)::text, 3, '0');

  IF NEW.trip_number IS NULL OR btrim(NEW.trip_number) = '' THEN
    NEW.trip_number := v_legacy;
  END IF;
  IF NEW.display_trip_id IS NULL OR btrim(NEW.display_trip_id) = '' THEN
    NEW.display_trip_id := v_legacy;
  END IF;
  IF NEW.sequence_number IS NULL THEN
    NEW.sequence_number := coalesce(v_seq_int, 1);
  END IF;

  IF NEW.indent_id IS NOT NULL THEN
    IF NEW.source_indent_id IS NULL THEN
      NEW.source_indent_id := NEW.indent_id;
    END IF;
    IF NEW.source_indent_code IS NULL OR btrim(NEW.source_indent_code) = '' THEN
      SELECT coalesce(i.indent_code, i.display_indent_id, i.indent_number)
      INTO NEW.source_indent_code
      FROM public.indents i
      WHERE i.id = NEW.indent_id;
    END IF;
    IF NEW.converted_from_indent_at IS NULL THEN
      NEW.converted_from_indent_at := now();
    END IF;
    IF NEW.converted_by IS NULL THEN
      NEW.converted_by := auth.uid();
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."set_trip_operational_identity"() OWNER TO "postgres";


