CREATE OR REPLACE FUNCTION "public"."sqids_shuffle"("p_alphabet" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  chars text[];
  len   int;
  e     int := 0;
  t     int;
  c     int;
  tmp   text;
BEGIN
  IF p_alphabet IS NULL OR length(p_alphabet) < 2 THEN
    RETURN coalesce(p_alphabet, '');
  END IF;
  chars := regexp_split_to_array(p_alphabet, '');
  len := coalesce(array_length(chars, 1), 0);
  t := len - 1;
  WHILE t > 0 LOOP
    c := (e * t + ascii(chars[e + 1]) + ascii(chars[t + 1])) % len;
    tmp := chars[e + 1];
    chars[e + 1] := chars[c + 1];
    chars[c + 1] := tmp;
    e := e + 1;
    t := t - 1;
  END LOOP;
  RETURN array_to_string(chars, '');
END;
$$;


ALTER FUNCTION "public"."sqids_shuffle"("p_alphabet" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sqids_to_id"("p_num" bigint, "p_alphabet" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  chars text[];
  len   int;
  n     bigint;
  rem   int;
  out   text := '';
BEGIN
  IF p_alphabet IS NULL OR length(p_alphabet) < 1 THEN
    RETURN '';
  END IF;
  chars := regexp_split_to_array(p_alphabet, '');
  len := coalesce(array_length(chars, 1), 0);
  n := p_num;
  IF n < 0 THEN
    RAISE EXCEPTION 'sqids_to_id: negative number %', p_num;
  END IF;
  LOOP
    rem := (n % len)::int;
    out := chars[rem + 1] || out;
    n := n / len;
    EXIT WHEN n = 0;
  END LOOP;
  RETURN out;
END;
$$;


ALTER FUNCTION "public"."sqids_to_id"("p_num" bigint, "p_alphabet" "text") OWNER TO "postgres";


