CREATE OR REPLACE FUNCTION "public"."submit_atomic_feedback"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_message_id" "uuid", "p_rated_type" "text", "p_rated_id" "uuid", "p_score" integer, "p_tags" "text"[] DEFAULT ARRAY[]::"text"[], "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_submitted_at TEXT;
  v_rows         INT;
  v_existing     JSONB;
BEGIN
  -- Clamp score to valid range
  p_score := GREATEST(1, LEAST(5, p_score));

  -- Idempotency: if already submitted, return the stored metadata unchanged.
  SELECT metadata INTO v_existing
  FROM   public.trip_messages
  WHERE  id = p_message_id;

  IF (v_existing->>'submitted_at') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok',               TRUE,
      'already_submitted', TRUE,
      'message_id',       p_message_id,
      'submitted_at',     v_existing->>'submitted_at',
      'submitted_score',  (v_existing->>'submitted_score')::INT,
      'submitted_tags',   v_existing->'submitted_tags'
    );
  END IF;

  -- Upsert rating record
  INSERT INTO public.ratings (
    organization_id, trip_id,
    rated_type, rated_id,
    score, tags, comment,
    created_at
  )
  VALUES (
    p_organization_id, p_trip_id,
    p_rated_type, p_rated_id,
    p_score, p_tags, p_comment,
    NOW()
  )
  ON CONFLICT (organization_id, trip_id, rated_type, rated_id)
  DO UPDATE SET
    score      = EXCLUDED.score,
    tags       = EXCLUDED.tags,
    comment    = COALESCE(EXCLUDED.comment, ratings.comment),
    updated_at = NOW();

  -- Stamp message metadata atomically — JSONB || requires no prior SELECT
  v_submitted_at := to_char(
    now() AT TIME ZONE 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );

  UPDATE public.trip_messages
  SET    metadata = COALESCE(metadata, '{}'::JSONB) || jsonb_build_object(
    'submitted_at',    v_submitted_at,
    'submitted_score', p_score,
    'submitted_tags',  to_jsonb(COALESCE(p_tags, ARRAY[]::TEXT[]))
  )
  WHERE  id = p_message_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'trip_message % not found', p_message_id;
  END IF;

  RETURN jsonb_build_object(
    'ok',               TRUE,
    'already_submitted', FALSE,
    'message_id',       p_message_id,
    'submitted_at',     v_submitted_at,
    'submitted_score',  p_score,
    'submitted_tags',   to_jsonb(COALESCE(p_tags, ARRAY[]::TEXT[]))
  );
END;
$$;


ALTER FUNCTION "public"."submit_atomic_feedback"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_message_id" "uuid", "p_rated_type" "text", "p_rated_id" "uuid", "p_score" integer, "p_tags" "text"[], "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_business_event"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_content" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_new_trip_status" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_user_name" "text" DEFAULT 'System'::"text", "p_conversation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prev_status  TEXT;
  v_updated_at   TEXT;
  v_message_ids  UUID[] := '{}';
  v_new_id       UUID;
  v_sender_role  TEXT;
BEGIN
  -- ── 1. Validate the caller's org can write to this trip ──────────────────
  SELECT status INTO v_prev_status
  FROM   public.trips
  WHERE  id = p_trip_id
    AND (
      organization_id = p_organization_id
      OR EXISTS (
        SELECT 1 FROM public.suppliers s
        WHERE  s.id          = supplier_id
          AND  s.linked_organization_id = p_organization_id
      )
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'submit_business_event: trip % not accessible for org %',
      p_trip_id, p_organization_id;
  END IF;

  -- ── 2. Optionally update trip status ─────────────────────────────────────
  IF p_new_trip_status IS NOT NULL AND p_new_trip_status <> v_prev_status THEN
    UPDATE public.trips
    SET    status     = p_new_trip_status,
           updated_at = NOW()
    WHERE  id = p_trip_id;
  END IF;

  v_updated_at := to_char(
    NOW() AT TIME ZONE 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );

  -- Derive sender_role from event type
  v_sender_role := CASE p_event_type
    WHEN 'tracking' THEN 'driver'
    WHEN 'ledger'   THEN 'dispatcher'
    ELSE                 'system'
  END;

  -- ── 3. Insert message(s) ──────────────────────────────────────────────────
  IF p_conversation_id IS NOT NULL THEN
    -- Targeted: single conversation
    INSERT INTO public.trip_messages (
      conversation_id, organization_id,
      sender_user_id, sender_role, sender_name,
      content, message_type, metadata,
      is_read, is_delivered
    ) VALUES (
      p_conversation_id, p_organization_id,
      p_user_id, v_sender_role, p_user_name,
      p_content, p_event_type, p_metadata,
      TRUE, TRUE
    )
    RETURNING id INTO v_new_id;
    v_message_ids := array_append(v_message_ids, v_new_id);
  ELSE
    -- Broadcast: one message per conversation for this trip
    FOR v_new_id IN
      INSERT INTO public.trip_messages (
        conversation_id, organization_id,
        sender_user_id, sender_role, sender_name,
        content, message_type, metadata,
        is_read, is_delivered
      )
      SELECT
        tc.id,
        tc.organization_id,
        p_user_id,
        v_sender_role,
        p_user_name,
        p_content,
        p_event_type,
        p_metadata,
        TRUE,
        TRUE
      FROM public.trip_conversations tc
      WHERE tc.trip_id = p_trip_id
      RETURNING id
    LOOP
      v_message_ids := array_append(v_message_ids, v_new_id);
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok',           TRUE,
    'message_ids',  v_message_ids,
    'updated_at',   v_updated_at,
    'prev_status',  v_prev_status,
    'new_status',   COALESCE(p_new_trip_status, v_prev_status),
    'event_type',   p_event_type
  );
END;
$$;


ALTER FUNCTION "public"."submit_business_event"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_event_type" "text", "p_content" "text", "p_metadata" "jsonb", "p_new_trip_status" "text", "p_user_id" "uuid", "p_user_name" "text", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_business_verification"("p_org_id" "uuid", "p_registration_type" "public"."registration_type_enum" DEFAULT NULL::"public"."registration_type_enum", "p_address_pincode" "text" DEFAULT NULL::"text", "p_address_proof_path" "text" DEFAULT NULL::"text", "p_address_proof_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role            text;
  v_current_status  public.kyc_verification_status;
  v_reg_type        public.registration_type_enum;
  v_has_gst_cert    boolean;
  v_has_pan_card    boolean;
BEGIN
  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_org_id
    AND user_id = auth.uid()
    AND status = 'active';

  IF v_role IS NULL OR v_role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'Only workspace owners or admins can submit for verification.';
  END IF;

  SELECT verification_status, registration_type
  INTO v_current_status, v_reg_type
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF v_current_status NOT IN ('unverified', 'rejected') THEN
    RAISE EXCEPTION 'Profile is already % and cannot be resubmitted.', v_current_status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = p_org_id AND business_pan IS NOT NULL AND gstin IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'PAN and GSTIN must be saved before submitting.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.verification_documents
    WHERE org_id = p_org_id AND document_type = 'gst_certificate' AND status <> 'REPLACED'
  ) INTO v_has_gst_cert;

  SELECT EXISTS (
    SELECT 1 FROM public.verification_documents
    WHERE org_id = p_org_id AND document_type = 'pan_card' AND status <> 'REPLACED'
  ) INTO v_has_pan_card;

  IF NOT v_has_gst_cert THEN
    RAISE EXCEPTION 'GST registration certificate must be uploaded before submitting.';
  END IF;

  IF NOT v_has_pan_card THEN
    RAISE EXCEPTION 'PAN card copy must be uploaded before submitting.';
  END IF;

  IF p_address_proof_path IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.organizations WHERE id = p_org_id AND address_proof_path IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Address proof must be uploaded before submitting.';
  END IF;

  UPDATE public.organizations SET
    registration_type   = COALESCE(p_registration_type,  registration_type),
    address_pincode     = COALESCE(NULLIF(TRIM(p_address_pincode), ''),   address_pincode),
    address_proof_path  = COALESCE(NULLIF(TRIM(p_address_proof_path), ''), address_proof_path),
    address_proof_type  = COALESCE(NULLIF(TRIM(p_address_proof_type), ''), address_proof_type),
    verification_status = 'pending',
    frozen_at           = now(),
    submitted_at        = now(),
    rejection_reasons   = NULL,
    updated_at          = now()
  WHERE id = p_org_id;

  INSERT INTO public.verification_audit_logs
    (org_id, changed_by, previous_status, new_status, notes)
  VALUES
    (p_org_id, auth.uid(), v_current_status, 'pending', 'user_submitted');

  v_reg_type := COALESCE(p_registration_type, v_reg_type);

  INSERT INTO public.verification_jobs (organization_id, status, pillar_2_mca_status)
  VALUES (
    p_org_id,
    'QUEUED'::public.verification_job_status,
    CASE WHEN v_reg_type IN ('llp', 'pvt_ltd', 'public_ltd', 'partnership')
         THEN 'QUEUED' ELSE 'NOT_STARTED' END::public.pillar_status_type
  )
  ON CONFLICT (organization_id) DO UPDATE SET
    status              = 'QUEUED',
    ocr_status          = 'QUEUED',
    pillar_1_tax_status = 'QUEUED',
    pillar_2_mca_status = EXCLUDED.pillar_2_mca_status,
    ocr_detail          = NULL,
    pillar_1_tax_detail = NULL,
    pillar_2_mca_detail = NULL,
    attempts            = 0,
    error_logs          = NULL,
    next_attempt_at     = now(),
    completed_at        = NULL,
    updated_at          = now();

  RETURN jsonb_build_object(
    'ok',                  true,
    'org_id',              p_org_id,
    'verification_status', 'pending',
    'frozen_at',           now(),
    'job_queued',          true
  );
END;
$$;


ALTER FUNCTION "public"."submit_business_verification"("p_org_id" "uuid", "p_registration_type" "public"."registration_type_enum", "p_address_pincode" "text", "p_address_proof_path" "text", "p_address_proof_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_business_verification"("p_org_id" "uuid", "p_registration_type" "public"."registration_type_enum" DEFAULT NULL::"public"."registration_type_enum", "p_address_pincode" "text" DEFAULT NULL::"text", "p_address_proof_path" "text" DEFAULT NULL::"text", "p_address_proof_type" "text" DEFAULT NULL::"text", "p_gst_not_applicable" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role               text;
  v_current_status     public.kyc_verification_status;
  v_reg_type           public.registration_type_enum;
  v_has_gst_cert       boolean;
  v_has_pan_card       boolean;
  v_gst_not_applicable boolean;
BEGIN
  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_org_id
    AND user_id = auth.uid()
    AND status = 'active';

  IF v_role IS NULL OR v_role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'Only workspace owners or admins can submit for verification.';
  END IF;

  SELECT verification_status, registration_type, gst_not_applicable
  INTO v_current_status, v_reg_type, v_gst_not_applicable
  FROM public.organizations
  WHERE id = p_org_id
  FOR UPDATE;

  IF v_current_status NOT IN ('unverified', 'rejected') THEN
    RAISE EXCEPTION 'Profile is already % and cannot be resubmitted.', v_current_status;
  END IF;

  -- Persist the flag first so the checks below (and the stored row) agree
  -- on the final value for this submission.
  v_gst_not_applicable := COALESCE(p_gst_not_applicable, v_gst_not_applicable, false);

  IF NOT EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = p_org_id AND business_pan IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'PAN must be saved before submitting.';
  END IF;

  IF NOT v_gst_not_applicable AND NOT EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = p_org_id AND gstin IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'GSTIN must be saved before submitting, or mark GST as not applicable.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.verification_documents
    WHERE org_id = p_org_id AND document_type = 'gst_certificate' AND status <> 'REPLACED'
  ) INTO v_has_gst_cert;

  SELECT EXISTS (
    SELECT 1 FROM public.verification_documents
    WHERE org_id = p_org_id AND document_type = 'pan_card' AND status <> 'REPLACED'
  ) INTO v_has_pan_card;

  IF NOT v_gst_not_applicable AND NOT v_has_gst_cert THEN
    RAISE EXCEPTION 'GST registration certificate must be uploaded before submitting.';
  END IF;

  IF NOT v_has_pan_card THEN
    RAISE EXCEPTION 'PAN card copy must be uploaded before submitting.';
  END IF;

  IF p_address_proof_path IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.organizations WHERE id = p_org_id AND address_proof_path IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Address proof must be uploaded before submitting.';
  END IF;

  UPDATE public.organizations SET
    registration_type   = COALESCE(p_registration_type,  registration_type),
    address_pincode     = COALESCE(NULLIF(TRIM(p_address_pincode), ''),   address_pincode),
    address_proof_path  = COALESCE(NULLIF(TRIM(p_address_proof_path), ''), address_proof_path),
    address_proof_type  = COALESCE(NULLIF(TRIM(p_address_proof_type), ''), address_proof_type),
    gst_not_applicable  = v_gst_not_applicable,
    verification_status = 'pending',
    frozen_at            = now(),
    submitted_at         = now(),
    rejection_reasons    = NULL,
    updated_at           = now()
  WHERE id = p_org_id;

  INSERT INTO public.verification_audit_logs
    (org_id, changed_by, previous_status, new_status, notes)
  VALUES
    (p_org_id, auth.uid(), v_current_status, 'pending', 'user_submitted');

  v_reg_type := COALESCE(p_registration_type, v_reg_type);

  INSERT INTO public.verification_jobs (organization_id, status, pillar_2_mca_status)
  VALUES (
    p_org_id,
    'QUEUED'::public.verification_job_status,
    CASE WHEN v_reg_type IN ('llp', 'pvt_ltd', 'public_ltd', 'partnership')
         THEN 'QUEUED' ELSE 'NOT_STARTED' END::public.pillar_status_type
  )
  ON CONFLICT (organization_id) DO UPDATE SET
    status              = 'QUEUED',
    ocr_status          = 'QUEUED',
    pillar_1_tax_status = 'QUEUED',
    pillar_2_mca_status = EXCLUDED.pillar_2_mca_status,
    ocr_detail          = NULL,
    pillar_1_tax_detail = NULL,
    pillar_2_mca_detail = NULL,
    attempts            = 0,
    error_logs          = NULL,
    next_attempt_at     = now(),
    completed_at        = NULL,
    updated_at          = now();

  RETURN jsonb_build_object(
    'ok',                  true,
    'org_id',              p_org_id,
    'verification_status', 'pending',
    'frozen_at',           now(),
    'job_queued',          true
  );
END;
$$;


ALTER FUNCTION "public"."submit_business_verification"("p_org_id" "uuid", "p_registration_type" "public"."registration_type_enum", "p_address_pincode" "text", "p_address_proof_path" "text", "p_address_proof_type" "text", "p_gst_not_applicable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_pulse_bid_with_direct_quote"("p_post_id" "uuid", "p_bidder_org_id" "uuid", "p_amount" numeric, "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_indent_id uuid;
  v_post_org_id uuid;
  v_post_active boolean;
  v_indent_status text;
  v_bid_id uuid;
  v_already boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_org_member(p_bidder_org_id) THEN
    RAISE EXCEPTION 'Not a member of bidder organization';
  END IF;

  SELECT p.source_indent_id, p.organization_id, p.is_active
  INTO v_indent_id, v_post_org_id, v_post_active
  FROM public.posts p
  WHERE p.id = p_post_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Post not found';
  END IF;
  IF v_indent_id IS NULL THEN
    RAISE EXCEPTION 'POST_NOT_LINKED_TO_INDENT';
  END IF;
  IF NOT coalesce(v_post_active, false) THEN
    RAISE EXCEPTION 'Post is not active';
  END IF;
  IF p_bidder_org_id = v_post_org_id THEN
    RAISE EXCEPTION 'Cannot bid on your own organization''s post';
  END IF;

  SELECT lower(trim(coalesce(i.status::text, '')))
  INTO v_indent_status
  FROM public.indents i
  WHERE i.id = v_indent_id
    AND i.organization_id = v_post_org_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Indent does not match post owner';
  END IF;

  IF v_indent_status = ANY (
    ARRAY['awarded', 'completed', 'cancelled', 'closed', 'expired']::text[]
  ) THEN
    RAISE EXCEPTION 'INDENT_NOT_OPEN_FOR_BIDS';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bids b
    WHERE b.post_id = p_post_id
      AND b.bidder_organization_id = p_bidder_org_id
  ) THEN
    v_already := true;
    UPDATE public.bids b
    SET
      amount = p_amount,
      note = nullif(trim(p_note), ''),
      updated_at = now()
    WHERE b.post_id = p_post_id
      AND b.bidder_organization_id = p_bidder_org_id
      AND b.status = 'pending'
    RETURNING b.id INTO v_bid_id;
    IF v_bid_id IS NULL THEN
      SELECT b.id INTO v_bid_id
      FROM public.bids b
      WHERE b.post_id = p_post_id
        AND b.bidder_organization_id = p_bidder_org_id;
    END IF;
  ELSE
    INSERT INTO public.bids (
      post_id,
      bidder_organization_id,
      bidder_user_id,
      amount,
      note,
      status
    )
    VALUES (
      p_post_id,
      p_bidder_org_id,
      v_uid,
      p_amount,
      nullif(trim(p_note), ''),
      'pending'
    )
    RETURNING id INTO v_bid_id;
  END IF;

  INSERT INTO public.direct_quotes (
    indent_id,
    bidder_organization_id,
    amount,
    notes,
    status
  )
  VALUES (
    v_indent_id,
    p_bidder_org_id,
    p_amount,
    nullif(trim(p_note), ''),
    'pending'
  )
  ON CONFLICT (indent_id, bidder_organization_id)
  DO UPDATE SET
    amount = excluded.amount,
    notes = excluded.notes,
    updated_at = now();

  RETURN jsonb_build_object('bid_id', v_bid_id, 'already_bid', v_already);
END;
$$;


ALTER FUNCTION "public"."submit_pulse_bid_with_direct_quote"("p_post_id" "uuid", "p_bidder_org_id" "uuid", "p_amount" numeric, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_pulse_bid_with_direct_quote"("p_post_id" "uuid", "p_bidder_org_id" "uuid", "p_amount" numeric, "p_note" "text") IS 'Pulse bid: writes bids row and upserts direct_quotes. Rejects when indent is awarded/closed or post inactive.';



CREATE OR REPLACE FUNCTION "public"."submit_trip_feedback"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_message_id" "uuid", "p_rated_type" "text", "p_rated_id" "uuid", "p_score" integer, "p_tags" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_submitted_at  TEXT;
  v_comment       TEXT;
  v_rows          INT;
BEGIN
  p_score := GREATEST(1, LEAST(5, p_score));

  IF EXISTS (
    SELECT 1
    FROM   public.trip_messages
    WHERE  id = p_message_id
      AND  (metadata->>'submitted_at') IS NOT NULL
  ) THEN
    RETURN jsonb_build_object('error', 'already_submitted');
  END IF;

  v_comment := jsonb_build_object(
    'source', 'trip_chat_feedback',
    'tags',   to_jsonb(COALESCE(p_tags, ARRAY[]::TEXT[]))
  )::TEXT;

  INSERT INTO public.ratings (
    organization_id,   trip_id,      rater_type,
    rater_id,          rated_type,   rated_id,
    score,             comment,      updated_at
  )
  VALUES (
    p_organization_id, p_trip_id,   'organization',
    p_organization_id, p_rated_type, p_rated_id,
    p_score,           v_comment,   now()
  )
  ON CONFLICT (trip_id, rater_type, rater_id, rated_type, rated_id)
  DO UPDATE SET
    score      = EXCLUDED.score,
    comment    = EXCLUDED.comment,
    updated_at = now();

  v_submitted_at := to_char(
    now() AT TIME ZONE 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );

  UPDATE public.trip_messages
  SET    metadata = COALESCE(metadata, '{}'::JSONB)
                    || jsonb_build_object(
                         'submitted_at',    v_submitted_at,
                         'submitted_score', p_score,
                         'submitted_tags',  to_jsonb(COALESCE(p_tags, ARRAY[]::TEXT[])),
                         'rating',          to_jsonb(p_score)
                       )
  WHERE  id = p_message_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'trip_message % not found', p_message_id;
  END IF;

  RETURN jsonb_build_object('ok', TRUE, 'submitted_at', v_submitted_at);
END;
$$;


ALTER FUNCTION "public"."submit_trip_feedback"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_message_id" "uuid", "p_rated_type" "text", "p_rated_id" "uuid", "p_score" integer, "p_tags" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_trip_feedback"("p_organization_id" "uuid", "p_trip_id" "uuid", "p_message_id" "uuid", "p_rated_type" "text", "p_rated_id" "uuid", "p_score" integer, "p_tags" "text"[]) IS 'Atomic feedback submit: upserts a rating row and stamps submitted_at on the feedback_request message metadata in a single transaction. Replaces the 3-round-trip client-side flow (upsert + SELECT + UPDATE). Returns {ok: true, submitted_at: ...} on success or {error: ...} on guard failure.';



CREATE OR REPLACE FUNCTION "public"."suppliers_block_deprecated_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- On INSERT, block if company_name or contact are being set
  IF TG_OP = 'INSERT' THEN
    IF NEW.company_name IS NOT NULL OR NEW.contact IS NOT NULL THEN
      RAISE EXCEPTION
        'suppliers: writing to deprecated columns company_name or contact is blocked. Use suppliers.name and suppliers.contact_person + suppliers.phone instead.';
    END IF;
  END IF;

  -- On UPDATE, block only if the value is actually changing
  IF TG_OP = 'UPDATE' THEN
    IF NEW.company_name IS DISTINCT FROM OLD.company_name OR
       NEW.contact IS DISTINCT FROM OLD.contact THEN
      RAISE EXCEPTION
        'suppliers: writing to deprecated columns company_name or contact is blocked. Use suppliers.name and suppliers.contact_person + suppliers.phone instead.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."suppliers_block_deprecated_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_conversation_on_message"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.trip_conversations
  SET
    last_message_at      = NEW.created_at,
    last_message_preview = LEFT(NEW.content, 120),
    unread_dispatcher_count = CASE
      WHEN public.fn_trip_message_counts_as_dispatcher_unread(NEW.sender_role, NEW.message_type)
      THEN unread_dispatcher_count + 1
      ELSE unread_dispatcher_count
    END,
    updated_at = NOW()
  WHERE id = NEW.conversation_id;
  RETURN NEW;
END;
$$;


