CREATE OR REPLACE FUNCTION "public"."sync_driver_email_from_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_new text := NULLIF(BTRIM(COALESCE(NEW.email, '')::text), '');
  v_old text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF v_new IS NOT NULL THEN
      UPDATE public.drivers d
      SET email = v_new
      WHERE d.user_id = NEW.id
        AND (d.email IS NULL OR BTRIM(COALESCE(d.email, '')) = '');
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND (OLD.email IS DISTINCT FROM NEW.email) THEN
    v_old := NULLIF(BTRIM(COALESCE(OLD.email, '')::text), '');
    UPDATE public.drivers d
    SET email = v_new
    WHERE d.user_id = NEW.id
      AND (
        d.email IS NULL
        OR BTRIM(COALESCE(d.email, '')) = ''
        OR (v_old IS NOT NULL AND BTRIM(COALESCE(d.email, '')) = v_old)
      );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_driver_email_from_profile"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_driver_email_from_profile"() IS 'When profiles.email is set/updated, backfill drivers.email for rows linked by user_id if driver email was empty or matched previous profile email.';



CREATE OR REPLACE FUNCTION "public"."sync_driver_rows_user_id_for_profile"("p_profile_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_email_norm text;
  v_last10 text;
  v_n int := 0;
BEGIN
  SELECT p.role,
         nullif(lower(trim(coalesce(p.email, ''))), ''),
         public.normalise_phone(p.phone)
    INTO v_role, v_email_norm, v_last10
  FROM public.profiles p
  WHERE p.id = p_profile_id;

  IF NOT FOUND OR coalesce(v_role, '') <> 'driver' THEN
    RETURN 0;
  END IF;

  UPDATE public.drivers d
  SET user_id = p_profile_id,
      status = 'offline',
      updated_at = now()
  WHERE d.user_id IS NULL
    AND d.left_at IS NULL
    AND (
      (v_email_norm IS NOT NULL AND v_email_norm <> ''
        AND nullif(lower(trim(coalesce(d.email, ''))), '') = v_email_norm)
      OR (
        length(coalesce(v_last10, '')) >= 10
        AND d.phone_normalised = v_last10
      )
    );

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."sync_driver_rows_user_id_for_profile"("p_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_driver_rows_user_id_for_profile"("p_profile_id" "uuid") IS 'Sets drivers.user_id to the driver profile id where user_id was null and email (case-insensitive) or phone last-10 matches. Idempotent.';



CREATE OR REPLACE FUNCTION "public"."sync_driver_tenure"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Driver just left (left_at was NULL, now set)
  IF NEW.left_at IS NOT NULL AND OLD.left_at IS NULL THEN
    UPDATE public.driver_tenures
    SET    left_at = NEW.left_at
    WHERE  driver_id = NEW.id
      AND  left_at IS NULL;
  END IF;

  -- Driver reconnected (left_at was set, now cleared)
  IF NEW.left_at IS NULL AND OLD.left_at IS NOT NULL THEN
    -- Close any stale open tenure (safety net)
    UPDATE public.driver_tenures
    SET    left_at = OLD.left_at
    WHERE  driver_id = NEW.id
      AND  left_at IS NULL;

    -- Open a fresh tenure
    INSERT INTO public.driver_tenures (driver_id, organization_id, joined_at, left_at)
    VALUES (NEW.id, NEW.organization_id, now(), NULL);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_driver_tenure"() OWNER TO "postgres";


