    UPDATE public.trips t
    SET driver_display_name = nullif(trim(coalesce(NEW.name, '')), ''),
        updated_at = now()
    WHERE t.driver_id = NEW.id
      AND t.driver_display_name IS DISTINCT FROM nullif(trim(coalesce(NEW.name, '')), '');
  END IF;
  RETURN NEW;
END;
$$;


