CREATE OR REPLACE FUNCTION "public"."toggle_chat_reaction"("p_message_id" "uuid", "p_emoji" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT conversation_id INTO v_conv FROM chat_messages WHERE id = p_message_id;
  IF v_conv IS NULL THEN
    RAISE EXCEPTION 'Message not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.fn_chat_can_access_conversation(v_conv) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1 FROM chat_reactions
    WHERE message_id = p_message_id AND user_id = auth.uid() AND emoji = p_emoji
  ) THEN
    DELETE FROM chat_reactions
    WHERE message_id = p_message_id AND user_id = auth.uid() AND emoji = p_emoji;
  ELSE
    INSERT INTO chat_reactions (message_id, user_id, emoji)
    VALUES (p_message_id, auth.uid(), p_emoji)
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN (
    SELECT coalesce(
      jsonb_object_agg(r.emoji, r.user_ids),
      '{}'::jsonb
    )
    FROM (
      SELECT emoji, jsonb_agg(user_id::text ORDER BY created_at) AS user_ids
      FROM chat_reactions
      WHERE message_id = p_message_id
      GROUP BY emoji
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."toggle_chat_reaction"("p_message_id" "uuid", "p_emoji" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_trip_message_reaction"("p_message_id" "uuid", "p_user_id" "uuid", "p_emoji" "text", "p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reactions    JSONB;
  v_user_ids     JSONB;
  v_uid_text     TEXT := p_user_id::TEXT;
  v_org_check    UUID;
BEGIN
  -- Verify caller belongs to the org that owns this message
  SELECT organization_id INTO v_org_check
  FROM trip_messages
  WHERE id = p_message_id;

  IF v_org_check IS NULL THEN
    RAISE EXCEPTION 'message not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_org_check != p_org_id THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Load current reactions
  SELECT COALESCE(reactions, '{}'::jsonb) INTO v_reactions
  FROM trip_messages WHERE id = p_message_id;

  v_user_ids := COALESCE(v_reactions->p_emoji, '[]'::jsonb);

  IF v_user_ids @> to_jsonb(v_uid_text) THEN
    -- Remove: filter out this user id
    SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
    INTO v_user_ids
    FROM jsonb_array_elements(v_user_ids) AS elem
    WHERE elem <> to_jsonb(v_uid_text);

    IF jsonb_array_length(v_user_ids) = 0 THEN
      v_reactions := v_reactions - p_emoji;          -- drop empty key
    ELSE
      v_reactions := jsonb_set(v_reactions, ARRAY[p_emoji], v_user_ids);
    END IF;
  ELSE
    -- Add: append user id to the array
    v_user_ids  := v_user_ids || to_jsonb(v_uid_text);
    v_reactions := jsonb_set(v_reactions, ARRAY[p_emoji], v_user_ids, true);
  END IF;

  UPDATE trip_messages
  SET reactions = v_reactions
  WHERE id = p_message_id;

  RETURN v_reactions;
END;
$$;


ALTER FUNCTION "public"."toggle_trip_message_reaction"("p_message_id" "uuid", "p_user_id" "uuid", "p_emoji" "text", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."toggle_trip_message_reaction"("p_message_id" "uuid", "p_user_id" "uuid", "p_emoji" "text", "p_org_id" "uuid") IS 'Idempotent emoji reaction toggle. Adds the emoji for the user if absent, removes it if present. Returns updated reactions map.';



