CREATE OR REPLACE FUNCTION "public"."tracking_record_checkpoint"("p_trip_id" "uuid", "p_driver_id" "uuid", "p_org_id" "uuid", "p_session_id" "uuid", "p_latitude" double precision, "p_longitude" double precision, "p_accuracy" double precision DEFAULT NULL::double precision, "p_heading" double precision DEFAULT NULL::double precision, "p_speed_kmh" double precision DEFAULT NULL::double precision, "p_source" "text" DEFAULT 'live'::"text", "p_recorded_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             uuid;
  v_last_lat        double precision;
  v_last_lon        double precision;
  v_last_at         timestamptz;
  v_dist_m          double precision;
  v_elapsed         interval;
  v_checkpoint_id   uuid;
  v_wrote           boolean := false;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.drivers d
    WHERE d.id = p_driver_id AND d.user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'driver mismatch';
  END IF;

  SELECT latitude, longitude, recorded_at
  INTO   v_last_lat, v_last_lon, v_last_at
  FROM   public.driver_presence
  WHERE  driver_id = p_driver_id;

  IF v_last_at IS NOT NULL THEN
    v_elapsed := p_recorded_at - v_last_at;
    v_dist_m := (
      6371000 * 2 * asin(sqrt(
        power(sin(radians(p_latitude - v_last_lat) / 2), 2) +
        cos(radians(v_last_lat)) * cos(radians(p_latitude)) *
        power(sin(radians(p_longitude - v_last_lon) / 2), 2)
      ))
    );
    IF v_dist_m < 50 AND v_elapsed < interval '30 seconds' THEN
      INSERT INTO public.driver_presence (
        driver_id, organization_id, trip_id, session_id,
        latitude, longitude, accuracy, heading, speed_kmh, recorded_at, updated_at
      ) VALUES (
        p_driver_id, p_org_id, p_trip_id, p_session_id,
        p_latitude, p_longitude, p_accuracy, p_heading, p_speed_kmh, p_recorded_at, now()
      )
      ON CONFLICT (driver_id) DO UPDATE SET
        organization_id = EXCLUDED.organization_id,
        trip_id         = EXCLUDED.trip_id,
        session_id      = EXCLUDED.session_id,
        latitude        = EXCLUDED.latitude,
        longitude       = EXCLUDED.longitude,
        accuracy        = EXCLUDED.accuracy,
        heading         = EXCLUDED.heading,
        speed_kmh       = EXCLUDED.speed_kmh,
        recorded_at     = EXCLUDED.recorded_at,
        updated_at      = now();
      RETURN jsonb_build_object('wrote', false, 'checkpoint_id', null, 'dist_m', v_dist_m);
    END IF;
  END IF;

  v_checkpoint_id := gen_random_uuid();
  INSERT INTO public.trip_location_checkpoints (
    id, trip_id, driver_id, organization_id, session_id,
    latitude, longitude, accuracy, heading, speed_kmh, distance_delta_m, source, recorded_at
  ) VALUES (
    v_checkpoint_id, p_trip_id, p_driver_id, p_org_id, p_session_id,
    p_latitude, p_longitude, p_accuracy, p_heading, p_speed_kmh,
    CASE WHEN v_last_at IS NOT NULL THEN v_dist_m ELSE NULL END,
    coalesce(p_source, 'live'), p_recorded_at
  );
  v_wrote := true;

  INSERT INTO public.driver_presence (
    driver_id, organization_id, trip_id, session_id,
    latitude, longitude, accuracy, heading, speed_kmh, recorded_at, updated_at
  ) VALUES (
    p_driver_id, p_org_id, p_trip_id, p_session_id,
    p_latitude, p_longitude, p_accuracy, p_heading, p_speed_kmh, p_recorded_at, now()
  )
  ON CONFLICT (driver_id) DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    trip_id         = EXCLUDED.trip_id,
    session_id      = EXCLUDED.session_id,
    latitude        = EXCLUDED.latitude,
    longitude       = EXCLUDED.longitude,
    accuracy        = EXCLUDED.accuracy,
    heading         = EXCLUDED.heading,
    speed_kmh       = EXCLUDED.speed_kmh,
    recorded_at     = EXCLUDED.recorded_at,
    updated_at      = now();

  UPDATE public.trips
  SET last_location_at = p_recorded_at
  WHERE id = p_trip_id;

  RETURN jsonb_build_object('wrote', v_wrote, 'checkpoint_id', v_checkpoint_id, 'dist_m', v_dist_m);
END;
$$;


ALTER FUNCTION "public"."tracking_record_checkpoint"("p_trip_id" "uuid", "p_driver_id" "uuid", "p_org_id" "uuid", "p_session_id" "uuid", "p_latitude" double precision, "p_longitude" double precision, "p_accuracy" double precision, "p_heading" double precision, "p_speed_kmh" double precision, "p_source" "text", "p_recorded_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tracking_record_checkpoint"("p_trip_id" "uuid", "p_driver_id" "uuid", "p_org_id" "uuid", "p_session_id" "uuid", "p_latitude" double precision, "p_longitude" double precision, "p_accuracy" double precision, "p_heading" double precision, "p_speed_kmh" double precision, "p_source" "text", "p_recorded_at" timestamp with time zone) IS 'Sparse GPS checkpoint + driver_presence UPSERT. Movement gate: 50m OR 30s since last presence. Returns wrote=true when checkpoint row was inserted.';



CREATE OR REPLACE FUNCTION "public"."trg_auto_link_driver_on_signup"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone_norm text;
  v_driver_id uuid;
  v_raw_phone text;
BEGIN
  v_raw_phone := coalesce(
    nullif(trim(NEW.phone::text), ''),
    nullif(trim(NEW.raw_user_meta_data->>'phone'), '')
  );

  IF v_raw_phone IS NULL OR v_raw_phone = '' THEN
    RETURN NEW;
  END IF;

  v_phone_norm := public.normalise_phone(v_raw_phone);
  IF length(coalesce(v_phone_norm, '')) < 10 THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_driver_id
  FROM public.drivers
  WHERE phone_normalised = v_phone_norm
    AND user_id IS NULL
    AND left_at IS NULL
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_driver_id IS NOT NULL THEN
    UPDATE public.drivers
    SET user_id = NEW.id,
        status = 'offline',
        updated_at = now()
    WHERE id = v_driver_id
      AND user_id IS NULL;
  END IF;

  RETURN NEW;
END;
$$;


