CREATE OR REPLACE FUNCTION "public"."trg_profiles_sync_linked_driver_name"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name text;
BEGIN
  IF coalesce(NEW.role, '') <> 'driver' THEN
    RETURN NEW;
  END IF;

  v_name := nullif(trim(coalesce(NEW.full_name, '')), '');
  IF v_name IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT'
     OR NEW.full_name IS DISTINCT FROM OLD.full_name
     OR NEW.role IS DISTINCT FROM OLD.role THEN
    UPDATE public.drivers d
    SET name = v_name,
        updated_at = now()
    WHERE d.user_id = NEW.id
      AND d.left_at IS NULL
      AND d.name IS DISTINCT FROM v_name;
  END IF;

  RETURN NEW;
END;
$$;


