  END IF;

  IF NEW.source_indent_id IS NULL AND NEW.indent_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_seq := nextval('public.booking_ref_seq');
  NEW.booking_ref := public.sqids_encode_booking_ref(v_seq);
