CREATE OR REPLACE FUNCTION "public"."trip_otp_increment_failed"("p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.trip_otps
  SET failed_attempts = failed_attempts + 1
  WHERE code = trim(coalesce(p_code, ''))
    AND used_at IS NULL;
END;
$$;


ALTER FUNCTION "public"."trip_otp_increment_failed"("p_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trip_otp_increment_failed"("p_code" "text") IS 'Increment failed_attempts for wrong OTP submission. O(1).';



CREATE OR REPLACE FUNCTION "public"."trips_sync_driver_vehicle_display"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.driver_id is not null then
    select name into new.driver_display_name from public.drivers where id = new.driver_id;
  else
    new.driver_display_name := null;
  end if;
  if new.vehicle_id is not null then
    select vehicle_number into new.vehicle_display_number from public.vehicles where id = new.vehicle_id;
  end if;
  -- when vehicle_id is null, do not overwrite vehicle_display_number (ad-hoc from client)
  return new;
end;
$$;


ALTER FUNCTION "public"."trips_sync_driver_vehicle_display"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trips_sync_driver_vehicle_display"() IS 'Syncs driver_display_name and vehicle_display_number from drivers/vehicles when driver_id/vehicle_id set. When vehicle_id is null, vehicle_display_number is left unchanged so ad-hoc vehicle numbers (e.g. aggregate trips) persist.';



CREATE OR REPLACE FUNCTION "public"."update_organization_logo"("p_org_id" "uuid", "p_logo_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_org_id
    AND user_id = auth.uid()
    AND status = 'active';

  IF v_role IS NULL OR v_role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'Only workspace owners or admins can update the workspace logo.';
  END IF;

  UPDATE public.organizations
  SET
    logo_url = p_logo_url,
    updated_at = now()
  WHERE id = p_org_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization not found.';
  END IF;
END;
$$;


ALTER FUNCTION "public"."update_organization_logo"("p_org_id" "uuid", "p_logo_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_organization_logo"("p_org_id" "uuid", "p_logo_url" "text") IS 'Sets organizations.logo_url for org admins/owners (membership-based).';



