CREATE OR REPLACE FUNCTION "public"."update_workspace_kyc"("p_org_id" "uuid", "p_pan" "text" DEFAULT NULL::"text", "p_gstin" "text" DEFAULT NULL::"text", "p_cin" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_role   text;
  v_pan    text := nullif(trim(upper(p_pan)), '');
  v_gstin  text := nullif(trim(upper(p_gstin)), '');
  v_cin    text := nullif(trim(upper(p_cin)), '');
BEGIN
  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_org_id
    AND user_id = auth.uid()
    AND status = 'active';

  IF v_role IS NULL OR v_role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'Only workspace owners or admins can update KYC details.';
  END IF;

  IF v_pan IS NOT NULL AND v_pan !~ '^[A-Z]{5}[0-9]{4}[A-Z]$' THEN
    RAISE EXCEPTION 'Invalid PAN format. Expected 10 characters like ABCDE1234F.';
  END IF;

  IF v_gstin IS NOT NULL AND v_gstin !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$' THEN
    RAISE EXCEPTION 'Invalid GSTIN format. Expected 15-character format.';
  END IF;

  IF v_cin IS NOT NULL AND length(v_cin) != 21 THEN
    RAISE EXCEPTION 'Invalid CIN format. Expected 21 characters.';
  END IF;

  UPDATE public.organizations
  SET
    business_pan = COALESCE(v_pan, business_pan),
    gstin        = COALESCE(v_gstin, gstin),
    cin          = COALESCE(v_cin, cin),
    updated_at   = now()
  WHERE id = p_org_id;

  RETURN (
    SELECT jsonb_build_object(
      'id',                  id,
      'business_pan',        business_pan,
      'gstin',               gstin,
      'cin',                 cin,
      'verification_status', verification_status,
      'verified_at',         verified_at
    )
    FROM public.organizations WHERE id = p_org_id
  );
END;
$_$;


ALTER FUNCTION "public"."update_workspace_kyc"("p_org_id" "uuid", "p_pan" "text", "p_gstin" "text", "p_cin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_entity_anchor"("p_entity_id" "uuid", "p_entity_type" "text", "p_org_id" "uuid", "p_legacy_ref" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  INSERT INTO public.entity_identity_anchors
    (entity_id, entity_type, org_id, legacy_ref)
  VALUES
    (p_entity_id, p_entity_type, p_org_id, p_legacy_ref)
  ON CONFLICT (entity_id) DO UPDATE
    SET legacy_ref  = coalesce(EXCLUDED.legacy_ref, entity_identity_anchors.legacy_ref),
        updated_at  = now();
$$;


