CREATE OR REPLACE FUNCTION "public"."upsert_trip_subcontract"("p_viewer_org_id" "uuid", "p_trip_id" "uuid", "p_supplier_id" "uuid", "p_rate" numeric) RETURNS "public"."trip_subcontracts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.trip_subcontracts%rowtype;
  v_supplier_org uuid;
  v_linked_org uuid;
BEGIN
  IF p_viewer_org_id IS NULL OR p_trip_id IS NULL OR p_supplier_id IS NULL THEN
    RAISE EXCEPTION 'viewer_org_id, trip_id, supplier_id are required';
  END IF;
  IF NOT public.is_org_member(p_viewer_org_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF coalesce(p_rate, 0) < 0 THEN
    RAISE EXCEPTION 'Rate must be >= 0';
  END IF;

  SELECT s.organization_id, s.linked_organization_id
  INTO v_supplier_org, v_linked_org
  FROM public.suppliers s
  WHERE s.id = p_supplier_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Supplier not found';
  END IF;
  IF v_supplier_org <> p_viewer_org_id THEN
    RAISE EXCEPTION 'Supplier must belong to viewer org';
  END IF;

  INSERT INTO public.trip_subcontracts (
    viewer_org_id,
    trip_id,
    supplier_id,
    rate,
    created_by,
    sub_supplier_on_platform,
    sub_supplier_org_id,
    status
  ) VALUES (
    p_viewer_org_id,
    p_trip_id,
    p_supplier_id,
    coalesce(p_rate, 0),
    auth.uid(),
    true,
    v_linked_org,
    'pending'
  )
  ON CONFLICT (viewer_org_id, trip_id) DO UPDATE SET
    supplier_id = excluded.supplier_id,
    rate = excluded.rate,
    sub_supplier_on_platform = true,
    sub_supplier_org_id = excluded.sub_supplier_org_id,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_trip_subcontract"("p_viewer_org_id" "uuid", "p_trip_id" "uuid", "p_supplier_id" "uuid", "p_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."uuidv7_generate"() RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ts         bigint;
  v_rand_a     bigint;
  v_rand_b     bigint;
  v_hex        text;
BEGIN
  v_ts     := (extract(epoch from clock_timestamp()) * 1000)::bigint;
  v_rand_a := (random() * 4095)::bigint;                -- 12 bits
  v_rand_b := (random() * 4611686018427387903)::bigint; -- 62 bits

  -- Pack into 128-bit UUID hex string
  v_hex := lpad(to_hex(v_ts), 12, '0')                  -- 48-bit timestamp
         || '7'                                           -- version = 7
         || lpad(to_hex(v_rand_a), 3, '0')              -- 12-bit rand_a
         || to_hex((2::bigint << 62) | v_rand_b)         -- variant 10 + 62-bit rand_b
         ;

  -- Reshape into UUID format: 8-4-4-4-12
  RETURN (
    substr(v_hex, 1, 8)  || '-' ||
    substr(v_hex, 9, 4)  || '-' ||
    substr(v_hex, 13, 4) || '-' ||
    substr(v_hex, 17, 4) || '-' ||
    substr(v_hex, 21, 12)
  )::uuid;
END;
$$;


ALTER FUNCTION "public"."uuidv7_generate"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."uuidv7_generate"() IS 'RFC 9562 UUIDv7: time-sortable (millisecond precision), globally unique, no extension required.';



CREATE OR REPLACE FUNCTION "public"."uuidv7_timestamp"("p_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT to_timestamp(
    ('x' || translate(split_part(p_id::text, '-', 1), '-', '') ||
             split_part(p_id::text, '-', 2) ||
             substr(split_part(p_id::text, '-', 3), 2, 3))::bit(48)::bigint
    / 1000.0
  );
$$;


ALTER FUNCTION "public"."uuidv7_timestamp"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."uuidv7_timestamp"("p_id" "uuid") IS 'Extract creation timestamp (ms precision) from a UUIDv7. Returns NULL-safe result for UUIDv4 inputs.';



CREATE OR REPLACE FUNCTION "public"."validate_identity_integrity"("p_since" timestamp with time zone DEFAULT ("now"() - '24:00:00'::interval)) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'period_start',         p_since,
    'orphan_events',        (
      SELECT count(*) FROM public.event_store e
      WHERE e.emitted_at >= p_since
        AND NOT EXISTS (
          SELECT 1 FROM public.idempotency_keys ik
          WHERE ik.entity_id = e.aggregate_id
        )
    ),
    'duplicate_refs',       (
      SELECT count(*) FROM (
        SELECT reference, count(*) AS cnt
        FROM public.global_references
        WHERE issued_at >= p_since
        GROUP BY reference
        HAVING count(*) > 1
      ) dups
    ),
    'stale_pending_keys',   (
      SELECT count(*) FROM public.idempotency_keys
      WHERE status = 'pending'
        AND created_at < now() - interval '5 minutes'
    ),
    'search_lag',           (
      SELECT count(*) FROM public.event_store e
      WHERE e.emitted_at >= p_since
        AND NOT EXISTS (
          SELECT 1 FROM public.search_index s WHERE s.entity_id = e.aggregate_id
        )
        AND e.aggregate_type IN ('trip', 'indent', 'driver', 'vehicle')
    ),
    'all_clear',            (
      SELECT
        (SELECT count(*) FROM public.global_references r1
         JOIN public.global_references r2 ON r1.reference = r2.reference AND r1.id <> r2.id) = 0
    )
  );
$$;


ALTER FUNCTION "public"."validate_identity_integrity"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."windowed_trip_message_history"("p_conversation_id" "uuid", "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 20, "p_party_type" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."trip_messages"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv public.trip_conversations%ROWTYPE;
BEGIN
  -- Load the conversation (bypasses RLS as SECURITY DEFINER).
  SELECT * INTO v_conv
  FROM public.trip_conversations
  WHERE id = p_conversation_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Auth gate: caller must be one of:
  --   (a) active member of the conversation's owning org
  --   (b) the assigned driver for this driver-lane conversation
  --   (c) an active member of the linked supplier org for this trip
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.user_id = auth.uid()
      AND om.organization_id = v_conv.organization_id
      AND om.status = 'active'
  ) AND NOT (
    v_conv.party_type = 'driver'
    AND v_conv.driver_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.drivers d
      WHERE d.id = v_conv.driver_id AND d.user_id = auth.uid()
    )
  ) AND NOT EXISTS (
    -- Linked supplier org member can read supplier-lane and driver-lane messages.
    SELECT 1
    FROM public.trips t
    JOIN public.suppliers s ON s.id = t.supplier_id
    JOIN public.organization_members om
      ON om.user_id = auth.uid()
     AND om.organization_id = s.linked_organization_id
     AND om.status = 'active'
    WHERE t.id = v_conv.trip_id
      AND v_conv.party_type IN ('supplier', 'driver')
  ) AND NOT EXISTS (
    -- Linked supplier via accepted direct_quote (indent-based trip without supplier_id yet).
    SELECT 1
    FROM public.trips t
    JOIN public.direct_quotes dq ON dq.indent_id = t.indent_id
      AND lower(trim(coalesce(dq.status, ''))) = 'accepted'
    JOIN public.organization_members om
      ON om.user_id = auth.uid()
     AND om.organization_id = dq.bidder_organization_id
     AND om.status = 'active'
    WHERE t.id = v_conv.trip_id
      AND t.indent_id IS NOT NULL
      AND v_conv.party_type IN ('supplier', 'driver')
  ) AND NOT EXISTS (
    -- Linked client org member can read client-lane messages.
    SELECT 1
    FROM public.trips t
    JOIN public.clients c ON c.id = t.client_id
    JOIN public.organization_members om
      ON om.user_id = auth.uid()
     AND om.organization_id = c.linked_organization_id
     AND (om.status = 'active' OR om.status IS NULL)
    WHERE t.id = v_conv.trip_id
      AND v_conv.party_type = 'client'
  ) THEN
    -- Not authorized — return empty result set silently.
    RETURN;
  END IF;

  RETURN QUERY
  SELECT m.*
  FROM   public.trip_messages m
  WHERE  m.conversation_id = p_conversation_id
    AND  (p_party_type IS NULL OR v_conv.party_type = p_party_type)
    AND  (p_before IS NULL OR m.created_at < p_before)
  ORDER BY m.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(NULLIF(p_limit, 0), 20), 1), 100);
END;
$$;


ALTER FUNCTION "public"."windowed_trip_message_history"("p_conversation_id" "uuid", "p_before" timestamp with time zone, "p_limit" integer, "p_party_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."windowed_trip_message_history"("p_conversation_id" "uuid", "p_before" timestamp with time zone, "p_limit" integer, "p_party_type" "text") IS 'Newest trip_messages for one trip_conversations lane; optional p_party_type must match tc.party_type.';



CREATE MATERIALIZED VIEW "private"."dashboard_trip_metrics" AS
 SELECT "organization_id",
    "count"(*) AS "total_trips",
    "count"(*) FILTER (WHERE ("lower"(TRIM(BOTH FROM COALESCE("status", ''::"text"))) <> ALL (ARRAY['completed'::"text", 'done'::"text", 'delivered'::"text", 'cancelled'::"text"]))) AS "active_trips",
    "count"(*) FILTER (WHERE ("lower"(TRIM(BOTH FROM COALESCE("status", ''::"text"))) = ANY (ARRAY['completed'::"text", 'done'::"text", 'delivered'::"text"]))) AS "completed_trips",
    COALESCE("sum"("client_price"), (0)::numeric) AS "total_revenue",
    COALESCE("sum"("supplier_rate"), (0)::numeric) AS "total_cost",
    COALESCE("sum"((COALESCE("client_price", (0)::numeric) - COALESCE("supplier_rate", (0)::numeric))), (0)::numeric) AS "total_margin",
    "max"("updated_at") AS "last_trip_updated_at"
   FROM "public"."trips" "t"
  WHERE ("deleted_at" IS NULL)
  GROUP BY "organization_id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "private"."dashboard_trip_metrics" OWNER TO "postgres";


