COMMENT ON TABLE "public"."clients" IS 'Client companies. Soft-delete via deleted_at.';



COMMENT ON COLUMN "public"."clients"."linked_organization_id" IS 'When set, this client is another platform org; use organization_links for two-way connection';



COMMENT ON COLUMN "public"."clients"."address" IS 'DEPRECATED: legacy general-purpose address field. Prefer registered_address (legal) or hq_address (operational). Do not write to this column if either of those is also set.';



COMMENT ON COLUMN "public"."clients"."hq_address" IS 'Head-office / primary operational address. Use for dispatch, billing fallback, and general correspondence.';



COMMENT ON COLUMN "public"."clients"."billing_address" IS 'Address printed on invoices. Defaults to hq_address if not set separately.';



COMMENT ON COLUMN "public"."clients"."registered_address" IS 'Legally registered address as per MCA/GST records. Required for KYC and compliance documents.';



COMMENT ON COLUMN "public"."clients"."corporate_address" IS 'Corporate/administrative office address when different from HQ. Optional.';



