    CONSTRAINT "trip_fuel_entries_approval_state_check" CHECK (("approval_state" = ANY (ARRAY['reported'::"text", 'review_pending'::"text", 'approved'::"text", 'rejected'::"text", 'settled'::"text"]))),
    CONSTRAINT "trip_fuel_entries_ledger_state_check" CHECK (("ledger_state" = ANY (ARRAY['not_posted'::"text", 'posted'::"text", 'void'::"text"]))),
    CONSTRAINT "trip_fuel_entries_liters_non_negative" CHECK ((("liters" IS NULL) OR ("liters" >= (0)::numeric))),
