    CONSTRAINT "trip_fuel_entries_posting_state_check" CHECK (("posting_state" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'posted'::"text", 'rejected'::"text", 'failed'::"text"]))),
    CONSTRAINT "trip_fuel_entries_reimbursement_state_check" CHECK (("reimbursement_state" = ANY (ARRAY['reported'::"text", 'approved'::"text", 'reimbursement_pending'::"text", 'reimbursed'::"text", 'rejected'::"text"]))),
    CONSTRAINT "trip_fuel_entries_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'voided'::"text"])))
);


