CREATE OR REPLACE VIEW "public"."v_active_trips" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."organization_id",
    "t"."trip_number",
    "t"."status",
    "t"."pickup_area",
    "t"."drop_location",
    "t"."pickup_date",
    "t"."client_name",
    "t"."client_price",
    "t"."supplier_rate",
    "t"."margin",
    "t"."payment_status",
    "t"."driver_display_name",
    "t"."vehicle_display_number",
    "d"."name" AS "driver_name",
    "d"."phone" AS "driver_phone",
    "d"."status" AS "driver_current_status",
    "v"."vehicle_number",
    "v"."vehicle_type",
    "s"."company_name" AS "supplier_name"
   FROM ((("public"."trips" "t"
     LEFT JOIN "public"."drivers" "d" ON (("d"."id" = "t"."driver_id")))
     LEFT JOIN "public"."vehicles" "v" ON (("v"."id" = "t"."vehicle_id")))
     LEFT JOIN "public"."suppliers" "s" ON (("s"."id" = "t"."supplier_id")))
  WHERE (("t"."deleted_at" IS NULL) AND ("t"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"])));


ALTER VIEW "public"."v_active_trips" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_client_revenue" WITH ("security_invoker"='true') AS
 SELECT "t"."organization_id",
    "t"."client_id",
    "c"."name" AS "client_name",
    "count"("t"."id") AS "total_trips",
    "sum"("t"."client_price") AS "total_billed",
    "sum"("t"."amount_paid") AS "total_collected",
    "sum"(("t"."client_price" - "t"."amount_paid")) AS "outstanding"
   FROM ("public"."trips" "t"
     JOIN "public"."clients" "c" ON (("c"."id" = "t"."client_id")))
  WHERE (("t"."deleted_at" IS NULL) AND ("t"."status" = 'completed'::"text"))
  GROUP BY "t"."organization_id", "t"."client_id", "c"."name";


ALTER VIEW "public"."v_client_revenue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_driver_balances" WITH ("security_invoker"='true') AS
 SELECT "d"."id" AS "driver_id",
    "d"."organization_id",
    "d"."name" AS "driver_name",
    "d"."phone",
    "d"."status",
    COALESCE("ledger_last"."balance_after", (0)::numeric) AS "current_balance",
    COALESCE("trip_counts"."completed_trips", (0)::bigint) AS "completed_trips"
   FROM (("public"."drivers" "d"
     LEFT JOIN LATERAL ( SELECT "driver_ledger"."balance_after"
           FROM "public"."driver_ledger"
          WHERE ("driver_ledger"."driver_id" = "d"."id")
          ORDER BY "driver_ledger"."created_at" DESC
         LIMIT 1) "ledger_last" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "completed_trips"
           FROM "public"."trips"
          WHERE (("trips"."driver_id" = "d"."id") AND ("trips"."status" = 'completed'::"text") AND ("trips"."deleted_at" IS NULL))) "trip_counts" ON (true))
  WHERE ("d"."deleted_at" IS NULL);


ALTER VIEW "public"."v_driver_balances" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_driver_tracking_health" WITH ("security_invoker"='true') AS
 SELECT "id",
    "trip_number",
    COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at") AS "anchor_at",
    (EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) / 86400.0) AS "days_elapsed",
    COALESCE(("actual_distance_traveled_km")::double precision, (0.0)::double precision) AS "actual_distance_km",
    GREATEST((((EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) / 86400.0) * 350.0))::double precision, (0.0)::double precision) AS "target_km",
        CASE
            WHEN ("lower"(TRIM(BOTH FROM "status")) <> ALL (ARRAY['in_transit'::"text", 'picked_up'::"text", 'in_progress'::"text", 'transit'::"text", 'at_drop'::"text", 'loading'::"text", 'unloading'::"text", 'at_pickup'::"text", 'assigned'::"text", 'active'::"text", 'on_route'::"text"])) THEN 'ON_TRACK'::"text"
            WHEN (COALESCE("started_at", ("pickup_date")::timestamp with time zone) IS NULL) THEN 'ON_TRACK'::"text"
            WHEN (EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) <= (0)::numeric) THEN 'ON_TRACK'::"text"
            WHEN (COALESCE(("actual_distance_traveled_km")::double precision, (0.0)::double precision) < (((EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) / 86400.0) * 350.0))::double precision) THEN 'RUNNING_LATE'::"text"
            ELSE 'ON_TRACK'::"text"
        END AS "tracking_status"
   FROM "public"."trips" "t";


ALTER VIEW "public"."v_driver_tracking_health" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_driver_tracking_health" IS 'Pace check: actual_distance_traveled_km vs days_since_anchor * 350 km/day. RUNNING_LATE when behind.';



CREATE OR REPLACE VIEW "public"."v_long_haul_health" WITH ("security_invoker"='true') AS
 SELECT "id" AS "trip_id",
    "trip_number",
    COALESCE(("distance")::double precision, (0)::double precision) AS "total_distance_km",
    ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at")) AS "time_elapsed",
    GREATEST((((EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) / 86400.0) * 350.0))::double precision, (0)::double precision) AS "expected_km",
    COALESCE(("actual_distance_traveled_km")::double precision, ( SELECT
                CASE
                    WHEN ("count"(*) FILTER (WHERE ("dl"."odometer_km" IS NOT NULL)) >= 2) THEN ("max"("dl"."odometer_km") - "min"("dl"."odometer_km"))
                    ELSE NULL::double precision
                END AS "case"
           FROM "public"."driver_locations" "dl"
          WHERE ("dl"."trip_id" = "t"."id")), (0)::double precision) AS "current_km",
        CASE
            WHEN (COALESCE("started_at", ("pickup_date")::timestamp with time zone) IS NULL) THEN 'ON_TRACK'::"text"
            WHEN ("lower"(TRIM(BOTH FROM "status")) <> ALL (ARRAY['in_transit'::"text", 'picked_up'::"text", 'in_progress'::"text", 'transit'::"text", 'at_drop'::"text", 'loading'::"text", 'unloading'::"text", 'at_pickup'::"text", 'assigned'::"text", 'active'::"text"])) THEN 'ON_TRACK'::"text"
            WHEN (EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) <= (0)::numeric) THEN 'ON_TRACK'::"text"
            WHEN (COALESCE(("actual_distance_traveled_km")::double precision, ( SELECT
                    CASE
                        WHEN ("count"(*) FILTER (WHERE ("dl2"."odometer_km" IS NOT NULL)) >= 2) THEN ("max"("dl2"."odometer_km") - "min"("dl2"."odometer_km"))
                        ELSE NULL::double precision
                    END AS "case"
               FROM "public"."driver_locations" "dl2"
              WHERE ("dl2"."trip_id" = "t"."id")), (0)::double precision) < ((((EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) / 86400.0) * 350.0) * 0.7))::double precision) THEN 'CRITICAL_DELAY'::"text"
            WHEN (COALESCE(("actual_distance_traveled_km")::double precision, ( SELECT
                    CASE
                        WHEN ("count"(*) FILTER (WHERE ("dl3"."odometer_km" IS NOT NULL)) >= 2) THEN ("max"("dl3"."odometer_km") - "min"("dl3"."odometer_km"))
                        ELSE NULL::double precision
                    END AS "case"
               FROM "public"."driver_locations" "dl3"
              WHERE ("dl3"."trip_id" = "t"."id")), (0)::double precision) < ((((EXTRACT(epoch FROM ("now"() - COALESCE("started_at", ("pickup_date")::timestamp with time zone, "created_at"))) / 86400.0) * 350.0) * 0.9))::double precision) THEN 'LATE_RISK'::"text"
            ELSE 'ON_TRACK'::"text"
        END AS "health_status"
   FROM "public"."trips" "t";


ALTER VIEW "public"."v_long_haul_health" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_long_haul_health" IS 'Long-haul pacing: expected km = days_since_anchor * 350; health from actual_distance_traveled_km or odometer span.';



