CREATE OR REPLACE VIEW "public"."v_open_indents" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."organization_id",
    "i"."indent_number",
    "i"."status",
    "i"."pickup_area",
    "i"."drop_location",
    "i"."client_name",
    "i"."client_price",
    "i"."supplier_target",
    "i"."pickup_date",
    "i"."vehicle_type",
    "i"."weight",
    "count"("dq"."id") AS "quote_count"
   FROM ("public"."indents" "i"
     LEFT JOIN "public"."direct_quotes" "dq" ON ((("dq"."indent_id" = "i"."id") AND ("dq"."status" = 'pending'::"text"))))
  WHERE (("i"."deleted_at" IS NULL) AND ("i"."status" = ANY (ARRAY['open'::"text", 'broadcast'::"text", 'pending'::"text", 'quoted'::"text"])))
  GROUP BY "i"."id";



