CREATE POLICY "Allow users to view their own organization's verification jobs" ON "public"."verification_jobs" FOR SELECT TO "authenticated" USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("organization_members"."status" = 'active'::"text")))));



CREATE POLICY "Bidders can insert own direct quotes" ON "public"."direct_quotes" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."organization_members" "om"
  WHERE (("om"."organization_id" = "direct_quotes"."bidder_organization_id") AND ("om"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Bidders can select own direct quotes" ON "public"."direct_quotes" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members" "om"
  WHERE (("om"."organization_id" = "direct_quotes"."bidder_organization_id") AND ("om"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Bidders can update own direct quotes" ON "public"."direct_quotes" FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members" "om"
  WHERE (("om"."organization_id" = "direct_quotes"."bidder_organization_id") AND ("om"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Drivers can insert own driver_salary_requests" ON "public"."driver_salary_requests" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."drivers" "d"
  WHERE (("d"."id" = "driver_salary_requests"."driver_id") AND ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Drivers can insert settlement for own ledger" ON "public"."driver_ledger" FOR INSERT WITH CHECK ((("type" = 'settlement'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."drivers" "d"
  WHERE (("d"."id" = "driver_ledger"."driver_id") AND ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))));



CREATE POLICY "Drivers can read own driver_salary_requests" ON "public"."driver_salary_requests" FOR SELECT USING ((EXISTS ( SELECT 1
