CREATE POLICY "Drivers can read own row" ON "public"."drivers" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "Drivers can read own trips" ON "public"."trips" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."drivers" "d"
  WHERE (("d"."id" = "trips"."driver_id") AND ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Drivers can read supplier transactions for assigned trips" ON "public"."transactions" FOR SELECT USING ((("contact_type" = 'supplier'::"text") AND "public"."driver_has_assigned_trip_for_trip_id"("trip_id")));



COMMENT ON POLICY "Drivers can read supplier transactions for assigned trips" ON "public"."transactions" IS 'Same as suppliers policy; helper avoids recursion into trips RLS.';



CREATE POLICY "Drivers can read suppliers linked to assigned trips" ON "public"."suppliers" FOR SELECT USING ("public"."driver_has_assigned_trip_for_supplier"("id"));



COMMENT ON POLICY "Drivers can read suppliers linked to assigned trips" ON "public"."suppliers" IS 'Cross-org aggregate trips: driver JWT is not org_member(trip.organization_id); uses SECURITY DEFINER helper to avoid trips RLS recursion.';



CREATE POLICY "Drivers can read trip assignment audit for assigned trips" ON "public"."trip_assignment_audit" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."trips" "t"
     JOIN "public"."drivers" "d" ON ((("d"."id" = "t"."driver_id") AND ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))
  WHERE ("t"."id" = "trip_assignment_audit"."trip_id"))));



CREATE POLICY "Drivers can send messages in their conversations" ON "public"."trip_messages" FOR INSERT TO "authenticated" WITH CHECK ((("sender_role" = 'driver'::"text") AND (("conversation_id" IN ( SELECT "tc"."id"
   FROM ("public"."trip_conversations" "tc"
     JOIN "public"."drivers" "d" ON (("d"."id" = "tc"."driver_id")))
  WHERE ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid")))) OR ("organization_id" IN ( SELECT "om"."organization_id"
   FROM "public"."organization_members" "om"
  WHERE ("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))));



