CREATE POLICY "Linked client org reads trip conversations" ON "public"."trip_conversations" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM (("public"."trips" "t"
     JOIN "public"."clients" "c" ON (("c"."id" = "t"."client_id")))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "c"."linked_organization_id") AND (("om"."status" = 'active'::"text") OR ("om"."status" IS NULL)))))
  WHERE ("t"."id" = "trip_conversations"."trip_id"))));



CREATE POLICY "Linked client org reads trip messages" ON "public"."trip_messages" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM ((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."clients" "c" ON (("c"."id" = "t"."client_id")))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "c"."linked_organization_id") AND (("om"."status" = 'active'::"text") OR ("om"."status" IS NULL)))))
  WHERE ("tc"."id" = "trip_messages"."conversation_id"))));



CREATE POLICY "Linked org members can read links where they are linked" ON "public"."organization_links" FOR SELECT USING ("public"."is_org_member"("linked_org_id"));



CREATE POLICY "Linked supplier dispatcher inserts in host trip convs" ON "public"."trip_messages" FOR INSERT WITH CHECK ((("sender_role" = 'dispatcher'::"text") AND ("organization_id" = ( SELECT "tc"."organization_id"
   FROM "public"."trip_conversations" "tc"
  WHERE ("tc"."id" = "trip_messages"."conversation_id"))) AND ((EXISTS ( SELECT 1
   FROM ((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."suppliers" "s" ON ((("s"."id" = "t"."supplier_id") AND ("s"."id" = "tc"."supplier_id"))))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "s"."linked_organization_id") AND ("om"."status" = 'active'::"text"))))
  WHERE (("tc"."id" = "trip_messages"."conversation_id") AND ("tc"."party_type" = 'supplier'::"text")))) OR (EXISTS ( SELECT 1
   FROM ((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."suppliers" "s" ON (("s"."id" = "t"."supplier_id")))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "s"."linked_organization_id") AND ("om"."status" = 'active'::"text"))))
  WHERE (("tc"."id" = "trip_messages"."conversation_id") AND ("tc"."party_type" = 'driver'::"text")))))));



CREATE POLICY "Linked supplier inserts supplier in driver thread" ON "public"."trip_messages" FOR INSERT TO "authenticated" WITH CHECK ((("sender_role" = 'supplier'::"text") AND ("organization_id" = ( SELECT "tc"."organization_id"
   FROM "public"."trip_conversations" "tc"
  WHERE ("tc"."id" = "trip_messages"."conversation_id"))) AND ((EXISTS ( SELECT 1
   FROM ((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."suppliers" "s" ON (("s"."id" = "t"."supplier_id")))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "s"."linked_organization_id") AND ("om"."status" = 'active'::"text"))))
  WHERE (("tc"."id" = "trip_messages"."conversation_id") AND ("tc"."party_type" = 'driver'::"text")))) OR (EXISTS ( SELECT 1
   FROM (((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."indents" "i" ON (("i"."id" = "t"."indent_id")))
     JOIN "public"."direct_quotes" "dq" ON ((("dq"."indent_id" = "i"."id") AND ("dq"."status" = 'accepted'::"text"))))
     JOIN "public"."organization_members" "om" ON ((("om"."organization_id" = "dq"."bidder_organization_id") AND ("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."status" = 'active'::"text"))))
  WHERE (("tc"."id" = "trip_messages"."conversation_id") AND ("tc"."party_type" = 'driver'::"text") AND ("t"."supplier_id" IS NULL) AND ("t"."indent_id" IS NOT NULL)))))));



COMMENT ON POLICY "Linked supplier inserts supplier in driver thread" ON "public"."trip_messages" IS 'Direct-insert fallback: supplier posts in shipper-owned driver thread (RPC preferred).';



CREATE POLICY "Linked supplier org inserts supplier party messages" ON "public"."trip_messages" FOR INSERT TO "authenticated" WITH CHECK ((("sender_role" = 'supplier'::"text") AND ("organization_id" = ( SELECT "tc"."organization_id"
   FROM "public"."trip_conversations" "tc"
  WHERE ("tc"."id" = "trip_messages"."conversation_id"))) AND ((EXISTS ( SELECT 1
   FROM ((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."suppliers" "s" ON ((("s"."id" = "t"."supplier_id") AND ("s"."id" = "tc"."supplier_id"))))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "s"."linked_organization_id") AND (COALESCE("om"."status", 'active'::"text") = 'active'::"text"))))
  WHERE (("tc"."id" = "trip_messages"."conversation_id") AND ("tc"."party_type" = 'supplier'::"text")))) OR (EXISTS ( SELECT 1
   FROM ((("public"."trip_conversations" "tc"
     JOIN "public"."trips" "t" ON (("t"."id" = "tc"."trip_id")))
     JOIN "public"."direct_quotes" "dq" ON ((("dq"."indent_id" = "t"."indent_id") AND ("lower"(TRIM(BOTH FROM COALESCE("dq"."status", ''::"text"))) = 'accepted'::"text"))))
     JOIN "public"."organization_members" "om" ON ((("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."organization_id" = "dq"."bidder_organization_id") AND (COALESCE("om"."status", 'active'::"text") = 'active'::"text"))))
  WHERE (("tc"."id" = "trip_messages"."conversation_id") AND ("tc"."party_type" = 'supplier'::"text") AND ("t"."indent_id" IS NOT NULL) AND ("tc"."supplier_id" IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM "public"."suppliers" "s2"
          WHERE (("s2"."id" = "tc"."supplier_id") AND ("s2"."linked_organization_id" = "dq"."bidder_organization_id"))))))))));



COMMENT ON POLICY "Linked supplier org inserts supplier party messages" ON "public"."trip_messages" IS 'Supplier org: post as supplier on supplier party thread when linked or accepted bidder matches.';



