CREATE POLICY "Orgs can read trips where they are the client" ON "public"."trips" FOR SELECT TO "authenticated" USING ((("source" = 'manual'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."clients" "c"
  WHERE (("c"."id" = "trips"."client_id") AND ("c"."linked_organization_id" IS NOT NULL) AND ("c"."linked_organization_id" IN ( SELECT "om"."organization_id"
           FROM "public"."organization_members" "om"
          WHERE (("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."status" = 'active'::"text")))))))));



CREATE POLICY "Orgs can read trips where they are the supplier" ON "public"."trips" FOR SELECT USING ((("indent_id" IS NOT NULL) AND ((EXISTS ( SELECT 1
   FROM "public"."suppliers" "s"
  WHERE (("s"."id" = "trips"."supplier_id") AND ("s"."linked_organization_id" IS NOT NULL) AND ("s"."linked_organization_id" IN ( SELECT "om"."organization_id"
           FROM "public"."organization_members" "om"
          WHERE (("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND (COALESCE("om"."status", 'active'::"text") = 'active'::"text"))))))) OR (EXISTS ( SELECT 1
   FROM "public"."direct_quotes" "dq"
  WHERE (("dq"."indent_id" = "trips"."indent_id") AND ("lower"(TRIM(BOTH FROM COALESCE("dq"."status", ''::"text"))) = 'accepted'::"text") AND ("dq"."bidder_organization_id" IN ( SELECT "om"."organization_id"
           FROM "public"."organization_members" "om"
          WHERE (("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND (COALESCE("om"."status", 'active'::"text") = 'active'::"text"))))))))));



COMMENT ON POLICY "Orgs can read trips where they are the supplier" ON "public"."trips" IS 'Supplier org: indent trips where they are linked supplier OR accepted bidder on the indent.';



CREATE POLICY "Supplier org can update trips where they are the supplier" ON "public"."trips" FOR UPDATE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."suppliers" "s"
  WHERE (("s"."id" = "trips"."supplier_id") AND ("s"."linked_organization_id" IS NOT NULL) AND ("s"."linked_organization_id" IN ( SELECT "om"."organization_id"
           FROM "public"."organization_members" "om"
          WHERE (("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."status" = 'active'::"text")))))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."suppliers" "s"
  WHERE (("s"."id" = "trips"."supplier_id") AND ("s"."linked_organization_id" IS NOT NULL) AND ("s"."linked_organization_id" IN ( SELECT "om"."organization_id"
           FROM "public"."organization_members" "om"
          WHERE (("om"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("om"."status" = 'active'::"text"))))))));



